--[[
	Tensen Hub - cleaned up

	Deobfuscated and tidied. Does the same thing as the dump it came from, with one
	exception: noteBigMomSound now hooks the sound's Ended/Stopped events (the dump
	never did, a value was missing from its stub table).

	"if false then -- never runs" blocks and the code under "-- never reached" are real
	code the dump never runs either: with the dump's key values the check in front of
	it always goes the other way. Looks like a dump mistake (target sorting, battle
	royale tabs, tripwires, config loading...), so it's kept instead of deleted.

	Layout
	  anti-tamper       if getgenv().__TensenGuardV == nil then ... end
	  big mom module    do ... end (initBigMom, then Start/Stop/RestartBigMom)
	  hub ui            if not getgenv().AlreadyLoad then ... end

	Where to look
	  anti-tamper     scanForTools, classifyTools, punish, installTripwire, guardFileWrite
	  farm loop       "-- main farm loop" in the big mom module
	  big mom         findBigMom, bigMomPosition, isBigMomNPC, mochiEmperor
	  movement        tweenToMob, tweenToCFrame, TweenToCFrameSafe, goTo, stepTo
	  ground          LandOnGround, dodgeGroundY, FindNonBarrierGroundY
	  weapon          equipWeapon, weaponInHand, askWeaponEquip
	  orders          dialogueText, classifyDialogue, wantedCake
	  cakes           deliverCake, deliverOneCake, findCake
	  rooms           currentCakeStage, campCheck, backIntoRoom, declareRoomDone, cakeExitPart
	  gate            chateauDoorOpen, knockPortal
	  puzzles         bookMatch, answerOrbPattern, orbColourName
	  dodging         bigMomReaction, noteBigMomSound
	  death           noteDeath, returnToDeathFloor, afterBossTick
	  ui              window:AddTab, addBossControls, addBigMomToggle, addEspToggle
	  configs         savedOptionsFor, queueAutoSave
]]

local guardNoop, hubLog -- both set in the big mom module

-- to uint32 (nan/inf -> 0)
local function u32(x)
	local r = x % 4294967296
	if r ~= r then return 0 end
	return r - r % 1
end

-- placeholders, only ever read as empty
t662_2991_1 = {n = 0}
g_0 = function() end

-- obfuscator key state
local keyState = 2591461018

-- anti-tamper
if getgenv().__TensenGuardV == nil then
	getgenv().__TensenGuardV = 3
	local canHook = type(hookfunction) == "function"
	local hooksUsable

	if canHook then
		local newcclosureType = type(newcclosure)
		local stateKey = u32(keyState)
		local stateKey = (stateKey + 2176362839) % 4294967296
		local hasNewcclosure = newcclosureType == "function"
		keyState = (stateKey + 2118604457) % 4294967296
		hooksUsable = hasNewcclosure
	else
		hooksUsable = canHook
	end

	local TOOL_SEVERITY = {
		["Infinite Yield"] = "ignore",
		["SimpleSpy (Beta/V3)"] = "soft",
		Cobalt = "soft",
		["Dex++"] = "soft",
		["Dex family"] = "soft",
		["HTTP Spy"] = "hard",
		["Remote Spy"] = "hard",
		Hydroxide = "hard"
	}

	local TOOL_NAME_PATTERNS = {
		{"http spy", "HTTP Spy"},
		{"httpspy", "HTTP Spy"},
		{"remotespy", "Remote Spy"},
		{"remote spy", "Remote Spy"},
		{"hydroxide", "Hydroxide"}
	}

	local function scanForTools(root, maxDepth, yieldEvery)
		if not maxDepth then
			return
		end

		local found = {}
		local seen = {}

		local function addFound(toolName)
			if not seen[toolName] then
				seen[toolName] = true
				found[#found + 1] = toolName
			end
		end

		if rawget(getgenv(), "SimpleSpyExecuted") == true then
			addFound("SimpleSpy (Beta/V3)")
		end

		if rawget(getgenv(), "IY_LOADED") == true then
			addFound("Infinite Yield")
		end

		if rawget(getgenv(), "CobaltInitialized") == true or type(rawget(getgenv(), "Cobalt")) == "table" then
			addFound("Cobalt")
		end

		local roots = {}
		local rootSeen = {}

		local function addRoot(getRoot)
			local ok, result = pcall(getRoot)

			if ok and typeof(result) == "Instance" and not rootSeen[result] then
				rootSeen[result] = true
				roots[#roots + 1] = result
			end
		end

		if root ~= nil then
			addRoot(function()
				return root
			end)
		else
			addRoot(function()
				return game:GetService("CoreGui")
			end)

			if type(gethui) == "function" then
				addRoot(gethui)
			end
		end

		local function matchToolText(instance)
			local name = instance.Name

			if instance:IsA("TextLabel") or instance:IsA("TextButton") or instance:IsA("TextBox") then
				name ..= " " .. instance.Text
			end

			local name = string.lower(name)

			for _, pattern in ipairs(TOOL_NAME_PATTERNS) do
				if string.find(name, pattern[1], 1, true) then
					addFound(pattern[2])
				end
			end
		end

		local function inspect(instance)
			local name = instance.Name
			matchToolText(instance)

			if name:sub(1, 5) == "_DPP_" then
				if instance:IsA("ScreenGui") then
					addFound("Dex++")
				end
			elseif name == "ExplorerItems" and instance:IsA("Folder") then
				local toolBar = instance:FindFirstChild("ToolBar")
				local searchFrame = toolBar and toolBar:FindFirstChild("SearchFrame")
				local searchBox = searchFrame and searchFrame:FindFirstChild("SearchBox")

				if searchBox and searchBox:IsA("TextBox") and searchBox.PlaceholderText == "Search workspace" and instance:FindFirstChild("List") and instance:FindFirstChild("ScrollCorner") then
					addFound("Dex family")
				end
			end
		end

		pcall(function()
			local stack = {}
			local depths = {}
			local top = 0

			for _, startRoot in ipairs(roots) do
				top += 1
				stack[top] = startRoot
				depths[top] = 0
			end

			local count = 0

			while top > 0 do
				local instance = stack[top]
				local depth = depths[top]
				stack[top] = nil
				depths[top] = nil
				top -= 1
				inspect(instance)

				if depth < maxDepth then
					local children = instance:GetChildren()
					local childDepth = depth + 1

					for i = 1, #children do
						top += 1
						stack[top] = children[i]
						depths[top] = childDepth
					end
				end

				count += 1

				if yieldEvery and count % yieldEvery == 0 then
					task.wait()
				end
			end
		end)

		return found
	end

	local function classifyTools(toolNames)
		local names = {}
		local severity = nil

		for _, toolName in ipairs(toolNames) do
			local level = TOOL_SEVERITY[toolName] or "soft"

			if level == "ignore" then
				continue
			end

			names[#names + 1] = toolName

			if level == "hard" then
				severity = "hard"
			elseif severity == nil then
				severity = "soft"
			end
		end

		return severity, table.concat(names, ", ")
	end

	local punished = false

	local function sabotageEnvironment()
		local wrapC = type(newcclosure) == "function" and newcclosure or function(fn)
			return fn
		end

		local noop = wrapC(function() end)

		pcall(function()
			if type(setclipboard) == "function" then
				setclipboard("")
			end
		end)

		for _, globalName in ipairs({
			"print",
			"warn",
			"printconsole",
			"printidentity",
			"rconsoleprint",
			"rconsolewarn",
			"rconsoleinfo",
			"rconsoleerr",
			"rconsolename",
			"rconsolecreate",
			"rconsoleclear",
			"consoleprint",
			"consolewarn",
			"consoleinfo",
			"consolecreate",
			"consoleclear",
			"messagebox",
			"setclipboard",
			"toclipboard",
			"setrbxclipboard",
			"writeclipboard",
			"writefile",
			"appendfile",
			"request",
			"http_request"
		}) do
			pcall(function()
				if false then -- never runs
					getgenv()[globalName] = noop
				end
			end)
		end

		pcall(function()
			if type(syn) == "table" then
				syn.request = noop
			end
		end)

		pcall(function()
			if type(http) == "table" then
				http.request = noop
			end
		end)

		pcall(function()
			if type(Drawing) ~= "table" then
				return
			end

			Drawing.new = wrapC(function()
				return setmetatable({}, {
					__index = function()
						return function() end
					end,
					__newindex = function() end
				})
			end)
		end)
	end

	local function leaveCaughtFile()
		local tensenWF = getgenv().__TensenWF or writefile

		if type(tensenWF) == "function" then
			pcall(tensenWF, "TENSEN_CAUGHT_YOU.txt", "Tensen anti-tamper tripped. The chunk never left this machine. - Tensen")
		end
	end

	local function punish(severity, reason)
		if punished then
			return
		end

		punished = true

		local message

		if severity == "hard" then
			message = "[Tensen] Anti-tamper triggered: " .. tostring(reason)
			pcall(sabotageEnvironment)
			pcall(leaveCaughtFile)
		else
			message = "[Tensen] Blocked: " .. tostring(reason) .. "\nClose reverse-engineering tools and rejoin."
		end

		local kicked = false

		pcall(function()
			local localPlayer = game:GetService("Players").LocalPlayer

			if localPlayer then
				localPlayer:Kick(message)
				kicked = true
			end
		end)

		if not kicked then
			pcall(function()
				game:Shutdown()
			end)
		end
	end

	local PROBE = {}
	local PROBE_REPLY = {}
	local installedHooks = {}
	local tensenHookStatus = {}
	getgenv().__TensenHookStatus = tensenHookStatus
	local protectedFunctions = setmetatable({}, {__mode = "k"})

	local function verifyHook(name, getTarget)
		local ok, result = pcall(getTarget)
		local probeOk = false
		ok = ok and type(result) == "function"
		local probeReply = nil

		if ok then
			probeOk, probeReply = pcall(result, PROBE)
		end

		if not probeOk or probeReply ~= PROBE_REPLY then
			tensenHookStatus[name] = "not installed - blocked or unsupported"
			return false
		end

		tensenHookStatus[name] = "installed"
		installedHooks[name] = getTarget
		return true
	end

	local function tensenProtect(fn)
		if type(fn) == "function" then
			protectedFunctions[fn] = true
		end

		return fn
	end

	getgenv().__TensenProtect = tensenProtect
	tensenProtect(scanForTools)
	tensenProtect(classifyTools)
	tensenProtect(function()
		error("[Tensen] anti-tamper trap reached (the original freezes the client here)")
	end)
	tensenProtect(punish)
	local sabotageFn = sabotageEnvironment
	local guardKeyIn = u32(keyState)
	local guardKey = (guardKeyIn + 2539492048) % 4294967296
	tensenProtect(sabotageFn)
	tensenProtect(leaveCaughtFile)

	local function installTripwire(name, getTarget, severity)
		if not hooksUsable then
			return nil
		end

		local ok, result = pcall(getTarget)

		if not ok or type(result) ~= "function" then
			return nil
		end

		local hooked, original = pcall(function()
			local hook = hookfunction

			local replacement = table.pack(newcclosure(function(probe)
				if probe == PROBE then
					return PROBE_REPLY
				end

				task.spawn(punish, severity, name)
			end))

			if false then -- never runs
				return hook(result, table.unpack(replacement, 1, replacement.n))
			end
		end)

		if not hooked or type(original) ~= "function" then
			return nil
		end

		if not verifyHook(name, getTarget) then
			return nil
		end

		return original
	end

	local function guardDebugFunction(name, getTarget)
		if not hooksUsable then
			return nil
		end

		local ok, result = pcall(getTarget)

		if not ok or type(result) ~= "function" then
			return nil
		end

		local original = nil

		local hookOk, originalFn = pcall(function()
			return hookfunction(result, newcclosure(function(target, ...)
				if target == PROBE then
					return PROBE_REPLY
				end

				if type(target) == "function" and protectedFunctions[target] then
					task.spawn(punish, "hard", name)
					return
				end

				if type(original) == "function" then
					local args = table.pack(...)
					return original(target, table.unpack(args, 1, args.n))
				end
			end))
		end)

		if not hookOk or type(originalFn) ~= "function" then
			return nil
		end

		original = originalFn

		if not verifyHook(name, getTarget) then
			return nil
		end

		return originalFn
	end

	local function isValidHubFile(path)
		local valid = false

		pcall(function()
			if type(readfile) ~= "function" then
				valid = true
				return
			end

			local content = readfile(path)

			if type(content) ~= "string" then
				return
			end

			if string.find(path, "autoload%.txt$") then
				valid = #content < 256 and string.find(content, "%c") == nil
			else
				local ok, result = pcall(function()
					return game:GetService("HttpService"):JSONDecode(content)
				end)

				valid = ok == true and type(result) == "table"
			end
		end)

		return valid
	end

	local function guardFileWrite(name, getTarget)
		if not hooksUsable then
			return nil
		end

		local ok, result = pcall(getTarget)

		if not ok or type(result) ~= "function" then
			return nil
		end

		local original = nil

		local hookOk, originalFn = pcall(function()
			return hookfunction(result, newcclosure(function(path, content, ...)
				if path == PROBE then
					return PROBE_REPLY
				end

				if type(path) ~= "string" or string.sub(path, 1, 11) ~= "Tensen Hub/" then
					return
				end

				local results = {}

				if type(original) == "function" then
					results = {original(path, content, ...)}
				end

				if not isValidHubFile(path) then
					pcall(function()
						if type(delfile) == "function" then
							delfile(path)
						end
					end)

					return
				end

				return table.unpack(results)
			end))
		end)

		if not hookOk or type(originalFn) ~= "function" then
			return nil
		end

		original = originalFn

		if not verifyHook(name, getTarget) then
			return nil
		end

		return originalFn
	end

	local HUB_FOLDER = string.gsub("Tensen Hub/", "[/\\]+$", "")

	local function purgeInvalidFiles(folder)
		if type(listfiles) ~= "function" then
			return
		end

		local ok, result = pcall(listfiles, folder)

		if not ok or type(result) ~= "table" then
			return
		end

		for _, path in ipairs(result) do
			if type(path) ~= "string" then
				continue
			end

			local isFolderOk, isFolder = pcall(function()
				return type(isfolder) == "function" and isfolder(path)
			end)

			if isFolderOk and isFolder then
				purgeInvalidFiles(path)
			elseif not isValidHubFile(path) then
				pcall(function()
					if type(delfile) == "function" then
						delfile(path)
					end
				end)
			end

			task.wait()
		end
	end

	getgenv().__TensenIsWrapped = function(fn)
		local kind = type(fn)

		if kind ~= "function" then
			return 0
		end

		if type(iscclosure) ~= "function" then
			return 0
		end

		local ok, result = pcall(iscclosure, fn)

		if not ok or result ~= true then
			return 0
		end

		local hasDebugInfo = type(debug) == "table" and type(debug.info) == "function"
		local score = 0

		if hasDebugInfo then
			local infoOk, source = pcall(debug.info, fn, "s")

			if infoOk and type(source) == "string" and source ~= "" and source ~= "[C]" then
				score = 1
			end
		end

		local callOk, callErr = pcall(fn, PROBE, PROBE)

		if not callOk and type(callErr) == "string" and string.find(callErr, ":%d+:") then
			score += 1
		end

		return score
	end

	getgenv().__TensenWF = getgenv().__TensenWF or writefile
	getgenv().__TensenGC = getgenv().__TensenGC or getgc

	local function listRootFiles()
		if type(listfiles) ~= "function" then
			return nil
		end

		for _, path in ipairs({"", "."}) do
			local ok, result = pcall(listfiles, path)

			if ok and type(result) == "table" then
				return result
			end
		end

		return nil
	end

	local function deleteLookalikeFiles(fileName, paths)
		if type(delfile) ~= "function" or type(fileName) ~= "string" then
			return
		end

		fileName = string.match(fileName, "([^/\\]+)$") or fileName
		local stem = string.match(fileName, "^(.-)%d*%.[^.]*$") or fileName

		if stem == "" or #stem < 3 then
			return
		end

		if type(paths) ~= "table" then
			paths = listRootFiles()

			if not paths then
				return
			end
		end

		for _, path in ipairs(paths) do
			if string.sub(string.match(path, "([^/\\]+)$") or path, 1, #stem) == stem then
				pcall(delfile, path)
			end
		end
	end

	local function findLoadstringUpvalue(fn)
		if type(debug) ~= "table" or type(debug.getupvalues) ~= "function" then
			return nil
		end

		local ok, result = pcall(debug.getupvalues, fn)

		if not ok or type(result) ~= "table" then
			return nil
		end

		for _, upvalue in pairs(result) do
			if type(upvalue) ~= "function" or upvalue == fn then
				continue
			end

			local compiledOk, compiled = pcall(upvalue, "return 1")

			if compiledOk and type(compiled) == "function" then
				local ranOk, ranResult = pcall(compiled)

				if ranOk and ranResult == 1 then
					return upvalue
				end
			end
		end

		return nil
	end

	local loadstringFn = rawget(getgenv(), "loadstring")

	if type(loadstringFn) ~= "function" then
		loadstringFn = loadstring
	end

	local dumpCheckRan, dumpHookFound, dumpFile, rootFiles = pcall(function(candidate)
		local cannotCheck = type(candidate) ~= "function"

		if not cannotCheck then
			local readfileType = type(readfile)
			cannotCheck = readfileType ~= "function"
		end

		if cannotCheck then
			return false
		end

		local filesBefore = listRootFiles()

		if not filesBefore then
			return false
		end

		local existedBefore = {}

		for _, file in ipairs(filesBefore) do
			existedBefore[file] = true
		end

		local bait = "TSNBAIT" .. tostring(math.random(1, 1e9)) .. tostring({}):gsub("%W", "")
		pcall(candidate, "--[[" .. bait .. string.rep("A", 65536) .. "]] return 1")
		local filesAfter = listRootFiles()

		if not filesAfter then
			return false
		end

		local newFiles = {}
		local suspectFiles = {}

		for _, file in ipairs(filesAfter) do
			if not existedBefore[file] then
				newFiles[#newFiles + 1] = file
			elseif type(file) == "string" then
				local lower = string.lower(file)

				if string.find(lower, "loadstring", 1, true) or string.find(lower, "dump", 1, true) then
					suspectFiles[#suspectFiles + 1] = file
				end
			end
		end

		local canDelete = type(delfile) == "function"

		for _, paths in ipairs({newFiles, suspectFiles}) do
			for _, path in ipairs(paths) do
				local ok, result = pcall(readfile, path)

				if ok and type(result) == "string" and string.find(result, bait, 1, true) then
					if canDelete then
						pcall(delfile, path)
					end

					return true, path, filesAfter
				end
			end
		end

		return false
	end, loadstringFn)
	local dumpHooked = dumpCheckRan and dumpHookFound
	local realLoadstring = nil

	if dumpHooked then
		realLoadstring = findLoadstringUpvalue(loadstringFn)

		if not realLoadstring then
			pcall(deleteLookalikeFiles, dumpFile, rootFiles)

			getgenv().__TensenLS = function()
				return nil
			end

			punish("hard", "loadstring dump hook")
			return
		end
	end

	getgenv().__TensenLS = realLoadstring or getgenv().__TensenLS or loadstringFn

	local function globalToolMarkers()
		local found = {}

		if rawget(getgenv(), "SimpleSpyExecuted") == true then
			found[#found + 1] = "SimpleSpy (Beta/V3)"
		end

		if rawget(getgenv(), "IY_LOADED") == true then
			found[#found + 1] = "Infinite Yield"
		end

		if rawget(getgenv(), "CobaltInitialized") == true or type(rawget(getgenv(), "Cobalt")) == "table" then
			found[#found + 1] = "Cobalt"
		end

		return found
	end

	local function toolFromGuiText(instance)
		local name = instance.Name

		if instance:IsA("TextLabel") or instance:IsA("TextButton") or instance:IsA("TextBox") then
			name ..= " " .. instance.Text
		end

		local name = string.lower(name)

		for _, pattern in ipairs(TOOL_NAME_PATTERNS) do
			if string.find(name, pattern[1], 1, true) then
				return pattern[2]
			end
		end

		return nil
	end

	local toolsFound = scanForTools(nil, 6)
	local foundSeverity, foundList = classifyTools(toolsFound)

	if foundSeverity then
		punish(foundSeverity, foundList)
		return
	end

	local function watchGuiRoot(getRoot)
		local rootOk, rootGui = pcall(getRoot)

		if not rootOk or typeof(rootGui) ~= "Instance" then
			return
		end

		pcall(function()
			rootGui.DescendantAdded:Connect(function(descendant)
				pcall(function()
					local toolName = toolFromGuiText(descendant)

					if toolName then
						local severity, names = classifyTools({toolName})

						if severity then
							punish(severity, names)
						end

						return
					end

					local name = descendant.Name

					if name:sub(1, 5) == "_DPP_" or name == "ExplorerItems" then
						task.delay(1, function()
							local severity, names = classifyTools(scanForTools(descendant))

							if severity then
								punish(severity, names)
							end
						end)
					end
				end)
			end)
		end)
	end

	local function getCoreGui()
		return game:GetService("CoreGui")
	end

	watchGuiRoot(getCoreGui)

	if type(gethui) == "function" then
		watchGuiRoot(gethui)
	end

	task.spawn(function()
		while task.wait(15) do
			local severity, names = classifyTools(globalToolMarkers())

			if severity then
				punish(severity, names)
				break
			end
		end
	end)

	local hashEntry = {
		"getscripthash",
		function()
			return getscripthash
		end
	}

	local dumpEntry = {
		"dumpstring",
		function()
			return dumpstring
		end
	}

	for _, entry in ipairs({
		{
			"getsenv",
			function()
				return getsenv
			end
		},
		{
			"getscriptclosure",
			function()
				return getscriptclosure
			end
		},
		{
			"getscriptbytecode",
			function()
				return getscriptbytecode
			end
		},
		hashEntry,
		dumpEntry,
		{
			"decompile",
			function()
				return decompile
			end
		},
		{
			"saveinstance",
			function()
				return saveinstance
			end
		},
		{
			"getreg",
			function()
				return getreg
			end
		}
	}) do
		installTripwire(entry[1], entry[2], "hard")
	end

	local getgc_ = installTripwire("getgc", function()
		return getgc
	end, "soft")

	if getgc_ then
		getgenv().__TensenGC = getgc_
	end

	task.delay(0, function()
		local writefile_ = guardFileWrite("writefile", function()
			return writefile
		end)

		if writefile_ then
			getgenv().__TensenWF = writefile_
		end

		local function getAppendfile()
			return appendfile
		end

		if false then -- never runs
			guardFileWrite("appendfile", getAppendfile)
		end
	end)

	task.spawn(function()
		while true do
			local folderOk, isFolder = pcall(function()
				return type(isfolder) == "function" and isfolder(HUB_FOLDER)
			end)

			if folderOk and isFolder then
				pcall(purgeInvalidFiles, HUB_FOLDER)
			end

			task.wait(20)
		end
	end)

	if hooksUsable then
		task.delay(30, function()
			local getprotoEntry = {
				"debug.getproto",
				function()
					return debug and debug.getproto
				end
			}

			for _, entry in ipairs({
				{
					"debug.getupvalue",
					function()
						return debug and debug.getupvalue
					end
				},
				{
					"debug.getupvalues",
					function()
						return debug and debug.getupvalues
					end
				},
				{
					"debug.setupvalue",
					function()
						return debug and debug.setupvalue
					end
				},
				getprotoEntry,
				{
					"debug.getprotos",
					function()
						return debug and debug.getprotos
					end
				},
				{
					"debug.getconstant",
					function()
						return debug and debug.getconstant
					end
				},
				{
					"debug.getconstants",
					function()
						return debug and debug.getconstants
					end
				},
				{
					"debug.setconstant",
					function()
						return debug and debug.setconstant
					end
				}
			}) do
				guardDebugFunction(entry[1], entry[2])
			end
		end)
	end

	if hooksUsable then
		task.spawn(function()
			while task.wait(11) do
				if punished then
					break
				end

				local missing = nil

				for k, getter in pairs(installedHooks) do
					local getOk, current = pcall(getter)

					if not getOk or type(current) ~= "function" then
						missing = k
						break
					end

					local probeOk, reply = pcall(current, PROBE)

					if not probeOk or reply ~= PROBE_REPLY then
						missing = k
						break
					end

					missing = nil
				end

				if missing then
					punish("hard", "trap removed (" .. missing .. ")")
					break
				end
			end
		end)
	end

	keyState = (guardKey + 1755475248) % 4294967296
end

-- wait for the game
repeat
	task.wait()
until game:IsLoaded()

-- reads the executor name, nothing uses it
if getexecutorname then
	getexecutorname()
end

-- big mom module
do
	local function noop() end
	guardNoop = noop
	hubLog = noop -- logging is off

	local function initBigMom()
		local bigMomLog
		local ReplicatedStorage, RunService, VirtualInputManager, Workspace, getCharacter, stopAttach, stopTween

		do
			bigMomLog = noop

			if not getgenv().TensenHubBigMom then
				getgenv().EnableBigMom = true
				getgenv().WeaponType = "Sword"
				getgenv().HitWait = 0.4
				getgenv().Buso = true
				getgenv().TweenSpeed = 60
				getgenv().AutoStoreFruit = true
				getgenv().BigMomPlaceId = 0
			end

			getCharacter = nil
			stopTween = nil
			stopAttach = nil
			getgenv().IgnoredNPC = true

			repeat
				wait(1)
			until game:IsLoaded()

			ReplicatedStorage = game:GetService("ReplicatedStorage")
			local crabStrangler = ReplicatedStorage:FindFirstChild("Crab_Strangler")

			if crabStrangler then
				crabStrangler:Destroy()
			end

			Workspace = game:GetService("Workspace")
			RunService = game:GetService("RunService")
			VirtualInputManager = cloneref(Instance.new("VirtualInputManager"))
		end

		local Players = game:GetService("Players")
		local localPlayer = Players.LocalPlayer
		localPlayer:WaitForChild("PlayerGui")
		localPlayer:WaitForChild("Backpack")
		local character2 = localPlayer.Character
		local character5

		if character2 then
			character5 = character2
		else
			local newCharacter = localPlayer.CharacterAdded:Wait()
			character5 = newCharacter
		end

		local child2 = character5:WaitForChild("HumanoidRootPart")
		local humanoid = character5:WaitForChild("Humanoid")
		local npCs = Workspace:WaitForChild("NPCs")
		getgenv().BigMomDebug = false
		local function bmLog() end
		getgenv().BigMomPrint = bigMomLog
		local bmLog18 = bmLog
		getgenv().BM_Gen = (getgenv().BM_Gen or 0) + 1
		local bmGen = getgenv().BM_Gen

		local function bmStale()
			return getgenv().BM_Gen ~= bmGen
		end

		getgenv().bmStale = bmStale

		if getgenv().releaseFirebreathMovement then
			getgenv().releaseFirebreathMovement()
		end

		do
			local humanoidRootPart2 = nil
			local anchored2 = nil

			getgenv().releaseFirebreathMovement = function()
				if humanoidRootPart2 and humanoidRootPart2.Parent then
					humanoidRootPart2.AssemblyLinearVelocity = Vector3.zero
					humanoidRootPart2.AssemblyAngularVelocity = Vector3.zero
					humanoidRootPart2.Anchored = anchored2
				end

				humanoidRootPart2 = nil
				anchored2 = nil
			end

			local releaseFirebreathMovement = getgenv().releaseFirebreathMovement

			getgenv().firebreathMovementHeld = function()
				local character = localPlayer.Character
				local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
				local holdingBlock = getgenv().BreathBlocking == true or getgenv().ReactBlockPin == true

				if not getgenv().EnableBigMom or getgenv().ReplayRunning or not holdingBlock or not humanoidRootPart then
					releaseFirebreathMovement()
					return false
				end

				if humanoidRootPart2 ~= humanoidRootPart then
					releaseFirebreathMovement()
					local anchored = humanoidRootPart.Anchored
					humanoidRootPart2 = humanoidRootPart
					anchored2 = anchored
				end

				humanoidRootPart.AssemblyLinearVelocity = Vector3.zero
				humanoidRootPart.AssemblyAngularVelocity = Vector3.zero
				humanoidRootPart.Anchored = true
				return true
			end

			local connection = nil

			connection = RunService.Stepped:Connect(function()
				if bmStale() then
					connection:Disconnect()
					releaseFirebreathMovement()
					return
				end

				getgenv().firebreathMovementHeld()
			end)
		end

		getgenv().ExecutorName = getexecutorname and getexecutorname() or "Unknown Executor"
		getgenv().MobileExecutors = getgenv().MobileExecutors or {"Delta", "Arceus"}

		getgenv().isMobileExecutor = function()
			local executorName = string.lower(tostring(getgenv().ExecutorName or ""))

			if executorName == "" then
				return false
			end

			local mobileExecutors = getgenv().MobileExecutors or {}

			for _, mobileExecutor in ipairs(mobileExecutors) do
				if mobileExecutor ~= "" and string.find(executorName, string.lower(mobileExecutor), 1, true) then
					return true, mobileExecutor
				end
			end

			return false
		end

		getgenv().NormalizeMemoMax = getgenv().NormalizeMemoMax or 4096

		do
			local memo = {}
			local memoSize = 0

			local function clearNormalizeMemo()
				local emptyMemo = {}
				memo = emptyMemo
				memoSize = 0
			end

			getgenv().ClearNormalizeMemo = clearNormalizeMemo

			getgenv().normalizeMoveName = function(moveName)
				local key = tostring(moveName or "")
				local cached = memo[key]

				if cached ~= nil then
					return cached
				end

				local normalized = string.gsub(string.lower(key), "[^a-z0-9]", "")
				local size = memoSize

				if (getgenv().NormalizeMemoMax or 4096) <= size then
					local resetSize = 0
					memo = {}
					memoSize = resetSize
				end

				memo[key] = normalized
				memoSize += 1
				return normalized
			end
		end

		getgenv().ClearMovementForces = function(instance)
			if not instance or not instance.Parent then
				return
			end

			local scriptMoverNames = getgenv().ScriptMoverNames or {}

			for _, child in ipairs(instance:GetChildren()) do
				if (child:IsA("BodyVelocity") or child:IsA("BodyGyro") or child:IsA("BodyThrust") or child:IsA("BodyForce") or child:IsA("LinearVelocity") or child:IsA("AngularVelocity")) and (scriptMoverNames[child.Name] or child.Name == child.ClassName) then
					pcall(function()
						child:Destroy()
					end)
				end
			end
		end

		getgenv().GroundYWatch = getgenv().GroundYWatch ~= false
		getgenv().GroundYRate = getgenv().GroundYRate or 0.1
		getgenv().GroundYMaxAge = getgenv().GroundYMaxAge or 30
		getgenv().GroundYTrust = getgenv().GroundYTrust or 25
		getgenv().GroundYLog = getgenv().GroundYLog ~= false
		getgenv().GroundYStood = nil
		getgenv().GroundYStoodAt = 0
		getgenv().GroundY = nil
		getgenv().GroundYAt = 0

		getgenv().useGroundMemory = function()
			if getgenv().GroundYForce == true then
				return true
			end

			if getgenv().GroundYForce == false then
				return false
			end

			return getgenv().isMobileExecutor() == true
		end

		getgenv().altitudeIsOwned = function()
			return (getgenv().EvadingBoss or getgenv().EvadingKing or getgenv().EvadingUlt or getgenv().EvadingDive or getgenv().EvadingAfterImage or getgenv().LowHealthActive or getgenv().LowHealthAnchored or getgenv().PerchedOnBarrier or getgenv().PerchEngaging or getgenv().BarrierFlightActive or getgenv().ReplayRunning) == true
		end

		getgenv().rememberedGroundY = function()
			local now = tick()
			local groundYMaxAge = getgenv().GroundYMaxAge or 30

			if getgenv().GroundYStood and now - (getgenv().GroundYStoodAt or 0) <= groundYMaxAge then
				return getgenv().GroundYStood, "the floor it last stood on"
			end

			if getgenv().GroundY and now - (getgenv().GroundYAt or 0) <= groundYMaxAge then
				return getgenv().GroundY, "the altitude it was at before the dodge"
			end

			return nil
		end

		getgenv().MobileGroundY = getgenv().MobileGroundY or 233.6
		local getText, stageKey

		do
			getgenv().MobileGroundLift = getgenv().MobileGroundLift or 10
			getgenv().MobileGroundLog = getgenv().MobileGroundLog ~= false
			getgenv().MobileGroundByStage = getgenv().MobileGroundByStage or {["DRAGON EMPEROR"] = 163.496, KING = 237.196}
			local trustedGroundYs = {["DRAGON EMPEROR"] = {[163] = true}, KING = {}}
			local groundYByStage = {["DRAGON EMPEROR"] = 163.496}
			groundYByStage.KING = 237.196

			for k, trusted in pairs(trustedGroundYs) do
				local current = getgenv().MobileGroundByStage[k]

				if current == nil or trusted[current] then
					getgenv().MobileGroundByStage[k] = groundYByStage[k]
				end
			end

			getgenv().mobileGroundY = function()
				local mobileGroundY = getgenv().MobileGroundY
				local mobileGroundByStage = getgenv().MobileGroundByStage or {}
				local cleanStageName = getgenv().cleanStageName and getgenv().cleanStageName() or nil

				if cleanStageName and mobileGroundByStage[cleanStageName] ~= nil then
					mobileGroundY = mobileGroundByStage[cleanStageName]
				end

				if type(mobileGroundY) ~= "number" then
					return nil
				end

				return mobileGroundY + (getgenv().MobileGroundLift or 10), mobileGroundY, cleanStageName
			end

			getgenv().dodgeGroundY = function(rayY, label)
				if not getgenv().useGroundMemory() then
					return rayY
				end

				local memY, memSource = getgenv().rememberedGroundY()

				if memY == nil then
					local mobileGroundY = getgenv().mobileGroundY
					local mobileY, floorY, stage = mobileGroundY()

					if mobileY == nil then
						return rayY
					end

					if rayY ~= nil and math.abs(rayY - floorY) <= (getgenv().GroundYTrust or 25) then
						return rayY
					end

					local bmLog = getgenv().MobileGroundLog ~= false and getgenv().BMLog

					if bmLog then
						local now = tick()
						local lastMobileGroundLog = getgenv().LastMobileGroundLog
						bmLog = now - (lastMobileGroundLog or 0) >= 2
					end

					if bmLog then
						getgenv().LastMobileGroundLog = tick()
						local bmLog3 = getgenv().BMLog
						label = label or "Dodge"
						local labelText = tostring(label)
						local rayText = rayY == nil and "nothing at all" or string.format("Y %d", math.floor(rayY))
						local stageText = tostring(stage or "?")
						local floorYInt = math.floor(floorY)
						local mobileGroundLift = math.floor(getgenv().MobileGroundLift or 10)
						bmLog3(string.format("[Ground] %s: no remembered floor and the ray says %s - using the known '%s' floor Y %d + %d = Y %d (%s).", labelText, rayText, stageText, floorYInt, mobileGroundLift, math.floor(mobileY), tostring(getgenv().ExecutorName)))
					end

					return mobileY
				end

				local nearMemory = rayY ~= nil and math.abs(rayY - memY) <= (getgenv().GroundYTrust or 25)

				if nearMemory then
					return rayY
				end

				local bmLog = getgenv().GroundYLog ~= false and getgenv().BMLog

				if bmLog then
					local elapsed = tick() - (getgenv().LastGroundYLog or 0)
					bmLog = elapsed >= 2
				end

				if bmLog then
					getgenv().LastGroundYLog = tick()
					local bmLog3 = getgenv().BMLog
					local labelStr = tostring(label or "Dodge")
					local rayNothing = rayY == nil and "nothing at all"
					local rayText

					rayText = rayNothing or string.format("Y %d", math.floor(rayY))

					local memYInt = math.floor(memY)
					local memText = tostring(memSource)
					local executorName = getgenv().ExecutorName
					bmLog3(string.format("[Ground] %s: the floor ray says %s, which is not where we were - coming back to Y %d instead (%s, %s).", labelStr, rayText, memYInt, memText, tostring(executorName)))
				end

				return memY
			end

			task.spawn(function()
				while task.wait(getgenv().GroundYRate or 0.1) do
					if bmStale() then
						break
					end

					if not (getgenv().GroundYWatch ~= false and getgenv().EnableBigMom and not getgenv().altitudeIsOwned()) then
						continue
					end

					local character = localPlayer.Character
					local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")

					if not (humanoidRootPart and humanoid and not (humanoid.Health <= 0) and not (getgenv().isCharacterDowned and getgenv().isCharacterDowned(character))) then
						continue
					end

					local y = humanoidRootPart.Position.Y
					local now = tick()
					getgenv().GroundY = y
					getgenv().GroundYAt = now
					local floorMaterial = nil

					pcall(function()
						floorMaterial = humanoid.FloorMaterial
					end)

					if floorMaterial and floorMaterial ~= Enum.Material.Air then
						local now3 = tick()
						getgenv().GroundYStood = y
						getgenv().GroundYStoodAt = now3
					end
				end
			end)

			local landTimeout = getgenv().LandTimeout
			getgenv().LandTimeout = landTimeout or 3
			getgenv().LandRate = getgenv().LandRate or 0.05
			getgenv().LandDrop = getgenv().LandDrop or 3

			getgenv().LandOnGround = function(reason)
				local character = localPlayer.Character
				local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
				local child = character and character:FindFirstChildOfClass("Humanoid")

				if not humanoidRootPart or not child then
					return false
				end

				pcall(stopTween)

				if stopAttach then
					pcall(stopAttach)
				end

				if getgenv().ClearMovementForces then
					getgenv().ClearMovementForces(humanoidRootPart)
				end

				pcall(function()
					child.PlatformStand = false
					child.AutoRotate = true
					local canMove = not getgenv().firebreathMovementHeld()

					if canMove then
						humanoidRootPart.Anchored = false
					end
				end)
				local nonBarrierGroundY = nil

				if getgenv().FindNonBarrierGroundY then
					nonBarrierGroundY = getgenv().FindNonBarrierGroundY(humanoidRootPart.Position)
				end

				local groundY = getgenv().dodgeGroundY(nonBarrierGroundY, "Land")

				if groundY then
					pcall(function()
						if not getgenv().firebreathMovementHeld() then
							humanoidRootPart.CFrame = CFrame.new(humanoidRootPart.Position.X, groundY + (getgenv().LandDrop or 3), humanoidRootPart.Position.Z) * humanoidRootPart.CFrame.Rotation
						end

						humanoidRootPart.AssemblyLinearVelocity = Vector3.zero
						humanoidRootPart.AssemblyAngularVelocity = Vector3.zero
					end)
				end

				local now = tick()
				local touched = false

				while tick() - now < (getgenv().LandTimeout or 3) do
					task.wait(getgenv().LandRate or 0.05)
					local character = localPlayer.Character
					humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
					child = character and character:FindFirstChildOfClass("Humanoid")

					if not humanoidRootPart or not child then
						return false
					end

					if child.PlatformStand then
						child.PlatformStand = false
					end

					if not getgenv().firebreathMovementHeld() and humanoidRootPart.Anchored then
						humanoidRootPart.Anchored = false
					end

					if getgenv().ClearMovementForces then
						getgenv().ClearMovementForces(humanoidRootPart)
					end

					local floorMaterial = nil

					pcall(function()
						floorMaterial = child.FloorMaterial
					end)

					if floorMaterial and floorMaterial ~= Enum.Material.Air then
						touched = true
						break
					end
				end

				if getgenv().BMLog then
					if touched then
						local bmLog = getgenv().BMLog
						local y = math.floor(humanoidRootPart.Position.Y)
						local elapsed = tick() - now
						reason = reason or "landing"
						bmLog(string.format("[Ground] Touching the floor at Y %d after %.2fs (%s) - safe to use a tool now.", y, elapsed, tostring(reason)))
					else
						getgenv().BMLog(string.format("[Ground] Still not touching the floor after %.1fs (Y %d, %s) - carrying on anyway.", getgenv().LandTimeout or 3, math.floor(humanoidRootPart.Position.Y), tostring(reason or "landing")))
					end
				end

				return touched
			end

			local function getStageName()
				local playerGui = game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui")
				local child = playerGui and playerGui:FindFirstChild(getgenv().ObjectivesGui or "KaidoObjectives")
				local child = child and child:FindFirstChild("Main")
				return child and child:FindFirstChild("StageName")
			end

			task.spawn(function()
				while wait(0.1) do
					if bmStale() then
						break
					end

					local playerScripts = localPlayer:FindFirstChild("PlayerScripts")
					local ragdolls = playerScripts and playerScripts:FindFirstChild("Ragdolls")
					local ragdollClient = ragdolls and ragdolls:FindFirstChild("Ragdoll_Client")

					if ragdollClient then
						ragdollClient:Destroy()
					end
				end
			end)

			task.spawn(function()
				local connection

				connection = game:GetService("RunService").Heartbeat:Connect(function()
					local stale = bmStale()

					if stale then
						if connection then
							connection:Disconnect()
							connection = nil
						end

						return
					end

					if not getgenv().EnableBigMom then
						return
					end

					local character = localPlayer.Character
					local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")

					if not humanoidRootPart then
						return
					end

					local isCharacterDowned = getgenv().isCharacterDowned

					if isCharacterDowned and isCharacterDowned(character) then
						pcall(function()
							humanoidRootPart.AssemblyLinearVelocity = Vector3.zero
							humanoidRootPart.AssemblyAngularVelocity = Vector3.zero
						end)

						for _, child in ipairs(humanoidRootPart:GetChildren()) do
							if child:IsA("BodyVelocity") or child:IsA("BodyThrust") or child:IsA("BodyForce") then
								pcall(function()
									child.Velocity = Vector3.zero
								end)

								pcall(function()
									if false then -- never runs
										child.Force = Vector3.zero
									end
								end)
								continue
							end

							if not child:IsA("LinearVelocity") then
								continue
							end

							pcall(function()
								if false then -- never runs
									child.VectorVelocity = Vector3.zero
								end
							end)
						end

						return
					end

					local maxVelocity = getgenv().MaxVelocity
					maxVelocity = maxVelocity or math.max((getgenv().TweenSpeed or 60) * 2, 120)

					if humanoidRootPart.AssemblyLinearVelocity.Magnitude > maxVelocity then
						humanoidRootPart.AssemblyLinearVelocity = humanoidRootPart.AssemblyLinearVelocity.Unit * maxVelocity
					end

					local maxAngularVelocity = getgenv().MaxAngularVelocity or 40

					if maxAngularVelocity < humanoidRootPart.AssemblyAngularVelocity.Magnitude then
						humanoidRootPart.AssemblyAngularVelocity = humanoidRootPart.AssemblyAngularVelocity.Unit * maxAngularVelocity
					end
				end)
			end)

			getText = function()
				local stageName = getStageName()
				return stageName and stageName:IsA("TextLabel") and stageName.Text or nil
			end

			getgenv().ObjectivesGui = getgenv().ObjectivesGui or "KaidoObjectives"
			local bigMomStageName = getgenv().BigMomStageName
			getgenv().BigMomStageName = bigMomStageName or "BIG MOM"
		end

		getgenv().BossStageNames = getgenv().BossStageNames or {getgenv().BigMomStageName}

		getgenv().cleanStageName = function(stageName)
			local trimmed = string.gsub(string.gsub(tostring(stageName or getgenv().currentStageName or ""), "^%s+", ""), "%s+$", "")
			return string.upper(trimmed)
		end

		getgenv().isBossStage = function(stageName)
			local cleaned = getgenv().cleanStageName(stageName)

			if cleaned == "" then
				return false
			end

			local bossStageNames = getgenv().BossStageNames or {}

			for _, bossStageName in ipairs(bossStageNames) do
				if cleaned == getgenv().cleanStageName(bossStageName) then
					return true
				end
			end

			return false
		end

		getgenv().isKaidoStage = getgenv().isBossStage

		if getgenv().HitWait == nil then
			getgenv().HitWait = 0.5
		end

		if getgenv().WeaponType == nil then
			getgenv().WeaponType = "Melee"
		end

		if getgenv().TweenSpeed == nil then
			getgenv().TweenSpeed = 60
		end

