			raycastParams.FilterType = Enum.RaycastFilterType.Exclude
			local filterDescendantsInstances = {}
			local character = localPlayer and localPlayer.Character

			if character then
				table.insert(filterDescendantsInstances, character)
			end

			local iterFn, iterState, iterStart = ipairs(ignoreList or {})

			for _, part in iterFn, iterState, iterStart do
				if part then
					table.insert(filterDescendantsInstances, part)
				end
			end

			raycastParams.FilterDescendantsInstances = filterDescendantsInstances
			local rayStart = origin + Vector3.new(0, 2, 0)

			for i = 1, 12 do
				local hit = Workspace:Raycast(rayStart, Vector3.new(0, -3000, 0), raycastParams)

				if not (hit and hit.Instance) then
					return nil
				end

				if not getgenv().isBarrierPart(hit.Instance) then
					return hit.Position.Y, hit.Instance
