			local offset = to - from

			if offset.Magnitude < 0.05 then
				return false
			end

			local raycastParams = RaycastParams.new()
			raycastParams.FilterType = Enum.RaycastFilterType.Exclude
			local filterDescendantsInstances = {}
			local character = localPlayer and localPlayer.Character

			if character then
				table.insert(filterDescendantsInstances, character)
			end

			local ignore = ignoreList or {}

			for _, part in ipairs(ignore) do
				if part then
					table.insert(filterDescendantsInstances, part)
				end
			end

			raycastParams.FilterDescendantsInstances = filterDescendantsInstances
			local rayDir = offset.Unit * (offset.Magnitude + (getgenv().BarrierProbePad or 3))

			for i = 1, 8 do
				local hit = Workspace:Raycast(from, rayDir, raycastParams)

				if not (hit and hit.Instance) then
					return false
				end

				if getgenv().isBarrierPart(hit.Instance) then
					return true, hit.Instance, hit.Position
				end

				table.insert(filterDescendantsInstances, hit.Instance)
				raycastParams.FilterDescendantsInstances = filterDescendantsInstances
			end

			return false
		end

