						bmLog(string.format("[TweenY] %s: standing at Y %.1f, floor ray hit '%s' at Y %.1f -> wants Y %.1f (%+.1f).", labelText, instance.Position.Y, instance2 and instance2:GetFullName() or "?", instance2 and instance2.Position.Y or 0, targetPos.Y, deltaY))
