				local function stunRemovalSuppressed()
					if getgenv().AutoRemoveStun == false then
						return true
					end

					if getgenv().AllowStun == true then
						return true
					end

					return false
				end

				getgenv().stunRemovalSuppressed = stunRemovalSuppressed

				local function onChildAdded(child)
					if not child or child.Name ~= "Stun" then
						return
					end

					if bmStale() or not getgenv().EnableBigMom then
						return
					end

					if stunRemovalSuppressed() then
						return
					end

					pcall(function()
						child:Destroy()
					end)
				end

				local function watchStunChildren(instance)
					if not instance then
						return
					end

					for _, child in ipairs(instance:GetChildren()) do
						onChildAdded(child)
					end

					instance.ChildAdded:Connect(onChildAdded)
				end

				watchStunChildren(localPlayer)
				watchStunChildren(localPlayer.Character)
				local characterAdded = localPlayer.CharacterAdded

				characterAdded.Connect(characterAdded, function(newCharacter)
					walkSpeed = 16
					watchStunChildren(newCharacter)
				end)

				while task.wait(0.1) do
					if bmStale() then
						break
					end

					if stunRemovalSuppressed() then
						continue
					end

					local character = localPlayer.Character

					if not character then
