				for _, part in ipairs(Workspace:GetPartBoundsInRadius(point, 2.6, overlapParams)) do
					local isCharacterPart = false

					if ignoreCharacters then
						local parent = part.Parent
						isCharacterPart = parent ~= nil and (parent:FindFirstChildOfClass("Humanoid") ~= nil or parent.Parent ~= nil and parent.Parent:FindFirstChildOfClass("Humanoid") ~= nil)
					end

					if not isCharacterPart and part.CanCollide and part.Transparency < 1 then
