			local rise = 0
			local vector2 = vector

			while rise < maxRise and spotBlocked(vector2, ignoreList, ignoreCharacters) do
				vector2 += Vector3.new(0, 3, 0)
				rise += 3
			end

			if spotBlocked(vector2, ignoreList, ignoreCharacters) then
