		local function arrowAvoidanceFor(position)
			local now = tick()
			local fresh = now - (arrowCache.at or 0) < (getgenv().ArrowScanRate or 0.1)

			if fresh then
				return arrowCache.vec
			end

			arrowCache.at = now
			local effects = Workspace:FindFirstChild("Effects")

			if not effects then
				arrowCache.vec = Vector3.zero
				return arrowCache.vec
			end

			local arrowPushback = getgenv().ArrowPushback or 30
			local arrowAvoidDist = getgenv().ArrowAvoidDist or 20
			local vector = Vector3.zero
			local vector2 = Vector3.new(position.X, 0, position.Z)

			for _, child in ipairs(effects:GetChildren()) do
				local name = string.lower(child.Name)

				if not ((string.find(name, "arrow", 1, true) or string.find(name, "pillar", 1, true)) and getgenv().effectFromBoss(child)) then
					continue
				end

				local function getPosition()
					local pivot = child:GetPivot()

					if false then -- never runs
						return pivot.Position
					end
				end

				local posOk, pos = pcall(getPosition)

				if not (posOk and pos) then
					continue
				end

				local vector3 = Vector3.new(pos.X, 0, pos.Z)

				if (vector3 - vector2).Magnitude < arrowAvoidDist then
					local vector4 = vector2 - vector3

					if vector4.Magnitude > 0 then
						vector += vector4.Unit * arrowPushback
					else
						vector += Vector3.new(1, 0, 0) * arrowPushback
					end
				end
			end

			arrowCache.vec = vector
			return vector
		end

