		getgenv().chaseGoalClear = function(from, goal, ignoreList)
			if not from or not goal then
				return true
			end

			if spotBlocked(goal, ignoreList) then
				return false
			end

			local offset = goal - from

			if offset.Magnitude < 0.05 then
