		getgenv().PickOpenChaseGoal = function(boss, goal, ignoreList, instance)
			if getgenv().ChaseWallGuard == false then
				return goal
			end

			if not (boss and boss.Parent) or not goal then
				return goal
			end

			local position = boss.Position
			local chaseWallCache = getgenv().ChaseWallCache
			local now = tick()
			local cacheValid = chaseWallCache.boss == boss

			if cacheValid then
				local elapsed = now - (chaseWallCache.at or 0)
				local chaseWallRate = getgenv().ChaseWallRate or 0.15

				cacheValid = elapsed < chaseWallRate
			end

			if cacheValid then
				if chaseWallCache.offset == nil then
					return goal
				end

				return Vector3.new(position.X + chaseWallCache.offset.X, goal.Y, position.Z + chaseWallCache.offset.Z)
			end

			chaseWallCache.boss = boss
			chaseWallCache.at = now
			chaseWallCache.offset = nil

			if getgenv().chaseGoalClear(position, goal, ignoreList) then
				return goal
			end

			if not instance then
				instance = localPlayer.Character

				if instance then
					instance = instance:FindFirstChild("HumanoidRootPart")
				end

				instance = instance and instance.Position or goal
			end

			local vector2 = Vector3.new(goal.X - position.X, 0, goal.Z - position.Z)
			local radius = math.max(vector2.Magnitude, 1)
			local baseAngle = vector2.Magnitude > 0.01 and math.atan2(vector2.Z, vector2.X) or 0

			local samples = math.max(getgenv().ChaseWallSamples or 12, 4)
			local angleStep = 6.283185307179586 / samples
