		getgenv().bossWallScan = function(origin, ignoreList)
			local once = "max"
			local samples = math.max(getgenv().LureSamples or 12, 4)
			local lureProbe, lureWallNear

			repeat
				lureProbe = getgenv().LureProbe or 70
				lureWallNear = getgenv().LureWallNear
			until once

			lureWallNear = lureWallNear or 14
			local raycastParams = RaycastParams.new()
			raycastParams.FilterType = Enum.RaycastFilterType.Exclude
			local filterDescendantsInstances = {}
			ignoreList = ignoreList or {}

			for _, part in ipairs(ignoreList) do
				if part then
					table.insert(filterDescendantsInstances, part)
				end
			end

			raycastParams.FilterDescendantsInstances = filterDescendantsInstances
			local rayStart = origin + Vector3.new(0, 3, 0)
			local blockedSides = 0
			local directions = {}

			for i = 1, samples do
				local angle = (i - 1) * (6.2831853071795862 / samples)
				local vector = Vector3.new(math.cos(angle), 0, math.sin(angle))
				local hit = Workspace:Raycast(rayStart, vector * lureProbe, raycastParams)
				local magnitude = hit and hit.Position and (hit.Position - rayStart).Magnitude or lureProbe

				if magnitude < lureWallNear then
