				local blockedSides, directions = getgenv().bossWallScan(position, ignoreList)
				local cornered = blockedSides >= (getgenv().LureCornerHits or 4)

				if cornered then
					lureState.corneredAt = now
				end

				local releaseCorner = not cornered and now - (lureState.corneredAt or 0) > (getgenv().LureSticky or 1)

				if releaseCorner then
