						getgenv().RecoveryVoidStops = (getgenv().RecoveryVoidStops or 0) + 1
						bmLog18(string.format("[Recovery] Y %d is under the world with a tween running - dropping the tween and letting the watchdog re-fire it from here (x%d).", math.floor(child.Position.Y), getgenv().RecoveryVoidStops))
						setNoclip(false)
