				end
			end

			unit = unit or Vector3.new(0, 0, -1)

			local uprightOk, uprightCF = pcall(function()
				return CFrame.lookAt(from, target, unit)
			end)

			if uprightOk and uprightCF then
				return uprightCF
			end

			return CFrame.new(from, target)
		end

