				local vector = Vector3.new(target.X, from.Y, target.Z)

				if (vector - from).Magnitude < 0.05 then
					return current and CFrame.new(from) * current.Rotation or CFrame.new(from)
				end

				return CFrame.new(from, vector)
			end

			getgenv().chaseAimCFrame = chaseAimCFrame
		end

