			if not (model and model.Parent) then
				return Vector3.zero
			end

			local who = getgenv().m1ShuffleWho(model)

			if not who then
				return Vector3.zero
			end

			local onMochi = who == "him"
			local onJuice = who == "juice"
			local reactionType = type(getgenv().reactionOwnsUs)

			if reactionType == "function" and getgenv().reactionOwnsUs() then
				return Vector3.zero
			end

			local character = localPlayer and localPlayer.Character
			local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
			local humanoidRootPart2 = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart

			if not (humanoidRootPart and humanoidRootPart2 and humanoidRootPart2.Parent) then
				return Vector3.zero
			end

			local vector2 = Vector3.new(humanoidRootPart.Position.X - humanoidRootPart2.Position.X, 0, humanoidRootPart.Position.Z - humanoidRootPart2.Position.Z)
			local magnitude = vector2.Magnitude

			if (getgenv().M1ShuffleRange or 45) < magnitude then
				return Vector3.zero
			end

			local m1ShuffleState = getgenv().M1ShuffleState
			local now = tick()
			local m1ShufflePeriodJuice = onJuice and (getgenv().M1ShufflePeriodJuice or 0.4) or onMochi and (getgenv().M1ShufflePeriodMochi or 0.4) or getgenv().M1ShufflePeriod or 0.4

			if m1ShufflePeriodJuice <= now - (m1ShuffleState.at or 0) then
				m1ShuffleState.at = now
				m1ShuffleState.phase = m1ShuffleState.phase == 1 and -1 or 1
				m1ShuffleState.dir = nil
