		getgenv().ceilingAbove = function(origin, ignoreList)
			local raycastParams = RaycastParams.new()
			raycastParams.FilterType = Enum.RaycastFilterType.Exclude
			local filterDescendantsInstances = {}
			local ignore = ignoreList or {}

			for _, part in ipairs(ignore) do
				if part then
					table.insert(filterDescendantsInstances, part)
				end
			end

			local climbCeilingProbe = getgenv().ClimbCeilingProbe or 80

			for i = 1, 6 do
				raycastParams.FilterDescendantsInstances = filterDescendantsInstances
				local hit = Workspace:Raycast(origin, Vector3.new(0, climbCeilingProbe, 0), raycastParams)

				if not (hit and hit.Instance) then
					return nil
				end

				local instance = hit.Instance

				if instance.CanCollide and instance.Transparency < 1 and not (getgenv().isBarrierPart and getgenv().isBarrierPart(instance)) then
					return hit.Position.Y, instance
				end

				table.insert(filterDescendantsInstances, instance)
				climbCeilingProbe -= hit.Position.Y - origin.Y

				if climbCeilingProbe <= 0 then
					return nil
				end

				origin = hit.Position
			end

			return nil
		end

		getgenv().climbLanding = function(root, hitPos, normal, wall, rayParams, ignoreList, label)
			local wallTopY = wall.Position.Y + wall.Size.Y / 2
			local vector = hitPos + (-normal) * 4
			local maxY = math.max(wallTopY, root.Position.Y) + 60
			local ceilingY = nil
			local ceilingPart = nil

			if getgenv().ClimbIndoorCheck ~= false then
				ceilingY, ceilingPart = getgenv().ceilingAbove(root.Position, ignoreList)
			end

			local y

			if ceilingY then
				if ceilingY - (getgenv().ClimbWallGap or 3) <= wallTopY then
					getgenv().ClimbIndoorHits = (getgenv().ClimbIndoorHits or 0) + 1
					local bmLog = getgenv().ClimbIndoorLog ~= false and getgenv().BMLog and tick() - (getgenv().LastIndoorClimbLog or 0) >= 3

					if not bmLog then
						return nil
					end

					getgenv().LastIndoorClimbLog = tick()
					local bmLog3 = getgenv().BMLog
					local labelText = tostring(label)
					local wallName = tostring(wall.Name)
					local ceilingName = tostring(ceilingPart and ceilingPart.Name)
					bmLog3(string.format("[Tween] %s: '%s' goes up to the ceiling ('%s' at Y %d) - that is a wall, not climbing it onto the roof (x%d).", labelText, wallName, ceilingName, math.floor(ceilingY), getgenv().ClimbIndoorHits))
					return nil
				end

				local climbCeilingPad = getgenv().ClimbCeilingPad
				y = math.min(maxY, ceilingY - (climbCeilingPad or 1))
			else
				y = maxY
			end

			local hit = Workspace:Raycast(Vector3.new(vector.X, y, vector.Z), Vector3.new(0, -400, 0), rayParams)
			local vector2

			if hit and hit.Instance then
				vector2 = Vector3.new(hit.Position.X, hit.Position.Y + 4, hit.Position.Z)
			else
				vector2 = Vector3.new(vector.X, wallTopY + 4, vector.Z)
			end

			local vector3 = getVector(vector2, ignoreList, 30)

			if ceilingY and vector3.Y > ceilingY - 2 then
				local x = vector3.X
				local y2 = math.max(ceilingY - 3, root.Position.Y)
				vector3 = Vector3.new(x, y2, vector3.Z)
			end

			return vector3
		end

