				local values = table.pack(table.unpack(extra, 1, extra.n))
				table.move(values, 1, values.n, 2, oldKingOffsets)
			end

			for _, old in ipairs(oldKingOffsets) do
				if getgenv().KingGroundOffset == old then
					getgenv().KingGroundOffset = nil
				end
			end
		end

		getgenv().KingGroundOffset = getgenv().KingGroundOffset or Vector3.new(0, 11, 0)

		do
			local oldKaidoOffsets = {}
			local first = Vector3.new(0, 2, 0)
			local vector = Vector3.new(0, 10, 0)
			local extra = table.pack(Vector3.new(0, 12, 0))
			oldKaidoOffsets[1] = first
			oldKaidoOffsets[2] = vector

			do
				local values = table.pack(table.unpack(extra, 1, extra.n))
				table.move(values, 1, values.n, 3, oldKaidoOffsets)
			end

			for _, old in ipairs(oldKaidoOffsets) do
				if getgenv().KaidoGroundOffset == old then
					getgenv().KaidoGroundOffset = nil
				end
			end
		end

		getgenv().KaidoGroundOffset = getgenv().KaidoGroundOffset or Vector3.new(0, 13, 0)

		for _, old in ipairs({4}) do
			if getgenv().MobChaseOffsetY == old then
				getgenv().MobChaseOffsetY = nil
			end
		end

		local mobCoverDrop = getgenv().MobCoverDrop ~= false
		getgenv().MobCoverDrop = mobCoverDrop
		getgenv().MobCoverOffset = getgenv().MobCoverOffset or Vector3.new(0, 3, 0)
		getgenv().MobCoverPad = getgenv().MobCoverPad or 4
		getgenv().MobCoverMinReach = getgenv().MobCoverMinReach or 12
		local getInstances, targetKey

		do
			local mobCoverRate = getgenv().MobCoverRate
			getgenv().MobCoverRate = mobCoverRate or 0.2
			getgenv().MobCoverLayers = getgenv().MobCoverLayers or 4
			getgenv().MobCoverSeeThrough = getgenv().MobCoverSeeThrough ~= false
			getgenv().MobCoverAboveMin = getgenv().MobCoverAboveMin or 6
			getgenv().MobCoverHold = getgenv().MobCoverHold or 2
			getgenv().LastMobCoverAt = getgenv().LastMobCoverAt or 0
			local mobCoverRange = getgenv().MobCoverRange or 30

			getgenv().MobCoverRange = mobCoverRange
			getgenv().MobCoverLog = getgenv().MobCoverLog ~= false
			getgenv().MobCoverCache = getgenv().MobCoverCache or setmetatable({}, {__mode = "k"})

			getgenv().ClearMobCoverCache = function()
				getgenv().MobCoverCache = setmetatable({}, {__mode = "k"})
			end

			getgenv().mobUnderCover = function(model, minReach)
				local mobCoverDrop = getgenv().MobCoverDrop

				if mobCoverDrop == false then
					return false
				end

				local parent

				parent = model and model.Parent

				if not parent then
					return false
				end

				local isBossNPC = getgenv().isBossNPC and getgenv().isBossNPC(model)

				if isBossNPC then
					return false
				end

				local humanoidRootPart = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart

				if not (humanoidRootPart and humanoidRootPart.Parent) then
					return false
				end

				local reachNum = tonumber(minReach) or 0
				local mobCoverMinReach = getgenv().MobCoverMinReach
				local reach = math.max(reachNum, mobCoverMinReach or 12) + (getgenv().MobCoverPad or 4)
				local now = tick()
				local cached = getgenv().MobCoverCache[model]

				if cached and cached.reach == reach and now - (cached.at or 0) < (getgenv().MobCoverRate or 0.2) then
					return cached.covered, cached.name
				end

				local rayParams = RaycastParams.new()
				rayParams.FilterType = Enum.RaycastFilterType.Exclude
				local filterDescendantsInstances = {model}
				local character = localPlayer and localPlayer.Character

				if character then
					table.insert(filterDescendantsInstances, character)
				end

				rayParams.FilterDescendantsInstances = filterDescendantsInstances
				local position = humanoidRootPart.Position + Vector3.new(0, 2, 0)
				local mobCoverLayers = getgenv().MobCoverLayers or 4
				local covered = false
				local name = nil

				for i = 1, mobCoverLayers do
					local hit = Workspace:Raycast(position, Vector3.new(0, reach, 0), rayParams)
					local instance = hit and hit.Instance
					name = nil

					if not instance then
						break
					end

					local instance = hit.Instance

					if not (getgenv().isBarrierPart and getgenv().isBarrierPart(instance)) then
						local parent = instance.Parent

						if parent then
							parent = parent:FindFirstChildOfClass("Humanoid") or parent.Parent and parent.Parent:FindFirstChildOfClass("Humanoid")
						end
					end

					table.insert(filterDescendantsInstances, instance)
					rayParams.FilterDescendantsInstances = filterDescendantsInstances
					name = nil
				end

				local mobCoverSeeThrough = getgenv().MobCoverSeeThrough

				if (mobCoverSeeThrough ~= false) and character then
					local humanoidRootPart2 = character:FindFirstChild("HumanoidRootPart")
					local parent = humanoidRootPart2 and humanoidRootPart2.Parent

					if parent then
						local aboveBy = humanoidRootPart2.Position.Y - humanoidRootPart.Position.Y
						local mobCoverAboveMin = getgenv().MobCoverAboveMin or 6

						parent = aboveBy >= mobCoverAboveMin
					end

					if parent then
						local raycastParams = RaycastParams.new()
						raycastParams.FilterType = Enum.RaycastFilterType.Exclude
						local filterDescendantsInstances = {model, character}
						raycastParams.FilterDescendantsInstances = filterDescendantsInstances
						local position = humanoidRootPart.Position - humanoidRootPart2.Position
						local mobCoverLayers = getgenv().MobCoverLayers or 4

						for i = 1, mobCoverLayers do
							local hit = Workspace:Raycast(humanoidRootPart2.Position, position, raycastParams)

							if not (hit and hit.Instance) then
								break
							end

							local instance = hit.Instance
							local parent3 = instance.Parent

							if not (getgenv().isBarrierPart and getgenv().isBarrierPart(instance) or parent3 ~= nil and (parent3:FindFirstChildOfClass("Humanoid") ~= nil or parent3.Parent ~= nil and parent3.Parent:FindFirstChildOfClass("Humanoid") ~= nil)) then
								name = instance.Name
								covered = true
								break
							end

							table.insert(filterDescendantsInstances, instance)
							raycastParams.FilterDescendantsInstances = filterDescendantsInstances
						end
					end
				end

				local mobCoverCache = getgenv().MobCoverCache
				local entry = {}
				entry.at = now
				entry.reach = reach
				entry.covered = covered
				entry.name = name
				mobCoverCache[model] = entry
				return covered, name
			end

			getgenv().MobChaseOffsetY = getgenv().MobChaseOffsetY or 10

			getgenv().mobChaseOffset = function(npc, offset)
				local mobChaseOffsetY = getgenv().MobChaseOffsetY

				if type(mobChaseOffsetY) ~= "number" or not offset then
					return offset
				end

				if npc and getgenv().isBossNPC and getgenv().isBossNPC(npc) then
					return offset
				end

				if offset.Y <= mobChaseOffsetY then
					return offset
				end

				return Vector3.new(offset.X, mobChaseOffsetY, offset.Z)
			end

			getgenv().bossChaseOffset = function(npc, offset)
				if getgenv().isKaidoFight and getgenv().isKaidoFight(npc) then
					return getgenv().KaidoGroundOffset or Vector3.new(0, 13, 0)
				end

				if offset and getgenv().KingUseAirOffset == true then
					return getgenv().KingAirOffset or Vector3.new(0, 11, 0)
				end

				return getgenv().KingGroundOffset or Vector3.new(0, 11, 0)
			end

			getgenv().BossLeadStuds = getgenv().BossLeadStuds or 3
			local bossLeadMinSpeed = getgenv().BossLeadMinSpeed
			local bossLeadMinSpeed3

			bossLeadMinSpeed3 = bossLeadMinSpeed or 6

			getgenv().BossLeadMinSpeed = bossLeadMinSpeed3
			getgenv().BossLeadSample = getgenv().BossLeadSample or 0.1
			getgenv().BossLeadHold = getgenv().BossLeadHold or 0.3
			getgenv().BossLeadKaidoOnly = getgenv().BossLeadKaidoOnly ~= false
			local bossLeadBigMom = getgenv().BossLeadBigMom ~= false
			getgenv().BossLeadBigMom = bossLeadBigMom
			getgenv().BossLeadLog = getgenv().BossLeadLog == true
			getgenv().BossLeadState = getgenv().BossLeadState or {}

			getgenv().bossLeadOffset = function(boss)
				local bossLeadStuds = getgenv().BossLeadStuds

				if type(bossLeadStuds) ~= "number" or bossLeadStuds == 0 then
					return Vector3.zero
				end

				if not (boss and boss.Parent) then
					return Vector3.zero
				end

				if getgenv().BossLeadKaidoOnly ~= false then
					if not (getgenv().isKaidoNPC and getgenv().isKaidoNPC(boss) or getgenv().BossLeadBigMom ~= false and getgenv().isBigMomNPC and getgenv().isBigMomNPC(boss)) then
						return Vector3.zero
					end
				else
					if not (getgenv().isBossNPC and getgenv().isBossNPC(boss)) then
						return Vector3.zero
					end
				end

				local humanoidRootPart = boss:FindFirstChild("HumanoidRootPart") or boss.PrimaryPart

				if not (humanoidRootPart and humanoidRootPart.Parent) then
					return Vector3.zero
				end

				local bossLeadState = getgenv().BossLeadState
				local now = tick()

				if bossLeadState.boss ~= boss then
					bossLeadState.boss = boss
					bossLeadState.dir = nil
					bossLeadState.at = 0
					bossLeadState.pos = humanoidRootPart.Position
					bossLeadState.sampledAt = now
					return Vector3.zero
				end

				local elapsed = now - (bossLeadState.sampledAt or 0)

				if elapsed >= (getgenv().BossLeadSample or 0.1) then
					local position = humanoidRootPart.Position - (bossLeadState.pos or humanoidRootPart.Position)
					local vector = Vector3.new(position.X, 0, position.Z)
					local speed = vector.Magnitude / math.max(elapsed, 0.016666666666666666)
					local bossLeadMinSpeed = getgenv().BossLeadMinSpeed

					if (bossLeadMinSpeed or 6) <= speed then
						bossLeadState.dir = vector.Unit
						bossLeadState.at = now
						bossLeadState.speed = speed
					end

					bossLeadState.pos = humanoidRootPart.Position
					bossLeadState.sampledAt = now
				end

				if not bossLeadState.dir then
					return Vector3.zero
				end

				local elapsed = now - (bossLeadState.at or 0)

				if (getgenv().BossLeadHold or 0.3) < elapsed then
					bossLeadState.dir = nil
					return Vector3.zero
				end

				local bmLog = getgenv().BossLeadLog == true and getgenv().BMLog

				if bmLog then
					local elapsed3 = now - (getgenv().LastLeadLog or 0)
					bmLog = elapsed3 >= 2
				end

				if bmLog then
					getgenv().LastLeadLog = now
					getgenv().BMLog(string.format("[Chase] He is walking at %d studs/s - aiming %d studs ahead of him instead of at him.", math.floor(bossLeadState.speed or 0), math.floor(bossLeadStuds)))
				end

				return bossLeadState.dir * bossLeadStuds
			end

			getgenv().BigMomFocus = getgenv().BigMomFocus ~= false
			getgenv().BigMomExtraReach = getgenv().BigMomExtraReach or 3
			getgenv().BigMomExtraTargets = getgenv().BigMomExtraTargets or nil

			getInstances = function(distance)
				local instances = {}

				if not child2 or not child2.Parent then
					return instances
				end

				distance = distance or getgenv().CombatRange or 55
				local npCs = Workspace:FindFirstChild("NPCs")

				if not npCs then
					return instances
				end

				local position = child2.Position
				local bigMomRoot = nil

				for _, child in ipairs(npCs:GetChildren()) do
					if isIgnoredNPC(child) then
						continue
					end

					local root = npcRoot(child)
					local humanoid = child:FindFirstChildOfClass("Humanoid")

					if root and humanoid and humanoid.Health > 0 and (position - root.Position).Magnitude <= distance then
						table.insert(instances, root)

						if bigMomRoot == nil and getgenv().isBigMomNPC(child) then
							bigMomRoot = root
						end
					end
				end

				table.sort(instances, function(a, b)
					local magnitude = (position - a.Position).Magnitude
					local position2 = b.Position

					if false then -- never runs
						return magnitude < (position - position2).Magnitude
					end
				end)
				local focusBigMom

				focusBigMom = bigMomRoot and getgenv().BigMomFocus ~= false

				if focusBigMom then
					for i, instance in ipairs(instances) do
						if instance == bigMomRoot then
							table.remove(instances, i)
							break
						end
					end

					table.insert(instances, 1, bigMomRoot)
				end

				local bigMomExtraTargets = getgenv().BigMomExtraTargets

				if type(bigMomExtraTargets) ~= "function" then
					return instances
				end

				local ok, result = pcall(bigMomExtraTargets, distance)

				if ok and type(result) == "table" then
					local distance = distance * (getgenv().BigMomExtraReach or 3)

					for _, instance in ipairs(result) do
						if typeof(instance) == "Instance" and instance:IsA("BasePart") and (position - instance.Position).Magnitude <= distance then
							table.insert(instances, instance)
						end
					end
				end

				return instances
			end

			getgenv().getNPCsInRange = getInstances
			getgenv().WeaponEquipWait = getgenv().WeaponEquipWait or 2
			local weaponEquipTries = getgenv().WeaponEquipTries
			getgenv().WeaponEquipTries = weaponEquipTries or 3
			getgenv().WeaponAskRate = getgenv().WeaponAskRate or 1
			getgenv().WeaponEquipFails = getgenv().WeaponEquipFails or 0
			getgenv().WeaponEquips = getgenv().WeaponEquips or 0
			getgenv().LastWeaponAsk = 0
			getgenv().StoringFruit = false
			getgenv().SwordNameCache = getgenv().SwordNameCache or {}
			getgenv().WorldEnderNames = getgenv().WorldEnderNames or {"World Ender", "World Ender 2", "Hollow's World Ender"}

			getgenv().swordNames = function(force)
				local swordNameCache = getgenv().SwordNameCache

				if not force and swordNameCache.names and tick() - (swordNameCache.at or 0) < 15 then
					return swordNameCache.names
				end

				local names = {}

				pcall(function()
					for _, child in ipairs(ReplicatedStorage.Modules.SwordHandle.Swords:GetChildren()) do
						names[child.Name] = true
					end
				end)

				local now = tick()
				swordNameCache.names = names
				swordNameCache.at = now
				return names
			end

			getgenv().isWeaponTool = function(instance)
				if not (instance and instance:IsA("Tool")) then
					return false
				end

				local weaponType = getgenv().WeaponType

				if weaponType == "World Ender" then
					for _, worldEnderName in ipairs(getgenv().WorldEnderNames) do
						if instance.Name == worldEnderName then
							return true
						end
					end

					return false
				end

				if weaponType == "PikaV2" then
					return instance.Name == (getgenv().PikaV2SwordName or "PikaV2-PikaV2")
				end

				if weaponType == "Sword" then
					local swordNames = getgenv().swordNames
					local isSword = swordNames()[instance.Name]
					return isSword == true and instance.Name ~= (getgenv().PikaV2SwordName or "PikaV2-PikaV2")
				end

				local ok, result = pcall(getgenv().fruitNameSet)

				if ok and type(result) == "table" and result[instance.Name] then
					return false
				end

				return true
			end

			getgenv().weaponInHand = function(forCharacter)
				local character = forCharacter or localPlayer.Character

				if not character then
					return nil
				end

				for _, child in ipairs(character:GetChildren()) do
					if getgenv().isWeaponTool(child) then
						return child
					end
				end

				return nil
			end

			getgenv().weaponInBag = function()
				local child = localPlayer:FindFirstChildOfClass("Backpack")

				if not child then
					return nil
				end

				if getgenv().WeaponType == "World Ender" then
					for _, worldEnderName in ipairs(getgenv().WorldEnderNames) do
						local worldEnder = child:FindFirstChild(worldEnderName)

						if worldEnder and worldEnder:IsA("Tool") then
							return worldEnder
						end
					end

					return nil
				end

				for _, child5 in ipairs(child:GetChildren()) do
					if getgenv().isWeaponTool(child5) then
						return child5
					end
				end

				return nil
			end

			getgenv().equipWeapon = function(reason)
				local character = localPlayer.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")

				if not (character and humanoid) or humanoid.Health <= 0 then
					return false
				end

				if getgenv().StoringFruit or getgenv().CarryingReinforcement then
					return false
				end

				local weapon = getgenv().weaponInHand(character)

				if weapon then
					return true, weapon
				end

				local instance = getgenv().weaponInBag()

				if not instance then
					local weaponEquipFails = getgenv().WeaponEquipFails or 0

					getgenv().WeaponEquipFails = weaponEquipFails + 1
					local bmLog = getgenv().BMLog and getgenv().WeaponEquipFails % 20 == 1

					if bmLog then
						getgenv().BMLog(string.format("[Weapon] %s and there is no %s in the bag either (x%d) - nothing to equip.", tostring(reason or "nothing in hand"), tostring(getgenv().WeaponType), getgenv().WeaponEquipFails))
					end

					return false
				end

				if character:FindFirstChildOfClass("Tool") then
					pcall(function()
						if false then -- never runs
							humanoid:UnequipTools()
						end
					end)
					task.wait(0.1)
				end

				local weaponEquipTries = getgenv().WeaponEquipTries or 3

				for i = 1, weaponEquipTries do
					if not (instance and instance.Parent) then
						instance = getgenv().weaponInBag()
					end

					if not instance then
						break
					end

					pcall(function()
						if false then -- never runs
							humanoid:EquipTool(instance)
						end
					end)
					local deadline = tick() + (getgenv().WeaponEquipWait or 2)

					repeat
						task.wait(0.05)
					until not (not (getgenv().weaponInHand() or tick() >= deadline or bmStale()) and getgenv().EnableBigMom)

					local weapon = getgenv().weaponInHand()

					if weapon then
						getgenv().WeaponEquips = (getgenv().WeaponEquips or 0) + 1

						if getgenv().BMLog and (i > 1 or getgenv().WeaponEquips % 10 == 1) then
							getgenv().BMLog(string.format("[Weapon] '%s' is in hand for %s (try %d, x%d).", weapon.Name, tostring(reason or "the fight"), i, getgenv().WeaponEquips))
						end

						return true, weapon
					end

					if bmStale() or not getgenv().EnableBigMom then
						break
					end
				end

				local weaponEquipFails = getgenv().WeaponEquipFails
				local weaponEquipFails2

				weaponEquipFails2 = weaponEquipFails or 0

				getgenv().WeaponEquipFails = weaponEquipFails2 + 1

				if getgenv().BMLog then
					getgenv().BMLog(string.format("[Weapon] '%s' would not go into our hands for %s after %d tries (x%d) - the combat loops will not swing without it.", instance and instance.Name or "?", tostring(reason or "the fight"), getgenv().WeaponEquipTries or 3, getgenv().WeaponEquipFails))
				end

				return false
			end

			getgenv().askWeaponEquip = function(reason)
				if getgenv().AutoEquipWeapon == false then
					return false
				end

				if tick() - (getgenv().LastWeaponAsk or 0) < (getgenv().WeaponAskRate or 1) then
					return false
				end

				getgenv().LastWeaponAsk = tick()
				local equipped, weapon = getgenv().equipWeapon(reason)
				getgenv().LastWeaponAsk = tick()
				return equipped, weapon
			end

			local function forceEquip()
				return getgenv().equipWeapon("ForceEquipTool")
			end

			if getgenv().AutoStoreFruit == nil then
				getgenv().AutoStoreFruit = true
			end

			getgenv().AutoStoreRate = getgenv().AutoStoreRate or 5
			getgenv().AutoStoreMaxRetry = getgenv().AutoStoreMaxRetry or 5
			getgenv().FruitStoreRetry = getgenv().FruitStoreRetry or 0
			local autoStoreExtraNames = getgenv().AutoStoreExtraNames
			local autoStoreExtraNames3

			autoStoreExtraNames3 = autoStoreExtraNames or {"Dragon", "Soul", "Bari", "Spin", "Tori"}

			getgenv().AutoStoreExtraNames = autoStoreExtraNames3

			getgenv().UnequipTool = function()
				local character = getCharacter()
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")

				if humanoid then
					pcall(function()
						humanoid:UnequipTools()
					end)
				end
			end

			getgenv().FruitCallbackFolder = getgenv().FruitCallbackFolder or "SkillCallbacks"
			local fruitCallbackChild = getgenv().FruitCallbackChild or "DevilFruit"

			getgenv().FruitCallbackChild = fruitCallbackChild
			getgenv().FruitNameRescan = getgenv().FruitNameRescan or 30
			getgenv().FruitNameCache = getgenv().FruitNameCache or {}

			getgenv().fruitFrontName = function(fullName)
				local text = tostring(fullName or "")
				local front = string.gsub(string.gsub(string.match(text, "^([^-]+)") or text, "^%s+", ""), "%s+$", "")

				if front == "" then
					return nil
				end

				return front
			end

			getgenv().listFruitNames = function(force)
				local fruitNameCache = getgenv().FruitNameCache
				local now = tick()
				local names = not force and fruitNameCache.names and now - (fruitNameCache.at or 0) < (getgenv().FruitNameRescan or 30)

				if names then
					return fruitNameCache.names
				end

				local names = {}
				local seen = {}

				pcall(function()
					local child = ReplicatedStorage:FindFirstChild(getgenv().FruitCallbackFolder or "SkillCallbacks")
					child = child and child:FindFirstChild(getgenv().FruitCallbackChild or "DevilFruit")

					if not child then
						return
					end

					for _, child5 in ipairs(child:GetChildren()) do
						local front = getgenv().fruitFrontName(child5.Name)

						if front and not seen[front] then
							seen[front] = true
							table.insert(names, front)
						end
					end
				end)
				fruitNameCache.names = names
				fruitNameCache.at = now

				if getgenv().FruitNameLog ~= false and getgenv().BMLog and #names ~= (fruitNameCache.logged or -1) then
					fruitNameCache.logged = #names
					getgenv().BMLog(string.format("[Fruit] %d fruit names read off %s.%s (front half only, e.g. 'Dragon-Dragon' -> 'Dragon').", #names, tostring(getgenv().FruitCallbackFolder or "SkillCallbacks"), tostring(getgenv().FruitCallbackChild or "DevilFruit")))
				end

				return names
			end

			getgenv().FruitNameSetCache = getgenv().FruitNameSetCache or {}

			getgenv().fruitNameSet = function()
				local fruitNameSetCache = getgenv().FruitNameSetCache
				local now = tick()

				if fruitNameSetCache.set and now - (fruitNameSetCache.at or 0) < (getgenv().FruitNameRescan or 30) then
					return fruitNameSetCache.set
				end

				local set = {}
				local fruitNames = getgenv().listFruitNames() or {}

				for _, fruitName in ipairs(fruitNames) do
					if fruitName and fruitName ~= "" then
						set[fruitName] = "SkillCallbacks.DevilFruit"
					end
				end

				pcall(function()
					local child = ReplicatedStorage:FindFirstChild("Effects")
					child = child and child:FindFirstChild("DevilFruits")

