						end
					end
				end)

				local autoStoreExtraNames = getgenv().AutoStoreExtraNames or {}

				for _, autoStoreExtraName in ipairs(autoStoreExtraNames) do
					if autoStoreExtraName and autoStoreExtraName ~= "" and not set[autoStoreExtraName] then
