					end
				end

				fruitNameSetCache.set = set
				fruitNameSetCache.at = now
				return set
			end

			getgenv().FruitStoreFailMax = getgenv().FruitStoreFailMax or 5
			getgenv().FruitStoreFails = getgenv().FruitStoreFails or setmetatable({}, {__mode = "k"})

