				getgenv().FruitStoreFails = setmetatable({}, {__mode = "k"})
			end

			getgenv().fruitStoreGaveUp = function(tool)
				if not tool then
					return false
				end

				return (getgenv().FruitStoreFails[tool] or 0) >= (getgenv().FruitStoreFailMax or 5)
			end

			getgenv().noteFruitStoreFail = function(tool)
				if not tool then
					return 0
				end

				local fruitStoreFail = (getgenv().FruitStoreFails[tool] or 0) + 1
				getgenv().FruitStoreFails[tool] = fruitStoreFail
				local fruitStoreFailMax = getgenv().FruitStoreFailMax or 5

				if fruitStoreFail == fruitStoreFailMax then
					getgenv().BMLog(string.format("[Fruit] '%s' did not go into storage after %d tries (already owned, or storage is full) - leaving it in the bag for the rest of the run.", tool.Name, fruitStoreFail))
				elseif fruitStoreFail < fruitStoreFailMax then
					getgenv().BMLog(string.format("[Fruit] '%s' is still in the bag after the store call (try %d/%d).", tool.Name, fruitStoreFail, fruitStoreFailMax))
				end

				return fruitStoreFail
			end

			getgenv().findFruitTool = function()
				local character = getCharacter()
				local backpack = localPlayer:FindFirstChildOfClass("Backpack")

				if not character or not backpack then
					return nil
				end

				local fruitNames = getgenv().fruitNameSet()
				local fruitStoreGaveUp = getgenv().fruitStoreGaveUp

				for _, child in ipairs(character:GetChildren()) do
					if child:IsA("Tool") and fruitNames[child.Name] and not fruitStoreGaveUp(child) then
						if getgenv().RecordFruitTool then
							getgenv().RecordFruitTool(child.Name)
						end

						return child, fruitNames[child.Name]
					end
				end

				for _, child in ipairs(backpack:GetChildren()) do
					if child:IsA("Tool") and fruitNames[child.Name] and not fruitStoreGaveUp(child) then
						if getgenv().RecordFruitTool then
							getgenv().RecordFruitTool(child.Name)
						end

						return child, fruitNames[child.Name]
					end
				end

				return nil
			end

			getgenv().AutoStore = function()
				local character = getCharacter()

				if not character then
