					local child = character:FindFirstChildOfClass("Humanoid")

					if not child then
						return false
					end

					getgenv().BMLog(string.format("[Fruit] '%s' found (%s) - storing it.", fruitTool.Name, tostring(fruitName)))

					pcall(function()
