					task.wait(0.5)

					local storeOk, storeErr = pcall(function()
						ReplicatedStorage.Events.FruitStorage:InvokeServer(true)
					end)
					task.wait(0.3)

					pcall(function()
						child:UnequipTools()
					end)
					task.wait(0.2)
					local backpack = localPlayer:FindFirstChildOfClass("Backpack")
					local parent = fruitTool.Parent

					if storeOk and not (parent ~= nil and (parent == character or backpack ~= nil and parent == backpack)) then
						getgenv().BMLog(string.format("[Fruit] Stored '%s'.", fruitTool.Name))
						getgenv().FruitStoreFails[fruitTool] = nil

						if getgenv().RecordFruitTool then
