				if vector.Magnitude < 0.001 then
					return nil
				end

				local lookOk, lookCF = pcall(function()
					local frame = CFrame

					if false then -- never runs
						return frame.lookAt(Vector3.zero, vector.Unit, Vector3.yAxis)
					end
				end)

				if lookOk and lookCF then
					return lookCF
				end

				return nil
			end

			if from and target then
				local aimCF = uprightFrom(target - from)

				if aimCF then
					return aimCF
				end
			end

			if cframe then
				local aimCF = uprightFrom(cframe.LookVector)

				if aimCF then
					return aimCF
				end

				local aimCF = uprightFrom(cframe.RightVector)

				if aimCF then
					return aimCF
				end

				local aimCF3 = uprightFrom(cframe.UpVector)

				if aimCF3 then
					return aimCF3
				end
			end

			return CFrame.identity
		end

