			local animation = track and track.Animation

			if not animation then
				return
			end

			local animId = tostring(animation.AnimationId or "?")
			local now = tick()
			getgenv().BigMomAnimNames[animId] = getgenv().BigMomAnimNames[animId] or tostring(animation.Name or "?")
			local bigMomAnimPlays = getgenv().BigMomAnimPlays
			local bigMomAnimPlay = getgenv().BigMomAnimPlays[animId]
			local bigMomAnimPlay2

			bigMomAnimPlay2 = bigMomAnimPlay or 0

			bigMomAnimPlays[animId] = bigMomAnimPlay2 + 1
			table.insert(getgenv().BigMomAnimRecent, {id = animId, at = now})

			while #getgenv().BigMomAnimRecent > 0 and now - getgenv().BigMomAnimRecent[1].at > (getgenv().BigMomAnimWindow or 2.5) * 2 do
				table.remove(getgenv().BigMomAnimRecent, 1)
			end

			local bigMomAnimLog = getgenv().BigMomAnimLog
			local entry = {id = animId, name = animation.Name, at = now}

			local function getLength()
				return track.Length
			end

			entry.len = pcall(getLength) and track.Length or nil
			table.insert(bigMomAnimLog, entry)

			while #bigMomAnimLog > 300 do
				table.remove(bigMomAnimLog, 1)
			end
		end

