			local iterFn, iterState, iterStart = ipairs(getgenv().BigMomAnimRecent or {})
			local credited = 0

			for _, recent in iterFn, iterState, iterStart do
				local animDigits = getgenv().animDigits and getgenv().animDigits(recent.id) or nil
				local isAmbientAnim = getgenv().isAmbientAnim and getgenv().isAmbientAnim(recent.id) or false or animDigits ~= nil and (getgenv().AnimNeverAttack or {})[animDigits] == true

				if not (now - recent.at <= bigMomAnimWindow and not isAmbientAnim) then
					continue
				end

				local hurt = getgenv().BigMomAnimHurt[recent.id] or {hits = 0, damage = 0}
				hurt.hits += 1
				hurt.damage += damage
				getgenv().BigMomAnimHurt[recent.id] = hurt
				credited += 1

				if not (animDigits and getgenv().flatToBoss) then
					continue
				end

				local max = getgenv().flatToBoss()

				if not max then
					continue
				end

				local reach = getgenv().ReactReach[animDigits] or {max = 0, n = 0}

				if (reach.max or 0) < max then
