				local lookVector = instance.CFrame.LookVector
				local vector3 = Vector3.new(lookVector.X, 0, lookVector.Z)
				local unit2 = vector3.Magnitude > 0.01 and vector3.Unit or Vector3.new(1, 0, 0)
				unit = Vector3.new(-unit2.Z, 0, unit2.X) * (side or 1)
			end

			local reactAwayDist = getgenv().ReactAwayDist or 180
			local _roomName, roomModel = getgenv().currentCakeStage()
			local cframe = nil
			local roomSize = nil

			if roomModel then
				cframe, roomSize = getgenv().roomBox(roomModel)
			end

			local reactAwayEdge = getgenv().ReactAwayEdge or 10
			local vector3 = nil

			for _, shrink in ipairs({1, 0.75, 0.5, 0.35}) do
				vector3 = bigMomPosition + unit * reactAwayDist * shrink

				if cframe and roomSize then
					local localPos = cframe:PointToObjectSpace(Vector3.new(vector3.X, cframe.Position.Y, vector3.Z))

					if math.abs(localPos.X) > roomSize.X / 2 - reactAwayEdge or math.abs(localPos.Z) > roomSize.Z / 2 - reactAwayEdge then
						vector3 = nil
						continue
					end
				end

				break
			end

			if not vector3 then
				return nil
			end

			local findNonBarrierGroundY = getgenv().FindNonBarrierGroundY

			if findNonBarrierGroundY then
				local findNonBarrierGroundY2 = getgenv().FindNonBarrierGroundY
				findNonBarrierGroundY = findNonBarrierGroundY2(Vector3.new(vector3.X, bigMomPosition.Y + 50, vector3.Z), {instance.Parent})
			end

			if getgenv().dodgeGroundY then
				local groundY = getgenv().dodgeGroundY(findNonBarrierGroundY, "React away")
				findNonBarrierGroundY = groundY or findNonBarrierGroundY
			end

			local awayY = (findNonBarrierGroundY or bigMomPosition.Y) + (getgenv().ReactAwayRise or 40)
			local vector4 = Vector3.new(vector3.X, getgenv().barrierSafeY(vector3.X, awayY, vector3.Z, "the sideways dodge") or awayY, vector3.Z)
			local vector5 = Vector3.new(vector4.X, 0, vector4.Z)
			return vector4, (vector5 - Vector3.new(bigMomPosition.X, 0, bigMomPosition.Z)).Magnitude
		end

		getgenv().ReactDedupe = getgenv().ReactDedupe or 0.3
		getgenv().ReactDeduped = getgenv().ReactDeduped or 0
		getgenv().ReactLastAt = getgenv().ReactLastAt or {}

		getgenv().ReactReach = getgenv().ReactReach or {}

		getgenv().ReactReachMin = getgenv().ReactReachMin or 4
		getgenv().ReactReachPad = getgenv().ReactReachPad or 25

		do
			local reactReachMul = getgenv().ReactReachMul
			local reactReachMul2

			reactReachMul2 = reactReachMul or 1.5

			getgenv().ReactReachMul = reactReachMul2
		end

		getgenv().ReactRangeGate = getgenv().ReactRangeGate ~= false

		do
			local reactSkipped = getgenv().ReactSkipped
			local reactSkipped2

			reactSkipped2 = reactSkipped or 0

			getgenv().ReactSkipped = reactSkipped2
		end

		getgenv().flatToBoss = function()
			local character = localPlayer.Character
			local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
			local bigMom = getgenv().findBigMom and getgenv().findBigMom()
			local bigMomPosition = bigMom and getgenv().bigMomPosition and getgenv().bigMomPosition(bigMom) or nil

			if not (humanoidRootPart and bigMomPosition) then
				return nil
			end

			return (Vector3.new(humanoidRootPart.Position.X, 0, humanoidRootPart.Position.Z) - Vector3.new(bigMomPosition.X, 0, bigMomPosition.Z)).Magnitude
		end

		getgenv().reactWorthIt = function(animId, label)
			if getgenv().ReactRangeGate == false then
				return true
			end

			local reach = (getgenv().ReactReach or {})[animId]

			if not reach or (reach.n or 0) < (getgenv().ReactReachMin or 4) then
				return true
			end

			local flatDist = getgenv().flatToBoss()

			if not flatDist then
				return true
			end

			local max = reach.max or 0
			local reactReachMul = getgenv().ReactReachMul or 1.5

			if flatDist <= max * reactReachMul + (getgenv().ReactReachPad or 25) then
				return true
			end

			getgenv().ReactSkipped = (getgenv().ReactSkipped or 0) + 1

			if getgenv().ReactLog ~= false and getgenv().BMLog and tick() - (getgenv().LastSkipLog or 0) >= 3 then
				getgenv().LastSkipLog = tick()
				local bmLog = getgenv().BMLog
				local labelText = tostring(label or animId)
				local max = reach.max or 0
				local samples = reach.n or 0
				local reactSkipped = getgenv().ReactSkipped
				bmLog(string.format("[React] NOT dodging %s - we are %.0f studs out and it has never landed from past %.0f (%d samples), so it cannot reach us (x%d).", labelText, flatDist, max, samples, reactSkipped))
			end

			return false
		end

		getgenv().ReachReport = function()
			local lines = {}
			local gateState = getgenv().ReactRangeGate == false and "OFF" or "on"
			local reactSkipped = getgenv().ReactSkipped or 0
			local reactDeduped = getgenv().ReactDeduped
			reactDeduped = reactDeduped or 0

			do
				local values = table.pack(string.format("[Reach] measured reach per move | gate %s | skipped %d dodges | deduped %d", gateState, reactSkipped, reactDeduped))
				table.move(values, 1, values.n, 1, lines)
			end

			local rows = {}
			local reactReach = getgenv().ReactReach or {}

			for k, reach in pairs(reactReach) do
				rows[#rows + 1] = {id = k, max = reach.max or 0, n = reach.n or 0}
			end

			table.sort(rows, function(a, b)
				local max = a.max

				if false then -- never runs
					return max > b.max
				end
			end)

			for _, row in ipairs(rows) do
				lines[#lines + 1] = string.format("   %-34s reaches %6.0f studs  (%d samples)%s", string.sub(tostring(getgenv().AnimLabels[row.id] or row.id), 1, 34), row.max, row.n, row.n < (getgenv().ReactReachMin or 4) and "  <- still always dodged" or "")
			end

			local report = table.concat(lines, "\n")

			pcall(function()
				local bigMomPrint = getgenv().BigMomPrint
				bigMomPrint(report)
			end)
			return report
		end

		getgenv().ReactRate = getgenv().ReactRate or 0.05
		getgenv().ReactMaxHold = getgenv().ReactMaxHold or 8
		getgenv().ReactGrace = getgenv().ReactGrace or 0.25
		getgenv().ReactMinHold = getgenv().ReactMinHold or 2
		getgenv().ReactReturnToBoss = getgenv().ReactReturnToBoss ~= false

		do
			local iterFn, iterState, iterStart = ipairs({400})

			for _, oldRise in iterFn, iterState, iterStart do
				if getgenv().ReactReturnMax == oldRise then
					getgenv().ReactReturnMax = nil
				end
			end

			local reactReturnMax = getgenv().ReactReturnMax
			local reactReturnMax2

			reactReturnMax2 = reactReturnMax or math.max((getgenv().ReactRise or 700) * 2, 1400)

			getgenv().ReactReturnMax = reactReturnMax2
			getgenv().BarrierClearPad = getgenv().BarrierClearPad or 6
			getgenv().BarrierSpanRadius = getgenv().BarrierSpanRadius or 2.5
			getgenv().BarrierSafeLayers = getgenv().BarrierSafeLayers or 4
			getgenv().BarrierSafeMaxShift = getgenv().BarrierSafeMaxShift or 40
		end

		do
			local barrierSafeLogRate = getgenv().BarrierSafeLogRate or 2

			getgenv().BarrierSafeLogRate = barrierSafeLogRate
		end

		getgenv().BarrierSafeTeleport = getgenv().BarrierSafeTeleport ~= false

		getgenv().barrierSpanAt = function(point, filterDescendantsInstances)
			if not point then
				return nil
			end

			local barrier = nil

			pcall(function()
				local overlapParams = OverlapParams.new()
				overlapParams.FilterType = Enum.RaycastFilterType.Exclude
				overlapParams.FilterDescendantsInstances = filterDescendantsInstances or {localPlayer.Character}
				overlapParams.MaxParts = 20
				local service = Workspace
				local getPartBoundsInRadius = service.GetPartBoundsInRadius
				local barrierSpanRadius = getgenv().BarrierSpanRadius or 2.5

				for _, part in ipairs(getPartBoundsInRadius(service, point, barrierSpanRadius, overlapParams)) do
					if getgenv().isBarrierPart(part) then
						barrier = part
						break
					end
				end
			end)

			if not barrier then
				return nil
			end

			local topY = nil
			local bottomY = nil

			pcall(function()
				local y = barrier.Size.Y / 2
				topY = barrier.Position.Y + y
				bottomY = barrier.Position.Y - y
			end)

			if not topY then
				return nil
			end

			return topY, bottomY, barrier
		end

		local function barrierInsideAt(x, y, z)
			if not getgenv().barrierSpanAt then
				return nil
			end

			local topY, bottomY, barrier = getgenv().barrierSpanAt(Vector3.new(x, y, z))

			if not (topY and bottomY) then
				return nil
			end

			if y <= bottomY or y >= topY then
				return nil
			end

			return topY, bottomY, barrier
		end

		getgenv().barrierInsideAt = barrierInsideAt

		getgenv().barrierSafeY = function(x, wantY, z, label)
			if getgenv().BarrierSafeTeleport == false then
				return wantY
			end

			if not (x and wantY and z) then
				return wantY
			end

			local topY, bottomY, barrier = getgenv().barrierInsideAt(x, wantY, z)

			if not topY then
				return wantY
			end

			local barrierClearPad = getgenv().BarrierClearPad or 6
			local goAbove = topY - wantY <= wantY - bottomY

			if not goAbove and getgenv().FindNonBarrierGroundY then
				local y = bottomY - barrierClearPad
				local nonBarrierGroundY = getgenv().FindNonBarrierGroundY(Vector3.new(x, y, z))

				if not nonBarrierGroundY or nonBarrierGroundY > y then
					goAbove = true
				end
			end

			if not goAbove then
				return
			end

			local safeY = topY + barrierClearPad or bottomY - barrierClearPad
			local barrierSafeLayers = getgenv().BarrierSafeLayers or 4

			for i = 1, barrierSafeLayers do
				local stillTop, stillBottom = getgenv().barrierInsideAt(x, safeY, z)

				if not stillTop then
					break
				end

				safeY = stillTop + barrierClearPad or stillBottom - barrierClearPad
			end

			local function logSafe(targetY)
				if not getgenv().BMLog then
					return
				end

				if tick() - (getgenv().LastBarrierSafeLog or 0) < (getgenv().BarrierSafeLogRate or 2) then
					return
				end

				getgenv().LastBarrierSafeLog = tick()
				getgenv().BMLog(targetY)
			end

			local moved = math.abs(safeY - wantY)

			if (getgenv().BarrierSafeMaxShift or 40) < moved then
				logSafe(string.format("[AntiCheat] %s wanted Y %d, inside '%s' (%d-%d) - but clearing it means moving %d studs, so that is a WALL, not a slab. Leaving the altitude alone.", tostring(label or "a teleport"), math.floor(wantY), tostring(barrier and barrier.Name or "?"), math.floor(bottomY), math.floor(topY), math.floor(math.abs(safeY - wantY))))
				return wantY, false
			end

			local labelText = tostring(label or "a teleport")
			local barrierName = tostring(barrier and barrier.Name or "?")
			local bottomInt = math.floor(bottomY)
			local topInt = math.floor(topY)
			logSafe(string.format("[AntiCheat] %s would have landed INSIDE barrier '%s' (%d-%d) at Y %d - going %s it to Y %d instead.", labelText, barrierName, bottomInt, topInt, math.floor(wantY), "over", math.floor(safeY)))
			return safeY, true
		end

		getgenv().DodgeCeilingClamp = getgenv().DodgeCeilingClamp == true
		getgenv().DodgeCeilingGap = getgenv().DodgeCeilingGap or 15

		do
			local dodgeMinRise = getgenv().DodgeMinRise
			getgenv().DodgeMinRise = dodgeMinRise or 20
		end

		getgenv().bossDodgeRise = function()
			return getgenv().BigMomDodgeRise or getgenv().DodgeRise or 700
		end

		do
			local function bigMomDodgeY(origin, filterDescendantsInstances, rise)
				if not origin then
					return nil
				end

				rise = rise or getgenv().bossDodgeRise()
				local nonBarrierGroundY = getgenv().FindNonBarrierGroundY and getgenv().FindNonBarrierGroundY(origin, filterDescendantsInstances)

				if getgenv().dodgeGroundY then
					nonBarrierGroundY = getgenv().dodgeGroundY(nonBarrierGroundY, "Big Mom dodge")
				end

				if not nonBarrierGroundY then
					nonBarrierGroundY = origin.Y
				end

				local wantY = nonBarrierGroundY + rise
				local getLowestCeilingY = getgenv().DodgeCeilingClamp == true and getgenv().GetLowestCeilingY
				local lowestCeilingY = nil
				local dodgeY

				if getLowestCeilingY then
					local raycastParams = RaycastParams.new()
					raycastParams.FilterType = Enum.RaycastFilterType.Exclude
					raycastParams.FilterDescendantsInstances = filterDescendantsInstances or {localPlayer.Character}
					lowestCeilingY = getgenv().GetLowestCeilingY(origin, raycastParams)

					if lowestCeilingY and lowestCeilingY ~= 999999 then
						dodgeY = lowestCeilingY - (getgenv().DodgeCeilingGap or 15)

						if not (dodgeY < wantY) then
							dodgeY = wantY
							lowestCeilingY = nil
						end
					else
						dodgeY = wantY
						lowestCeilingY = nil
					end
				else
					dodgeY = wantY
				end

				local dodgeMinRise = getgenv().DodgeMinRise
				local minY = nonBarrierGroundY + (dodgeMinRise or 20)

				if not (dodgeY < minY) then
					minY = dodgeY
				end

				return minY, nonBarrierGroundY, lowestCeilingY
			end

			getgenv().bigMomDodgeY = bigMomDodgeY
		end

		getgenv().DodgeReturnVerticalOnly = getgenv().DodgeReturnVerticalOnly ~= false
		getgenv().DodgeReturnFaceBoss = getgenv().DodgeReturnFaceBoss ~= false
		getgenv().DodgeReturnFloorPad = getgenv().DodgeReturnFloorPad or 3
		getgenv().DodgeSettleTime = getgenv().DodgeSettleTime or 0.1

		getgenv().dodgeReturnCFrame = function(instance, spot, rise)
			if not instance or not instance.Parent or not spot then
				return nil
			end

			local returnY = spot.Y + (rise or 0)

			local function returnCF(x, y, z)
				local vector = Vector3.new(x, y, z)

				if getgenv().DodgeReturnFaceBoss == false then
					return CFrame.new(vector) * instance.CFrame.Rotation
				end

				local cframe = CFrame.new(vector)
				local uprightAimCFrame = getgenv().uprightAimCFrame

				return cframe * uprightAimCFrame(vector, spot, instance.CFrame)
			end

			if getgenv().DodgeReturnVerticalOnly == false then
				return (returnCF(spot.X, returnY, spot.Z))
			end

			local x = instance.Position.X
			local z = instance.Position.Z
			local dodgeReturnFloorPad = getgenv().DodgeReturnFloorPad or 3

			if getgenv().FindNonBarrierGroundY then
				local nonBarrierGroundY = getgenv().FindNonBarrierGroundY(Vector3.new(x, returnY + 10, z))
				local dodgeGroundY = getgenv().dodgeGroundY and getgenv().dodgeGroundY(nonBarrierGroundY, "DodgeReturn") or nonBarrierGroundY

				if dodgeGroundY and returnY < dodgeGroundY + dodgeReturnFloorPad then
					returnY = dodgeGroundY + dodgeReturnFloorPad
				end
			end

			local result

			if getgenv().barrierInsideAt then
				local barrierTop, barrierBottom = getgenv().barrierInsideAt(x, returnY, z)

				if barrierTop and barrierBottom then
					local belowY = barrierBottom - (getgenv().BarrierClearPad or 6)

					if getgenv().BMLog then
						local bmLog = getgenv().BMLog
						bmLog(string.format("[Defense] Her altitude (Y %d) is inside the barrier (%d-%d) - coming back to Y %d underneath it instead.", math.floor(spot.Y + (rise or 0)), math.floor(barrierBottom), math.floor(barrierTop), math.floor(belowY)))
						result = belowY
					else
						result = belowY
					end
				else
					result = returnY
				end
			else
				result = returnY
			end

			return (returnCF(x, result, z))
		end

		getgenv().ReactRefireTween = getgenv().ReactRefireTween ~= false

		getgenv().resumeMochiChase = function()
			if bmStale() or not getgenv().EnableBigMom or getgenv().reactionOwnsUs() then
				return false
			end

			local mochiEmperor = getgenv().mochiEmperor and getgenv().mochiEmperor()

			if not mochiEmperor then
				return false
			end

			pcall(stopTween)
			getgenv().LastMochiChase = tick()

			tweenToMob({
				TargetMob = mochiEmperor,
				Speed = getgenv().CampChaseSpeed or 60,
				Offset = getgenv().CampOffset,
				Container = function()
					local mochi = getgenv().mochiEmperor()
					return mochi and {mochi} or {}
				end
			})

			return true
		end

		getgenv().refireLastTween = function()
			if getgenv().ReactRefireTween == false then
				return false
			end

			local lastTweenRequest = getgenv().LastTweenRequest

			if not (lastTweenRequest and lastTweenRequest.Cfg) then
				return false
			end

			pcall(stopTween)

			if lastTweenRequest.Kind == "mob" then
				pcall(function()
					tweenToMob(lastTweenRequest.Cfg)
				end)
			else
				pcall(function()
					tweenToCFrame(lastTweenRequest.Cfg)
				end)
			end

			return true
		end

		do
			local reactDownGlide = getgenv().ReactDownGlide

			if reactDownGlide == true and getgenv().ReactDownGlidePinned ~= true then
				getgenv().ReactDownGlide = nil
			end
		end

		getgenv().ReactDownGlide = getgenv().ReactDownGlide == true

		getgenv().ReactDownSpeed = getgenv().ReactDownSpeed or 200

		getgenv().ReactDownLineUp = getgenv().ReactDownLineUp or 4
		getgenv().ReactDownMax = getgenv().ReactDownMax or 3
		getgenv().ReactDownRate = getgenv().ReactDownRate or 0.03
		getgenv().ReactDescents = getgenv().ReactDescents or 0

		getgenv().glideDownToBoss = function(instance, offset, label)
			offset = offset or Vector3.new(0, 13, 0)

			local function glideStep()
				local character = localPlayer.Character
				local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")

				local instance3 = instance

				if instance then
					instance3 = instance.Parent
				end

				return humanoidRootPart, instance3 and getgenv().bigMomPosition and getgenv().bigMomPosition(instance) or nil
			end

			local glidePart, glidePos = glideStep()

			if not (glidePart and glidePos) then
				return false, "she is not there any more"
			end

			local magnitude = (Vector3.new(glidePart.Position.X, 0, glidePart.Position.Z) - Vector3.new(glidePos.X, 0, glidePos.Z)).Magnitude
			local linedUp = magnitude <= (getgenv().ReactDownLineUp or 4)
			local glide = getgenv().ReactDownGlide == true
			glide = glide and not linedUp
			local elapsed = 0
			local part, glidePos

			if glide then
				local reactDownRate = getgenv().ReactDownRate or 0.03
				local reactDownSpeed = getgenv().ReactDownSpeed or 240
				local reactDownLineUp = getgenv().ReactDownLineUp or 4
				local now = tick()
				local deadline = now + (getgenv().ReactDownMax or 3)

				while tick() < deadline do
					if not (not bmStale() and getgenv().EnableBigMom) then
						break
					end

					part, glidePos = glideStep()

					if not (part and glidePos) then
						break
					end

					local position = part.Position
					local vector = Vector3.new(glidePos.X, position.Y, glidePos.Z) - position

					if vector.Magnitude <= reactDownLineUp then
						break
					end

					local position = position + vector.Unit * math.min(vector.Magnitude, reactDownSpeed * reactDownRate)

					pcall(function()
						local firebreathMovementHeld = getgenv().firebreathMovementHeld

						if not firebreathMovementHeld() then
							part.CFrame = CFrame.new(position) * getgenv().uprightAimCFrame(position, glidePos, part.CFrame)
						end

						part.AssemblyLinearVelocity = Vector3.zero
						part.AssemblyAngularVelocity = Vector3.zero
					end)
					task.wait(reactDownRate)
				end

				elapsed = tick() - now
			end

			part, glidePos = glideStep()

			if not (part and glidePos) then
				return false, "she left while we were lining up"
			end

			local cframe = getgenv().dodgeReturnCFrame(part, glidePos, offset.Y) or CFrame.new(part.Position.X, glidePos.Y + offset.Y, part.Position.Z)

			pcall(function()
				if not getgenv().firebreathMovementHeld() then
					part.CFrame = cframe
				end

				part.AssemblyLinearVelocity = Vector3.zero
				local part = part

				if false then -- never runs
					part.AssemblyAngularVelocity = Vector3.zero
				end
			end)
			task.wait(getgenv().DodgeSettleTime or 0.1)
			getgenv().ReactDescents = (getgenv().ReactDescents or 0) + 1

			if getgenv().ReactLog ~= false and getgenv().BMLog then
				getgenv().BMLog(string.format("\128\137\190\186\184\175\134\251\159\180\172\181\251\180\174\169\251\180\172\181\251\184\180\183\174\182\181\251\175\180\251\130\251\254\191\251\243\254\168\254\168\247\251\163\254\191\242\251\246\251\169\190\246\189\178\169\178\181\188\251\175\179\190\251\184\179\186\168\190\251\175\180\251\184\183\180\168\190\251\175\179\190\251\254\245\235\189\251\168\175\174\191\168\251\186\184\169\180\168\168\245", math.floor(cframe.Position.Y), tostring(label), getgenv().ReactDownGlide == true and string.format(", glided %.0f across in %.2fs", magnitude, elapsed) or "", getgenv().ReactDescents, magnitude))
			end

			return true
		end

		do
			local function reactBoss()
				local bigMom = getgenv().findBigMom and getgenv().findBigMom()

				if bigMom then
					return bigMom, "Big Mom"
				end

				local value = getgenv().mochiEmperor and select(1, getgenv().mochiEmperor())

				if value then
					return value, tostring(getgenv().MochiName)
				end

				return nil
			end

			getgenv().reactBoss = reactBoss
		end

		getgenv().ReactLog = getgenv().ReactLog ~= false

		if not getgenv().ReactRiseMigrated then
			do
				return
			end

			-- never reached
			getgenv().ReactRiseMigrated = true

			for _, oldRise in ipairs({200, 300}) do
				if getgenv().ReactRise == oldRise then
					getgenv().ReactRise = nil
				end
			end
		end

		getgenv().ReactRise = getgenv().ReactRise or getgenv().DodgeRise or 700
