			local distance = (getgenv().HoldStepSpeed or 200) * (getgenv().ReactRate or 0.05)
			local x = position2.X
			local z = position2.Z

			if distance < vector.Magnitude then
				local position = position + vector.Unit * distance
				x = position.X
				z = position.Z
			end

			pcall(function()
				part.CFrame = CFrame.new(x, position2.Y, z) * spot.Rotation
				part.AssemblyLinearVelocity = Vector3.zero
				part.AssemblyAngularVelocity = Vector3.zero
