				local animation = track and track.Animation

				if not animation then
					return false
				end

				local kind, label = getgenv().bigMomReaction(animation.AnimationId)

				if not kind then
					return false
				end

				local id = getgenv().animDigits(animation.AnimationId)

				if id then
					local lastAt = (getgenv().ReactLastAt or {})[id]

					if lastAt and tick() - lastAt < (getgenv().ReactDedupe or 0.3) then
						getgenv().ReactDeduped = (getgenv().ReactDeduped or 0) + 1
						return false
					end

					getgenv().ReactLastAt[id] = tick()
				end

				local worthIt, id2

				if id then
					worthIt = getgenv().reactWorthIt(id, label)
					id2 = not worthIt
				else
					id2 = id
				end

				if id2 then
					return false
				end

				local bigMomDodgeStyle = getgenv().BigMomDodgeStyle or {}
				local style = "up"

				for k, styleEntry in pairs(bigMomDodgeStyle) do
