						break
					end
				end

				local animLength = 0

				pcall(function()
					animLength = tonumber(track.Length) or 0
				end)
				local hold = math.max(animLength > 0 and animLength + (getgenv().ReactGrace or 0.25) or getgenv().ReactMaxHold or 8, getgenv().ReactMinHold or 2)
				local holdCapped = math.min(hold, getgenv().ReactMaxHold or 8)
				local reaction = {}
				reaction.kind = kind
				reaction.label = label
				reaction.done = false
				reaction.id = id
				local styleSource = "style"
				reaction.style = style
				reaction.until_ = tick() + holdCapped
				reaction.at = tick()
				local now = tick()
				local reactMinHold = getgenv().ReactMinHold
				reactMinHold = reactMinHold or 2
				local reactMaxHold = getgenv().ReactMaxHold
				local reactMaxHold2

				if reactMaxHold then
					reactMaxHold2 = reactMaxHold
				else
					reactMaxHold = 8
					reactMaxHold2 = reactMaxHold
				end

				reaction.floor_ = now + math.min(reactMinHold, reactMaxHold2)

				if styleSource then
					reaction.side = math.random() < 0.5 and 1 or -1
					getgenv().BigMomReactLive[track] = reaction
					local liveCount = 0

					for k, live in pairs(getgenv().BigMomReactLive) do
