					getgenv().Reactions = reactions + 1

					if getgenv().ReactLog ~= false and getgenv().BMLog then
						getgenv().BMLog(string.format("[React] %s -> %s, holding until the track stops (%s, x%d).", tostring(label), kind == "dodge" and "GET OUT OF IT" or "BLOCK", animLength > 0 and string.format("%.1fs long", animLength) or string.format("no length, capped at %.0fs", holdCapped), getgenv().Reactions))
					end

					return true
				end

				local exitTo

				repeat
					local done = worthIt.done
					exitTo = nil

					while true do
						if done then
