					end

					local bigMomDodgeY = getgenv().bigMomDodgeY
					local position = child.Position
					local ignoreList = {}
					ignoreList[1] = character
					local dodgeY, y, dodgeNote = bigMomDodgeY(position, ignoreList, reactRise)
					y = y or child.Position.Y
					dodgeY = dodgeY or y + (getgenv().ReactRise or 700)

					if dodgeNote and getgenv().ReactLog ~= false and getgenv().BMLog and tick() - (getgenv().LastDodgeCeilLog or 0) >= 5 then
						getgenv().LastDodgeCeilLog = tick()
						getgenv().BMLog(string.format("[React] Ceiling at Y %d - taking the dodge to Y %d instead of the full %d studs, so we stay inside the room.", math.floor(dodgeNote), math.floor(dodgeY), math.floor(getgenv().ReactRise or 700)))
					end

					local y2 = getgenv().barrierSafeY(child.Position.X, dodgeY, child.Position.Z, "the dodge") or dodgeY
					local reactSideStep = getgenv().ReactSideStep or 0
					local vector = Vector3.zero

					if reactSideStep > 0 then
						local lookVector = child.CFrame.LookVector
						local vector2 = Vector3.new(lookVector.X, 0, lookVector.Z)

						if vector2.Magnitude > 0.01 then
							local unit = vector2.Unit
							vector = Vector3.new(-unit.Z, 0, unit.X) * (reactSideStep * side)
						end
					end

					dodgeSpot = awaySpot
					local vector2

					if awaySpot then
						vector2 = Vector3.new(child.Position.X, awaySpot.Y, child.Position.Z)
					else
						vector2 = Vector3.new(child.Position.X + vector.X, y2, child.Position.Z + vector.Z)
					end

					local awayNoSpot = style == "away" and not awaySpot

					if awayNoSpot then
						local reactLog = getgenv().ReactLog
						awayNoSpot = reactLog ~= false
					end

					if awayNoSpot and getgenv().BMLog and tick() - (getgenv().LastAwayFailLog or 0) >= 5 then
						getgenv().LastAwayFailLog = tick()
						getgenv().BMLog(string.format("[React] %s wants a sideways dodge but there is nowhere in the room to put us - going up instead, which does NOT beat the beam.", tostring(label)))
					end

					pcall(function()
						getgenv().dropFaceMouseNow("React dodge")
					end)
					local clampedPos = getgenv().clampYUp(child, vector2, "React dodge")
					local rotation = child.CFrame.Rotation

					if getgenv().DodgeUprightAim ~= false then
						local reactBoss = getgenv().reactBoss and getgenv().reactBoss() or getgenv().findBigMom and getgenv().findBigMom()
						reactBoss = reactBoss and getgenv().bigMomPosition(reactBoss) or nil
						rotation = getgenv().uprightAimCFrame(clampedPos, reactBoss or clampedPos + child.CFrame.LookVector, child.CFrame)
					end

					dodgeCF = CFrame.new(clampedPos) * rotation
					clearReactMovers()
					bmReactVel = Instance.new("BodyVelocity")
					bmReactVel.Name = "BM_ReactVel"
					bmReactVel.MaxForce = Vector3.new(1000000000, 1e9, 1000000000)
					bmReactVel.Velocity = Vector3.zero
					bmReactVel.Parent = child

					pcall(function()
						if not getgenv().firebreathMovementHeld() then
							child.CFrame = CFrame.new(child.Position.X, clampedPos.Y, child.Position.Z) * dodgeCF.Rotation
						end

						child.AssemblyLinearVelocity = Vector3.zero
						child.AssemblyAngularVelocity = Vector3.zero
					end)

					getgenv().ReactUp = true
					task.wait(getgenv().DodgeSettleTime or 0.1)

					if getgenv().ReactLog ~= false and getgenv().BMLog then
						if awaySpot then
							getgenv().BMLog(string.format("[React] SIDEWAYS for %s - going up does not beat this one. Y %.0f now, then WALKING %d studs out of her column at %d/s (never a sideways teleport, that is a kick).", tostring(label), clampedPos.Y, math.floor(awayWhy or 0), math.floor(getgenv().ReactAwaySpeed or 200)))
						else
							getgenv().BMLog(string.format("[React] Up %d studs off the floor (Y %.0f -> %.0f) for %s - holding there until it ends.", math.floor(reactRise or 700), y, clampedPos.Y, tostring(label)))
						end
					end
				elseif dodgeCF then
					if dodgeSpot then
						local position = dodgeCF.Position
						local vector = Vector3.new(dodgeSpot.X - position.X, 0, dodgeSpot.Z - position.Z)

						if vector.Magnitude <= 1 then
							dodgeSpot = nil
						else
							local position = position + vector.Unit * math.min(vector.Magnitude, (getgenv().ReactAwaySpeed or 200) * (getgenv().ReactRate or 0.05))
							dodgeCF = CFrame.new(position.X, dodgeSpot.Y, position.Z) * dodgeCF.Rotation
						end
					end

					if not bmReactVel or bmReactVel.Parent ~= child then
						clearReactMovers()
						bmReactVel = Instance.new("BodyVelocity")
						bmReactVel.Name = "BM_ReactVel"
						bmReactVel.MaxForce = Vector3.new(1e9, 1e9, 1000000000)
						bmReactVel.Velocity = Vector3.zero
						bmReactVel.Parent = child
					end

					local magnitude = (child.Position - dodgeCF.Position).Magnitude

					if (getgenv().ReactHoldSlack or 0.5) < magnitude then
						getgenv().holdAtSpot(child, dodgeCF)
					end

					pcall(function()
						child.AssemblyLinearVelocity = Vector3.zero
						child.AssemblyAngularVelocity = Vector3.zero
					end)
				end

				if reacting == "upblock" then
					if not blockPinned then
						blockPinned = true
						blockPinCF = CFrame.new(child.Position) * child.CFrame.Rotation
						getgenv().AutoBlocking = true

						pcall(function()
							if false then -- never runs
								getgenv().DoBlock(true)
							end
						end)

						if getgenv().ReactLog ~= false and getgenv().BMLog then
							getgenv().BMLog(string.format("[React] Blocking %s at Y %.0f - anchored, nothing moves us until it ends.", tostring(label), child.Position.Y))
						end
					end

					if getgenv().ReactBlockAnchor ~= false then
						getgenv().ReactBlockPin = true
					end

					getgenv().subStatus = "Up + blocking " .. tostring(label)
				else
					getgenv().subStatus = "Dodging " .. tostring(label)
				end
			end
		end)

		getgenv().ReactInfo = function()
			local lines = {}
			local reactState = getgenv().BigMomReact == false and "OFF" or "on"
			local reactingText = getgenv().Reacting and getgenv().Reacting .. " - " .. tostring(getgenv().ReactingWhy) or "nothing"
			local reactions = getgenv().Reactions or 0

			do
				local values = table.pack(string.format("[React] %s | now: %s | reactions this session: %d", reactState, reactingText, reactions))
				table.move(values, 1, values.n, 1, lines)
			end

			local lineCount = #lines
			lines[lineCount + 1] = "  BLOCK:"
			local bigMomBlockAnims = getgenv().BigMomBlockAnims or {}

			for k, bigMomBlockAnim in pairs(bigMomBlockAnims) do
				lines[#lines + 1] = string.format("    %-16s %s", k, bigMomBlockAnim)
			end

			lines[#lines + 1] = "  UP + BLOCK (rise then block, pinned):"
			local bigMomUpBlockAnims = getgenv().BigMomUpBlockAnims or {}

			for k, bigMomUpBlockAnim in pairs(bigMomUpBlockAnims) do
				lines[#lines + 1] = string.format("    %-16s %s", k, bigMomUpBlockAnim)
			end

			local bigMomTorchSounds = getgenv().BigMomTorchSounds or {}

			for k, bigMomTorchSound in pairs(bigMomTorchSounds) do
				lines[#lines + 1] = string.format("    sound %-24s %s", k, bigMomTorchSound)
			end

			lines[#lines + 1] = "  DODGE:"
			local bigMomDodgeAnims = getgenv().BigMomDodgeAnims or {}

			for k, bigMomDodgeAnim in pairs(bigMomDodgeAnims) do
				lines[#lines + 1] = string.format("    %-16s %s", k, bigMomDodgeAnim)
			end

			lines[#lines + 1] = string.format("  %s DODGE (measured, %d shout names learned):", tostring(getgenv().MochiName), getgenv().MochiShouts or 0)
			local iterFn, iterState, iterStart = pairs(getgenv().MochiDodgeAnims or {})

			for k, entry in iterFn, iterState, iterStart do
				lines[#lines + 1] = string.format("    %-16s %s%s", k, entry, (getgenv().MochiAnimLabels or {})[k] and "  [he calls it: " .. tostring(getgenv().MochiAnimLabels[k]) .. "]" or "")
			end

			lines[#lines + 1] = string.format("  %s NOT reacted to:", tostring(getgenv().MochiName))
			local mochiNoReact = getgenv().MochiNoReact
			local mochiNoReact2

			mochiNoReact2 = mochiNoReact or {}

			for k, entry in pairs(mochiNoReact2) do
				lines[#lines + 1] = string.format("    %-16s %s", k, entry)
			end

			local report = table.concat(lines, "\n")

			pcall(function()
				local bigMomPrint = getgenv().BigMomPrint
				bigMomPrint(report)
			end)
			return report
		end

