				local iterFn, iterState, iterStart = ipairs(getgenv().EffectOwnerKeys)

				for _, name in iterFn, iterState, iterStart do
					local child = instance:FindFirstChild(name)

					if child then
						if child:IsA("ObjectValue") and child.Value then
							local value = child.Value

							if value:IsA("Model") then
								return value
							end

							local firstAncestorOfClass = value:FindFirstAncestorOfClass("Model")

							if firstAncestorOfClass then
								return firstAncestorOfClass
							end
						elseif child:IsA("StringValue") and child.Value ~= "" then
							local child = Players:FindFirstChild(child.Value)

							if child and child.Character then
								return child.Character
							end
						end
					end

					local function getAttribute()
						return instance:GetAttribute(name)
					end

					local attrOk, name = pcall(getAttribute)

					if attrOk and typeof(name) == "string" and name ~= "" then
						local child = Players:FindFirstChild(name)

						if child and child.Character then
