				local effectName = getgenv().normalizeMoveName(effect.Name)

				if effectName == "" then
					return false
				end

				local bossAlwaysKeywords = getgenv().BossAlwaysKeywords or {}

				for _, bossAlwaysKeyword in ipairs(bossAlwaysKeywords) do
					local keyword = getgenv().normalizeMoveName(bossAlwaysKeyword)

					if keyword ~= "" and string.find(effectName, keyword, 1, true) then
