			getgenv().ClearEffectVerdicts = clearEffectVerdicts

			getgenv().effectFromBoss = function(instance)
				if getgenv().BossOnlyMoves ~= true then
					return true
				end

				if not instance or not instance.Parent then
					return false
				end

				if getgenv().effectAlwaysBoss(instance) then
					return true
				end

				local effectVerdict = getgenv().EffectVerdicts[instance]

				if effectVerdict ~= nil then
					return effectVerdict
				end

				local ownerModel = getgenv().effectOwnerModel(instance)

				if ownerModel then
					if getgenv().isBossNPC(ownerModel) then
						return getgenv().rememberEffect(instance, true)
					end

					local playerFromCharacter = Players:GetPlayerFromCharacter(ownerModel)

					if playerFromCharacter then
						return getgenv().rememberEffect(instance, playerFromCharacter == localPlayer)
					end
				end

				local firstAncestorOfClass = instance:FindFirstAncestorOfClass("Model")

				if firstAncestorOfClass then
					if getgenv().isBossNPC(firstAncestorOfClass) then
						return getgenv().rememberEffect(instance, true)
					end

					local playerFromCharacter = Players:GetPlayerFromCharacter(firstAncestorOfClass)

					if playerFromCharacter and playerFromCharacter ~= localPlayer then
						return getgenv().rememberEffect(instance, false)
					end
				end

				local playerChars = getgenv().otherPlayerChars()

				if #playerChars == 0 then
					return true
				end

				local origin = getgenv().effectOrigin(instance)

				if not origin then
					return true
				end

				local magnitude = math.huge
				local child = child2 and child2.Parent and child2 or localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")

				if child then
					magnitude = (origin - child.Position).Magnitude
				end

				local magnitude2 = math.huge
				local kingNPC = getgenv().findKingNPC and getgenv().findKingNPC()

				if kingNPC then
					local kingRoot = npcRoot(kingNPC)

					if kingRoot then
						magnitude2 = (origin - kingRoot.Position).Magnitude
					end
				end

				local magnitude5 = math.huge
				local name = nil

				for _, char in ipairs(playerChars) do
					local magnitude = (origin - char.pos).Magnitude

					if magnitude < magnitude5 then
						name = char.name
						magnitude5 = magnitude
					end
				end

				local bossReach = magnitude5 + (getgenv().BossEffectMargin or 12)

				if bossReach < math.min(magnitude, magnitude2) then
					if getgenv().MoveFilterLog and getgenv().BMLog then
						local bmLog = getgenv().BMLog
						local effectName = tostring(instance.Name)
						local magnitude3 = math.floor(magnitude5)
						local ownerName = tostring(name)
						local magnitude = math.floor(magnitude)
						bmLog(string.format("[MoveFilter] Ignoring '%s' - spawned %d studs from %s, %d from us, %d from the boss.", effectName, magnitude3, ownerName, magnitude, math.floor(magnitude2)))
					end

