				local speedCap = math.max((speedBypass < 0 and 0 or speedBypass) * (getgenv().SpeedBypassScale or 1) + (getgenv().SpeedBypassBase or 0), getgenv().SpeedBypassMin or 20)
				local speed

				if type(getgenv().SpeedBypassMax) ~= "number" then
					speed = speedCap
				else
					speed = math.min(speedCap, getgenv().SpeedBypassMax)
				end

				return speed, speedBypass
			end
		end

