		getgenv().dialogueOpen = function()
			local instance, instance2 = getgenv().cakeTextFrame()

			if not instance or not instance2 then
				return false
			end

			if not (instance2:IsA("ScreenGui") and instance2.Enabled == false) then
				if not instance.Visible then
					return false
				end

				for _, child in ipairs(instance:GetChildren()) do
					if child:IsA("GuiObject") and child.Name == "Line" then
						return true
					end
				end

				return false
			end

			return false
