		getgenv().readCakeDialogue = function()
			local instance, instance2 = getgenv().cakeTextFrame()

			if not instance then
				return nil
			end

			local scrapeOnlyWhenShown = getgenv().ScrapeOnlyWhenShown

			if scrapeOnlyWhenShown ~= false and instance2 then
				if instance2:IsA("ScreenGui") and instance2.Enabled == false then
					return nil
				end

				local child = instance2:FindFirstChild("Main")

				if child and child:IsA("GuiObject") and not child.Visible then
					return nil
				end

				if not instance.Visible then
					return nil
				end
			end

			local lines = {}

			for _, child in ipairs(instance:GetChildren()) do
				if not (child:IsA("GuiObject") and child.Name == "Line") then
					continue
				end

				local rows = {}

				for _, child5 in ipairs(child:GetChildren()) do
					if child5:IsA("GuiObject") then
						local textLabel = child5:FindFirstChildWhichIsA("TextLabel", true)

						if textLabel then
							rows[#rows + 1] = {x = child5.AbsolutePosition.X, t = textLabel.Text}
						end
					end
				end

				table.sort(rows, function(a, b)
					return a.x < b.x
				end)
				local ts = {}

				for _, row in ipairs(rows) do
					ts[#ts + 1] = row.t
				end

				lines[#lines + 1] = {y = child.AbsolutePosition.Y, text = table.concat(ts)}
			end

			if #lines == 0 then
				return nil
			end

			table.sort(lines, function(a, b)
				return a.y < b.y
			end)
			local texts = {}

			for _, row in ipairs(lines) do
				texts[#texts + 1] = row.text
			end

			return table.concat(texts), lines
		end

