			local count = 0
			local cakeSettleTries = getgenv().CakeSettleTries or 25
			local cakeDialogue2 = nil

			for i = 1, cakeSettleTries do
				local cakeDialogue = getgenv().readCakeDialogue()

				if cakeDialogue and cakeDialogue == cakeDialogue2 then
					count += 1

					if 1 <= count then
						return cakeDialogue
					end
				else
					count = 0
				end

				task.wait(getgenv().CakeSettleRate or 0.15)
				cakeDialogue2 = cakeDialogue
