		getgenv().installDialogueHook = function()
			local dialogueModulePath = getgenv().DialogueModulePath or {}
			local ReplicatedStorage2 = ReplicatedStorage

			for _, name in ipairs(dialogueModulePath) do
				ReplicatedStorage2 = ReplicatedStorage2:FindFirstChild(name)

				if not ReplicatedStorage2 then
					return false, "no " .. tostring(name)
				end
			end

			local ok, dialogueModule = pcall(require, ReplicatedStorage2)

			if not ok or type(dialogueModule) ~= "table" or type(dialogueModule.start) ~= "function" then
				return false, "module has no .start"
			end

			if getgenv().__cakeStartOriginal == nil then
				getgenv().__cakeStartOriginal = dialogueModule.start
			end

			local cakeStartOriginal = getgenv().__cakeStartOriginal

			dialogueModule.start = function(module, player)
				if type(player) == "table" then
					if type(player.Text) ~= "string" or player.Text == "" then
						getgenv().DialogueClosedAt = tick()
						return cakeStartOriginal(module, player)
					end

					local lastDialogue = {Text = player.Text}
					lastDialogue.Mood = player.Mood or "Normal"
					lastDialogue.Character = player.Character or "Big Mom"
					lastDialogue.Duration = player.Duration
					lastDialogue.At = tick()
					getgenv().LastDialogue = lastDialogue
					local dialogueLog = getgenv().DialogueLog
					table.insert(dialogueLog, lastDialogue)

					while #dialogueLog > (getgenv().DialogueLogMax or 40) do
						table.remove(dialogueLog, 1)
					end

					if getgenv().DialogueHookLog ~= false and getgenv().BMLog then
						local bmLog = getgenv().BMLog
						bmLog(string.format("[Dialogue] %s (%s): %s", tostring(lastDialogue.Character), tostring(lastDialogue.Mood), tostring(lastDialogue.Text)))
					end

					local dialogueHandlers = getgenv().DialogueHandlers or {}

					for _, dialogueHandler in ipairs(dialogueHandlers) do
						pcall(dialogueHandler, lastDialogue)
					end
				end

				return cakeStartOriginal(module, player)
			end

			return true
		end

