			local dialogueClose = instance:FindFirstChild(getgenv().DialogueCloseName or "Close", true)
			local closed = false

			if dialogueClose and typeof(getconnections) == "function" then
				pcall(function()
					for _, connection in ipairs(getconnections(dialogueClose.MouseButton1Click)) do
						connection:Fire()
						closed = true
					end
				end)
			end

			if not closed then
