						instance.Enabled = false
					end
				end)
				closed = true
			end

			getgenv().DialoguesClosed = (getgenv().DialoguesClosed or 0) + 1

			if getgenv().BMLog then
				getgenv().BMLog(string.format("[Dialogue] Closed the box (%s) - that line has been acted on, so it stops reading as the current instruction (x%d).", tostring(reason or "done"), getgenv().DialoguesClosed))
