		getgenv().listCakeFlavours = function()
			local seen = {}
			local flavours = {}

			local function addFlavour(flavour)
				if flavour and flavour ~= "" and not seen[flavour] then
					seen[flavour] = true
					flavours[#flavours + 1] = flavour
				end
			end

			for _, cakeFolder in ipairs(getgenv().cakeFolders()) do
				for _, child in ipairs(cakeFolder:GetChildren()) do
					addFlavour(child.Name)
					local cakeFlavoursFallback = getgenv().CakeFlavoursFallback or {}

					for _, flavour in ipairs(cakeFlavoursFallback) do
						if flavour == child.Name then
							break
						end
					end

					getgenv().CakeFlavoursFallback = cakeFlavoursFallback
				end
			end

			local cakeFlavoursFallback = getgenv().CakeFlavoursFallback or {}

			for _, flavour in ipairs(cakeFlavoursFallback) do
				addFlavour(flavour)
			end

			table.sort(flavours, function(a, b)
				return #a > #b
			end)

			return flavours
		end

