		getgenv().classifyDialogue = function(text)
			local order = nil

			if text == nil then
				local _source
				text, _source, order = getgenv().dialogueText()
				_ = _source
			end

			if type(text) ~= "string" or text == "" then
				return "none", nil, nil
			end

			local lower = string.lower(text)
			local mood = order and order.Mood or nil

			local function matchesRule(kind)
				local dialogueRules = getgenv().DialogueRules or {}

				for _, dialogueRule in ipairs(dialogueRules) do
					if dialogueRule.kind ~= kind then
						continue
					end

					local words = dialogueRule.words or {}

					for _, word in ipairs(words) do
						if word ~= "" and string.find(lower, string.lower(word), 1, true) then
							return true
						end
					end
				end

				return false
			end

			local cake = getgenv().wantedCake(text)

			if cake and getgenv().dialogueAsksFor(lower) then
				return "cake", text, cake, mood
			end

			if matchesRule("finished") then
				return "finished", text, nil, mood
			end

			if matchesRule("wrong") then
				return "wrong", text, nil, mood
			end

			if matchesRule("puzzle") then
				return "puzzle", text, nil, mood
			end

			if cake then
				if matchesRule("pleased") then
					return "pleased", text, nil, mood
				end

				return "cake", text, cake, mood
			end

			if matchesRule("pleased") then
				return "pleased", text, nil, mood
			end

			local dialogueRules = getgenv().DialogueRules or {}

			for _, dialogueRule in ipairs(dialogueRules) do
				local words = dialogueRule.words or {}

				for _, word in ipairs(words) do
					if word ~= "" and string.find(lower, string.lower(word), 1, true) then
						return dialogueRule.kind, text, nil, mood
					end
				end
			end

			return "unknown", text, nil, mood
		end

		getgenv().DialogueHistory = function()
			local dialogueLog = getgenv().DialogueLog or {}

			if #dialogueLog == 0 then
				bmLog18("[Dialogue] nothing caught yet - the hook installs at load, so lines from before that are not here")
				return {}
			end

			local lines = {string.format("[Dialogue] %d line(s) this session:", #dialogueLog)}

			for i, player in ipairs(dialogueLog) do
				local index = #lines + 1
				local speaker = tostring(player.Character)
				local mood = tostring(player.Mood)
				local lineText = tostring(player.Text)
				local kind = getgenv().classifyDialogue(player.Text)
				lines[index] = string.format("  %2d. [%s/%s] %s -> %s", i, speaker, mood, lineText, tostring(kind))
			end

			local report = table.concat(lines, "\n")
			bmLog18(report)
			return dialogueLog, report
		end

