		getgenv().findCake = function(flavour, children)
			flavour = flavour or getgenv().wantedCake()

			if not flavour then
				return nil
			end

			if not children then
				children = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
				children = children and children.Position
			end

			local lowerFlavour = string.lower(flavour)
			local magnitude2 = math.huge
			local child5 = nil
			local proximityPrompt2 = nil
			local best = nil

			for _, cakeFolder in ipairs(getgenv().cakeFolders()) do
				for _, child in ipairs(cakeFolder:GetChildren()) do
					if string.lower(child.Name) ~= lowerFlavour then
						continue
					end

					local proximityPrompt = child:FindFirstChildWhichIsA("ProximityPrompt", true)

					if not (proximityPrompt and proximityPrompt.Enabled) then
						continue
					end

					local cakePos = getgenv().cakePosition(child)

					if not cakePos then
						continue
					end

					local magnitude = children and (cakePos - children).Magnitude or 0

					if magnitude < magnitude2 then
						magnitude2 = magnitude
						child5 = child
						proximityPrompt2 = proximityPrompt
						best = cakePos
					end
				end
			end

			return child5, proximityPrompt2, best, magnitude2
		end

