		getgenv().waitForCake = function(flavour, timeout)
			local wanted = flavour or getgenv().wantedCake()

			if not wanted then
				return nil, "no flavour asked for"
			end

			local deadline = tick() + (timeout or getgenv().CakeWaitTimeout or 15)

			while true do
				local cake, cakePos, cakeMain, cakeDist = getgenv().findCake(wanted)

				if cake then
					return cake, cakePos, cakeMain, cakeDist
				end

				task.wait(getgenv().CakeWaitRate or 0.25)

				if not (deadline < tick()) then
					continue
				end

				break
			end

			return nil, string.format("no '%s' appeared within %.0fs", tostring(wanted), timeout or getgenv().CakeWaitTimeout or 15)
		end

		getgenv().CakeCounts = function()
