			for _, cakeFolder in ipairs(getgenv().cakeFolders()) do
				for _, child in ipairs(cakeFolder:GetChildren()) do
					if lines[child.Name] == nil then
						lines[child.Name] = 0
						names[#names + 1] = child.Name
					end

					lines[child.Name] = lines[child.Name] + 1
				end
			end

			table.sort(names)
			local present = {}

			for _, name in ipairs(names) do
				present[#present + 1] = string.format("%s %d", name, lines[name])
			end

			local report = "[Cake] in the room: " .. (#present > 0 and table.concat(present, ", ") or "nothing")
			bmLog18(report)
			return lines, report
