		getgenv().cakeMain = function(instance)
			if not instance then
				return nil
			end

			local main = instance:FindFirstChild("Main")

			if main and main:IsA("BasePart") then
				return main
			end

			local bestVolume = -1
			local descendant2 = nil

			for _, descendant in ipairs(instance:GetDescendants()) do
				if descendant:IsA("BasePart") then
					local volume = descendant.Size.X * descendant.Size.Y * descendant.Size.Z

					if bestVolume < volume then
						bestVolume = volume
						descendant2 = descendant
					end
				end
			end

			return descendant2
		end

		getgenv().cakeVolume = function(cake)
			local main = getgenv().cakeMain(cake)

			if not main then
				return -1
			end

			return main.Size.X * main.Size.Y * main.Size.Z
		end

		local function cakesByFlavour(flavour, children)
			local wanted = flavour or getgenv().wantedCake()

			if not wanted then
				return {}
			end

			local lowerWanted = string.lower(wanted)
			local found = {}

			for _, cakeFolder in ipairs(getgenv().cakeFolders()) do
				for _, child in ipairs(cakeFolder:GetChildren()) do
					if string.lower(child.Name) == lowerWanted and not (children and children[child]) then
						local proximityPrompt = child:FindFirstChildWhichIsA("ProximityPrompt", true)

						if proximityPrompt and proximityPrompt.Enabled then
							found[#found + 1] = {cake = child, main = getgenv().cakeMain(child), prompt = proximityPrompt, vol = getgenv().cakeVolume(child)}
						end
					end
				end
			end

			table.sort(found, function(a, b)
				return a.vol > b.vol
			end)
			return found
		end

		getgenv().cakesByFlavour = cakesByFlavour

		getgenv().biggestCake = function(flavour, children)
