			local delay = tonumber(lead) or tonumber(getgenv().EKeyLead) or 0

			if delay > 0 then
				task.wait(delay)
			end

			local ok = pcall(function()
				VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.E, false, game)
			end)

			task.wait(getgenv().EKeyGap or 0.06)

			pcall(function()
				VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.E, false, game)
			end)

			return ok
		end

		do
			local clickDelay = getgenv().ClickDelay
			local clickDelay2

			clickDelay2 = clickDelay or 0.5

			getgenv().ClickDelay = clickDelay2
		end

		getgenv().waitBeforeClick = function(label)
			local delay = tonumber(getgenv().ClickDelay) or 0.5

			if delay <= 0 then
				return false
			end

			getgenv().BigMomStatus = string.format("waiting %.1fs before pressing E on %s", delay, tostring(label or "it"))
			local deadline = tick() + delay

			repeat
				task.wait(0.05)
			until not (not (tick() >= deadline or bmStale()) and getgenv().EnableBigMom)

			return true
		end

		getgenv().armSoundWatch = function(instance, soundName)
			local watch = {fired = false, sound = nil, name = soundName}

			if not instance then
				return watch
			end

			watch.conn = instance.ChildAdded:Connect(function(child)
				if child.Name == soundName then
					watch.fired = true
					watch.sound = child
				end
			end)

			return watch
		end

		getgenv().waitSoundWatch = function(watch, timeout)
			local deadline = tick() + (timeout or 8)

			while not watch.fired do
				task.wait(0.05)

				if deadline < tick() then
					break
				end
			end

			if watch.conn then
				pcall(function()
					watch.conn:Disconnect()
				end)

				watch.conn = nil
			end

			if watch.fired then
				return true
			end

			return false, string.format("no '%s' sound within %.0fs", tostring(watch.name), timeout or 8)
		end

		if getgenv().ArriveSettle == 1.5 then
			getgenv().ArriveSettle = nil
		end

		getgenv().ArriveSettle = getgenv().ArriveSettle or 1
		getgenv().ArriveSettleLog = getgenv().ArriveSettleLog ~= false
		getgenv().ArriveStrict = getgenv().ArriveStrict == true
		getgenv().ArriveSettles = getgenv().ArriveSettles or 0

		getgenv().settleAfterArrive = function(target, label, reach)
			pcall(stopTween)
			local settle = tonumber(getgenv().ArriveSettle) or 1

			if settle <= 0 then
				return true, 0
			end

			local arriveSettles = getgenv().ArriveSettles or 0
			getgenv().ArriveSettles = arriveSettles + 1
			getgenv().BigMomStatus = string.format("at %s - settling %.1fs", tostring(label or "the goal"), settle)
			local deadline = tick() + settle

			repeat
				task.wait(0.05)
			until not (not (tick() >= deadline or bmStale()) and getgenv().EnableBigMom)

			local character = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")

			local magnitude = character and target and (character.Position - target.Position).Magnitude or math.huge

			local arrived = magnitude <= (reach or 8)
			local bmLog = getgenv().ArriveSettleLog ~= false and getgenv().BMLog
			local bmLog4

			bmLog4 = bmLog and (not arrived or (getgenv().ArriveSettles or 0) % 10 == 1)

			if bmLog4 then
				local bmLog3 = getgenv().BMLog
				local labelText = tostring(label or "the goal")
				local status

				status = arrived and "still there"

				bmLog3(string.format("[Arrive] %s - stood still %.1fs before doing anything, now %.1f studs away (%s).", labelText, settle, magnitude, status or "DRIFTED off"))
			end

			if not arrived and getgenv().ArriveStrict == true then
				return false, magnitude
			end

			return true, magnitude
		end

		getgenv().goTo = function(target, label, distance)
			distance = distance or 8
			pcall(stopTween)
			getgenv().BigMomStatus = tostring(label)

			tweenToCFrame({
				CFrame = target,
				Speed = getgenv().CakeTweenSpeed or 60,
				StopDistance = distance,
				TeleportOnClose = true,
				TeleportDistance = distance
			})

			local now = tick()
			local travelTimeout = getgenv().TravelTimeout
			local deadline = now + (travelTimeout or 30)

			repeat
				task.wait(0.1)

				if bmStale() or not getgenv().EnableBigMom then
					return false, "stopped"
				end

				local humanoidRootPart = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")

				if humanoidRootPart and (humanoidRootPart.Position - target.Position).Magnitude <= distance then
					local settled, settleWhy = getgenv().settleAfterArrive(target, label, distance)

					if not settled then
						return false, string.format("drifted %d studs off %s while settling", math.floor(settleWhy or -1), tostring(label))
					end

					return true
				end
			until tick() > deadline

			local settled = false
			local labelText = tostring(label)
			local travelTimeout = getgenv().TravelTimeout
			return settled, string.format("did not reach %s within %.0fs", labelText, travelTimeout or 30)
		end

		getgenv().deliverOneCake = function(instance, instance2, flavour)
			if not (instance and instance.Parent) then
				return false, "the cake went away"
			end

			local parent

			parent = instance2 and instance2.Parent

			if not parent then
				return false, "that cake has no part to walk to"
			end

			if not flavour then
				flavour = instance.Name
			end

			getgenv().BigMomStep = "fetching " .. tostring(flavour)
			local reached, reachWhy = getgenv().goTo(CFrame.new(instance2.Position), "the cake", getgenv().CakeReachDist)

			if not reached then
				return false, tostring(reachWhy)
			end

			getgenv().BigMomStep = "picking it up"
			local cakeRetries = getgenv().CakeRetries
			cakeRetries = cakeRetries or 3
			local pickedUp = false

			for i = 1, cakeRetries do
				if not instance2.Parent then
					return false, "the cake went away"
				end

				local pickWatch = getgenv().armSoundWatch(instance2, getgenv().CakePickUpSound or "CakePickUp")

				if i > 1 then
					getgenv().waitBeforeClick("another go at the cake")
				end

				getgenv().tapE(0)
				pickedUp = getgenv().waitSoundWatch(pickWatch, (getgenv().PickUpTimeout or 8) / (getgenv().CakeRetries or 3))

				if pickedUp then
					break
				end

				getgenv().BMLog(string.format("[Cake] tap %d did not take, trying again", i))
			end

			if not pickedUp then
				return false, "pressed E but no " .. tostring(getgenv().CakePickUpSound)
			end

			getgenv().BigMomStep = "carrying it to Mama"
			local goTo = getgenv().goTo
			local cakeDropCF = getgenv().CakeDropCF
			local dropReachDist = getgenv().DropReachDist
			local dropReached, dropWhy = goTo(cakeDropCF, "the drop point", dropReachDist)

			if not dropReached then
				return false, tostring(dropWhy)
			end

			getgenv().BigMomStep = "dropping it"
			local dropped = false
			local cakeRetries = getgenv().CakeRetries or 3

			for i = 1, cakeRetries do
				local instance = instance2 and instance2.Parent and instance2 or nil

				if not instance then
					return false, "lost track of the cake"
				end

				local dropWatch = getgenv().armSoundWatch(instance, getgenv().CakeDropSound or "CakeDrop")

				if 1 < i then
					getgenv().waitBeforeClick("another go at the drop")
				end

				getgenv().tapE(0)
				local waitSoundWatch = getgenv().waitSoundWatch
				local dropTimeout = getgenv().DropTimeout or 8
				local cakeRetries3 = getgenv().CakeRetries or 3

				dropped = waitSoundWatch(dropWatch, dropTimeout / cakeRetries3)

				if dropped then
					break
				end

				getgenv().BMLog(string.format("[Cake] drop tap %d did not take, trying again", i))
			end

			if not dropped then
				return false, "pressed E but no " .. tostring(getgenv().CakeDropSound)
			end

			if getgenv().CakeDeletePrompt ~= false and instance and instance.Parent then
				local count = 0

				for _, descendant in ipairs(instance:GetDescendants()) do
					if not descendant:IsA("ProximityPrompt") then
						continue
					end

					if pcall(function()
						if false then -- never runs
							descendant:Destroy()
						end
					end) then
						count += 1
					end
				end

				if count > 0 and getgenv().BMLog then
					local bmLog = getgenv().BMLog
					bmLog(string.format("[Cake] delivered - removed %d prompt(s) from '%s' so it cannot be picked up again.", count, tostring(instance.Name)))
				end
			end

			return true
		end

		getgenv().CakeDeliverMax = getgenv().CakeDeliverMax or 6

		getgenv().deliverCake = function(flavour)
			local wanted

			wanted = flavour or getgenv().wantedCake()

			if not wanted then
				return false, 0, "nothing has been asked for"
			end

			local tried = {}
			local stopped = false
			local cakeDeliverMax = getgenv().CakeDeliverMax or 6
			local delivered = 0

			for i = 1, cakeDeliverMax do
				if bmStale() or not getgenv().EnableBigMom then
					return false, delivered, "stopped"
				end

				local nowWanted = getgenv().wantedCake()

				if nowWanted and nowWanted ~= wanted then
					getgenv().BMLog(string.format("[Cake] she switched from %s to %s mid-set after %d - taking the new order.", tostring(wanted), tostring(nowWanted), delivered))
					return delivered > 0, delivered, "flavour changed"
				end

				local cakes = getgenv().cakesByFlavour(wanted, tried)

				if #cakes == 0 and delivered == 0 then
					local count = 0

					for _, cakeFolder in ipairs(getgenv().cakeFolders()) do
						for _, child in ipairs(cakeFolder:GetChildren()) do
							if string.lower(child.Name) == string.lower(wanted) then
								count += 1
							end
						end
					end

					if not stopped then
						getgenv().BigMomStep = "waiting for the " .. tostring(wanted) .. " cakes to load in"
						stopped = true

						if getgenv().waitForCake(wanted) then
							continue
						end

						return false, 0, string.format("no '%s' in the room", tostring(wanted))
					end

					return false, 0, string.format("no '%s' in the room", tostring(wanted))
				end

				local cake = cakes[1]
				getgenv().BMLog(string.format("[Cake] %s %d/%d: taking the biggest left (volume %.1f, %d still here)", tostring(wanted), delivered + 1, delivered + #cakes, cake.vol, #cakes))
				local deliveredOk, deliverWhy = getgenv().deliverOneCake(cake.cake, cake.main, wanted)

				if not deliveredOk then
					return false, delivered, tostring(deliverWhy)
				end

				tried[cake.cake] = true
				delivered += 1
				getgenv().BigMomRuns = (getgenv().BigMomRuns or 0) + 1
				getgenv().BMLog(string.format("[Cake] delivered %s #%d (%d this session)", tostring(wanted), delivered, getgenv().BigMomRuns))
			end

			local bmLog = getgenv().BMLog
			local wantedText = tostring(wanted)
			bmLog(string.format("[Cake] stopped after %d of %s - the %d cap. Raise CakeDeliverMax if a round really is longer than that.", delivered, wantedText, getgenv().CakeDeliverMax or 6))
			return delivered > 0, delivered, "hit the delivery cap"
		end

		getgenv().CakeFloorDone = getgenv().CakeFloorDone ~= false
		getgenv().CakeFloorLeft = getgenv().CakeFloorLeft or 6
		getgenv().CakeFloorSaid = nil

		getgenv().cakesLeft = function()
			local count = 0

			for _, cakeFolder in ipairs(getgenv().cakeFolders()) do
				count += #cakeFolder:GetChildren()
			end

			return count
		end

		getgenv().cakeFloorFinished = function()
			if getgenv().CakeFloorDone == false then
				return false
			end

			local left = getgenv().cakesLeft()
			return left <= (getgenv().CakeFloorLeft or 6), left
		end

		if getgenv().CakeStageRescan == 10 then
			getgenv().CakeStageRescan = nil
		end

		getgenv().CakeStageRescan = getgenv().CakeStageRescan or 30
		getgenv().CakeStagePad = getgenv().CakeStagePad or 0

		do
			local cakeStageMaxDist = getgenv().CakeStageMaxDist
			getgenv().CakeStageMaxDist = cakeStageMaxDist or 2500
		end

		getgenv().CakeStageBoxes = getgenv().CakeStageBoxes or setmetatable({}, {__mode = "k"})

		getgenv().wholeCakeRoomsRaw = function()
			local cakeRoomPath = getgenv().CakeRoomPath or {}
			local service = Workspace

			for _, name in ipairs(cakeRoomPath) do
				service = service:FindFirstChild(name)

				if not service then
					return {}
				end
			end

			local rooms = {}

			for _, child in ipairs(service:GetChildren()) do
				if child:IsA("Model") then
					rooms[#rooms + 1] = child
				end
			end

			return rooms
		end

		getgenv().CakeRoomsFor = getgenv().CakeRoomsFor or 0.5

		do
			getgenv().CakeRoomsMemo = getgenv().CakeRoomsMemo or {}

			getgenv().wholeCakeRooms = function()
				local cakeRoomsMemo = getgenv().CakeRoomsMemo
				local now = tick()
				local list = cakeRoomsMemo.list

				if list and now - (cakeRoomsMemo.at or 0) < (getgenv().CakeRoomsFor or 0.5) then
					for _, instance in ipairs(list) do
						if not instance.Parent then
							break
						end
					end
				end

				local list = getgenv().wholeCakeRoomsRaw()
				cakeRoomsMemo.at = now
				cakeRoomsMemo.list = list
				return list
			end

			getgenv().CakeBoxGap = getgenv().CakeBoxGap or 0.05
			getgenv().CakeBoxedAt = getgenv().CakeBoxedAt or 0

			getgenv().roomBox = function(model)
				if not (model and model.Parent) then
					return nil
				end

				local cakeStageBox = getgenv().CakeStageBoxes[model]
				local now = tick()

				if cakeStageBox and now - (cakeStageBox.at or 0) < (cakeStageBox.every or getgenv().CakeStageRescan or 30) then
					return cakeStageBox.cf, cakeStageBox.size
				end

				local cakeStageBox2

				if cakeStageBox then
					local cakeBoxedAt = getgenv().CakeBoxedAt
					cakeStageBox2 = now - (cakeBoxedAt or 0) < (getgenv().CakeBoxGap or 0.05)
				else
					cakeStageBox2 = cakeStageBox
				end

				if cakeStageBox2 then
					return cakeStageBox.cf, cakeStageBox.size
				end

				getgenv().CakeBoxedAt = now

				local function getBoundingBox()
					return model:GetBoundingBox()
				end

				local boxOk, boxCF, boxSize = pcall(getBoundingBox)

				if not boxOk or not boxCF or not boxSize or boxSize.X <= 0 or boxSize.Y <= 0 or boxSize.Z <= 0 then
					if cakeStageBox then
						return cakeStageBox.cf, cakeStageBox.size
					end

					return nil
				end

				getgenv().CakeStageBoxes[model] = {at = now, cf = boxCF, size = boxSize, every = (getgenv().CakeStageRescan or 30) * (0.75 + math.random() * 0.5)}
				return boxCF, boxSize
			end

			getgenv().CakeStageFor = getgenv().CakeStageFor or 0.1
			getgenv().CakeStageStill = getgenv().CakeStageStill or 10
			local cakeStageMemo = getgenv().CakeStageMemo
			getgenv().CakeStageMemo = cakeStageMemo or {}

			getgenv().currentCakeStage = function(position)
				if not position then
					local humanoidRootPart = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")

					if not humanoidRootPart then
						return nil
					end

					position = humanoidRootPart.Position
				end

				local cakeStageMemo = getgenv().CakeStageMemo
				local now = tick()
				local memoFresh = cakeStageMemo.pos and now - (cakeStageMemo.at or 0) < (getgenv().CakeStageFor or 0.1) and (position - cakeStageMemo.pos).Magnitude < (getgenv().CakeStageStill or 3)

				if memoFresh and (cakeStageMemo.room == nil or cakeStageMemo.room.Parent) then
					return
				end

				local function remember(name, room, how, dist)
					local pos = position
					cakeStageMemo.at = now
					cakeStageMemo.pos = pos
					cakeStageMemo.name = name
					cakeStageMemo.room = room
					cakeStageMemo.how = how
					cakeStageMemo.dist = dist
					return name, room, how, dist
				end

				local cakeStagePad = getgenv().CakeStagePad or 0
				local num = tonumber(getgenv().CakeStageUp) or math.max(tonumber(getgenv().ReactRise) or 700, tonumber(getgenv().MochiDodgeRise) or 300) + 150

				local nearestDist = math.huge
				local magnitude2 = math.huge
				local smallestVolume = math.huge
				local magnitude3 = math.huge
				local magnitude4 = math.huge
				local wholeCakeRoom2 = nil
				local wholeCakeRoom3 = nil
				local wholeCakeRoom4 = nil

				for _, wholeCakeRoom in ipairs(getgenv().wholeCakeRooms()) do
					local cframe, size = getgenv().roomBox(wholeCakeRoom)

					if not (cframe and size) then
						continue
					end

					local magnitude = (position - cframe.Position).Magnitude

					if magnitude < magnitude4 then
						magnitude4 = magnitude
						wholeCakeRoom2 = wholeCakeRoom
					end

					local localPos = cframe:PointToObjectSpace(position)
					local volume = size.X * size.Y * size.Z

					if not (math.abs(localPos.X) <= size.X / 2 + cakeStagePad and math.abs(localPos.Z) <= size.Z / 2 + cakeStagePad) then
						continue
					end

					if math.abs(localPos.Y) <= size.Y / 2 + cakeStagePad then
						if volume < nearestDist then
							nearestDist = volume
							wholeCakeRoom3 = wholeCakeRoom
							magnitude2 = magnitude
						end
						continue
					end

					local above = position.Y - cframe.Position.Y

					if above > 0 and above <= size.Y / 2 + num and volume < smallestVolume then
						smallestVolume = volume
						wholeCakeRoom4 = wholeCakeRoom
						magnitude3 = magnitude
					end
				end

				if wholeCakeRoom3 then
					local rName, rRoom, rHow, rDist = remember(wholeCakeRoom3.Name, wholeCakeRoom3, "inside", magnitude2)
					return rName, rRoom, rHow, rDist
				end

				if wholeCakeRoom4 then
					local bmLog = getgenv().CakeStageUpLog ~= false and getgenv().BMLog

					if bmLog then
						local cakeStageUpSaid = getgenv().CakeStageUpSaid
						bmLog = cakeStageUpSaid ~= wholeCakeRoom4.Name
					end

					if bmLog then
						getgenv().CakeStageUpSaid = wholeCakeRoom4.Name
						local bmLog3 = getgenv().BMLog
						bmLog3(string.format("[Room] We are in the air over room %s rather than in its box - that is the dodge rise, not a different floor, so we still count as being in that room.", tostring(wholeCakeRoom4.Name)))
					end

					local rName, rRoom, rHow, rDist = remember(wholeCakeRoom4.Name, wholeCakeRoom4, "inside", magnitude3)
					return rName, rRoom, rHow, rDist
				end

				if wholeCakeRoom2 and magnitude4 <= (getgenv().CakeStageMaxDist or 2500) then
					local rName, rRoom, rHow, rDist = remember(wholeCakeRoom2.Name, wholeCakeRoom2, "nearest", magnitude4)
					return rName, rRoom, rHow, rDist
				end

				local rName, rRoom, rHow, rDist = remember(nil, nil, "outside the dungeon", magnitude4)
				return rName, rRoom, rHow, rDist
			end

			getgenv().CakeStageNames = getgenv().CakeStageNames or {["1"] = "CAKE ROOM", ["4"] = "TREASURE ROOM", ["5"] = "BIG MOM"}

			if getgenv().CakeStageNames["4"] == "PRISON" then
				getgenv().CakeStageNames["4"] = "TREASURE ROOM"
			end

			local stage5Name = getgenv().CakeStageNames["5"]

			if stage5Name == nil then
				getgenv().CakeStageNames["5"] = "BIG MOM"
			end

			getgenv().cakeStageLabel = function(roomName)
				if roomName == nil then
					return nil
				end

				return (getgenv().CakeStageNames or {})[roomName] or "ROOM " .. tostring(roomName)
			end

			getgenv().BusoFromRoom = getgenv().BusoFromRoom or "4"

			getgenv().busoAllowedNow = function()
				local busoFromRoom = getgenv().BusoFromRoom

				if busoFromRoom == false then
					return true
				end

				local roomName, _room, how = getgenv().currentCakeStage()

				if how ~= "inside" then
					return false
				end

				local num = tonumber(roomName)
				local num2 = tonumber(busoFromRoom)

				if not num or not num2 then
					return false
				end

				return num >= num2
			end

			getgenv().CampClear = getgenv().CampClear ~= false
			getgenv().CampRooms = getgenv().CampRooms or {["4"] = true, ["5"] = true}

			if getgenv().CampRooms["5"] == nil then
				getgenv().CampRooms["5"] = true
			end

			getgenv().CampRoomPad = getgenv().CampRoomPad or 0
			getgenv().CampBossOnly = getgenv().CampBossOnly or {["5"] = true}

			if getgenv().CampBossOnly["5"] == nil then
				getgenv().CampBossOnly["5"] = true
			end

			getgenv().campMobs = function(instance)
				local mobs = {}
				local npCs = Workspace:FindFirstChild("NPCs")

				if not (npCs and instance and instance.Parent) then
					return mobs
				end

				local cframe, size = getgenv().roomBox(instance)

				if not (cframe and size) then
					return mobs
				end

				local campRoomPad = getgenv().CampRoomPad or 0
				local bossOnly = (getgenv().CampBossOnly or {})[instance.Name] == true

				for _, child in ipairs(npCs:GetChildren()) do
					local humanoid = child:FindFirstChildOfClass("Humanoid")
					local npcRoot = getgenv().npcRoot and getgenv().npcRoot(child)

					if bossOnly and not (getgenv().isBigMomNPC and getgenv().isBigMomNPC(child)) then
						humanoid = nil
					end

					if humanoid and npcRoot and humanoid.Health > 0 and not (getgenv().isIgnoredNPC and getgenv().isIgnoredNPC(child)) then
						local localPos = cframe:PointToObjectSpace(npcRoot.Position)

						if math.abs(localPos.X) <= size.X / 2 + campRoomPad and math.abs(localPos.Y) <= size.Y / 2 + campRoomPad and math.abs(localPos.Z) <= size.Z / 2 + campRoomPad then
							mobs[#mobs + 1] = child
						end
					end
				end

				return mobs
			end

			getgenv().CampChaseLock = getgenv().CampChaseLock ~= false
		end

		getgenv().CampChaseAlways = getgenv().CampChaseAlways ~= false
		getgenv().CampGrace = getgenv().CampGrace or 25

		getgenv().CampEmptyDone = getgenv().CampEmptyDone ~= false

		getgenv().BossAppearMax = getgenv().BossAppearMax or 60
		getgenv().CampClearHold = getgenv().CampClearHold or 3
		getgenv().CampReach = getgenv().CampReach or 18

		getgenv().CampChaseRefire = getgenv().CampChaseRefire or 1

		getgenv().CampChaseSpeed = getgenv().CampChaseSpeed or getgenv().TweenSpeed or 65
		getgenv().CampSeen = {}
		getgenv().CampCleared = {}
		getgenv().CampSince = {}
		getgenv().CampClearAt = {}

		getgenv().campCheck = function()
			if getgenv().CampClear == false then
				return nil
			end

			local roomName, roomModel, how = getgenv().currentCakeStage()

			if how ~= "inside" or not roomName or not roomModel then
				return nil
