			if how ~= "inside" or roomName == nil then
				return false
			end

			if (getgenv().BacktrackGaveUp or {})[tostring(roomName)] then
				return false
			end

			local num = tonumber(roomName)
			local num2 = tonumber(getgenv().DeepestRoom)

			if not (num and num2) then
				return false
			end

			if num2 <= num then
				return false
			end

			return true, tostring(roomName), num, num2
		end

		getgenv().backtrackingNow = backtrackingNow
