			if how == "inside" and tonumber(roomName) then
				getgenv().OutsideSince = nil
				local num = tonumber(getgenv().DeepestRoom)

				if not num or tonumber(roomName) > num then
					getgenv().DeepestRoom = tostring(roomName)
					getgenv().DeepestAt = tick()
				end

				return
			end

			getgenv().OutsideSince = getgenv().OutsideSince or tick()
			local elapsed = tick() - (getgenv().DeathAt or 0)
			local recentlyDied = (getgenv().DeathAt or 0) > 0 and elapsed < (getgenv().DeathKeepDepth or 300)
			local forget = getgenv().DeepestRoom and not getgenv().ReturnAfterDeath and not recentlyDied

			if forget then
				local now = tick()
				forget = now - getgenv().OutsideSince >= (getgenv().BacktrackForget or 30)
			end

			if not forget then
				return
			end

			if getgenv().BMLog then
				local bmLog = getgenv().BMLog
				local backtrackForget = getgenv().BacktrackForget or 30
				local logArgs = table.pack(string.format("[Room] Out of the dungeon for %ds - forgetting that we got as far as room %s, so a fresh run starts from the top.", math.floor(backtrackForget), tostring(getgenv().DeepestRoom)))
				bmLog(table.unpack(logArgs, 1, logArgs.n))
			end

			getgenv().DeepestRoom = nil
			getgenv().BacktrackRoom = nil
		end

