			getgenv().OutOfRoomSince = getgenv().OutOfRoomSince or tick()
			local elapsed = tick() - getgenv().OutOfRoomSince
			local roomReturnGrace = getgenv().RoomReturnGrace or 3

			if elapsed < roomReturnGrace then
				getgenv().BigMomStep = string.format("outside room %s - giving it a moment", tostring(getgenv().LastInsideRoom))
				return false
			end

			if (getgenv().RoomReturnGiveUp or 60) < elapsed then
				local bmLog = getgenv().RoomReturnLog ~= false and getgenv().BMLog

				if bmLog then
					getgenv().BMLog(string.format("[Room] %.0fs outside room %s and I cannot get back in - carrying on from where I am.", elapsed, tostring(getgenv().LastInsideRoom)))
				end

				getgenv().LastInsideRoom = nil
				getgenv().OutOfRoomSince = nil
				return true
			end

			local lastInsidePos = getgenv().LastInsidePos
			local boxCF = getgenv().roomBox(lastRoom)

			if lastInsidePos and boxCF then
				local _name2, roomThere = getgenv().currentCakeStage(lastInsidePos)

				if roomThere ~= lastRoom then
