			local magnitude = instance and (instance.Position - lastInsidePos).Magnitude or -1
			getgenv().BigMomStep = string.format("outside room %s - walking back in (%.0f studs)", tostring(getgenv().LastInsideRoom), magnitude)
			local bmLog = getgenv().RoomReturnLog ~= false and getgenv().BMLog and tick() - (getgenv().LastRoomReturnLog or 0) >= 5

