		getgenv().wholeCakeLiveRaw = function()
			local instance = getgenv().wholeCakeNode()

			if not instance then
				return nil, "WholeCake is not loaded", 0, 0
			end

			local count = 0
			local count3 = 0

			pcall(function()
				for _, descendant in ipairs(instance:GetDescendants()) do
					if not descendant:IsA("ParticleEmitter") then
						continue
					end

					count3 += 1
					local enabled = true

					pcall(function()
						enabled = descendant.Enabled
					end)

					if enabled ~= false then
						count += 1
					end
				end
			end)

			if count3 == 0 then
				return nil, "no ParticleEmitter under it to read", 0, 0
			end

			if count > 0 then
				return true, string.format("%d of %d emitters are live", count, count3), count, count3
			end

			return false, string.format("all %d emitters are off", count3), 0, count3
		end

