			local descendants = {}
			local mirrorPaths = getgenv().MirrorPaths or {}

			for _, mirrorPath in ipairs(mirrorPaths) do
				local path = getgenv().resolvePath(Workspace, mirrorPath)

				if path then
					pcall(function()
						for _, descendant in ipairs(path:GetDescendants()) do
							if descendant:IsA("BasePart") and string.find(string.lower(descendant.Name), "mirror", 1, true) then
								descendants[#descendants + 1] = descendant
							end
