		getgenv().mirrorVisible = function()
			local mirrors = getgenv().mirrorParts()

			if #mirrors == 0 then
				return false, "no mirror part is loaded", nil
			end

			local transparency2 = 2
			local visiblePart = nil

			for _, mirror in ipairs(mirrors) do
				local transparency = 1

				pcall(function()
					transparency = mirror.Transparency
				end)

				if transparency < transparency2 then
					visiblePart = mirror
					transparency2 = transparency
				end
			end

			if transparency2 >= (getgenv().MirrorVisibleTol or 0.95) then
				return false, string.format("%d mirror part(s) loaded but the clearest is %.2f transparent", #mirrors, transparency2), visiblePart
			end

			return true, string.format("%s is %.2f transparent (%d loaded)", tostring(visiblePart and visiblePart.Name), transparency2, #mirrors), visiblePart
		end

