		getgenv().findTPBrickBy = function(path)
			local descendant2

			pcall(function()
				for _, descendant in ipairs(Workspace:GetDescendants()) do
					if not (descendant.Name == "TPBrick" and descendant:IsA("BasePart")) then
						continue
					end

					local fullName = string.lower(descendant:GetFullName())
					local names = path or {}
					local first = true

					for _, name in ipairs(names) do
						if not string.find(fullName, string.lower(name), 1, true) then
							first = false
							break
						end
					end

					if first then
						descendant2 = descendant
						return
					end
				end
			end)

			return descendant2
		end

		getgenv().afterBossPart = function(stage)
			local chain = (getgenv().AfterBossChain or {})[stage]

			if not chain then
				return nil
			end

			local brickCache = getgenv().BrickCache
			local path = getgenv().resolvePath(Workspace, chain.path)

			if path and path:IsA("BasePart") then
				brickCache[stage] = {part = path, at = tick(), how = "the exact path"}
				return path, chain.why, "the exact path"
			end

			local cached = brickCache[stage]

			if cached and cached.part and cached.part.Parent and tick() - (cached.at or 0) <= (getgenv().BrickCacheHold or 10) then
				return cached.part, chain.why, tostring(cached.how) .. " (held)"
			end

			local miss = cached and cached.miss

			if miss then
				local elapsed = tick() - cached.miss
				local brickScanGap = getgenv().BrickScanGap or 3

				miss = elapsed < brickScanGap
			end

			if miss then
				return nil, chain.why
			end

			local tpBrickBy = getgenv().findTPBrickBy(chain.hints)

			if not tpBrickBy then
				brickCache[stage] = {miss = tick()}
				return nil, chain.why
			end

			local how = "found by name under " .. table.concat(chain.hints or {}, " / ")
			local entry = {part = tpBrickBy}
			entry.at = tick()
			entry.how = how
			brickCache[stage] = entry
			return tpBrickBy, chain.why, how
		end

		getgenv().isMochiNPC = function(npc)
