		getgenv().mochiEmperor = function()
			local npCs = Workspace:FindFirstChild("NPCs")

			if not npCs then
				return nil
			end

			local mochiName = string.lower(getgenv().MochiName or "Mochi Emperor")

			for _, child in ipairs(npCs:GetChildren()) do
				if string.find(string.lower(child.Name), mochiName, 1, true) then
					local child5 = child:FindFirstChildOfClass("Humanoid")

					if child5 and child5.Health > 0 then
