				return true
			end

			if (tonumber(getgenv().DeepestRoom) or 0) >= 5 then
				return true
			end

			return (getgenv().BigMomSeenAt or 0) > 0 and tick() - getgenv().BigMomSeenAt <= (getgenv().BossSeenMemory or 900)
		end

		getgenv().bossFightDone = function()
			local roomName, _room, how = getgenv().currentCakeStage()
			local num = how == "inside" and tonumber(roomName) or nil
			local earlyRoom

			earlyRoom = num and num < 5

			if earlyRoom then
				return false
			end

			if (getgenv().CampCleared or {})["5"] == true then
				getgenv().noteBeaten("we cleared room 5 this run")
				return true
			end

			if getgenv().mochiEmperor() then
				getgenv().noteBeaten("the Mochi Emperor is up")
				return true
			end

			local doorOpen, doorWhy = getgenv().chateauDoorOpen()

			if doorOpen == false then
				local elapsed = tick() - (getgenv().MochiKilledAt or 0)
				local mochiKilled = (getgenv().MochiKilledAt or 0) > 0

				if mochiKilled and elapsed <= (getgenv().MochiDeadHold or 600) and not getgenv().mochiEmperor() then
					if getgenv().BMLog and tick() - (getgenv().LastDeadGateLog or 0) >= 20 then
						getgenv().LastDeadGateLog = tick()
						getgenv().BMLog(string.format("[Door] The gate is shut, but %s died %.0fs ago - that is the farm needing another run, not a farm that is finished. Waiting for it to reopen.", tostring(getgenv().MochiName), elapsed))
					end

					return false
				end

				getgenv().noteBeaten("the Cake Chateau door is shut (" .. tostring(doorWhy) .. ")")
				return true
			end

			if doorOpen == true then
				return false
			end

			if getgenv().wholeCakeLive() == true and getgenv().reachedBossThisRun() then
				return true
			end

			if getgenv().reachedBossThisRun() and not (getgenv().findBigMom and getgenv().findBigMom()) and getgenv().postBossPortalOpen and getgenv().postBossPortalOpen() then
				getgenv().noteBeaten("the post-boss portal is open")
				return true
			end

