					continue
				end

				local instance = getgenv().wholeCakeNode()
				local tpBrick = instance and instance:FindFirstChild("TPBrick")
				local found = instance ~= nil

				if found == lastFound then
					continue
				end

				local elapsed = tick() - (getgenv().BigMomBeatenAt or 0)

				if lastFound ~= nil and getgenv().BMLog then
					getgenv().BMLog(string.format("[WholeCake] Important.WholeCake %s%s | TPBrick=%s | path=%s", found and "APPEARED" or "went away", (getgenv().BigMomBeatenAt or 0) > 0 and string.format(" %.1fs after the kill", elapsed) or "", tpBrick and "present" or "MISSING", instance and instance:GetFullName() or "-"))
				end

				getgenv().WholeCakeSeen[#getgenv().WholeCakeSeen + 1] = {at = tick(), present = found, sinceKill = elapsed, brick = tpBrick ~= nil}
				lastFound = found
			end
		end)

