		getgenv().mochiExitPart = function(stage)
			local chain = (getgenv().MochiExitChain or {})[stage]

			if not chain then
				return nil
			end

			local path = getgenv().resolvePath(Workspace, chain.path)

			if path and path:IsA("BasePart") then
				getgenv().MochiExitCache[stage] = {part = path, at = tick(), how = "the exact path"}
				return path, chain.why, "the exact path"
			end

			local cached = getgenv().MochiExitCache[stage]

			if cached and cached.part and cached.part.Parent and tick() - (cached.at or 0) <= (getgenv().BrickCacheHold or 10) then
				return cached.part, chain.why, tostring(cached.how) .. " (held)"
			end

			if cached and cached.miss and tick() - cached.miss < (getgenv().BrickScanGap or 3) then
				return nil, chain.why
			end

			local tpBrickBy = getgenv().findTPBrickBy(chain.hints)

			if not tpBrickBy then
				getgenv().MochiExitCache[stage] = {miss = tick()}
				return nil, chain.why
			end

			local how = "found by name under " .. table.concat(chain.hints or {}, " / ")
			getgenv().MochiExitCache[stage] = {part = tpBrickBy, at = tick(), how = how}
			return tpBrickBy, chain.why, how
		end

		getgenv().mochiExitTick = function(_unused, root)
			local chainLen = #(getgenv().MochiExitChain or {})
			local mochiExitStage = getgenv().MochiExitStage or 1

			if chainLen < mochiExitStage then
				local gateCF, gateLabel = getgenv().bigMomStartAt()
				local magnitude

				magnitude = gateCF and (root.Position - gateCF.Position).Magnitude

				magnitude = magnitude or math.huge

				if gateCF and magnitude > (getgenv().MochiGateReach or 25) then
					getgenv().BigMomStep = string.format("out of the mirror - tweening back to %s to restart (%.0f studs)", tostring(gateLabel), magnitude)
					getgenv().BigMomBusy = true
					pcall(getgenv().goTo, gateCF, tostring(gateLabel), getgenv().MochiGateReach or 25)
					getgenv().BigMomBusy = false
					return false
				end

				local doorOpen, doorWhy = getgenv().chateauDoorOpen()
				getgenv().MochiGateSince = getgenv().MochiGateSince or tick()
				local elapsed = tick() - getgenv().MochiGateSince

				if (doorOpen ~= true) and elapsed <= (getgenv().MochiGateWait or 180) then
					getgenv().BigMomStep = string.format("at the gate - waiting for it to reopen (%s, %.0fs of %.0f)", tostring(doorWhy), elapsed, getgenv().MochiGateWait or 180)
					local bmLog = getgenv().BMLog
					local bmLog3

					if bmLog then
						local now = tick()
						local lastGateWaitLog = getgenv().LastGateWaitLog or 0
						bmLog3 = now - lastGateWaitLog >= 15
					else
						bmLog3 = bmLog
					end

					if bmLog3 then
						getgenv().LastGateWaitLog = tick()
						getgenv().BMLog(string.format("[Restart] Back at %s after the %s kill, but the gate reads %s (%s) - holding here until it opens rather than restarting onto a door we cannot use.", tostring(gateLabel), tostring(getgenv().MochiName), doorOpen == nil and "UNREADABLE" or "SHUT", tostring(doorWhy)))
					end

					return false
				end

				getgenv().MochiGateSince = nil
				local farmRestart = getgenv().farmRestart
				local mochiName = tostring(getgenv().MochiName)
				local gateText = tostring(gateLabel)
				local doorText = doorOpen == true and "OPEN" or string.format("still not open after %.0fs - restarting anyway", elapsed)

				farmRestart(string.format("%s is dead, we are back at %s and the gate is %s", mochiName, gateText, doorText))
				return true
			end

			local mochiExitSeatPos = getgenv().MochiExitSeatPos and (root.Position - getgenv().MochiExitSeatPos).Magnitude > (getgenv().AfterBossJump or 250)

			if mochiExitSeatPos then
				getgenv().MochiExitStage = mochiExitStage + 1
				getgenv().MochiExitSince = nil
				getgenv().MochiExitSeatPos = nil
				getgenv().MochiExitCache = {}
				pcall(getgenv().clearPortalKnock)

				if getgenv().BMLog then
					local bmLog = getgenv().BMLog
					local mochiExitStage3 = getgenv().MochiExitStage
					bmLog(string.format("[MochiExit] step %d teleported us - on to step %d of %d.", mochiExitStage, mochiExitStage3, chainLen + 1))
				end

				return false
			end

			local exitPart, exitLabel, exitWhy = getgenv().mochiExitPart(mochiExitStage)

			if not exitPart then
				getgenv().MochiExitSince = getgenv().MochiExitSince or tick()
				local elapsed = tick() - getgenv().MochiExitSince

				if (getgenv().MochiExitWait or 60) < elapsed then
					if getgenv().BMLog then
						getgenv().BMLog(string.format("[MochiExit] %s never loaded in %.0fs - giving up on the mirror exit and letting the run find its own way back.", tostring(exitLabel), elapsed))
					end

					getgenv().farmRestart("the mirror exit bricks never loaded")
					return true
				end

				local bigMomStep = string.format("%s is not loaded yet (%.0fs)", tostring(exitLabel), elapsed)
				getgenv().BigMomStep = bigMomStep
				return false
			end

			local exitSpot = getgenv().standAtPart(exitPart)

			if not exitSpot then
				return false
			end

			if getgenv().MochiExitSeatPos and (root.Position - getgenv().MochiExitSeatPos).Magnitude > (getgenv().AfterBossJump or 250) then
				getgenv().MochiExitStage = mochiExitStage + 1
				getgenv().MochiExitSince = nil
				getgenv().MochiExitSeatPos = nil
				getgenv().MochiExitCache = {}
				pcall(getgenv().clearPortalKnock)

				if getgenv().BMLog then
					local bmLog = getgenv().BMLog
					bmLog(string.format("[MochiExit] %s teleported us - on to step %d of %d.", tostring(exitLabel), getgenv().MochiExitStage, chainLen + 1))
				end

				return false
			end

			local magnitude = (root.Position - exitSpot.Position).Magnitude

			if getgenv().insidePart(exitPart, root.Position) then
				getgenv().MochiExitSeatPos = exitSpot.Position
				getgenv().BigMomStep = "standing on " .. tostring(exitLabel) .. ", waiting to be taken"
				getgenv().knockPortal(exitPart, exitSpot, tostring(exitLabel))
				return false
			end

			if magnitude > (getgenv().ExitSeatFrom or 22) then
				local exitApproachCF = getgenv().exitApproachCF
				local approachCF = exitApproachCF(exitPart, exitSpot, root.Position)
				local mochiName = tostring(getgenv().MochiName)
				local exitText = tostring(exitLabel)
				local bigMomStep = string.format("%s is dead - heading for %s (%.0f studs, %s)", mochiName, exitText, magnitude, tostring(exitWhy))
				getgenv().BigMomStep = bigMomStep
				pcall(getgenv().clearPortalKnock)
				getgenv().BigMomBusy = true
				local goTo = getgenv().goTo
				local floorLabel = "the floor in front of " .. tostring(exitLabel)

				if bigMomStep then
					pcall(goTo, approachCF, floorLabel, getgenv().AfterBossReach or 3)
					getgenv().BigMomBusy = false
					return false
				end
			else
				getgenv().MochiExitSeatPos = exitSpot.Position
				getgenv().BigMomStep = string.format("%.1f studs from %s - stepping onto it", magnitude, tostring(exitLabel))
				local knockPortal = getgenv().knockPortal

				if not knockPortal(exitPart, exitSpot, tostring(exitLabel)) then
					getgenv().stepTo(root, exitSpot.Position, tostring(exitLabel))
					return false
				end
			end

			return false
		end

		getgenv().MochiExitActive = false
