		getgenv().inCakeRoom = function()
			local child = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")

			if not child then
				return false
			end

			local position = child.Position
			local magnitude = (position - getgenv().CakeDropCF.Position).Magnitude

			if getgenv().InCakeRoomByStage ~= false and getgenv().currentCakeStage then
				local roomName, _room, how = getgenv().currentCakeStage(position)

				if roomName and how == "inside" then
					return true, magnitude, roomName
				end
			end

			local magnitude2 = (position - getgenv().bigMomStartAt().Position).Magnitude

			if magnitude <= (getgenv().BigMomRoomRadius or 1500) then
				return true, magnitude
			end

			return magnitude < magnitude2, magnitude
		end

