		getgenv().standAtPart = function(instance, spot)
			if not instance or not instance:IsA("BasePart") then
				return nil
			end

			spot = spot or getgenv().PartStandLift or 3
			local position = instance.Position
			return CFrame.new(position.X, math.min(position.Y, position.Y - instance.Size.Y / 2 + spot), position.Z)
		end

		getgenv().insidePart = function(instance, position, pad)
			if not (instance and instance:IsA("BasePart") and position) then
				return false
			end

			pad = pad or 0

			local ok, result = pcall(function()
				return instance.CFrame:PointToObjectSpace(position)
			end)

			if not ok or not result then
				return false
			end

			local size = instance.Size / 2
			local inside = math.abs(result.X) <= size.X + pad

			if inside then
				local y = math.abs(result.Y)
				inside = y <= (size.Y + pad)
			end

			return inside and math.abs(result.Z) <= size.Z + pad
		end

