		getgenv().learnMochiDamage = function(animId, damage, playAt)
			local noAnim = not animId

			if noAnim then
				local noReact

				noReact = noAnim or (getgenv().MochiNoReact or {})[animId]

				if noReact then
					return false
				end
			elseif animId then
				if damage <= 0 or (getgenv().MochiNoReact or {})[animId] then
					return false
				end
			end

			local mochiDmg = getgenv().MochiDmg
			local known = getgenv().MochiDmg[animId]
			mochiDmg[animId] = (known or 0) + damage

			if getgenv().MochiAutoDodge == false or getgenv().MochiDodgeAnims[animId] or getgenv().MochiBlockAnims[animId] then
				return false
			end

			if (getgenv().MochiPlays[animId] or 0) >= (getgenv().MochiAmbient or 150) then
				return false
			end

			local evidence = getgenv().MochiDamageEvidence[animId] or {hits = 0}

			if evidence.playAt ~= playAt then
				evidence.hits += 1
			end

			evidence.playAt = playAt
			getgenv().MochiDamageEvidence[animId] = evidence

			if evidence.hits < 2 then
				return false
			end

			if (getgenv().MochiDmg[animId] or 0) / math.max(getgenv().MochiPlays[animId] or 1, 1) < (getgenv().MochiAutoDodgeMin or 40) then
				return false
			end

			getgenv().MochiDodgeAnims[animId] = "Damage observed on multiple plays: " .. tostring(getgenv().MochiAnimLabels[animId] or animId)

			if getgenv().BMLog then
				getgenv().BMLog("[Mochi] Added damage-correlated dodge: " .. animId)
			end

			return true
		end

