					end
				end

				return best
			end

			getgenv().mochiShoutName = mochiShoutName
		end

		getgenv().takeMochiShout = function()
			local lastDialogue = getgenv().LastDialogue
			local dialogueType = type(lastDialogue)

			if dialogueType ~= "table" then
				return nil
			end

			local elapsed = tick() - (lastDialogue.At or 0)

			if (getgenv().MochiShoutWindow or 2) < elapsed then
				return nil
			end

			if (lastDialogue.At or 0) == (getgenv().MochiShoutUsed or 0) then
				return nil
			end

			local speaker = string.lower(tostring(lastDialogue.Character or ""))

			if not (string.find(speaker, "katakuri", 1, true) or string.find(speaker, "mochi", 1, true)) then
				return nil
			end

			local mochiShoutName = getgenv().mochiShoutName
			local shoutName = mochiShoutName(lastDialogue.Text)

			if not shoutName then
				return nil
			end

			getgenv().MochiShoutUsed = lastDialogue.At or 0
			getgenv().MochiShouts = (getgenv().MochiShouts or 0) + 1
			return shoutName
		end

		getgenv().MochiLabelVer = getgenv().MochiLabelVer or 0

