		getgenv().MochiFirstSeen = getgenv().MochiFirstSeen or {}
		getgenv().MochiNewLog = getgenv().MochiNewLog ~= false

		getgenv().noteMochiAnim = function(track)
			if getgenv().MochiSpy == false then
				return
			end

			local animation = track and track.Animation
			local mochiRecent = getgenv().animDigits(animation and animation.AnimationId)

			if not mochiRecent then
				return
			end

			if getgenv().MochiAnimNames[mochiRecent] == nil then
				local animName = "?"

				pcall(function()
					animName = tostring(animation.Name or "?")
				end)
				getgenv().MochiAnimNames[mochiRecent] = animName
				getgenv().MochiFirstSeen[mochiRecent] = tick()
				local logNew = getgenv().MochiNewLog ~= false
				local bmLog

				bmLog = logNew and getgenv().BMLog

				if bmLog then
					getgenv().BMLog(string.format("[Mochi] NEW TRACK  %-28s %s", string.sub(animName, 1, 28), mochiRecent))
				end

				if not ((getgenv().MochiPlays[mochiRecent] or 0) >= (getgenv().MochiAmbient or 150)) and (getgenv().MochiNoReact or {})[mochiRecent] == nil then
					local shout = getgenv().takeMochiShout()

					if shout then
						getgenv().MochiAnimLabels[mochiRecent] = shout

						if getgenv().BMLog then
							getgenv().BMLog(string.format("[Mochi] NAMED %s -> '%s' - a NEW track started as he shouted it. Correlation, not proof: more than one track can play during one line.", mochiRecent, shout))
						end
					end
				end
			end

			pcall(function()
				local trackLength = tonumber(track.Length) or 0

				if trackLength > 0 then
					getgenv().MochiAnimLen[mochiRecent] = trackLength
				end
			end)
			local mochiPlays = getgenv().MochiPlays
			local mochiPlay = getgenv().MochiPlays[mochiRecent] or 0
			mochiPlays[mochiRecent] = mochiPlay + 1
			local reactable = not (getgenv().MochiNoReact or {})[mochiRecent]

			if reactable and ((getgenv().MochiPlays[mochiRecent] or 0) < (getgenv().MochiAmbient or 150) or getgenv().MochiDodgeAnims[mochiRecent]) then
				local now = tick()
				getgenv().MochiRecent = mochiRecent
				getgenv().MochiRecentAt = now
			end

			local now = tick()

			if now - (getgenv().MochiSaidAt[mochiRecent] or 0) < (getgenv().MochiSpyRepeat or 3) then
				return
			end

			getgenv().MochiSaidAt[mochiRecent] = now
			local mochiPlay = getgenv().MochiPlays[mochiRecent] or 1
			local damage = getgenv().MochiDmg[mochiRecent] or 0
			local perHit = damage / math.max(mochiPlay, 1)
			local mochiDodgeAnim = getgenv().MochiDodgeAnims[mochiRecent] or getgenv().MochiBlockAnims[mochiRecent]

			local candidate = (mochiDodgeAnim or getgenv().MochiNoReact[mochiRecent]) == nil and perHit >= (getgenv().MochiCandidateDmg or 40) and mochiPlay >= 3
			local note = ""

			if candidate then
				note = "   <<< NOT IN ANY LIST - candidate to dodge"
			end

			local count = 0

			pcall(function()
				count = tonumber(track.Length) or 0
			end)

			if getgenv().BMLog then
				getgenv().BMLog(string.format("[Mochi] %s  %s  |  %s  |  %.1fs%s", tostring(getgenv().MochiAnimLabels[mochiRecent] or getgenv().MochiAnimNames[mochiRecent] or (getgenv().AnimLabels or {})[mochiRecent] or "UNKNOWN"), mochiRecent, damage > 0 and string.format("%.0f dmg/play over %d plays", perHit, mochiPlay) or string.format("no damage yet (%d plays)", mochiPlay), count, note))
			end
		end

		getgenv().mochiLabel = function(animId)
			return getgenv().MochiAnimLabels[animId] or getgenv().MochiAnimNames[animId] or (getgenv().AnimLabels or {})[animId] or "?"
		end

		getgenv().MochiMoves = function()
			local rows = {}
			local mochiPlays = getgenv().MochiPlays or {}

			for k, mochiPlay in pairs(mochiPlays) do
				local damage = getgenv().MochiDmg[k] or 0
				rows[#rows + 1] = {id = k, plays = mochiPlay, dmg = damage, per = damage / math.max(mochiPlay, 1)}
			end

			table.sort(rows, function(a, b)
				if a.per ~= b.per then
					return a.per > b.per
				end

				return a.plays > b.plays
			end)
			local lines = {}
			local rowCount = #rows
			local mochiName = tostring(getgenv().MochiName)
			local mochiCredit = getgenv().MochiCredit or 2

			do
				local values = table.pack(string.format("[Mochi] %d track(s) seen on %s | a hit is credited to the last non-ambient track started within %.1fs", rowCount, mochiName, mochiCredit))
				table.move(values, 1, values.n, 1, lines)
			end

			lines[#lines + 1] = "   dmg/play   total  plays   len   id                name"

			for _, row in ipairs(rows) do
				local ambient = row.plays >= (getgenv().MochiAmbient or 150)
				local known = (getgenv().MochiDodgeAnims[row.id] or getgenv().MochiBlockAnims[row.id] or getgenv().MochiNoReact[row.id]) ~= nil
				lines[#lines + 1] = string.format("  %8.0f  %6d  %5d  %4.1fs  %-16s  %-28s%s", row.per, math.floor(row.dmg), row.plays, (getgenv().MochiAnimLen or {})[row.id] or 0, row.id, string.sub(tostring(getgenv().mochiLabel(row.id)), 1, 28), ambient and "  <- plays constantly, ambient" or known and "  <- has a reaction" or row.dmg == 0 and "  <- never followed by damage" or row.per >= (getgenv().MochiCandidateDmg or 40) and "  <<< CANDIDATE to dodge" or "")
			end

			if #rows == 0 then
				local lineCount = #lines
				lines[lineCount + 1] = "  (nothing yet - he has to be loaded and swinging)"
			end

			lines[#lines + 1] = "   -> damage 0 means no damage observed. Correlation only: two"
			lines[#lines + 1] = "      moves that always co-occur cannot be separated this way."
			local report = table.concat(lines, "\n")

			pcall(function()
				local bigMomPrint = getgenv().BigMomPrint

				if false then -- never runs
					bigMomPrint(report)
				end
			end)
			return report
		end

		getgenv().MochiHooks = getgenv().MochiHooks or 0

		task.spawn(function()
			local obj = setmetatable({}, {__mode = "k"})
			local connections = {}
			local lastSeen = nil

			local function disconnectAll()
				for _, connection in ipairs(connections) do
					pcall(function()
						connection:Disconnect()
					end)
				end

				connections = {}
				obj = setmetatable({}, {__mode = "k"})
				lastSeen = nil
			end

			while task.wait(0.5) do
				if bmStale() then
					disconnectAll()
					break
				end

				if not getgenv().EnableBigMom then
					continue
				end

				local value = getgenv().mochiEmperor and select(1, getgenv().mochiEmperor())

				if not value then
					if lastSeen then
						disconnectAll()
					end

					continue
				end

				if lastSeen ~= value then
					disconnectAll()
					lastSeen = value
				end

				local count = 0

				for _, descendant in ipairs(value:GetDescendants()) do
					if not ((descendant:IsA("Animator") or descendant:IsA("AnimationController")) and not obj[descendant]) then
						continue
					end

					obj[descendant] = true
					count += 1

					pcall(function()
						local function onAnimationPlayed(track)
							if bmStale() or not getgenv().EnableBigMom then
								return
							end

							pcall(getgenv().noteMochiAnim, track)
							pcall(getgenv().noteBigMomReact, track)
						end

						if false then -- never runs
							connections[#connections + 1] = descendant.AnimationPlayed:Connect(onAnimationPlayed)

							for _, track in ipairs(descendant:GetPlayingAnimationTracks()) do
								onAnimationPlayed(track)
							end
						end
					end)
				end

				if 0 < count then
					getgenv().MochiHooks = (getgenv().MochiHooks or 0) + count

					if getgenv().BMLog then
						getgenv().BMLog(string.format("[Mochi] Watching '%s' - hooked %d more animator(s), %d in total. Every animation he starts is recorded with its own name; getgenv().MochiMoves() ranks them by the damage that followed.", tostring(value.Name), count, getgenv().MochiHooks))
					end
				end
			end
		end)

		task.spawn(function()
			local health2 = nil
			local child5 = nil

			while task.wait(0.1) do
				if bmStale() then
					break
				end

				local character = localPlayer.Character
				local child = character and character:FindFirstChildOfClass("Humanoid")
				local mochiEmperor = getgenv().mochiEmperor and getgenv().mochiEmperor()

				if not (getgenv().EnableBigMom and getgenv().MochiSpy ~= false and child and mochiEmperor) then
					getgenv().MochiRecent = nil
					getgenv().MochiRecentAt = 0
					health2 = nil
					child5 = nil
					continue
				end

				local health = child.Health

				if child == child5 and health2 and health < health2 - 0.5 then
					local mochiRecent = getgenv().MochiRecent

					if mochiRecent and tick() - (getgenv().MochiRecentAt or 0) <= (getgenv().MochiCredit or 2) then
						getgenv().learnMochiDamage(mochiRecent, health2 - health, getgenv().MochiRecentAt)
						health2 = health
						child5 = child
					else
						health2 = health
						child5 = child
					end
				else
					health2 = health
					child5 = child
				end
			end
		end)

		do
			local chateauDoorModelPath = getgenv().ChateauDoorModelPath
			local chateauDoorModelPath2

			chateauDoorModelPath2 = chateauDoorModelPath or {"Islands", "Whole Cake Island", "WholeCakeIsland", "Important", "CakeChateau", "Door"}

			getgenv().ChateauDoorModelPath = chateauDoorModelPath2
		end

		getgenv().ChateauDoorNode = function()
			return getgenv().resolvePath(Workspace, getgenv().ChateauDoorModelPath)
		end

		getgenv().DoorVFXLog = getgenv().DoorVFXLog ~= false

		getgenv().chateauDoorOpen = function()
			local instance = getgenv().ChateauDoorNode()

			if not instance then
				return nil, "the Chateau door is not loaded", 0, 0
			end

			local vfx = instance:FindFirstChild("VFX") or instance
			local count = 0
			local count3 = 0
			local count4 = 0
			local liveBeams = 0

			pcall(function()
				for _, descendant in ipairs(vfx:GetDescendants()) do
					local isParticleEmitter = descendant:IsA("ParticleEmitter")
					local isBeam = descendant:IsA("Beam")

					if not (isParticleEmitter or isBeam) then
						continue
					end

					local enabled = true

					pcall(function()
						enabled = descendant.Enabled
					end)

					if isParticleEmitter then
						count3 += 1

						if enabled ~= false then
							count += 1
						end
					else
						liveBeams += 1

						if enabled ~= false then
							count4 += 1
						end
					end
				end
			end)

			local liveTotal = count + count4
			local total = count3 + liveBeams

			if liveTotal > 0 then
				return true, string.format("%d of %d door VFX are live (%d/%d emitters, %d/%d beams)", liveTotal, total, count, count3, count4, liveBeams), liveTotal, total
			end

			if count3 == 0 then
				return nil, string.format("no emitters under the door to read yet (%d beams present) - still streaming in", liveBeams), 0, total
			end

			return false, string.format("all %d emitters are dark (%d beams present)", count3, liveBeams), 0, total
		end

		do
			local doorVFXLast = getgenv().DoorVFXLast
			local doorVFXLast2

			doorVFXLast2 = doorVFXLast or nil

			getgenv().DoorVFXLast = doorVFXLast2
		end

		task.spawn(function()
			while task.wait(1) do
				if bmStale() then
