				local doorVFXLast, lastWhy = getgenv().chateauDoorOpen()

				if doorVFXLast == nil then
					continue
				end

				if getgenv().DoorVFXLast ~= doorVFXLast then
					local doorVFXLast2 = getgenv().DoorVFXLast
					getgenv().DoorVFXLast = doorVFXLast

					if doorVFXLast2 ~= nil and getgenv().BMLog then
						getgenv().BMLog(string.format("[Door] The Cake Chateau gate went %s - %s. Katakuri %s.", doorVFXLast and "OPEN" or "SHUT", tostring(lastWhy), (getgenv().MochiKilledAt or 0) > 0 and string.format("died %.0fs ago", tick() - getgenv().MochiKilledAt) or "has not died this session"))
					end
				end
			end
		end)

		getgenv().ChateauDoorInfo = function()
