		getgenv().DoorRetryAfter = getgenv().DoorRetryAfter or 20
		getgenv().DoorBackoffAt = getgenv().DoorBackoffAt or 0
		getgenv().DoorWaitSaid = getgenv().DoorWaitSaid or 0

