		getgenv().CakeExitByRoom = getgenv().CakeExitByRoom or {["1"] = {"Door", "Exit", "Part"}}

		do
			local cakeExitPaths = getgenv().CakeExitPaths

			if not cakeExitPaths then
				cakeExitPaths = {}
				local defaultPath = {"Door", "Exit", "Part"}
				local paths = {}
				paths[1] = "Doors"
				paths[2] = "Exit"
				paths[3] = "Part"
