				cakeExitPaths[2] = paths
			end

			getgenv().CakeExitPaths = cakeExitPaths
		end

		getgenv().ExitViaEnterDoor = getgenv().ExitViaEnterDoor == true

		local cakeExitPaths = {}

		for _, cakeExitPath in ipairs(getgenv().CakeExitPaths) do
