				if getgenv().BMLog then
					getgenv().BMLog(string.format("[Exit] Dropping '%s' from the exit list - that is the way in, not the way to the next floor.", table.concat(cakeExitPath, ".")))
				end
			else
				cakeExitPaths[#cakeExitPaths + 1] = cakeExitPath
			end
		end

