			getgenv().DoorColourTol = getgenv().DoorColourTol or 0.12
			getgenv().DoorNeedsParticle = getgenv().DoorNeedsParticle ~= false
			getgenv().DoorNeedsPortalSound = getgenv().DoorNeedsPortalSound ~= false
			getgenv().DoorPortalSound = getgenv().DoorPortalSound or "TPPortalLoop"
			getgenv().DoorParticleClass = getgenv().DoorParticleClass or "ParticleEmitter"

			getgenv().anyBasePart = function(instance)
				if not instance then
					return nil
				end

				if instance:IsA("BasePart") then
					return instance
				end

				for _, descendant in ipairs(instance:GetDescendants()) do
					if descendant:IsA("BasePart") then
						return descendant
					end
				end

				return nil
			end

			getgenv().DoorNeonCache = getgenv().DoorNeonCache or setmetatable({}, {__mode = "k"})
			getgenv().DoorNeonRetry = getgenv().DoorNeonRetry or 2

			getgenv().doorNeonPart = function(instance)
				if not instance then
					return nil
				end

				local doorNeonCache = getgenv().DoorNeonCache
				local now = tick()
				local cached = doorNeonCache[instance]

				if cached then
					if cached.found and cached.found.Parent then
						return cached.found
					end

					if not cached.found and now - (cached.at or 0) < (getgenv().DoorNeonRetry or 2) then
						return nil
					end
				end

				local doorNeonName = getgenv().DoorNeonName or "DoorNeon"
				local found = nil

				pcall(function()
					if instance.Name == doorNeonName then
						found = getgenv().anyBasePart(instance)

						if found then
							return
						end
					end

					local parent = instance.Parent

					if parent then
						local doorNeon = parent:FindFirstChild(doorNeonName)

						if doorNeon then
							found = getgenv().anyBasePart(doorNeon)

							if found then
								return
							end
						end
					end

					local doorNeon = instance:FindFirstChild(doorNeonName, true)

					if doorNeon then
						found = getgenv().anyBasePart(doorNeon)

						if found then
							return
						end
					end

					if parent then
						local doorNeon = parent:FindFirstChild(doorNeonName, true)

						if doorNeon then
							found = getgenv().anyBasePart(doorNeon)
						end
					end
				end)

				local parts = {}
				parts.found = found or false
				parts.at = now
				doorNeonCache[instance] = parts
				return found
			end

			getgenv().colourGap = function(colourA, colourB)
				if not (colourA and colourB) then
					return math.huge
				end

				return math.sqrt((colourA.R - colourB.R) ^ 2 + (colourA.G - colourB.G) ^ 2 + (colourA.B - colourB.B) ^ 2)
			end

			getgenv().DoorReadFor = getgenv().DoorReadFor or 0.2
			local doorReadMemo = getgenv().DoorReadMemo

			if not doorReadMemo then
				local neon = {}
				local particles = {}
				particles.__mode = "k"
				doorReadMemo = setmetatable(neon, particles)
			end

			getgenv().DoorReadMemo = doorReadMemo

			getgenv().doorIsOpen = function(instance)
				if not instance then
					return false, "no part"
				end

				if getgenv().DoorOpenCheck == false then
					return true, "the check is off"
				end

				local doorReadMemo = getgenv().DoorReadMemo
				local now = tick()
				local memo = doorReadMemo[instance]

				if memo and now - memo.at < (getgenv().DoorReadFor or 0.2) then
					return memo.open, memo.why
				end

				local function decide(open, why)
					doorReadMemo[instance] = {at = now, open = open, why = why}
					return open, why
				end

				local doorNeonPart = getgenv().doorNeonPart
				local neonPart = doorNeonPart(instance)

				if neonPart then
					local colourGap = getgenv().colourGap
					local gap = colourGap(neonPart.Color, getgenv().DoorOpenColour)
					local doorColourTol = getgenv().DoorColourTol or 0.12
					local r = math.floor(neonPart.Color.R * 255 + 0.5)
					local g = math.floor(neonPart.Color.G * 255 + 0.5)
					local b = math.floor(neonPart.Color.B * 255 + 0.5)

					if gap <= doorColourTol then
						local open1, why1 = decide(true, string.format("%s is %d, %d, %d - the open colour (%.3f off)", tostring(neonPart.Name), r, g, b, gap))
						return open1, why1
					end

					local open2, why2 = decide(false, string.format("%s is %d, %d, %d, which is %.3f off the open colour (tolerance %.3f)", tostring(neonPart.Name), r, g, b, gap, doorColourTol))
					return open2, why2
				end

				if getgenv().DoorNeedsParticle == false then
					local openDefault = true
					local doorNeonName = getgenv().DoorNeonName or "DoorNeon"

					local open3, why3 = decide(openDefault, "no " .. tostring(doorNeonName) .. " and the particle check is off")
					return open3, why3
				end

				if getgenv().DoorNeedsPortalSound ~= false then
					local parent = instance.Parent

					if not (parent and parent:FindFirstChild(getgenv().DoorPortalSound or "TPPortalLoop", true)) then
						local open4, why4 = decide(false, string.format("no %s on it and no '%s' either, so it is not a way onward", tostring(getgenv().DoorNeonName or "DoorNeon"), tostring(getgenv().DoorPortalSound or "TPPortalLoop")))
						return open4, why4
					end
				end

				local doorParticleClass = getgenv().DoorParticleClass or "ParticleEmitter"
				local anyParticle = false
				local liveParticle = false

				pcall(function()
					for _, descendant in ipairs(instance:GetDescendants()) do
						if not descendant:IsA(doorParticleClass) then
							continue
						end

						anyParticle = true
						local enabled = true

						pcall(function()
							enabled = descendant.Enabled
						end)

						if enabled ~= false then
							liveParticle = true
							return
						end
					end
				end)

				if liveParticle then
					local open5, why5 = decide(true, "it has a live " .. tostring(doorParticleClass))
					return open5, why5
				end

				if anyParticle then
					local open6, why6 = decide(false, string.format("its %s is switched off", tostring(doorParticleClass)))
					return open6, why6
				end

				local open7, why7 = decide(true, string.format("no %s and no %s to read it by", tostring(getgenv().DoorNeonName or "DoorNeon"), tostring(doorParticleClass)))
				return open7, why7
			end

			getgenv().roomExitPart = function(instance)
				if not (instance and instance.Parent) then
					return nil
				end

				local paths = {}
				local cakeExitByRoom = getgenv().CakeExitByRoom or {}
				local named = cakeExitByRoom[instance.Name]

				if named then
					paths[#paths + 1] = named
				end

				local cakeExitPaths = getgenv().CakeExitPaths or {getgenv().CakeExitPath or {"Door", "Exit", "Part"}}

				for _, cakeExitPath in ipairs(cakeExitPaths) do
					paths[#paths + 1] = cakeExitPath
				end

				local iterFn, iterState, iterStart = ipairs(paths)
				local instance2 = nil
				local lastWhy = nil

				for k, path in iterFn, iterState, iterStart do
					if path[2] == "Enter" and getgenv().ExitViaEnterDoor ~= true then
						continue
					end

					local instance = instance

					for _, name in ipairs(path) do
						instance = instance and instance:FindFirstChild(name)
					end

					if not (instance and instance:IsA("BasePart")) then
						continue
					end

					local label = string.format("the exit door (%s%s)", table.concat(path, "."), named and k == 1 and ", the one named for this room" or "")
					local isOpen, openWhy = getgenv().doorIsOpen(instance)

					if isOpen then
						return instance, label
					end

					if not instance2 then
						lastWhy = string.format("%s is not open yet - %s", label, tostring(openWhy))
						instance2 = instance
					end
				end

				if instance2 then
					return nil, lastWhy, instance2
				end

				local exitPadSkipNames = getgenv().ExitPadSkipNames

				if not exitPadSkipNames then
					exitPadSkipNames = {}
					exitPadSkipNames.Spawn = true
					exitPadSkipNames.spawn = true
				end

				local exitTeleport = instance:FindFirstChild(getgenv().ExitTeleportName or "ExitTeleport")

				if exitTeleport then
					if exitTeleport:IsA("BasePart") and not exitPadSkipNames[exitTeleport.Name] then
						return exitTeleport, "the ExitTeleport pad (unverified)"
					end

					for _, child in ipairs(exitTeleport:GetChildren()) do
						if child:IsA("BasePart") and not exitPadSkipNames[child.Name] then
							return child, "the ExitTeleport pad (unverified)"
						end
					end
				end

				return nil
			end

			if getgenv().StopAtRoom == nil then
				getgenv().StopAtRoom = false
			end

			getgenv().ExitDoorDone = getgenv().ExitDoorDone ~= false
			getgenv().ExitDoorDoneHold = getgenv().ExitDoorDoneHold or 1.5
			getgenv().ExitDoorLitSince = getgenv().ExitDoorLitSince or {}

			getgenv().exitDoorSaysDone = function(instance)
				if getgenv().ExitDoorDone == false then
					return false
				end

				if not (instance and instance.Parent) then
					return false
				end

				local exitPart, exitLabel = getgenv().roomExitPart(instance)

				if not (exitPart and exitLabel and string.find(exitLabel, "exit door", 1, true)) then
					getgenv().ExitDoorLitSince[instance.Name] = nil
					return false
				end

				local findBigMom = getgenv().findBigMom and getgenv().findBigMom()

				if findBigMom and not getgenv().bossFightDone() then
					local room
					room, room = getgenv().currentCakeStage()

					if room == instance then
						getgenv().ExitDoorLitSince[instance.Name] = nil
						return false
					end
				end

				local now = getgenv().ExitDoorLitSince[instance.Name]

				if not now then
					local now3 = tick()
					getgenv().ExitDoorLitSince[instance.Name] = now3
					now = now3
				end

				local elapsed = tick() - now
				local exitDoorDoneHold = getgenv().ExitDoorDoneHold

				if elapsed < (exitDoorDoneHold or 1.5) then
					local labelText = tostring(exitLabel)
					return false, string.format("%s has read open for %.1fs of %.1f", labelText, elapsed, getgenv().ExitDoorDoneHold or 1.5)
				end

				return true, exitLabel, exitPart
			end
		end

		getgenv().ExitDoorInfo = function()
			local lines = {}
			local doneState = getgenv().ExitDoorDone == false and "OFF" or "on"
			local exitDoorDoneHold = getgenv().ExitDoorDoneHold or 1.5

			do
				local values = table.pack(string.format("[Door] the stage-done check is %s (hold %.1fs)", doneState, exitDoorDoneHold))
				table.move(values, 1, values.n, 1, lines)
			end

			local wholeCakeRooms = getgenv().wholeCakeRooms
			local rooms = wholeCakeRooms() or {}

			for _, room in ipairs(rooms) do
				local exitPart, exitLabel, exitWhy = getgenv().roomExitPart(room)
				local done, doneWhy = getgenv().exitDoorSaysDone(room)
				lines[#lines + 1] = string.format("  room %-3s done=%-5s %s", tostring(room.Name), tostring(done == true), exitPart and tostring(exitLabel) or tostring(exitWhy and exitLabel or "no exit found"))

				if doneWhy then
					lines[#lines + 1] = "        " .. tostring(doneWhy)
				end
			end

			local report = table.concat(lines, "\n")

			pcall(function()
				local bigMomPrint = getgenv().BigMomPrint

				if false then -- never runs
					bigMomPrint(report)
				end
			end)
			return report
		end

		getgenv().StopAtRoomLogged = getgenv().StopAtRoomLogged or {}

		getgenv().mayLeaveRoom = function(roomName)
			local stopAtRoom = getgenv().StopAtRoom

			if stopAtRoom == false or stopAtRoom == nil then
				return true
			end

			local num = tonumber(roomName)
			local num2 = tonumber(stopAtRoom)

			if not num or not num2 then
				return true
			end

			return num < num2
		end

		getgenv().SeatStepSpeed = getgenv().SeatStepSpeed or 200
		getgenv().SeatStepRate = getgenv().SeatStepRate or 0.03
		getgenv().SeatStepMax = getgenv().SeatStepMax or 3
		getgenv().SeatSteps = getgenv().SeatSteps or 0

		getgenv().stepTo = function(part, targetPos, label, opts)
			local parent

			parent = part and part.Parent

			if not (parent and targetPos) then
				return false
			end

			local seatStepRate = getgenv().SeatStepRate or 0.03
			opts = opts or getgenv().SeatStepSpeed or 200
			local deadline = tick() + (getgenv().SeatStepMax or 3)

			while tick() < deadline do
				if bmStale() or not getgenv().EnableBigMom then
					break
				end

				if not (part and part.Parent) then
					return false
				end

				if getgenv().firebreathMovementHeld() then
					return false
				end

				local position = part.Position
				local offset = targetPos - position

				if offset.Magnitude <= 0.5 then
					break
				end

				local distance = math.min(offset.Magnitude, opts * seatStepRate)
				local position = position + offset.Unit * distance

				pcall(function()
					part.CFrame = CFrame.new(position) * part.CFrame.Rotation
					part.AssemblyLinearVelocity = Vector3.zero
					part.AssemblyAngularVelocity = Vector3.zero
				end)

				if offset.Magnitude <= distance then
					break
				end

				task.wait(seatStepRate)
			end

			pcall(function()
				if false then -- never runs
					if not getgenv().firebreathMovementHeld() then
						part.CFrame = CFrame.new(targetPos) * part.CFrame.Rotation
					end

					part.AssemblyLinearVelocity = Vector3.zero
					part.AssemblyAngularVelocity = Vector3.zero
				end
			end)
			return true
		end

		getgenv().PortalKnock = getgenv().PortalKnock ~= false

		getgenv().PortalKnockAfter = getgenv().PortalKnockAfter or 2
		getgenv().PortalKnockRate = getgenv().PortalKnockRate or 0.8
		getgenv().PortalKnockOut = getgenv().PortalKnockOut or 8

		getgenv().PortalKnockHold = getgenv().PortalKnockHold or 0.15

		getgenv().PortalKnockLog = getgenv().PortalKnockLog ~= false
		getgenv().PortalKnocks = getgenv().PortalKnocks or 0
		getgenv().PortalWaitOn = nil
		getgenv().PortalWaitSince = nil
		getgenv().LastPortalKnock = 0

		getgenv().clearPortalKnock = function()
			getgenv().PortalWaitOn = nil
			getgenv().PortalWaitSince = nil
		end

		getgenv().knockPortal = function(instance, spot, label)
			if getgenv().PortalKnock == false then
				return false
			end

			if not (instance and instance.Parent and spot) then
				return false
			end

			local character = localPlayer.Character
			local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")

			if not humanoidRootPart then
				return false
			end

			if getgenv().firebreathMovementHeld() then
				return false
			end

			local portalWaitOn = tostring(label or instance:GetFullName())

			if getgenv().PortalWaitOn ~= portalWaitOn then
				local now = tick()
				getgenv().PortalWaitOn = portalWaitOn
				getgenv().PortalWaitSince = now
				return false
			end

			local now = tick()
			local portalWaitSince = getgenv().PortalWaitSince
			local portalWaitSince2

			portalWaitSince2 = portalWaitSince or tick()

			local elapsed = now - portalWaitSince2

			if elapsed < (getgenv().PortalKnockAfter or 2) then
				return false
			end

			if tick() - (getgenv().LastPortalKnock or 0) < (getgenv().PortalKnockRate or 0.8) then
				return false
			end

			getgenv().LastPortalKnock = tick()
			local portalKnocks = getgenv().PortalKnocks or 0
			getgenv().PortalKnocks = portalKnocks + 1
			local size = instance.Size / 2
			local lookVector = instance.CFrame.LookVector
			local z = size.Z

			if size.X < z then
				lookVector = instance.CFrame.RightVector
				z = size.X
			end

			if size.Y < z then
				lookVector = instance.CFrame.UpVector
				z = size.Y
			end

			local outDist = z + (getgenv().PortalKnockOut or 8)
			local side = getgenv().PortalKnocks % 2 == 0 and 1 or -1

			local function stepToward(position)
				local stepTo = getgenv().stepTo
				return stepTo(humanoidRootPart, position, "the portal knock")
			end

			pcall(stopTween)
			stepToward(spot.Position + lookVector * outDist * side)
			task.wait(getgenv().PortalKnockHold or 0.15)

			if instance and instance.Parent then
				stepToward(spot.Position)

				if getgenv().PortalKnockLog ~= false and getgenv().BMLog and getgenv().PortalKnocks % 5 == 1 then
					getgenv().BMLog(string.format("[Exit] %.0fs sitting in %s and it has not taken us - stepping %d studs out and back in so the trigger fires again (x%d).", elapsed, portalWaitOn, math.floor(outDist), getgenv().PortalKnocks))
				end

				return true
			end

			return true
		end

		getgenv().ExitApproach = getgenv().ExitApproach or 8
		getgenv().ExitSeatFrom = getgenv().ExitSeatFrom or 22

		getgenv().exitApproachCF = function(exitPart, spot, fromPos)
			if not (exitPart and spot) then
				return spot
			end

			if not fromPos then
				return spot
			end

			local size = exitPart.Size / 2
			local lookVector = exitPart.CFrame.LookVector
			local z = size.Z

			if size.X < z then
				lookVector = exitPart.CFrame.RightVector
				z = size.X
			end

			if size.Y < z then
				lookVector = exitPart.CFrame.UpVector
				z = size.Y
			end

			local side = (fromPos - spot.Position):Dot(lookVector) >= 0 and 1 or -1
			local approachDist = z + (getgenv().ExitApproach or 8)
			return CFrame.new(spot.Position + lookVector * approachDist * side), approachDist
		end

		getgenv().ExitOnlyFromHere = getgenv().ExitOnlyFromHere ~= false
		getgenv().ExitSeatMax = getgenv().ExitSeatMax or 15

		getgenv().ExitRetryAfter = getgenv().ExitRetryAfter or 45

		getgenv().ExitBlocked = getgenv().ExitBlocked or {}
		getgenv().ExitSeatOn = nil
		getgenv().ExitSeatCount = 0

		getgenv().noteExitSeat = function(exitSeatOn, roomName)
			if getgenv().ExitSeatOn ~= exitSeatOn then
				getgenv().ExitSeatOn = exitSeatOn
				getgenv().ExitSeatCount = 0
			end

			getgenv().ExitSeatCount = (getgenv().ExitSeatCount or 0) + 1

			if getgenv().ExitSeatCount < (getgenv().ExitSeatMax or 15) then
				return false
			end

			getgenv().ExitBlocked[tostring(roomName)] = tick()
			getgenv().ExitSeatOn = nil
			getgenv().ExitSeatCount = 0

			if getgenv().BMLog then
				getgenv().BMLog(string.format("[Exit] Stood on '%s' %d times and room %s has not let us out - it is not the way out. Leaving it alone for %ds and solving the room instead.", tostring(exitSeatOn), getgenv().ExitSeatMax or 15, tostring(roomName), getgenv().ExitRetryAfter or 45))
			end

			return true
		end

		do
			local function exitIsBlocked(roomName)
				local blocked = (getgenv().ExitBlocked or {})[tostring(roomName)]

				if not blocked then
					return false
				end

				if not (tick() - blocked < (getgenv().ExitRetryAfter or 45)) then
					getgenv().ExitBlocked[tostring(roomName)] = nil
					return false
				end

				return true
			end

			getgenv().exitIsBlocked = exitIsBlocked
		end

		getgenv().cakeExitPart = function()
			local _name, room, how = getgenv().currentCakeStage()

			if getgenv().ExitOnlyFromHere ~= false and how ~= "inside" then
				return nil, "we are not inside a room, so there is no exit of ours to take"
			end

			if room and getgenv().exitIsBlocked(room.Name) then
				return nil, string.format("room %s's exit did not take us, so it is parked for now", tostring(room.Name))
			end

			if room then
				local exitPart, exitLabel, exitWhy = getgenv().roomExitPart(room)

				if exitPart then
					return exitPart, exitLabel .. " in room " .. tostring(room.Name)
				end

				if exitWhy then
					return nil, tostring(exitLabel) .. " in room " .. tostring(room.Name), exitWhy
				end

				if getgenv().ExitOnlyFromHere ~= false then
					return nil, string.format("room %s has no exit door I can find", tostring(room.Name))
				end
			end

			local roomExitPart = getgenv().roomExitPart
			local exitPart, exitLabel = roomExitPart(getgenv().cakeStageRoom())

			if exitPart then
				return exitPart, exitLabel
			end

			local rooms = table.pack(getgenv().wholeCakeRooms())

			for _, room in ipairs(table.unpack(rooms, 1, rooms.n)) do
				local exitPart, exitLabel = getgenv().roomExitPart(room)

				if exitPart then
					return exitPart, exitLabel .. " in room " .. tostring(room.Name)
				end
			end

			return nil
		end

		getgenv().DoorInfo = function()
			local doorOpenColour = getgenv().DoorOpenColour
			local lines = {}
			local red = math.floor(doorOpenColour.R * 255 + 0.5)
			local g = math.floor(doorOpenColour.G * 255 + 0.5)
			local b = math.floor(doorOpenColour.B * 255 + 0.5)
			local doorColourTol = getgenv().DoorColourTol or 0.12
			local checkOff = getgenv().DoorOpenCheck == false
			local offText

			offText = checkOff and "OFF"

			local checkText = offText or "on"

			do
				local values = table.pack(string.format("[Door] open colour %d, %d, %d | tolerance %.3f | check %s", red, g, b, doorColourTol, checkText))
				table.move(values, 1, values.n, 1, lines)
			end

			local roomName, roomModel = getgenv().currentCakeStage()
			lines[#lines + 1] = "  standing in room " .. tostring(roomName or "?")

			for _, wholeCakeRoom in ipairs(getgenv().wholeCakeRooms()) do
				local cakeExitPaths = getgenv().CakeExitPaths or {}

				for _, cakeExitPath in ipairs(cakeExitPaths) do
					local wholeCakeRoom2 = wholeCakeRoom

					for _, name in ipairs(cakeExitPath) do
						wholeCakeRoom2 = wholeCakeRoom2 and wholeCakeRoom2:FindFirstChild(name)
					end

					if wholeCakeRoom2 and wholeCakeRoom2:IsA("BasePart") then
						local isOpen, openWhy = getgenv().doorIsOpen(wholeCakeRoom2)
						lines[#lines + 1] = string.format("   room %-3s %-24s %s  %s%s", tostring(wholeCakeRoom.Name), table.concat(cakeExitPath, "."), isOpen and "OPEN " or "shut ", tostring(openWhy), wholeCakeRoom == roomModel and "   <- here" or "")
					end
				end
			end

			if #lines == 2 then
				lines[#lines + 1] = "   no door part matched any of the known paths"
			end

			local report = table.concat(lines, "\n")

			pcall(function()
				getgenv().BigMomPrint(report)
			end)
			return report
		end

		getgenv().BookHintName = getgenv().BookHintName or "Hint:Book"
		getgenv().BookColorName = getgenv().BookColorName or "Recolorable"

		getgenv().BookChoicesName = getgenv().BookChoicesName or "Interactables"
		getgenv().BookColorTol = getgenv().BookColorTol or 0.08
		getgenv().BookAmbiguous = getgenv().BookAmbiguous or 0.05
		getgenv().BookReachDist = getgenv().BookReachDist or 6
		getgenv().BookPuzzle = getgenv().BookPuzzle ~= false
		getgenv().BookLog = getgenv().BookLog ~= false

		getgenv().firstBasePart = function(instance)
			if not instance then
				return nil
			end

			if instance:IsA("BasePart") then
				return instance
			end

			for _, descendant in ipairs(instance:GetDescendants()) do
				if descendant:IsA("BasePart") then
					return descendant
				end
			end

			return nil
		end

		getgenv().biggestBasePart = function(instance)
			if not instance then
				return nil
			end

			if instance:IsA("BasePart") then
				return instance
			end

			local bestVolume = -1
			local descendant2 = nil

			for _, descendant in ipairs(instance:GetDescendants()) do
				if descendant:IsA("BasePart") then
					local volume = descendant.Size.X * descendant.Size.Y * descendant.Size.Z

					if bestVolume < volume then
						bestVolume = volume
						descendant2 = descendant
					end
				end
			end

			return descendant2
		end

		getgenv().recolorablePart = function(instance)
			if not instance then
				return nil
			end

			local bookColorName = getgenv().BookColorName or "Recolorable"

			if instance.Name == bookColorName then
				return getgenv().firstBasePart(instance), bookColorName .. " itself"
			end

			local bookColor = instance:FindFirstChild(bookColorName)

			if bookColor then
				return getgenv().firstBasePart(bookColor), "its " .. bookColorName
			end

			local bookColor = instance:FindFirstChild(bookColorName, true)

			if bookColor then
				return getgenv().firstBasePart(bookColor), "a nested " .. bookColorName
			end

			return getgenv().biggestBasePart(instance), "its biggest part - no " .. bookColorName
		end

		getgenv().bookHintNode = function(instance)
			if not instance then
				return nil
			end

			local bookHint = instance:FindFirstChild(getgenv().BookHintName or "Hint:Book")

			if bookHint then
				return bookHint
			end

			for _, child in ipairs(instance:GetChildren()) do
				if string.find(string.lower(child.Name), "hint", 1, true) then
					return child
				end
			end

			return nil
		end

		getgenv().bookSubRooms = function()
			local room
			room, room = getgenv().currentCakeStage()
			local wholeCakeRooms = {}

			if room then
				wholeCakeRooms[#wholeCakeRooms + 1] = room
			else
				for _, wholeCakeRoom in ipairs(getgenv().wholeCakeRooms()) do
					wholeCakeRooms[#wholeCakeRooms + 1] = wholeCakeRoom
				end
			end

			local subRooms = {}

			for _, wholeCakeRoom in ipairs(wholeCakeRooms) do
				for _, child in ipairs(wholeCakeRoom:GetChildren()) do
					if getgenv().bookHintNode(child) and child:FindFirstChild(getgenv().BookChoicesName or "Interactables") then
						subRooms[#subRooms + 1] = child
					end
				end
			end

			return subRooms
		end

		getgenv().bookSubRoom = function()
			local subRooms = getgenv().bookSubRooms()

			if #subRooms == 0 then
				return nil
			end

			local humanoidRootPart = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")

			if humanoidRootPart then
				local magnitude2 = math.huge
				local iterFn, iterState, iterStart = ipairs(subRooms)
				local model2 = nil

				for _, model in iterFn, iterState, iterStart do
					local function getBoundingBox()
						return model:GetBoundingBox()
					end

					local boxOk, cframe, boxSize = pcall(getBoundingBox)

					if not (boxOk and cframe and boxSize and boxSize.X > 0) then
						continue
					end

					local localPos = cframe:PointToObjectSpace(humanoidRootPart.Position)

					if math.abs(localPos.X) <= boxSize.X / 2 and math.abs(localPos.Y) <= boxSize.Y / 2 and math.abs(localPos.Z) <= boxSize.Z / 2 then
						local magnitude = (humanoidRootPart.Position - cframe.Position).Magnitude

						if magnitude < magnitude2 then
							model2 = model
							magnitude2 = magnitude
						end
					end
				end

				if model2 then
					return model2, "the one I am standing in"
				end

				local magnitude3 = math.huge
				local iterFn2, iterState2, iterStart2 = ipairs(subRooms)
				local instance2 = nil

				for _, instance in iterFn2, iterState2, iterStart2 do
					local spawn_ = instance:FindFirstChild("Spawn")
					local position

					if spawn_ and spawn_:IsA("BasePart") then
						position = spawn_.Position
					else
						local function getPivot()
							return instance:GetPivot()
						end

						local ok, result = pcall(getPivot)
						ok = ok and result
						position = nil

						if ok then
							position = result.Position
						end
					end

					if position then
						local magnitude = (humanoidRootPart.Position - position).Magnitude

						if magnitude < magnitude3 then
							instance2 = instance
							magnitude3 = magnitude
						end
					end
				end

				if instance2 then
					return instance2, string.format("nearest by its Spawn, %.0f studs", magnitude3)
				end
			end

			return subRooms[1], "the first with a hint"
		end

		getgenv().BookHintPartNames = getgenv().BookHintPartNames or {"Recolorable", "Hint"}

		getgenv().bookHintColor = function(subRoom)
			subRoom = subRoom or getgenv().bookSubRoom()

			if not subRoom then
				return nil
			end

			local instance = getgenv().bookHintNode(subRoom)

			if not instance then
				return nil, nil, "no hint node in " .. tostring(subRoom.Name), subRoom
			end

			local descendants = {}

			if instance:IsA("BasePart") then
				descendants[1] = instance
			end

			for _, descendant in ipairs(instance:GetDescendants()) do
				if descendant:IsA("BasePart") then
					descendants[#descendants + 1] = descendant
				end
			end

			if #descendants == 0 then
				return nil, nil, "the hint has no BasePart to read a colour off", subRoom
			end

			local bookHintPartNames = getgenv().BookHintPartNames or {}

			for _, bookHintPartName in ipairs(bookHintPartNames) do
				for _, descendant in ipairs(descendants) do
					if descendant.Name == bookHintPartName then
						return descendant.Color, descendant, "a part named " .. bookHintPartName, subRoom
					end
				end
			end

			local colours = {}
			local seen = {}
			local count = 0

			for _, descendant in ipairs(descendants) do
				local color = descendant.Color
				local colourKey = string.format("%.3f,%.3f,%.3f", color.R, color.G, color.B)
				colours[colourKey] = (colours[colourKey] or 0) + 1
				seen[colourKey] = seen[colourKey] or descendant

				if colours[colourKey] > count then
					count = colours[colourKey]
				end
			end

			local mainPart = getgenv().biggestBasePart(instance)

			if not mainPart then
				return nil, nil, "the hint has no BasePart to read a colour off", subRoom
			end

			return mainPart.Color, mainPart, "its biggest part - nothing better to go on", subRoom
		end

		getgenv().bookChoices = function(instance)
			if not instance then
				local bookSubRoom = getgenv().bookSubRoom
				instance = bookSubRoom()
			end

			if not instance then
				return {}
			end

			local bookChoices = instance:FindFirstChild(getgenv().BookChoicesName or "Interactables")

			if not bookChoices then
				return {}
			end

			local hint = getgenv().bookHintColor(instance)

			local function colourDist(color)
				if not hint then
					return math.huge
				end

				return math.sqrt(((color.R - hint.R) ^ 2 + (color.G - hint.G) ^ 2) + (color.B - hint.B) ^ 2)
			end

			local choices = {}

			for _, child in ipairs(bookChoices:GetChildren()) do
				local bestDist = math.huge
				local bookColor = child:FindFirstChild(getgenv().BookColorName or "Recolorable", true)
				bookColor = bookColor and getgenv().firstBasePart(bookColor) or nil
				local bestName

				if bookColor then
					bestDist = colourDist(bookColor.Color)
					bestName = "its Recolorable"
				else
					local count = 0
					local descendants = child:IsA("BasePart") and {child} or child:GetDescendants()
					bookColor = nil

					for _, descendant in ipairs(descendants) do
						if descendant:IsA("BasePart") then
							count += 1
							local dist = colourDist(descendant.Color)

							if not bookColor or dist < bestDist then
								bookColor = descendant
								bestDist = dist
							end
						end
					end

					bestName = string.format("closest of its %d parts", count)
				end

				if bookColor then
					choices[#choices + 1] = {model = child, part = bookColor, colour = bookColor.Color, dist = bestDist, how = bestName}
				end
			end

			table.sort(choices, function(a, b)
				local dist = a.dist
				local dist2 = b.dist

				if false then -- never runs
					return dist < dist2
				end
			end)
			return choices, hint, instance
		end

		getgenv().BookTouchName = getgenv().BookTouchName or "Part"

		getgenv().bookTouchPart = function(instance)
			if not instance then
				return nil
			end

			if instance:IsA("BasePart") then
				return instance, "the model itself"
			end

			local bookTouchName = getgenv().BookTouchName or "Part"
			local bookTouch = instance:FindFirstChild(bookTouchName)

			if bookTouch and bookTouch:IsA("BasePart") then
				return bookTouch, "its '" .. bookTouchName .. "'"
			end

			local bookTouch = instance:FindFirstChild(bookTouchName, true)

			if bookTouch and bookTouch:IsA("BasePart") then
				return bookTouch, "a nested '" .. bookTouchName .. "'"
			end

			return getgenv().biggestBasePart(instance), "its biggest part"
		end

		getgenv().BookExitNames = getgenv().BookExitNames or {"Exit"}

		getgenv().bookMatch = function(subRoom)
			local choices, hint, room = getgenv().bookChoices(subRoom)

			if not hint then
				local iterFn, iterState, iterStart = ipairs(choices or {})

				for _, choice in iterFn, iterState, iterStart do
					local bookExitNames = getgenv().BookExitNames or {}

					for _, bookExitName in ipairs(bookExitNames) do
						if string.lower(choice.model.Name) == string.lower(bookExitName) then
							if getgenv().BookLog ~= false and getgenv().BMLog then
								getgenv().BMLog(string.format("[Book] %s has no hint colour and a choice called '%s' - taking it as the way out.", tostring(room and room.Name or "this room"), tostring(choice.model.Name)))
							end

							return choice.model, 0, choices, nil, room
						end
					end
				end

				return nil, nil, choices, nil, room
			end

			local best = choices[1]

			if not best or best.dist == math.huge then
				return nil, nil, choices, hint, room
			end

			local dist = best.dist

			if (getgenv().BookColorTol or 0.08) < dist then
				return nil, best.dist, choices, hint, room
			end

			local second = choices[2]
			local clear

			clear = second and second.dist - best.dist < (getgenv().BookAmbiguous or 0.05)

			if clear and getgenv().BookLog ~= false and getgenv().BMLog then
				local dist2 = best.dist
				getgenv().BMLog(string.format("[Book] '%s' (%.3f off) and '%s' (%.3f off) are nearly the same distance from the hint colour - taking the closer one, but this is close to a coin toss.", tostring(best.model.Name), dist2, tostring(second.model.Name), second.dist))
			end

			return best.model, best.dist, choices, hint, room
		end

		getgenv().BookInfo = function()
			local subRoom, subWhy = getgenv().bookSubRoom()

			if not subRoom then
				bmLog18("[Book] no sub-room with both a hint and an " .. tostring(getgenv().BookChoicesName or "Interactables") .. " folder - either we are not in the book room, or the names are not what I assumed. Check BookHintName / BookChoicesName.")
				return
			end

			local hint, instance, hintWhy = getgenv().bookHintColor(subRoom)
			local choices = getgenv().bookChoices(subRoom)
			local lines = {string.format("[Book] sub-room '%s' (%s)", subRoom.Name, tostring(subWhy))}
			local idx1 = #lines + 1

			if hint then
				hint = string.format("  hint colour %.3f, %.3f, %.3f   read off %s (%s)", hint.R, hint.G, hint.B, instance and instance:GetFullName():gsub(".*" .. subRoom.Name .. "%.", "") or "?", tostring(hintWhy))
			end

			lines[idx1] = hint or "  hint colour: UNREADABLE - " .. tostring(hintWhy)
			local idx2 = #lines + 1
			lines[idx2] = string.format("  %d choice(s), closest first:", #choices)

			for i, choice in ipairs(choices) do
				lines[#lines + 1] = string.format("   %d. %-22s %.3f, %.3f, %.3f   %s  (%s)", i, tostring(choice.model.Name), choice.colour.R, choice.colour.G, choice.colour.B, choice.dist == math.huge and "no hint to compare" or string.format("%.4f off", choice.dist), tostring(choice.how))
			end

			local match, matchDist = getgenv().bookMatch(subRoom)
			local idx3 = (#lines) + 1

			if match then
				match = string.format("  -> would walk to '%s' (%.4f off, tolerance %.3f)", match.Name, matchDist or -1, getgenv().BookColorTol or 0.08)
			end

			lines[idx3] = match or string.format("  -> NO match within %.3f%s", getgenv().BookColorTol or 0.08, matchDist and string.format(" (closest was %.4f off)", matchDist) or "")
			local report = table.concat(lines, "\n")
			bmLog18(report)
			return report
		end

		getgenv().SoulOrbPuzzle = getgenv().SoulOrbPuzzle ~= false

		do
			local orbPath = getgenv().OrbPath or {"Interactables", "CenterTree", "Orbs", "Orb", "Orb"}

			getgenv().OrbPath = orbPath
		end

		getgenv().FlowerPath = getgenv().FlowerPath or {"Interactables", "Minigame", "Small Flowers"}

		do
			local orbPalette = getgenv().OrbPalette

			if not orbPalette then
				local white = {name = "WHITE", colour = Color3.fromRGB(255, 255, 255)}
				local yellow = {name = "Yellow", colour = Color3.fromRGB(255, 176, 0)}
				local pink = {name = "Pink", colour = Color3.fromRGB(255, 111, 255)}
