		getgenv().isOrbPing = function(sound)
			if not sound or sound.ClassName ~= "Sound" then
				return false
			end

			if sound.Name == (getgenv().OrbPingName or "Ping") then
				return true
			end

			local pingId = tostring(getgenv().OrbPingId or "")

			if pingId ~= "" then
				local soundId = tostring(sound.SoundId or "")

				if soundId == pingId then
					return true
				end

				local pingDigits = string.match(pingId, "%d+")

				if pingDigits and string.find(soundId, pingDigits, 1, true) then
					return true
				end
			end

			return false
		end

