			getgenv().LastOrbPing = now
			getgenv().OrbPingHeard = (getgenv().OrbPingHeard or 0) + 1
			local orbPingQueue = getgenv().OrbPingQueue
			orbPingQueue[#orbPingQueue + 1] = now
			return true
		end

