		getgenv().orbColourName = function(colour)
			local bestDist = math.huge
			local iterFn, iterState, iterStart = ipairs(getgenv().OrbPalette or {})
			local name = nil

			for _, entry in iterFn, iterState, iterStart do
				local dist = math.sqrt((colour.R - entry.colour.R) ^ 2 + (colour.G - entry.colour.G) ^ 2 + (colour.B - entry.colour.B) ^ 2)

				if dist < bestDist then
					name = entry.name
					bestDist = dist
				end
			end

			return name, bestDist
		end

		getgenv().flowerFor = function(name, flowers)
			local instance = flowers or getgenv().soulFlowers()

			if not (instance and name) then
