			local child = instance:FindFirstChild(name)
			local how = "by name"

			if not child then
				local orbPalette = getgenv().OrbPalette or {}
				local colour = nil

				for _, entry in ipairs(orbPalette) do
					if entry.name == name then
						colour = entry.colour
						break
					end

					colour = nil
				end

				if colour then
					local bestDist = math.huge
					child = nil

					for _, child5 in ipairs(instance:GetChildren()) do
						local bookColor = child5:FindFirstChild(getgenv().BookColorName or "Recolorable", true)
						bookColor = bookColor and getgenv().firstBasePart(bookColor)

						if bookColor then
							local color = bookColor.Color
							local dist = math.sqrt((color.R - colour.R) ^ 2 + (color.G - colour.G) ^ 2 + (color.B - colour.B) ^ 2)

							if dist < bestDist then
								bestDist = dist
								child = child5
							end
						end
					end

					how = "by its Recolorable colour"
				end
			end

			if not child then
				return nil
			end

			local bookTouch = child:FindFirstChild(getgenv().BookTouchName or "Part")

			if not (bookTouch and bookTouch:IsA("BasePart")) then
				local biggestBasePart = getgenv().biggestBasePart
				bookTouch = biggestBasePart(child)
