				if getgenv().FlowerCamLook == false or not (instance and instance.Parent) then
					return getgenv().tapE(0)
				end

				prompt = prompt or instance.Parent
				local currentCamera = Workspace.CurrentCamera
				local child = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
				local instance2 = getgenv().flowerPrompt(instance, prompt)
				local instance3 = instance2 and getgenv().promptWorldPos(instance2) or instance.Position

				if not (currentCamera and child) then
					return getgenv().tapE(0)
				end

				local vector = Vector3.new(instance3.X - child.Position.X, 0, instance3.Z - child.Position.Z)
				local cframe = CFrame.lookAt(child.Position - (vector.Magnitude > 0.1 and vector.Unit or child.CFrame.LookVector) * (getgenv().FlowerCamBack or 8) + Vector3.new(0, getgenv().FlowerCamUp or 4, 0), instance3)
				local cameraType = currentCamera.CameraType

				local function onRenderStepped()
					local function aimCamera()
						currentCamera.CFrame = cframe
					end

					if false then -- never runs
						pcall(aimCamera)
					end
				end

				pcall(function()
					currentCamera.CameraType = Enum.CameraType.Scriptable
				end)
				onRenderStepped()
