						currentCamera.CameraType = cameraType
					end
				end)

				if getgenv().BMLog then
					getgenv().BMLog(string.format("[Orb] Camera on %s's prompt (%s) for the E press.", tostring(label or instance.Name), instance2 and instance2:GetFullName() or "no prompt found, aimed at the part"))
