					local magnitude = humanoidRootPart and (humanoidRootPart.Position - instance.Position).Magnitude or math.huge
					local sameAsLast = lastColour ~= nil and lastColour == colour

					local heldFor = 0

					if not (now4 > 0) then
						if bmStale() or not getgenv().EnableBigMom then
							break
						end

						if (getgenv().FlowerReach or 10) + 2 < magnitude then
							getgenv().BigMomStep = string.format("soul orbs %d/%d - walking to the %s sunflower", i, #pattern, tostring(colour))
							local goTo = getgenv().goTo
							local spot = getgenv().standAtPart(instance)
							local flowerLabel = "the " .. tostring(colour) .. " sunflower"
							local flowerReach = getgenv().FlowerReach or 10

							pcall(goTo, spot, flowerLabel, flowerReach)
							local humanoidRootPart = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
							magnitude = humanoidRootPart and (humanoidRootPart.Position - instance.Position).Magnitude or math.huge
						else
							local waitBeforeClick = getgenv().waitBeforeClick
							waitBeforeClick(string.format("the %s sunflower", tostring(colour)))
						end

						if bmStale() or not getgenv().EnableBigMom then
