							bmLog(string.format("[Orb] %5.1fs  %d/%d  E on the %s sunflower at %.1f studs%s.", tick() - now, i, #pattern, tostring(colour), magnitude, heldFor > 0 and string.format(" (held %.1fs first%s)", heldFor, sameAsLast and ", same flower twice" or "") or ""))
						end

						lastColour = colour
