					how = how and tostring(flowerDist) .. ", stand at " .. (character and character.Name or "?") or "NOT FOUND"
					local character4 = character and character3

					if character4 then
						character = character3.Position - character.Position
						character4 = string.format(" (%.0f studs)", character.Magnitude)
					end

					lines[idx] = string.format("  %-7s %s%s", name3, how, character4 or "")
