		getgenv().orbAnswerNow = function(pattern, label)
			local count = #pattern

			if (getgenv().OrbFinalLength or 4) <= count then
				getgenv().OrbSolved = true
				getgenv().OrbSolvedAt = tick()

				if getgenv().BMLog then
					getgenv().BMLog(string.format("[Orb] that was a %d-colour round, which is the last one - treating the minigame as WON and heading for the door without waiting for her to say so.", #pattern))
				end
			end

			getgenv().OrbPattern = {}
			getgenv().OrbRounds = (getgenv().OrbRounds or 0) + 1

			if getgenv().BMLog then
