				bmLog(string.format("[Orb] %s - answering %d: %s", tostring(label), #pattern, table.concat(pattern, " -> ")))
			end

			getgenv().BigMomBusy = true
			local cakeTweenSpeed = getgenv().CakeTweenSpeed
			local ran, answered, pressedCount, total = pcall(getgenv().answerOrbPattern, pattern)
			getgenv().CakeTweenSpeed = cakeTweenSpeed
			getgenv().BigMomBusy = false
			getgenv().OrbQuietSince = tick()

			if not getgenv().BMLog then
