	getgenv().StopBigMom = function()
		if not running then
			return
		end

		running = false
		getgenv().EnableBigMom = false
		getgenv().BM_Gen = (getgenv().BM_Gen or 0) + 1
		getgenv().ReactBlockPin = false
		getgenv().BreathBlocking = false
		getgenv().AutoBlocking = false
		getgenv().EvadingBoss = false
		getgenv().ReactUp = false
		getgenv().ReactLanding = false
		getgenv().Reacting = nil
		getgenv().ReactingWhy = nil
		getgenv().BigMomBusy = false

		pcall(function()
			if getgenv().releaseFirebreathMovement then
				getgenv().releaseFirebreathMovement()
			end
		end)

		pcall(function()
			local character = game.Players.LocalPlayer.Character
			local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")

			if humanoidRootPart then
				for _, child in ipairs(humanoidRootPart:GetChildren()) do
					if child.Name == "BM_ReactVel" or child.Name == "BM_DodgeGyro" or child.Name == "BM_MochiHold" or child.Name == "KD_TweenGyro" or child.Name == "KD_TweenVel" or child.Name == "KD_CFrameGyro" or child.Name == "KD_CFrameVel" or child.Name == "KD_AttachGyro" or child.Name == "KD_AttachVel" then
						child:Destroy()
					end
				end

				humanoidRootPart.Anchored = false
				humanoidRootPart.AssemblyLinearVelocity = Vector3.zero
			end

			if humanoid then
				humanoid.PlatformStand = false
				humanoid.AutoRotate = true
			end
		end)

		if savedSettings then
			for _, key in ipairs(BIGMOM_SETTINGS) do
				if savedSettings[key] ~= nil then
					getgenv()[key] = savedSettings[key]
				end
			end

			savedSettings = nil
		end
	end

	getgenv().StartBigMom = function(bigMomOnly)
		getgenv().BigMomOnly = bigMomOnly == true

		if running then
			return
		end

		if game.PlaceId == 1730877806 then
			return
		end

		running = true
		count += 1
		local count3 = count

		task.spawn(function()
			savedSettings = {}

			for _, key in ipairs(BIGMOM_SETTINGS) do
				savedSettings[key] = getgenv()[key]
			end

			getgenv().ApplyBigMomConfig()
			getgenv().EnableBigMom = true
			local ok, result = pcall(initBigMom)

			if not ok then
				hubLog("[Tensen] The Big Mom module stopped with an error: " .. tostring(result))
			end

			if not running or count ~= count3 then
				return
			end

			local missing = {}
			local keys = BIGMOM_SETTINGS

			for _, key in ipairs(BIGMOM_SETTINGS) do
				missing[key] = getgenv()[key]
			end

			while not getgenv().__TensenMainReady do
				if not running or count ~= count3 then
					return
				end

				task.wait(0.5)
			end

			local stopped

			while true do
				stopped = not running

				if stopped then
					break
				end

				local count4 = count
				keys = not keys

				if not keys then
					stopped = count4 ~= count3
					break
				end
			end

			if stopped or not savedSettings then
				return
			end

			local iterFn, iterState, iterStart = ipairs(BIGMOM_SETTINGS)

			for _, key in iterFn, iterState, iterStart do
				if getgenv()[key] ~= missing[key] then
					savedSettings[key] = getgenv()[key]
					getgenv()[key] = missing[key]
				end
			end
		end)
	end

	getgenv().RestartBigMom = function()
		if not running then
			return
		end

		local bigMomOnly = getgenv().BigMomOnly
		getgenv().StopBigMom()
		task.wait(0.3)
		getgenv().StartBigMom(bigMomOnly)
	end

	getgenv().BigMomRunning = function()
		return running
	end
end

