				if type(entry) == "table" then
					local default = espColorCache[kind]

					if default and default.src == entry then
						return default.out
					end

					local color = Color3.fromRGB(tonumber(entry[1]) or 255, tonumber(entry[2]) or 255, tonumber(entry[3]) or 255)
					espColorCache[kind] = {src = entry, out = color}
					return color
				end

				return Color3.new(1, 1, 1)
			end

