			local normalizeSelectedItems = function(items)
				local list = {}

				if type(items) == "table" then
					for k, value in pairs(items) do
						if type(k) == "number" and type(value) == "string" then
							table.insert(list, value)
						elseif type(k) == "string" and value == true then
							table.insert(list, k)
						elseif type(value) == "string" and value ~= "" and not tonumber(k) then
							table.insert(list, value)
						end
					end
				elseif type(items) == "string" and items ~= "" then
					table.insert(list, items)
				end

				return list
			end

			getgenv().NormalizeSelectedItems = normalizeSelectedItems
			local savedSelections = nil

			local function savedOptionsFor(dropdownKey, key)
				if savedSelections == nil then
					savedSelections = {}
					local loadKey = 259887351

					local keyIn = u32(key)
					local keyMix = bit32.bxor(keyIn, 396193772)
					local keyOld = u32(loadKey)
					loadKey = bit32.bxor(keyOld, keyMix)
					pcall(function()
						local HttpService = game:GetService("HttpService")
						local Configs = {}

						if type(listfiles) == "function" then
							Configs = listfiles("Tensen Hub/Configs")
						end

						local configCount = #Configs
						local keyNow = u32(loadKey)
						local keyCheck = bit32.bxor(keyNow, 293854722)

						if keyCheck == 534943960 then
							return
						end

						if configCount == 0 then
							Configs = {"Tensen Hub/Configs/GrandPieceOnline" .. tostring(game:GetService("Players").LocalPlayer.Name) .. ".json"}
						end

						for _, Config in ipairs(Configs) do
							if not (string.sub(Config, -5) == ".json" and isfile(Config)) then
								continue
							end

							pcall(function()
								local data = HttpService:JSONDecode(readfile(Config))

								if type(data) ~= "table" then
									return
								end

								for k, value in pairs(data) do
									if type(value) == "table" then
										local set = savedSelections[k] or {}
										savedSelections[k] = set

										for _, item in ipairs(normalizeSelectedItems(value)) do
											set[item] = true
										end
									end
								end
							end)
						end
					end)
				end

				local options = {}
				local saved = savedSelections[dropdownKey] or {}

				for k in pairs(saved) do
					table.insert(options, k)
				end

				table.sort(options)
				return options
			end

			local function keepSinglePick(selected, previous, options)
				if type(selected) == "table" then
					selected = normalizeSelectedItems(selected)[1]
				end

				if selected ~= nil and selected ~= "" and selected ~= "None" then
					return selected
				end

				if type(previous) == "table" then
					previous = previous[1]
				end

				if previous ~= nil and previous ~= "" and previous ~= "None" and not table.find(options or {}, previous) then
					return previous
				end

				return selected
			end

