				local RunService = game:GetService("RunService")
				local setfpscap_ = setfpscap or syn and syn.setfpscap
				local focused = true
				local appliedFpsCap = nil
				local defaultFpsCap = nil
				local lastTabbedOut = false

				local function currentFpsCap()
					if type(getfpscap) == "function" then
						local ok, result = pcall(getfpscap)

						if ok and tonumber(result) and tonumber(result) > 0 then
							return tonumber(result)
						end
					end

					local ok, result = pcall(function()
						return UserSettings():GetService("UserGameSettings").FramerateCap
					end)

					if ok and tonumber(result) and tonumber(result) > 0 then
						return tonumber(result)
					end

					return 240
				end

				local function targetFpsCap()
					if getgenv().TabbedOutSaver == true and not focused then
						return math.clamp(tonumber(getgenv().TabbedOutFPS) or 10, 5, 60)
					end

					if getgenv().FPSCapOn == true then
						return math.clamp(tonumber(getgenv().FPSCapValue) or 240, 15, 1000)
					end

					return nil
