				getgenv().FPSCapSupported = type(setfpscap_) == "function"

				getgenv().RefreshFPSCap = function()
					local tabbedOutSaver = getgenv().TabbedOutSaver == true
					tabbedOutSaver = tabbedOutSaver and not focused

					if tabbedOutSaver ~= lastTabbedOut then
						lastTabbedOut = tabbedOutSaver

						if tabbedOutSaver then
							pcall(function()
								RunService:Set3dRenderingEnabled(false)
							end)
						elseif not getgenv().LowerCPUUsage then
							pcall(function()
								RunService:Set3dRenderingEnabled(true)
							end)
						end
					end

					if type(setfpscap_) ~= "function" then
						return false
					end

					local wanted = targetFpsCap()

					if wanted == appliedFpsCap then
						return true
					end

					if appliedFpsCap == nil then
						defaultFpsCap = currentFpsCap()
					end

					if pcall(setfpscap_, wanted or defaultFpsCap or 240) then
						appliedFpsCap = wanted
					end

					return true
				end

				UserInputService.WindowFocusReleased:Connect(function()
					focused = false
					pcall(getgenv().RefreshFPSCap)
				end)

				UserInputService.WindowFocused:Connect(function()
