				local fpsBoostTextures2 = false
				local descendantAddedConn = nil
				local count = 0
				local hitLimit = false
				local classNames = {ParticleEmitter = true, Trail = true, Smoke = true, Fire = true, Sparkles = true, Beam = true}

				local function setTracked(object, property, value)
					local old = object[property]

					if old == value then
						return
					end

					if #undo >= 120000 then
						if not hitLimit then
							hitLimit = true
							hubLog(string.format("[FPS] %d changes is the undo limit - the rest of the map is left as it is, so everything can still be put back when the toggle goes off.", 120000))
						end

						return
					end

					undo[#undo + 1] = {object, property, old}
					object[property] = value
				end

				local function setProp(object, property, value)
					object[property] = value
				end

				local function stripInstance(instance, _)
					local className = instance.ClassName

					if classNames[className] then
						setTracked(instance, "Enabled", false)
						getgenv().FPSBoostStripped = (getgenv().FPSBoostStripped or 0) + 1
						return
					end

					if not _ then
						return
					end

					if instance:IsA("BasePart") then
						setTracked(instance, "Material", Enum.Material.SmoothPlastic)
						setTracked(instance, "Reflectance", 0)
						setTracked(instance, "CastShadow", false)

						if className == "MeshPart" then
							setTracked(instance, "TextureID", "")
						end
					elseif instance:IsA("Decal") then
						setTracked(instance, "Transparency", 1)
					elseif className == "SurfaceAppearance" then
						setTracked(instance, "Parent", nil)
					end
				end

				local function isProtectedPart(instance)
					if instance == terrain then
						return true
					end

					local name = instance.Name

					if name == "NPCs" or name == "Players" then
						return true
					end

					if instance:IsA("Model") and instance:FindFirstChildOfClass("Humanoid") then
						return true
					end

					return false
				end

				local function applyTextures(fpsBoostTextures)
					count += 1
					local count3 = count

					task.spawn(function()
						local deadline = os.clock() + 0.004

						for _, child in ipairs(workspace:GetChildren()) do
							if count3 ~= count then
								return
							end

							local strip = fpsBoostTextures and not isProtectedPart(child)
							pcall(stripInstance, child, strip)
							local descendants = child:GetDescendants()

							for i = 1, #descendants do
								pcall(stripInstance, descendants[i], strip)

								if i % 256 == 0 and os.clock() > deadline then
									task.wait()

									if count3 ~= count then
										return
									end

									deadline = os.clock() + 0.004
								end
							end

							if not (deadline < os.clock()) then
								continue
							end

							task.wait()

							if count3 ~= count then
								return
							end

							deadline = os.clock() + 0.004
						end

						getgenv().FPSBoostReady = true
					end)
				end

				local function stripLighting()
					pcall(setTracked, Lighting, "GlobalShadows", false)
					pcall(setTracked, Lighting, "FogEnd", 1000000)

					for _, descendant in ipairs(Lighting:GetDescendants()) do
						if descendant:IsA("Atmosphere") then
							pcall(setTracked, descendant, "Density", 0)
						elseif descendant:IsA("PostEffect") then
							pcall(setTracked, descendant, "Enabled", false)
						end
					end

					if terrain then
						pcall(setTracked, terrain, "WaterWaveSize", 0)
						pcall(setTracked, terrain, "WaterWaveSpeed", 0)
						pcall(setTracked, terrain, "WaterReflectance", 0)
						pcall(setTracked, terrain, "WaterTransparency", 0)
						pcall(setTracked, terrain, "Decoration", false)
					end

					pcall(function()
						local settingsFn = settings

						if false then -- never runs
							settingsFn().Rendering.QualityLevel = Enum.QualityLevel.Level01
						end
					end)
				end

				local function undoAll()
					count += 1

					for i = #undo, 1, -1 do
						local entry = undo[i]
						pcall(setProp, entry[1], entry[2], entry[3])
						undo[i] = nil
					end

					table.clear(undo)
					hitLimit = false
					getgenv().FPSBoostStripped = 0
					getgenv().FPSBoostReady = false

					pcall(function()
						settings().Rendering.QualityLevel = Enum.QualityLevel.Automatic
					end)
				end

				getgenv().FPSBoostStripped = 0
				getgenv().FPSBoostReady = false

				local function refreshFPSBoost()
					local boostOn = getgenv().FPSBoost and true or false
					local fpsBoostTextures = boostOn and (getgenv().FPSBoostTextures and true or false)

					if boostOn == boosted and fpsBoostTextures == fpsBoostTextures2 then
						return
					end

					if not boostOn then
						if descendantAddedConn then
							descendantAddedConn:Disconnect()
							descendantAddedConn = nil
						end

						undoAll()
						boosted = false
						fpsBoostTextures2 = false
						return
					end

					if boosted then
						if descendantAddedConn then
							descendantAddedConn:Disconnect()
							descendantAddedConn = nil
						end

						boosted = false
						undoAll()
					end

					boosted = true
					fpsBoostTextures2 = fpsBoostTextures
					stripLighting()
					applyTextures(fpsBoostTextures)

					if not descendantAddedConn then
						descendantAddedConn = workspace.DescendantAdded:Connect(function(descendant)
							if not boosted then
								return
							end

							pcall(stripInstance, descendant, fpsBoostTextures2)
						end)
					end
				end

