			getgenv().FruitNamesSaved = 0
			getgenv().FruitNamesLoaded = 0

			getgenv().BuildFruitNameSet = function()
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local HttpService = game:GetService("HttpService")
				local fruitFrontName = getgenv().FruitFrontName
				local names = {}
				local changed = false

				pcall(function()
					local skillCallbacks = ReplicatedStorage:FindFirstChild("SkillCallbacks")
					local devilFruit = skillCallbacks and skillCallbacks:FindFirstChild("DevilFruit")

					if not devilFruit then
						return
					end

					for _, child in ipairs(devilFruit:GetChildren()) do
						local front = fruitFrontName(child.Name)

						if front then
							names[front] = true
							changed = true
						end
					end
				end)

				pcall(function()
					local effects = ReplicatedStorage:FindFirstChild("Effects")
					local devilFruits = effects and effects:FindFirstChild("DevilFruits")

					if not devilFruits then
						return
					end

					for _, child in ipairs(devilFruits:GetChildren()) do
						if child.Name ~= "" then
							names[child.Name] = true
							changed = true
						end

						local front = fruitFrontName(child.Name)

						if front then
							names[front] = true
						end
					end
				end)

				pcall(function()
					if not isfile(getgenv().FruitCacheFile) then
						return
					end

					local data = HttpService:JSONDecode(readfile(getgenv().FruitCacheFile))

					if type(data) ~= "table" then
						return
					end

					for _, name in ipairs(data) do
						if type(name) == "string" and name ~= "" then
							names[name] = true
							getgenv().FruitNamesLoaded = (getgenv().FruitNamesLoaded or 0) + 1
						end
					end
				end)

				local fruitExtraNames = getgenv().FruitExtraNames or {}

				for _, fruitExtraName in ipairs(fruitExtraNames) do
					if fruitExtraName ~= "" then
						names[fruitExtraName] = true
					end
				end

				if changed then
					pcall(function()
						local list = {}

						for k in pairs(names) do
							table.insert(list, k)
						end

						table.sort(list);
						(getgenv().__TensenWF or writefile)(getgenv().FruitCacheFile, HttpService:JSONEncode(list))
						getgenv().FruitNamesSaved = #list
					end)
				end

				return names
			end

