				return value
			end

			local function mergeOptions(base, key, extra)
				local merged = {}
				local keyIn = u32(key)

				if keyIn ~= 452800363 then
					return
				end

				base = base or {}

				for _, item in ipairs(base) do
					table.insert(merged, item)
				end

				for _, item in ipairs(normalizeSelectedItems(extra)) do
					if not table.find(merged, item) then
						table.insert(merged, item)
					end
				end

				return merged
			end

