					local function createTextLabel(parent, text, y, textColor)
						local tensenDesc = Instance.new("TextLabel")
						tensenDesc.Name = "TensenDesc"
						tensenDesc.Text = text
						tensenDesc.Font = Enum.Font.Gotham
						tensenDesc.TextSize = 11
						tensenDesc.TextColor3 = textColor or Color3.fromRGB(140, 140, 150)
						tensenDesc.TextXAlignment = Enum.TextXAlignment.Left
						tensenDesc.BackgroundTransparency = 1
						tensenDesc.Position = UDim2.fromOffset(0, y)
						tensenDesc.Size = UDim2.new(1, 0, 0, 12)
						tensenDesc.Parent = parent
						return tensenDesc
					end

					local function getChild(instance, children)
						for _, child in ipairs(instance:GetChildren()) do
							if not children[child] and child:IsA("GuiObject") then
								return child
							end
						end
					end

					local function getChildren(instance)
						local children = {}

						for _, child in ipairs(instance:GetChildren()) do
							children[child] = true
						end

						return children
					end

					local addSlider = index.AddSlider

					index.AddSlider = function(tab, opts)
						local description = opts and opts.Description
						local children = description and tab._card and getChildren(tab._card)
						local slider = addSlider(tab, opts)
						local child = children and getChild(tab._card, children)

						if child then
							pcall(function()
								local textColor = nil

								for _, child2 in ipairs(child:GetChildren()) do
									if child2:IsA("GuiObject") and child2.Position.Y.Offset >= 16 then
										child2.Position += UDim2.fromOffset(0, 14)
									elseif child2:IsA("TextLabel") and child2.TextXAlignment == Enum.TextXAlignment.Right then
										textColor = child2.TextColor3
									end
								end

								child.Size += UDim2.fromOffset(0, 14)
								createTextLabel(child, description, 16, textColor)
							end)
						end

						return slider
					end

					local addButton = index.AddButton

					index.AddButton = function(tab, opts)
						local parent = addButton(tab, opts)
						local description = opts and opts.Description

						if description and parent then
							pcall(function()
								local textLabel = Instance.new("TextLabel")
								textLabel.Text = parent.Text
								textLabel.Font = parent.Font
								textLabel.TextSize = parent.TextSize
								textLabel.TextColor3 = parent.TextColor3
								textLabel.BackgroundTransparency = 1
								textLabel.Position = UDim2.fromOffset(0, 5)
								textLabel.Size = UDim2.new(1, 0, 0, 14)
								textLabel.Parent = parent
								local textLabel = createTextLabel(parent, description, 21)
								textLabel.TextXAlignment = Enum.TextXAlignment.Center
								textLabel.TextColor3 = parent.TextColor3
								textLabel.TextTransparency = 0.35
								parent.Text = ""
								parent.Size += UDim2.fromOffset(0, 12)
							end)
						end

						return parent
					end

