						index[method] = function(tab, opts)
							local control = original(tab, opts)
							local callback = opts and opts.Callback

							if type(control) == "table" and type(control.Set) == "function" and callback then
								local set = control.Set

								control.Set = function(ctl, value, ...)
									set(ctl, value, ...)

									local ok, result = pcall(function()
										return ctl:Get()
