						local opts = {Name = label, Description = description, Default = getgenv()[setting] == true, Flag = "Boss_" .. setting}

						local function callback(enabled)
							getgenv()[setting] = enabled

							if queueAutoSave then
								queueAutoSave()
								return
							end

