			local function addEspToggle(tab, label, setting, description)
				local function onToggle(enabled)
					getgenv().ESP[setting] = enabled

					if queueAutoSave then
						queueAutoSave()
					end
				end

				tab:AddToggle({Name = label, Description = description, Default = getgenv().ESP[setting] == true, Flag = "ESP_" .. setting, Callback = onToggle})
			end

			local function addEspSlider(tab, label, setting, min, max, description, unit)
				local addSlider = tab.AddSlider

				local opts = {
					Name = label,
					Description = description,
					Min = min,
					Max = max,
					Suffix = unit or "",
					Default = tonumber(getgenv().ESP[setting]) or min,
					Flag = "ESP_" .. setting
				}

				local function callback(value)
					local esp = getgenv().ESP
					esp[setting] = value

					if queueAutoSave then
						queueAutoSave()
					end
				end

				opts.Callback = callback
				addSlider(tab, opts)
			end

			local function addEspColor(tab, label, setting, description)
				local function onColor(colour)
					getgenv().ESPSetColor(setting, colour)

					queueAutoSave()
				end

				tab:AddColorPicker({Name = label, Description = description, Default = getgenv().ESPColor(setting), Flag = "ESP_" .. setting, Callback = onColor})
			end

