			getgenv().KeybindList = getgenv().KeybindList or {}

			getgenv().RegisterKeybind = function(name, key, state)
				for _, entry in ipairs(getgenv().KeybindList) do
					if entry.name == name then
						entry.key = key
						entry.state = state
						return entry
					end
				end

				local entry = {name = name, key = key, state = state}
				table.insert(getgenv().KeybindList, entry)
				return entry
			end

			getgenv().FastWalkKey = getgenv().FastWalkKey or Enum.KeyCode.Y

			getgenv().ToggleFastWalk = function(enabled)
				local fastWalkToggleUI = getgenv().FastWalkToggleUI

				if enabled == nil then
					local wasOn = getgenv().WalkSpeed == true
					local nowOn

					if fastWalkToggleUI and fastWalkToggleUI.Get then
						local ok, result = pcall(function()
							return fastWalkToggleUI:Get()
						end)

						if ok and type(result) == "boolean" then
							nowOn = result
						else
							nowOn = wasOn
						end
					else
						nowOn = wasOn
					end

					enabled = not nowOn
				end

				local walkSpeed = enabled == true

				if fastWalkToggleUI and fastWalkToggleUI.Set then
					pcall(function()
						fastWalkToggleUI:Set(walkSpeed)
					end)
				end

				getgenv().WalkSpeed = walkSpeed

				if getgenv().EnableFastWalk then
					pcall(getgenv().EnableFastWalk, walkSpeed)
				end

				if queueAutoSave then
					queueAutoSave()
				end

				return walkSpeed
			end

