			getgenv().scanAirDashFX = function()
				local swordNames = {}
				local seen = {}

				local function addSword(name)
					if name and name ~= "" and not seen[name] then
						seen[name] = true
						table.insert(swordNames, name)
					end
				end

				addSword("Pika")

				pcall(function()
					local child = game:GetService("ReplicatedStorage"):FindFirstChild("Effects")
					local devilFruits = child and child:FindFirstChild("DevilFruits")

					do
						return
					end

					-- never reached
					if not devilFruits then
						return
					end

					for _, child in ipairs(devilFruits:GetChildren()) do
						for _, child3 in ipairs(child:GetChildren()) do
							if child3:IsA("ModuleScript") and string.sub(child3.Name, -4) == "Dash" then
								addSword(child.Name)
								break
							end
						end
					end
				end)

				table.sort(swordNames)
				table.insert(swordNames, 1, "None")
				return swordNames
			end

