					if noFog then
						getgenv()._NoFogOrigFogEnd = Lighting.FogEnd
						getgenv()._NoFogOrigFogStart = Lighting.FogStart
						Lighting.FogEnd = 1e10
						Lighting.FogStart = 0
					else
