			Visuals:AddToggle({
				Name = "Fullbright",
				Description = "Remove dark areas and make everything fully lit",
				Default = getgenv().Fullbright or false,
				Flag = "FullbrightToggle",
				Callback = function(fullbright)
					getgenv().Fullbright = fullbright
					local Lighting = game:GetService("Lighting")

					if fullbright then
						getgenv()._FBOrigBrightness = Lighting.Brightness
						getgenv()._FBOrigAmbient = Lighting.Ambient
						getgenv()._FBOrigOutdoorAmbient = Lighting.OutdoorAmbient
						Lighting.Brightness = 8
						Lighting.Ambient = Color3.fromRGB(178, 178, 178)
						Lighting.OutdoorAmbient = Color3.fromRGB(178, 178, 178)
					else
						Lighting.Brightness = getgenv()._FBOrigBrightness or 1
						Lighting.Ambient = getgenv()._FBOrigAmbient or Color3.fromRGB(127, 127, 127)
						Lighting.OutdoorAmbient = getgenv()._FBOrigOutdoorAmbient or Color3.fromRGB(127, 127, 127)
					end

					if queueAutoSave then
						queueAutoSave()
					end
				end
			})

