			task.wait(0.1)
			local Players2 = game:GetService("Players")
			local RunService = game:GetService("RunService")
			cloneref(Instance.new("VirtualInputManager"))
			local localPlayer = Players2.LocalPlayer
			local character = localPlayer.Character or localPlayer.CharacterAdded:Wait()
			local hasGeppo, climbKey

			do
				local humanoidRootPart = character:WaitForChild("HumanoidRootPart")
				character:WaitForChild("Humanoid")
				localPlayer:WaitForChild("PlayerGui")
				local playerGui = localPlayer:WaitForChild("PlayerGui")

				local function joinPrivateServer(privateServerCode, name)
					task.spawn(function()
						pcall(function()
							game:GetService("ReplicatedStorage"):FindFirstChild("Events").reserved:InvokeServer(privateServerCode)
						end)
					end)
					task.wait(2)

					if name == "First Sea" or name == "Second Sea" then
						for _, connection in ipairs(getconnections(game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui"):WaitForChild("chooseType"):WaitForChild("Frame"):WaitForChild("Options"):WaitForChild("Regular").MouseButton1Click)) do
							connection:Fire()
						end

						task.wait(2)

						for _, connection in ipairs(getconnections(game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui"):WaitForChild("ConfirmationPrompt"):WaitForChild("Main"):WaitForChild("OptionsFrame"):WaitForChild(name).MouseButton1Click)) do
							connection:Fire()
						end

						return
					end

					local iterFn, iterState, iterStart = ipairs(getconnections(game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui"):WaitForChild("chooseType"):WaitForChild("Frame"):WaitForChild("Options"):WaitForChild(name).MouseButton1Click))

					for _, connection in iterFn, iterState, iterStart do
						connection:Fire()
					end
				end

				getgenv().KaitunTravelSecondSea = function()
					local autoJoin = getgenv().AutoJoinPrivateServer == true

					if not autoJoin then
						local privateIdType = type(game.PrivateServerId)
						autoJoin = privateIdType == "string" and game.PrivateServerId ~= ""
					end

					if not autoJoin then
						TeleportService:Teleport(7465136166, localPlayer)
						return
					end

					local match = tostring(getgenv().PrivateServerCode or ""):match("^%s*(.-)%s*$")

					if match == "" then
						error("Set Private Server Code and enable Auto Join Private Server for private Second Sea travel")
					end

					local teleport = queue_on_teleport or queueonteleport or syn and syn.queue_on_teleport

					if type(teleport) ~= "function" then
						error("Private Second Sea travel requires queue_on_teleport support")
					end

					if type(getconnections) ~= "function" then
						error("Private Second Sea travel requires getconnections support")
					end

					if getgenv().KaitunQueuedPrivateCode ~= match then
						teleport(string.format([[                                if not game:IsLoaded() then game.Loaded:Wait() end
                                if game.PlaceId ~= 1730877806 then return end
                                if getgenv().KaitunPrivateJoinRunning then return end
                                getgenv().KaitunPrivateJoinRunning = true
                                getgenv().AutoJoinPrivateServer = false
                                getgenv().PrivateServerCode = %q
                                getgenv().WherePrivateServer = "Second Sea"
                                task.spawn(function()
                                    local ok, err = pcall(function()
                                        local events = game:GetService("ReplicatedStorage"):WaitForChild("Events", 60)
                                        assert(events, "Private server events did not load")
                                        local reserved = events:WaitForChild("reserved", 30)
                                        assert(reserved, "Private server join remote did not load")
                                        task.spawn(function()
                                            local joined, why = pcall(function()
                                                reserved:InvokeServer(getgenv().PrivateServerCode)
                                            end)
                                            if not joined then warn("[Kaitun] Private join failed: " .. tostring(why)) end
                                        end)
                                        local gui = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
                                        local function child(parent, name)
                                            local found = parent:WaitForChild(name, 60)
                                            assert(found, "Private join UI missing: " .. name)
                                            return found
                                        end
                                        local function click(button)
                                            local connections = getconnections(button.MouseButton1Click)
                                            assert(#connections > 0, "Private join button is not ready")
                                            for _, connection in ipairs(connections) do connection:Fire() end
                                        end
                                        local regular = child(child(child(child(gui, "chooseType"), "Frame"), "Options"), "Regular")
                                        task.wait(2)
                                        click(regular)
                                        local sea = child(child(child(child(gui, "ConfirmationPrompt"), "Main"), "OptionsFrame"), "Second Sea")
                                        task.wait(2)
                                        click(sea)
                                    end)
                                    if not ok then warn("[Kaitun] Private Second Sea join failed: " .. tostring(err)) end
                                    getgenv().KaitunPrivateJoinRunning = false
                                end)
                            ]], match))

						getgenv().KaitunQueuedPrivateCode = match
					end

					TeleportService:Teleport(1730877806, localPlayer)
				end

				if game.PlaceId == 1730877806 then
					task.spawn(function()
						while task.wait() do
							if getgenv().AutoJoinPrivateServer and not getgenv().KaitunPrivateJoinRunning and getgenv().PrivateServerCode and getgenv().WherePrivateServer then
								joinPrivateServer(getgenv().PrivateServerCode, getgenv().WherePrivateServer)
								task.wait(8)
							end
						end
					end)
				end

				local function hideGui(instance)
					if not instance then
						return
					end

					if instance:IsA("ScreenGui") then
						instance.Enabled = false
					elseif instance:IsA("GuiObject") then
						instance.Visible = false
					end

					if instance:IsA("Sound") then
						instance.Volume = 0
						instance:Stop()
					end

					for _, descendant in ipairs(instance:GetDescendants()) do
						if descendant:IsA("Sound") then
							descendant.Volume = 0
							descendant:Stop()
						elseif descendant:IsA("GuiObject") then
							descendant.Visible = false
						elseif descendant:IsA("ScreenGui") then
							descendant.Enabled = false
						end
					end
				end

				task.spawn(function()
					while true do
						local notifications = playerGui:FindFirstChild("Notifications")

						if notifications then
							for _, descendant in ipairs(notifications:GetDescendants()) do
								if descendant:IsA("TextLabel") then
									local text = string.lower(descendant.Text)

									if text:find("climb") or text:find("cd") or text:find("error") then
										(descendant.Parent and descendant.Parent ~= notifications and descendant.Parent:IsA("GuiObject") and descendant.Parent or descendant):Destroy()
									end
								end
							end
						end

						local modules = game:GetService("ReplicatedStorage"):FindFirstChild("Modules")

						if modules and modules:FindFirstChild("Client") and modules.Client:FindFirstChild("Notification") then
							local redText = modules.Client.Notification:FindFirstChild("RedText4")

							if redText then
								hideGui(redText)
							end
						end

						task.wait(0.3)
					end
				end)

				if getgenv().EnableVisualRaycast == nil then
					getgenv().EnableVisualRaycast = false
				end

				local rayKey = bit32.bxor(espKey, 1243648088)

				local function visualizeRay(_from, _to, duration)
					if not getgenv().EnableVisualRaycast then
						return
					end

					local part = Instance.new("Part")
					part.Anchored = true
					part.CanCollide = false
					part.CanQuery = false
					part.CastShadow = false
					local rayKey = rayKey
					local rayKeyIn
					rayKeyIn = u32(rayKey)
					local rayKeyMix = bit32.bxor(rayKeyIn, 0)
					part.Material = nil
					local _duration, color, zero

					if duration then
						_duration = duration
					else
						color = Color3.new
						zero = 0
						rayKeyIn = 1
						_duration = rayKeyMix(rayKeyIn, 0, zero)
					end

					return nil, nil, false, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, color, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil
				end

				local rayKeyOld = u32(rayKey)
				rayKey = bit32.bxor(rayKeyOld, 531869032)
				getgenv().VisualizeRay = visualizeRay
				local climbController = nil
				local checked = {}

				local function climbControllerIsOurs(instances)
					local character = localPlayer.Character

					for _, instance in pairs(instances) do
						if typeof(instance) ~= "Instance" then
							continue
						end

						if instance:IsA("Model") and instance ~= character and instance:FindFirstChild("Humanoid") then
							return false
						end

						if instance:IsA("Player") and instance ~= localPlayer then
							return false
						end
					end

					return true
				end

				getgenv().climbControllerIsOurs = climbControllerIsOurs
				getgenv().ClimbScanTimeout = getgenv().ClimbScanTimeout or 20
				getgenv().ClimbScanRejected = 0

				task.spawn(function()
					local now = os.clock()

					while task.wait(0.25) do
						local gcObjects = getgenv().__TensenGC(true)
						local deadline = os.clock() + 0.002

						for i = 1, #gcObjects do
							local object = gcObjects[i]

							if type(object) == "table" and rawget(object, "Handler") and rawget(object, "Utils") and rawget(object, "ClimbingObject") and not checked[object] then
								checked[object] = true

								if climbControllerIsOurs(object) then
									climbController = object
									break
								end

								getgenv().ClimbScanRejected = (getgenv().ClimbScanRejected or 0) + 1
							end

							if i % 512 == 0 and os.clock() > deadline then
								task.wait()
								deadline = os.clock() + 0.002
							end
						end

						if climbController then
							hubLog(string.format("[Climb] bound our own controller after %.1fs (rejected %d belonging to others)", os.clock() - now, getgenv().ClimbScanRejected or 0))
							break
						end

						local elapsed = os.clock() - now

						if (getgenv().ClimbScanTimeout or 20) < elapsed then
							hubLog(string.format("[Climb] no controller of ours found in %ds (rejected %d) - continuing without one; wall climbing will be skipped until respawn re-scans.", getgenv().ClimbScanTimeout or 20, getgenv().ClimbScanRejected or 0))
							break
						end
					end
				end)

				getgenv().StopClimbing = function()
					pcall(function()
						if not climbController then
							return
						end

						local value = rawget(climbController, "ClimbingObject")

						if not (value and value.Enabled == true) then
							return
						end

						local localPlayer = game.Players.LocalPlayer
						local child = localPlayer and localPlayer:FindFirstChild("Backpack")
						local inputCallbacks2

						if child then
							local inputCallbacks = localPlayer.Backpack:FindFirstChild("InputCallbacks")
							inputCallbacks2 = inputCallbacks
						else
							inputCallbacks2 = child
						end

						local climb = inputCallbacks2 and localPlayer.Backpack.InputCallbacks:FindFirstChild("Climb")

						if climb then
							local module = require(climb)

							if module and module.PC_Activate then
								module.PC_Activate(climbController)
							end
						end

						if value.Enabled == true then
							value.Enabled = false

							if value.stop then
								value:stop()
							end

							_G.canuse = true

							pcall(function()
								local g = getrenv()._G
								g.canuse = true
							end)
						end

						local character = localPlayer and localPlayer.Character

						if character then
							for _, child in ipairs(character:GetChildren()) do
								if child:IsA("BasePart") then
									child.CollisionGroup = "Players"
								end
							end
						end
					end)
				end

				getgenv().CanUseWatch = getgenv().CanUseWatch ~= false
				getgenv().CanUseStuckFor = getgenv().CanUseStuckFor or 2
				getgenv().CanUseFixes = 0

				task.spawn(function()
					local now = nil

					while task.wait(0.25) do
						if getgenv().CanUseWatch == false then
							now = nil
							continue
						end

						local function getG()
							local renv = getrenv()
							return renv._G
						end

						local gOk, G = pcall(getG)

						if not gOk or type(G) ~= "table" or G.canuse ~= false then
							now = nil
							continue
						end

						local character = localPlayer.Character
						local humanoid = character and character:FindFirstChildOfClass("Humanoid")
						local enabled = not humanoid or humanoid.Health <= 0 or character:GetAttribute("usingSkill") == true or character:FindFirstChild("Stun") ~= nil or nil

						if not enabled and getgenv().ClimbingNow then
							local ok, result = pcall(getgenv().ClimbingNow)
							enabled = ok and result == true
						end

						if enabled then
							now = nil
							continue
						end

						now = now or tick()

