				getgenv().AimStanceRemoteState = aimStanceRemoteState
				getgenv().FaceMouseByRemote = (getgenv().FaceMouseByRemote or 0) + 1

				pcall(function()
					local events = ReplicatedStorage:FindFirstChild("Events")
					local faceMouse = events and events:FindFirstChild("faceMouse")

					if faceMouse then
						faceMouse:FireServer(aimStanceRemoteState)
					end
				end)
			end

			getgenv().fireAimStanceRemote = fireAimStanceRemote

			getgenv()

			local function sendFaceMouse(faceMouse)
				if faceMouse and getgenv().faceMouseBanned() then
					faceMouse = false
				end

				local aimStanceEnv = getgenv().AimStanceEnv

				if not aimStanceEnv then
					aimStanceEnv = _G

					pcall(function()
						aimStanceEnv = getrenv()._G
					end)

					getgenv().AimStanceEnv = aimStanceEnv
				end

				aimStanceEnv.FaceMouse = faceMouse

				if getgenv().FaceMouseModuleWorks == true then
					return true
				end

				if getgenv().FaceMouseModuleWorks == false then
					getgenv().fireAimStanceRemote(faceMouse)
					return true
				end

				return true
			end

			getgenv().sendFaceMouse = sendFaceMouse

			-- functions the hub calls that live outside the dumped part, rebuilt from the other dumps
			do
				-- BossStatusText(boss): status line for the Juzo / Mihawk / Roger tabs

				local Players = game:GetService("Players")
				local localPlayer = Players.LocalPlayer

				-- the boss farm loop sets these in the original, it isn't here so they stay false
				local rogerDone = false
				local mihawkDone = false

				-- roger: every 5400s, window is the first 900s (server clock is +3h)
				local function rogerSchedule()
					local utc = os.date("!*t")
					local intoCycle = ((utc.hour + 3) % 24 * 3600 + utc.min * 60 + utc.sec) % 5400

					if intoCycle <= 900 then
						return 0, intoCycle, true
					end

					rogerDone = false
					return 5400 - intoCycle, intoCycle, false
				end

				-- mihawk: first 900s of every odd hour (+3h)
				local function mihawkSchedule()
					local utc = os.date("!*t")
					local hour = (utc.hour + 3) % 24
					local seconds = utc.min * 60 + utc.sec

					if hour % 2 == 1 then
						if seconds <= 900 then
							return 0, seconds, true
						end

						mihawkDone = false
						return 7200 - seconds, seconds, false
					end

					mihawkDone = false
					return 3600 - seconds, seconds, false
				end

				-- roger or mihawk window open, or opening within 180s
				local function umiBossComingUp()
					if game.PlaceId ~= 7465136166 then
						return false
					end

					local mihawkWait, _, mihawkOpen = mihawkSchedule()
					local rogerWait, _, rogerOpen = rogerSchedule()
					local mihawkPending = getgenv().AutoMihawkBoss and not mihawkDone
					local rogerPending = getgenv().AutoRogerBoss and not rogerDone

					return mihawkPending and (mihawkWait <= 180 or mihawkOpen) or rogerPending and (rogerWait <= 180 or rogerOpen)
				end

				-- m:ss
				local function clock(seconds)
					local total = math.max(0, math.floor(seconds))
					return string.format("%d:%02d", math.floor(total / 60), total % 60)
				end

				getgenv().BossStatusText = function(boss)
					if not (boss == "Juzo" and getgenv().AutoJuzoBoss or boss == "Roger" and getgenv().AutoRogerBoss or boss == "Mihawk" and getgenv().AutoMihawkBoss) then
						return "off"
					end

					if game.PlaceId ~= 7465136166 then
						return "only works in Second Sea"
					end

					if getgenv().BossFarmDisabled then
						return "held off - BossFarmDisabled is set"
					end

					local paused = getgenv().AutoFishing or getgenv().AutoMerchant

					if paused then
						return "paused - Auto Fishing or Auto Merchant is on"
					end

					local label = boss == "Juzo" and "Juzo" or boss == "Roger" and "Roger" or "Mihawk"
					local npcName = boss == "Juzo" and "Juzo the Diamondback" or boss == "Roger" and "Roger" or "Hawk Eye"
					local character = localPlayer.Character
					local rootPart = character and character:FindFirstChild("HumanoidRootPart")
					local npcs = workspace:FindFirstChild("NPCs")
					local bossModel = npcs and npcs:FindFirstChild(npcName)
					local bossHumanoid = bossModel and bossModel:FindFirstChildOfClass("Humanoid")
					local bossRoot = bossModel and (bossModel:FindFirstChild("HumanoidRootPart") or bossModel.PrimaryPart)
					local bossAlive = bossHumanoid and bossRoot and bossHumanoid.Health > 0

					-- "fighting ..." line
					local function fightingLine()
						local studs = rootPart and (rootPart.Position - bossRoot.Position).Magnitude or -1
						local blocking = getgenv().bossTargetBlocking and getgenv().bossTargetBlocking(bossModel)

						return string.format(
							"fighting %s - %d studs away - HP %d/%d%s",
							npcName,
							math.floor(studs),
							math.floor(bossHumanoid.Health),
							math.floor(bossHumanoid.MaxHealth),
							blocking and (getgenv()[label .. "FeintOnBlock"] ~= false and " - blocking so fake m1" or " - blocking") or ""
						)
					end

					if boss == "Juzo" then
						if bossAlive and getgenv().JuzoFighting then
							return fightingLine()
						end

						if getgenv().BossLootDwelling and not bossAlive then
							return "Juzo is down - picking up the loot"
						end

						if (getgenv().AutoRogerBoss or getgenv().AutoMihawkBoss) and (umiBossComingUp() or getgenv().UmiBossEngaged) then
							return "waiting - Roger/Mihawk is up first"
						end

						local studs

						if rootPart then
							studs = (rootPart.Position - Vector3.new(1770.34546, 36.0756149, -10659.0898)).Magnitude
						end

						studs = studs or 0

						if studs > 150 then
							return string.format("heading to Juzo's island (%d studs)", math.floor(studs))
						end

						return "at Juzo's island - waiting for him to spawn"
					end

					local untilOpen, intoCycle, windowOpen, done

					if boss == "Roger" then
						untilOpen, intoCycle, windowOpen = rogerSchedule()
					else
						untilOpen, intoCycle, windowOpen = mihawkSchedule()
					end

					if bossAlive and getgenv().UmiBossEngaged then
						return fightingLine()
					end

					if getgenv().BossLootDwelling and not bossAlive then
						return label .. " is down - picking up the loot"
					end

					local studs

					if rootPart then
						studs = (rootPart.Position - Vector3.new(12642.7695, 144.162933, 2898.39746)).Magnitude
					end

					studs = studs or 0

					if windowOpen then
						if studs > 150 then
							return string.format("%s is up - heading to Umi (%d studs)", label, math.floor(studs))
						end

						return string.format("at Umi - waiting for %s (window closes in %s)", label, clock(900 - intoCycle))
					end

					if untilOpen <= 180 then
						if studs > 150 then
							return string.format("%s spawns in %s - heading to Umi (%d studs)", label, clock(untilOpen), math.floor(studs))
						end

						return string.format("at Umi - %s spawns in %s", label, clock(untilOpen))
					end

					return string.format("waiting - %s spawns in %s", label, clock(untilOpen))
				end
			end

			-- ESPIsTeammate
			do
				-- ESPIsTeammate(player): party, name list, same team, same crew, same faction (cached 2s)

				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local localPlayer = Players.LocalPlayer

				local resultCache = setmetatable({}, { __mode = "k" })

				-- the dump checks a flag here that's never defined, treated as always on

				-- party member names (party gui + health bars), cached 1s
				local partyCache = { at = 0, set = {} }

				local function getPartySet()
					if tick() - partyCache.at < 1 then
						return partyCache.set
					end

					local set = {}

					pcall(function()
						local playerGui = localPlayer:FindFirstChild("PlayerGui")
						local globalFeed = playerGui and playerGui:FindFirstChild("globalFeed")
						local partyMembers = globalFeed and globalFeed:FindFirstChild("partyMembers")

						if partyMembers then
							for _, child in ipairs(partyMembers:GetChildren()) do
								if child:IsA("GuiObject") then
									set[string.lower(child.Name)] = true
								end
							end
						end

						local healthBars = playerGui and playerGui:FindFirstChild("HealthBars")

						if healthBars then
							for _, child in ipairs(healthBars:GetChildren()) do
								local memberName = string.match(child.Name, "^(.+)PartyCircle$")

								if memberName then
									set[string.lower(memberName)] = true
								end
							end
						end
					end)

					partyCache.at = tick()
					partyCache.set = set
					return set
				end

				-- names from the "Teammate Names" box, rebuilt when the text changes
				local lastTeamNames = nil
				local teamNameSet = {}

				local function getTeamNameSet()
					local text = tostring(getgenv().ESP.PlayerTeamNames or "")

					if text ~= lastTeamNames then
						lastTeamNames = text
						teamNameSet = {}

						for piece in string.gmatch(text, "[^,]+") do
							local name = string.lower((string.gsub(piece, "%s", "")))

							if name ~= "" then
								teamNameSet[name] = true
							end
						end
					end

					return teamNameSet
				end

				-- real team name or nil (lobby / queue / default teams don't count)
				local ignoredTeamNames = { Teleporting = true, Players = true, Waiting = true }

				local function getTeamName(player)
					local team = player.Team

					if not team then
						return nil
					end

					local name = team.Name

					if ignoredTeamNames[name] then
						return nil
					end

					if string.sub(name, -6) ~= " Queue" then
						local ok, result = pcall(function()
							return #team:GetPlayers() >= #Players:GetPlayers()
						end)

						if ok and result then
							return nil
						end

						return name
					end

					-- queue teams count as no team
					return nil
				end

				local function getStatsFolder(player)
					return ReplicatedStorage:FindFirstChild("Stats" .. player.Name)
				end

				local function getStatString(player, name)
					local folder = getStatsFolder(player)
					local stats = folder and folder:FindFirstChild("Stats")
					local valueObject = stats and stats:FindFirstChild(name)

					if not valueObject then
						return nil
					end

					local ok, result = pcall(function()
						return valueObject.Value
					end)

					if not ok or type(result) ~= "string" or result == "" then
						return nil
					end

					return result
				end

				getgenv().ESPIsTeammate = function(player)
					local cached = resultCache[player]

					if cached and tick() - cached.at < 2 then
						return cached.v
					end

					local teammate = false

					pcall(function()
						if getgenv().ESP.PlayerTeamParty ~= false then
							local party = getPartySet()

							if party[string.lower(player.Name)] or party[string.lower(player.DisplayName)] then
								teammate = true
								return
							end
						end

						local named = getTeamNameSet()

						if named[string.lower(player.Name)] or named[string.lower(player.DisplayName)] then
							teammate = true
							return
						end

						local myTeam = getTeamName(localPlayer)
						local theirTeam = getTeamName(player)

						if myTeam and theirTeam then
							teammate = myTeam == theirTeam
							return
						end

						local myCrew = getStatString(localPlayer, "Crew")

						if myCrew and getStatString(player, "Crew") == myCrew then
							teammate = true
							return
						end

						if getgenv().ESP.PlayerTeamFaction == false then
							return
						end

						local myFaction = getStatString(localPlayer, "Team")
						teammate = myFaction ~= nil and getStatString(player, "Team") == myFaction
					end)

					resultCache[player] = { at = tick(), v = teammate }
					return teammate
				end
			end

			-- EnableFastWalk
			do
				-- EnableFastWalk(walkSpeed)

				local Players = game:GetService("Players")
				local RunService = game:GetService("RunService")
				local localPlayer = Players.LocalPlayer

				local fastWalkBound = false

				-- turns off the game's own connections on a signal (best guess at what the original called)
				local function disableGameConnections(signal)
					local disabled = {}
					local getCons = getconnections or get_signal_cons

					if type(getCons) ~= "function" then
						return disabled
					end

					for _, connection in ipairs(getCons(signal)) do
						local callback = connection.Function

						if type(callback) == "function" then
							local isLua = type(islclosure) == "function" and islclosure(callback)
							local isExecutor = type(is_synapse_function) == "function" and is_synapse_function(callback)

							if isLua and not isExecutor then
								connection:Disable()
								table.insert(disabled, connection)
							end
						end
					end

					return disabled
				end

				getgenv().EnableFastWalk = function(walkSpeed)
					getgenv().WalkSpeed = walkSpeed

					if walkSpeed then
						if fastWalkBound then
							return
						end

						-- grabs root/humanoid at bind time instead of the hub's cached ones
						local character = localPlayer.Character
						local rootPart = character and character:FindFirstChild("HumanoidRootPart")
						local humanoid = character and character:FindFirstChild("Humanoid")

						if not rootPart then
							-- quiet return, the original errors here
							return
						end

						disableGameConnections(rootPart.Changed)
						disableGameConnections(rootPart:GetPropertyChangedSignal("CFrame"))

						RunService:BindToRenderStep("FastWalk", 1, function(dt)
							if getgenv().ForceDisableFastWalk then
								return
							end

							if not getgenv().WalkSpeed then
								return
							end

							if not rootPart or not humanoid then
								return
							end

							local step = math.min(dt, 0.016666666666666666)
							local moveDirection = humanoid.MoveDirection

							if moveDirection.Magnitude < 0.05 then
								return
							end

							local speed = tonumber(getgenv().FastWalkSpeed) or 60

							if speed <= 0 then
								return
							end

							rootPart.CFrame += moveDirection * step * speed
						end)

						fastWalkBound = true
					elseif fastWalkBound then
						RunService:UnbindFromRenderStep("FastWalk")
						fastWalkBound = false
					end
				end
			end

			-- FarmStatusText
			do
				-- FarmStatusText(key): status line for each farm tab

				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local localPlayer = Players.LocalPlayer

				local function playerGui()
					return localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:FindFirstChild("PlayerGui")
				end

				-- the hub's tween state isn't exported, so this is a stand-in and "heading to ..." never shows
				local tweenState = getgenv().__TensenTweenState or { Enabled = false }   -- hub tween state

				local function characterParts()
					local character = localPlayer.Character
					return character, character and character:FindFirstChild("HumanoidRootPart"), character and character:FindFirstChildOfClass("Humanoid")
				end

				-- studs from the player (returns 0 with no root, that part is a guess)
				local function distanceTo(position)
					local _, root = characterParts()
					if not root then
						return 0
					end
					return (position - root.Position).Magnitude
				end

				-- dropdown value -> list of names
				local function toList(value)
					local list = {}

					if type(value) == "table" then
						for k, v in pairs(value) do
							local item = type(k) == "string" and k or v
							if type(item) == "string" then
								table.insert(list, item)
							end
						end
					elseif type(value) == "string" then
						table.insert(list, value)
					end

					return list
				end

				-- m:ss
				local function clock(seconds)
					local total = math.max(0, math.floor(seconds))
					return string.format("%d:%02d", math.floor(total / 60), total % 60)
				end

				-- reads the Peli label on the hud
				local function getPeli()
					local gui = playerGui()
					local hud = gui and gui:FindFirstChild("HUD")
					local main = hud and hud:FindFirstChild("Main")
					local peli = main and main:FindFirstChild("Peli")
					local label = peli and peli:FindFirstChild("TextLabel")

					if not label then
						return 0
					end

					local digits = label.Text:gsub("[^%d]", "")
					return tonumber(digits) or 0
				end

				-- traveling merchant marker, nil when he's not out
				local function getMerchantMarker()
					local compassGuider = ReplicatedStorage:FindFirstChild("CompassGuider")
					return compassGuider and compassGuider:FindFirstChild("Traveling Merchant")
				end

				-- restock time anchor is missing from the dump, so "next restock in" is left out
				local restockAnchor = nil

				local function restockSuffix()
					do
						return nil
					end
					-- never reached
					local elapsed = os.time(os.date("!*t")) - os.time(restockAnchor)
					return clock(1800 - elapsed % 1800)
				end

				-- already owns buso haki?
				local function hasBusoHaki()
					local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)

					if stats then
						local skills = stats:FindFirstChild("Skills")

						if skills then
							for _, name in ipairs({ "busoHaki", "BusoHaki", "buso", "Buso", "haki", "Haki", "busoshokuHaki", "BusoshokuHaki" }) do
								local skill = skills:FindFirstChild(name)

								if skill then
									skill = skill.Value == true or skill.Value == 1 or type(skill.Value) == "number" and skill.Value > 0
								end

								if skill then
									return true
								end
							end
						end

						local inner = stats:FindFirstChild("Stats")

						if inner then
							local buso = inner:FindFirstChild("Buso") or inner:FindFirstChild("buso")

							if buso then
								if buso.Value == true then
									buso = true
								elseif type(buso.Value) == "number" then
									buso = buso.Value > 0
								else
									buso = false
								end
							end

							if buso then
								return true
							end

							local mastery = inner:FindFirstChild("BusoMastery") or inner:FindFirstChild("busoMastery")

							if mastery and type(mastery.Value) == "number" and mastery.Value > 0 then
								return true
							end
						end
					end

					local character = localPlayer.Character

					if character then
						if character:FindFirstChild(localPlayer.Name .. "Buso") or character:FindFirstChild("Buso") or character:FindFirstChild("Haki") then
							return true
						end

						if character:GetAttribute("Buso") == true or character:GetAttribute("Haki") == true then
							return true
						end
					end

					local hud = playerGui() and playerGui():FindFirstChild("HUD")
					-- the original retries the HUD lookup on another container that couldn't be identified

					if not hud then
						return false
					end

					local main = hud:FindFirstChild("Main")

					if main then
						for _, descendant in ipairs(main:GetDescendants()) do
							if descendant:IsA("GuiObject") and (descendant.Name == "Buso" or descendant.Name == "busoHaki" or descendant.Name == "Haki") then
								return true
							end
						end
					end

					return false
				end

				-- quest panel open?
				local function questPanelOpen()
					local gui = playerGui()
					local quest = gui and gui:FindFirstChild("Quest")
					local main = quest and quest:FindFirstChild("Main")
					return main and main.Visible == true
				end

				-- nearest alive npc with that name + how many are alive (details are a guess)
				local function findNearestAlive(name)
					local npcs = workspace:FindFirstChild("NPCs")
					local _, root = characterParts()
					local best, bestStuds, alive = nil, math.huge, 0

					if not npcs then
						return nil, 0, 0
					end

					for _, child in ipairs(npcs:GetChildren()) do
						if child.Name ~= name then
							continue
						end

						local humanoid = child:FindFirstChildOfClass("Humanoid")
						local part = child:FindFirstChild("HumanoidRootPart") or child.PrimaryPart

						if humanoid and humanoid.Health > 0 and part then
							alive += 1
							local studs = root and (part.Position - root.Position).Magnitude or 0

							if studs < bestStuds then
								best, bestStuds = child, studs
							end
						end
					end

					if not best then
						return nil, 0, 0
					end

					return best, bestStuds, alive
				end

				-- reach the kill aura / tween farm needs
				local function targetRange()
					local range = 15

					if getgenv().KillAura then
						range = math.max(tonumber(getgenv().KillAuraRange) or 15, 15)
					end

					local withNpc

					if getgenv().TweenToNPC then
						withNpc = math.max((tonumber(getgenv().NPCOffsetY) or 9) + 6, range)
					else
						withNpc = range
					end

					local withPlayer

					if getgenv().TweenToPlayer then
						withPlayer = math.max((tonumber(getgenv().PvPOffsetY) or 9) + 6, withNpc)
					else
						withPlayer = withNpc
					end

					return withPlayer
				end

				-- targets within range, nearest first
				local function targetsWithin(distance)
					local _, root = characterParts()
					local parts = {}
					local npcs = workspace:FindFirstChild("NPCs")

					if npcs and root then
						for _, child in ipairs(npcs:GetChildren()) do
							local lowered = child.Name:lower()
							local selected = getgenv().TweenToNPC and getgenv().SelectedNPC and child.Name == getgenv().SelectedNPC

							if not (getgenv().KillAura and not getgenv().npcHasForceField(child) or selected or lowered:find("scient") or lowered:find("law") or child.Name == "Donmingo Family" or child.Name == "Fishman Karate User" or child.Name == "Yeti" or child.Name == "Crazy Wolf" or child.Name == "Juzo the Diamondback" or child.Name == "Roger" or child.Name == "Hawk Eye") then
								continue
							end

							local npcRoot = child:FindFirstChild("HumanoidRootPart")
							local humanoid = child:FindFirstChildOfClass("Humanoid")

							if npcRoot and humanoid and humanoid.Health > 0 and (npcRoot.Position - root.Position).Magnitude <= distance then
								table.insert(parts, npcRoot)
							end
						end
					end

					if getgenv().TweenToPlayer and root then
						local playerReach = math.min(distance, tonumber(getgenv().PvPRange) or 2000)

						for _, player in ipairs(Players:GetPlayers()) do
							if not getgenv().PvPSkippable(player) then
								local npcRoot = player.Character:FindFirstChild("HumanoidRootPart")

								if (npcRoot.Position - root.Position).Magnitude <= playerReach then
									table.insert(parts, npcRoot)
								end
							end
						end
					end

					if (getgenv().AutoFactory or getgenv().AutoFarmGearCyborg) and root then
						local env = workspace:FindFirstChild("Env")
						local factoryPool = env and env:FindFirstChild("FactoryPool")
						local hitbox = factoryPool and factoryPool:FindFirstChild("hitbox")
						local barrelHP = factoryPool and factoryPool:FindFirstChild("barrelHP")

						if hitbox and hitbox:IsA("BasePart") and (not barrelHP or barrelHP.Value and barrelHP.Value > 0) and (hitbox.Position - root.Position).Magnitude <= 50 then
							table.insert(parts, hitbox)
						end
					end

					if root and #parts > 1 then
						local origin = root.Position

						table.sort(parts, function(a, b)
							return (a.Position - origin).Magnitude < (b.Position - origin).Magnitude
						end)
					end

					return parts
				end

				-- selected fish that are actually in the inventory
				local function sellableFish()
					local inventory = ReplicatedStorage:WaitForChild("Stats" .. localPlayer.Name).Inventory:WaitForChild("Inventory")

					if not inventory.Value or inventory.Value == "" then
						return {}
					end

					local ok, decoded = pcall(function()
						return game:GetService("HttpService"):JSONDecode(inventory.Value)
					end)

					if not ok or type(decoded) ~= "table" then
						return {}
					end

					local list = {}

					if not getgenv().SelectedFish then
						return list
					end

					for k, v in pairs(getgenv().SelectedFish) do
						local name = type(k) == "string" and k or v
						local amount = decoded[name]

						if amount and amount > 0 then
							table.insert(list, name)
						end
					end

					return list
				end

				-- holding or carrying a fishing rod
				local function hasRod()
					local function findRod(container)
						if not container then
							return nil
						end
						for _, child in ipairs(container:GetChildren()) do
							if child:IsA("Tool") and string.find(child.Name:lower(), "rod") then
								return child
							end
						end
						return nil
					end

					return findRod(localPlayer.Character) ~= nil or findRod(localPlayer:FindFirstChild("Backpack")) ~= nil
				end

				-- within 25 studs of the fishing spot
				local function atFishingSpot()
					local spot = getgenv().FishingSpotCF

					if not spot then
						return true
					end

					local _, root = characterParts()

					if not root then
						return false
					end

					return (spot.Position - root.Position).Magnitude <= (getgenv().FishingSpotRange or 25)
				end

				local statusFns = {}

				statusFns.Farm = function(genv, root, humanoid)
					if not genv.autofarm then
						return "off"
					end

					local placeId = game.PlaceId

					if placeId ~= 3978370137 and placeId ~= 7465136166 then
						return "only works in First or Second Sea"
					end

					if not (humanoid and humanoid.Health > 0) then
						return "waiting to respawn"
					end

					if genv.AutoFishing then
						return "paused - Auto Fishing is on"
					end

					if genv.AutoMerchant and getMerchantMarker() and not genv.AlreadyGoToMerchant then
						return "paused - Auto Merchant is going to the merchant"
					end

					if genv.JuzoFighting or genv.UmiBossEngaged or genv.BossLootDwelling then
						return "paused - a boss fight is on"
					end

					local level = genv.Level and genv.Level() or 0 -- uses getgenv().Level
					local yetiQuest = genv.haki and placeId == 3978370137 and not hasBusoHaki()

					if yetiQuest then
						yetiQuest = genv.IsOnYetiQuest()
						yetiQuest = yetiQuest or level >= 80 and getPeli() >= 25000
					end

					if yetiQuest then
						return "paused - Auto Haki is doing the Yeti quest"
					end

					-- the real Y threshold isn't known, uses FishmanInsideY if set, otherwise skips the check
					local fishmanY = genv.FishmanInsideY

					if placeId == 3978370137 and root and fishmanY and root.Position.Y > fishmanY then
						return string.format("Lv %d - heading to Fishman Island", level)
					end

					local mobName = placeId == 3978370137 and "Fishman Karate User" or "Crazy Wolf"

					if not questPanelOpen() then
						return string.format("Lv %d - going to take the quest", level)
					end

					local mob, studs, alive = findNearestAlive(mobName)

					if not mob then
						return string.format("Lv %d - waiting for %s to spawn", level, mobName)
					end

					return string.format("Lv %d - fighting %s (%d studs - %d alive)", level, mobName, studs, alive)
				end

				statusFns.Scroll = function(genv)
					if not genv.AutoWorldScroll then
						return "off"
					end

					if game.PlaceId ~= 3978370137 then
						return "only works in the First Sea"
					end

					local minLevel = genv.ScrollMinLevel or 325
					local level = genv.Level and genv.Level() or 0

					if minLevel > 0 and level < minLevel then
						return string.format("waiting for level %d - you are %d", minLevel, level)
					end

					local inBag = 0

					if genv.WorldScrollCount then
						local ok, result = pcall(genv.WorldScrollCount)

						if ok then
							inBag = result or inBag
						end
					end

					local tail = string.format(" - %d taken, %d in the bag", genv.ScrollsTaken or 0, inBag)

					if genv.GettingScroll then
						local reason = tostring(genv.ScrollBlockReason or "camping the spot")
						local campTime = genv.ScrollCampStart and clock(tick() - genv.ScrollCampStart) or nil

						if campTime then
							return reason .. " (" .. campTime .. ")" .. tail
						end

						return reason .. tail
					end

					if genv.ScrollNeeded and not genv.ScrollNeeded() then
						return "you already have a scroll" .. tail
					end

					return "getting ready to camp the scroll spot" .. tail
				end

				statusFns.Haki = function(genv)
					if not genv.haki then
						return "off"
					end

					if game.PlaceId ~= 3978370137 then
						return "only works in First Sea"
					end

					if hasBusoHaki() then
						return "done - you already have Buso Haki"
					end

					if not genv.IsOnYetiQuest() then
						local level = genv.Level and genv.Level() or 0
						local peli = getPeli()

						if level < 80 or peli < 25000 then
							return string.format("needs Lv 80 and 25k peli (Lv %d with %d peli)", level, peli)
						end

						return "going to take the Yeti quest"
					end

					local yeti, studs = findNearestAlive("Yeti")

					if not yeti then
						return "on the quest - waiting for the Yeti to spawn"
					end

					return string.format("fighting the Yeti (%d studs)", studs)
				end

				statusFns.KillAura = function(genv)
					if not genv.KillAura then
						return "off"
					end

					local range = targetRange()
					local targets = targetsWithin(range)

					if #targets == 0 then
						return string.format("no mobs within %d studs", math.floor(range))
					end

					local parent = targets[1].Parent
					return string.format("hitting %s (%d in range)", tostring(parent and parent.Name), #targets)
				end

				statusFns.NPC = function(genv, _, humanoid)
					if not genv.TweenToNPC then
						return "off"
					end

					local selected = genv.SelectedNPC

					if not selected or selected == "None" then
						return "pick an NPC first"
					end

					if genv.autofarm or genv.haki or genv.AutoJuzoBoss or genv.AutoMihawkBoss or genv.AutoRogerBoss or genv.AutoFishing or genv.AutoMerchant or genv.StartTweenIsland then
						return "paused - another farm is running"
					end

					if not (humanoid and humanoid.Health > 0) then
						return "waiting to respawn"
					end

					local npc, studs = findNearestAlive(selected)

					if not npc then
						return "waiting for " .. selected .. " to spawn"
					end

					local npcHumanoid = npc:FindFirstChildOfClass("Humanoid")
					return string.format("fighting %s (%d studs - HP %d/%d)", selected, studs, math.floor(npcHumanoid.Health), math.floor(npcHumanoid.MaxHealth))
				end

				statusFns.Merchant = function(genv)
					if not genv.AutoMerchant then
						return "off"
					end

					local restock = restockSuffix()
					local restockText = restock and (" - next restock in " .. restock) or ""
					local noItems = #toList(genv.SelectedMerchantItems) == 0 and " - no items picked" or ""

					if genv.AlreadyGoToMerchant then
						return "bought from this stock" .. restockText .. noItems
					end

					local marker = getMerchantMarker()

					if not marker then
						return "the merchant is not out" .. restockText .. noItems
					end

					if getPeli() <= 0 then
						return "the merchant is out but you have no peli"
					end

					if tick() < (genv.MerchantRetryAt or 0) then
						return string.format("last visit failed - trying again in %ds", math.ceil(genv.MerchantRetryAt - tick())) .. noItems
					end

					if genv.CraftingTrip then
						return "paused - crafting bait"
					end

					local position = marker.Value

					if typeof(position) == "CFrame" then
						position = position.Position
					end

					local studs = typeof(position) == "Vector3" and distanceTo(position) or 0

					if studs > 30 then
						return string.format("heading to the merchant (%d studs)", studs) .. noItems
					end

					return "at the merchant - buying" .. noItems
				end

				statusFns.Fishing = function(genv, _, humanoid)
					if not genv.AutoFishing then
						return "off"
					end

					if not (humanoid and humanoid.Health > 0) then
						return "waiting to respawn"
					end

					if genv.FruitHold then
						return "paused - storing fruit"
					end

					if genv.CraftingTrip then
						return "paused - crafting bait"
					end

					if genv.StoringFruit then
						return "paused - storing a fruit"
					end

					local toMerchant = genv.AutoMerchant and getMerchantMarker() and genv.MerchantReady

					toMerchant = toMerchant and genv.MerchantReady() and getPeli() > 0

					if toMerchant then
						return "paused - going to the merchant"
					end

					if not hasRod() then
						return "no rod - going to buy one"
					end

					local casts = string.format(" - %d casts", genv.ThrowsAccepted or 0)

					if genv.IsFishing then
						if genv.FishingReeled then
							return "reeling in a fish" .. casts
						end

						return string.format("line out %ds - waiting for a bite", math.floor(tick() - (genv.FishingCastAt or tick()))) .. casts
					end

					if not atFishingSpot() then
						local spot = genv.FishingSpotCF

						if tweenState.Enabled and spot then
							return string.format("heading to the fishing spot (%d studs)", distanceTo(spot.Position))
						end

						return "getting ready to head to the fishing spot"
					end

					return "at the spot - " .. tostring(genv.FishingBlockReason or "casting") .. casts
				end

				statusFns.Sell = function(genv)
					if not genv.SellFish then
						return "off"
					end

					if #toList(genv.SelectedFish) == 0 then
						return "pick fish to sell first"
					end

					if getPeli() >= 1000000 then
						return "paused - peli is at the 1M cap"
					end

					local ok, result = pcall(sellableFish)

					if not ok or #result == 0 then
						return "nothing to sell right now"
					end

					return string.format("selling %d kind(s) of fish", #result)
				end

				statusFns.Craft = function(genv)
					if not genv.AutoCraftSelectedBait then
						return "off"
					end

					local baits = toList(genv.CurrentFishBaitToCraft)

					if #baits == 0 then
						return "pick a bait to craft first"
					end

					if genv.CraftingTrip then
						return "crafting at " .. tostring(genv.CraftNPCName or "the blacksmith")
					end

					local parts = {}

					for _, bait in ipairs(baits) do
						table.insert(parts, string.format("%s have %d can make %d", string.gsub(bait, " Fish Bait", ""), genv.baitCount(bait), genv.craftableCount(bait)))
					end

					local summary = table.concat(parts, " | ")

					if tick() < (genv.CraftRetryAt or 0) then
						return string.format("nothing could be made - checking again in %ds - ", math.ceil(genv.CraftRetryAt - tick())) .. summary
					end

					if genv.craftWorkPending() then
						return "ready - going to craft - " .. summary
					end

					return "waiting for enough fish - " .. summary
				end

				statusFns.Fruit = function(genv)
					if not genv.AutoStoreFruit and not genv.DropUnlistedFruit then
						return "off"
					end

					if genv.StoringFruit then
						if genv.FruitHold and not genv.FruitHoldAck then
							return "waiting for the cast to finish"
						end

						return "storing a fruit"
					end

					local text = string.format("watching the bag for %s - %d stored", genv.StoreAllFruit and "every fruit" or #toList(genv.SelectedFruitToStore) .. " picked fruit", genv.FruitsStored or 0)
					local webhook = genv.FruitWebhookLast

					if genv.FruitWebhook and webhook and webhook.ok == false then
						text ..= " - last webhook failed"
					end

					return text
				end

				-- island teleport (Tween tab)
				statusFns.Tween = function(genv)
					if not genv.StartTweenIsland then
						return "off"
					end

					local island = genv.CurrentIsland

					if type(island) == "table" then
						island = island[1]
					end

					if not island or island == "" or island == "None" then
						return "pick an island first"
					end

					local islands = workspace:FindFirstChild("Islands")
					local islandModel = islands and islands:FindFirstChild(island)

					if not islandModel then
						return island .. " is not loaded"
					end

					local ok, pivot = pcall(function()
						return islandModel:GetPivot()
					end)

					local studs = ok and distanceTo(pivot.Position) or 0

					if tweenState.Enabled then
						return string.format("heading to %s (%d studs)", island, studs)
					end

					return string.format("at %s (%d studs)", island, studs)
				end

				statusFns.Trade = function(genv)
					if not genv.AutoTrade then
						return "off"
					end

					if game.PlaceId ~= 6811831486 then
						return "only works in the Trade place"
					end

					local mainAccount = genv.TradeMainAccount or ""

					if mainAccount == "" then
						return "set the Main Account first"
					end

					local done = genv.TradesCompleted or 0
					local gui = playerGui()

					if gui and gui:FindFirstChild("TradeGUI") then
						return string.format("trade window open - adding items (%d done)", done)
					end

					if localPlayer.Name == mainAccount then
						return string.format("MAIN - waiting for a trade from the alt (%d done)", done)
					end

					local stock = genv.tradeStockFor and genv.tradeStockFor(false) or 0

					if stock <= 0 then
						return string.format("ALT - nothing left to send (%d done)", done)
					end

					return string.format("ALT - sending %d item(s) to %s (%d done)", stock, mainAccount, done)
				end

				statusFns.PvP = function(genv, _, humanoid)
					if not genv.TweenToPlayer then
						return "off"
					end

					if genv.autofarm or genv.haki or genv.AutoJuzoBoss or genv.AutoMihawkBoss or genv.AutoRogerBoss or genv.AutoFishing or genv.AutoMerchant or genv.StartTweenIsland or genv.TweenToNPC then
						return "paused - another farm is running"
					end

					if not (humanoid and humanoid.Health > 0) then
						return "waiting to respawn"
					end

					local target = genv.PvPTarget and genv.PvPTarget()

					if not target then
						if genv.PvPAutoTarget == false then
							local selected = genv.SelectedPlayer

							if type(selected) == "table" then
								selected = selected[1]
							end

							if not selected or selected == "None" then
								return "pick a player first"
							end

							return "waiting for " .. tostring(selected) .. " to show up"
						end

						return string.format("nobody to fight within %d studs", math.floor(tonumber(genv.PvPRange) or 2000))
					end

					local targetCharacter = target.Character
					local targetRoot = targetCharacter and targetCharacter:FindFirstChild("HumanoidRootPart")
					local targetHumanoid = targetCharacter and targetCharacter:FindFirstChildOfClass("Humanoid")
					local myCharacter = localPlayer.Character
					local myRoot = myCharacter and myCharacter:FindFirstChild("HumanoidRootPart")

					if not (targetRoot and targetHumanoid and myRoot) then
						return "target is loading in"
					end

					return string.format(
						"fighting %s (%d studs - HP %d/%d)",
						target.Name,
						math.floor((targetRoot.Position - myRoot.Position).Magnitude),
						math.floor(targetHumanoid.Health),
						math.floor(targetHumanoid.MaxHealth)
					)
				end

				getgenv().FarmStatusText = function(key)
					local fn = statusFns[key]

					if not fn then
						return "off"
					end

					local _, root, humanoid = characterParts()
					return fn(getgenv(), root, humanoid)
				end
			end

			-- FloorUnder
			do
				-- FloorUnder(position, options): first standable hit straight down, skips barriers / water / see-through parts

				-- water if the part or one of its 6 parents has "ocean" / "water" in the name
				local function isWaterPart(instance)
					if getgenv().GroundRaySkipWater == false then
						return false
					end

					for _ = 1, 6 do
						if not instance or instance == workspace then
							break
						end

						local name = string.lower(instance.Name)

						if string.find(name, "ocean", 1, true) or string.find(name, "water", 1, true) then
							return true
						end

						instance = instance.Parent
					end

					return false
				end

				-- collidable, visible, not a barrier, not water
				local function isStandable(part)
					if not part then
						return false
					end

					if isWaterPart(part) then
						getgenv().GroundRayWaterHits = (getgenv().GroundRayWaterHits or 0) + 1
						return false
					end

					local ok, result = pcall(function()
						if not part.CanCollide then
							return false
						end

						if 1 <= part.Transparency then
							return false
						end

						local collisionGroup = part.CollisionGroup

						if collisionGroup and string.match(collisionGroup, "Barrier") then
							return false
						end

						return true
					end)

					return ok and result == true
				end

				getgenv().FloorUnder = function(position, options)
					options = options or {}

					if typeof(position) == "CFrame" then
						position = position.Position
					end

					if typeof(position) ~= "Vector3" then
						return nil
					end

					local groundRayDown = tonumber(options.Drop) or getgenv().GroundRayDown

					groundRayDown = groundRayDown or 1000
					local groundRayLayers = tonumber(options.Layers) or getgenv().GroundRayLayers or 8

					local raycastParams = RaycastParams.new()

					if options.Include then
						raycastParams.FilterType = Enum.RaycastFilterType.Include
						raycastParams.FilterDescendantsInstances = options.Include
					else
						raycastParams.FilterType = Enum.RaycastFilterType.Exclude
						raycastParams.FilterDescendantsInstances = options.Exclude or {}
					end

					raycastParams.IgnoreWater = true

					for _ = 1, groundRayLayers do
						if groundRayDown <= 0 then
							return nil
						end

						local hit = workspace:Raycast(position, Vector3.new(0, -groundRayDown, 0), raycastParams)

						if not (hit and hit.Instance) then
							return nil
						end

						if isStandable(hit.Instance) then
							return hit.Position, hit.Instance
						end

						groundRayDown = groundRayDown - (position.Y - hit.Position.Y) - 0.05
						position = Vector3.new(position.X, hit.Position.Y - 0.05, position.Z)
					end

					return nil
				end
			end

			-- fruits stored this run (nothing increments it, the dump only sets it to 0)
			getgenv().FruitsStored = getgenv().FruitsStored or 0

			-- InstallNoDashStamina
			do
				-- InstallNoDashStamina(): __namecall hook that drops dash stamina charges

				local ReplicatedStorage = game:GetService("ReplicatedStorage")

				-- shared with InstallNoGeppoStamina through getgenv so only one hook gets installed

				local function log(message)
					if getgenv().BMLog then
						getgenv().BMLog(message)
					end
				end

				local function getDashRemote()
					local events = ReplicatedStorage:FindFirstChild("Events")
					return events and events:FindFirstChild("takestam")
				end

				local function getSkillRemote()
					local events = ReplicatedStorage:FindFirstChild("Events")
					return events and events:FindFirstChild("Skill")
				end

				-- hub tween state isn't exported, so while this is nil every dash / geppo charge gets dropped
				local tweenState = getgenv().__TensenTweenState   -- hub tween state

				local function scriptIsTweening()
					return tweenState ~= nil and tweenState.Enabled == true
				end

				local function hookApiAvailable()
					return type(hookmetamethod) == "function" and type(newcclosure) == "function" and type(getnamecallmethod) == "function"
				end

				-- installs the stamina hook (shared by both Install* functions)
				local function installStaminaHook()
					if getgenv().__TensenStaminaHooked then
						return true
					end

					if not hookApiAvailable() then
						if not getgenv().__TensenStaminaWarned then
							getgenv().__TensenStaminaWarned = true
							log("[Tensen] No Dash/Geppo Stamina needs hookmetamethod, newcclosure and getnamecallmethod - this executor is missing one, so the toggle(s) stay inert.")
						end

						return false
					end

					local oldNamecall

					local ok, result = pcall(function()
						oldNamecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
							local args = table.pack(...)
							local active = getgenv().NoDashStamina == true or getgenv().NoGeppoStamina == true

							if active then
								local method = getnamecallmethod()

								if getgenv().NoDashStamina ~= true or method ~= "FireServer" or self ~= getDashRemote() then
									if getgenv().NoGeppoStamina == true and method == "InvokeServer" and self == getSkillRemote() then
										local skillName = ...

										if type(skillName) == "string" and (getgenv().GeppoSkillNames or {})[skillName] and not scriptIsTweening() then
											getgenv().GeppoStaminaSaved = (getgenv().GeppoStaminaSaved or 0) + 1
											return
										end
									end

									return oldNamecall(self, table.unpack(args, 1, args.n))
								end

								if select(2, ...) == "dash" and not scriptIsTweening() then
									getgenv().DashStaminaSaved = (getgenv().DashStaminaSaved or 0) + 1
									return
								end

								return oldNamecall(self, table.unpack(args, 1, args.n))
							end

							return oldNamecall(self, table.unpack(args, 1, args.n))
						end))
					end)

					if ok and type(oldNamecall) == "function" then
						getgenv().__TensenStaminaHooked = true
						return true
					end

					log("[Tensen] stamina hook could not hook __namecall: " .. tostring(result))
					return false
				end

				getgenv().InstallNoDashStamina = function()
					local installed = installStaminaHook()

					if installed and getgenv().NoDashStamina == true and getgenv().LogNoDashStamina ~= false and not getgenv().__DashStamSaid then
						getgenv().__DashStamSaid = true
						log("[Tensen] No Dash Stamina armed - the dash stamina charge is dropped while you dash by hand, so the bar never drains and you can dash freely (farm tweens are left alone).")
					end

					return installed
				end
			end

			-- InstallNoGeppoStamina
			do
				-- InstallNoGeppoStamina(): same hook, for geppo / sky walk

				local ReplicatedStorage = game:GetService("ReplicatedStorage")

				-- shared with InstallNoDashStamina through getgenv so only one hook gets installed

				local function log(message)
					if getgenv().BMLog then
						getgenv().BMLog(message)
					end
				end

				local function getDashRemote()
					local events = ReplicatedStorage:FindFirstChild("Events")
					return events and events:FindFirstChild("takestam")
				end

				local function getSkillRemote()
					local events = ReplicatedStorage:FindFirstChild("Events")
					return events and events:FindFirstChild("Skill")
				end

				-- hub tween state isn't exported, so while this is nil every dash / geppo charge gets dropped
				local tweenState = getgenv().__TensenTweenState   -- hub tween state

				local function scriptIsTweening()
					return tweenState ~= nil and tweenState.Enabled == true
				end

				local function hookApiAvailable()
					return type(hookmetamethod) == "function" and type(newcclosure) == "function" and type(getnamecallmethod) == "function"
				end

				-- installs the stamina hook (shared by both Install* functions)
				local function installStaminaHook()
					if getgenv().__TensenStaminaHooked then
						return true
					end

					if not hookApiAvailable() then
						if not getgenv().__TensenStaminaWarned then
							getgenv().__TensenStaminaWarned = true
							log("[Tensen] No Dash/Geppo Stamina needs hookmetamethod, newcclosure and getnamecallmethod - this executor is missing one, so the toggle(s) stay inert.")
						end

						return false
					end

					local oldNamecall

					local ok, result = pcall(function()
						oldNamecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
							local args = table.pack(...)
							local active = getgenv().NoDashStamina == true or getgenv().NoGeppoStamina == true

							if active then
								local method = getnamecallmethod()

								if getgenv().NoDashStamina ~= true or method ~= "FireServer" or self ~= getDashRemote() then
									if getgenv().NoGeppoStamina == true and method == "InvokeServer" and self == getSkillRemote() then
										local skillName = ...

										if type(skillName) == "string" and (getgenv().GeppoSkillNames or {})[skillName] and not scriptIsTweening() then
											getgenv().GeppoStaminaSaved = (getgenv().GeppoStaminaSaved or 0) + 1
											return
										end
									end

									return oldNamecall(self, table.unpack(args, 1, args.n))
								end

								if select(2, ...) == "dash" and not scriptIsTweening() then
									getgenv().DashStaminaSaved = (getgenv().DashStaminaSaved or 0) + 1
									return
								end

								return oldNamecall(self, table.unpack(args, 1, args.n))
							end

							return oldNamecall(self, table.unpack(args, 1, args.n))
						end))
					end)

					if ok and type(oldNamecall) == "function" then
						getgenv().__TensenStaminaHooked = true
						return true
					end

					log("[Tensen] stamina hook could not hook __namecall: " .. tostring(result))
					return false
				end

				getgenv().InstallNoGeppoStamina = function()
					local installed = installStaminaHook()

					if installed and getgenv().NoGeppoStamina == true and getgenv().LogNoGeppoStamina ~= false and not getgenv().__GeppoStamSaid then
						getgenv().__GeppoStamSaid = true
						log("[Tensen] No Geppo Stamina armed - the Geppo / Sky Walk stamina charge is dropped when you geppo by hand, so the bar never drains (farm flight keep-alive is left alone). You still rise from the Infinite Jump push.")
					end

					return installed
				end
			end

			-- NearbyNPCNames
			do
				-- NearbyNPCNames(): npc names within NPCListRange, nearest first. needs getgenv().npcHasForceField, which nothing defines
				local Players = game:GetService("Players")
				local localPlayer = Players.LocalPlayer

				getgenv().NearbyNPCNames = function()
					local names = {}
					local seen = {}
					local character = localPlayer.Character
					local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
					local npcs = workspace:FindFirstChild("NPCs")

					if not (humanoidRootPart and npcs) then
						return names
					end

					local found = {}

					for _, child in ipairs(npcs:GetChildren()) do
						local npcRoot = child:FindFirstChild("HumanoidRootPart") or child.PrimaryPart
						local humanoid = child:FindFirstChildOfClass("Humanoid")

						if npcRoot and humanoid and humanoid.Health > 0 and not seen[child.Name] and not getgenv().npcHasForceField(child) then
							local distance = (npcRoot.Position - humanoidRootPart.Position).Magnitude

							if distance <= (getgenv().NPCListRange or 1500) then
								seen[child.Name] = true
								table.insert(found, { name = child.Name, d = distance })
							end
						end
					end

					table.sort(found, function(a, b)
						return a.d < b.d
					end)

					for _, entry in ipairs(found) do
						table.insert(names, entry.name)
					end

					return names
				end
			end

			-- NearbyPlayerNames
			do
				-- NearbyPlayerNames(): attackable players, nearest first. needs getgenv().PvPSkippable, which nothing defines
				local Players = game:GetService("Players")
				local localPlayer = Players.LocalPlayer

				getgenv().NearbyPlayerNames = function()
					local names = {}
					local character = localPlayer.Character
					local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")

					if not humanoidRootPart then
						return names
					end

					local found = {}

					for _, player in ipairs(Players:GetPlayers()) do
						-- no character check here, PvPSkippable is what keeps the local player and dead players out
						if not getgenv().PvPSkippable(player) then
							table.insert(found, {
								name = player.Name,
								d = (player.Character:FindFirstChild("HumanoidRootPart").Position - humanoidRootPart.Position).Magnitude,
							})
						end
					end

					table.sort(found, function(a, b)
						return a.d < b.d
					end)

					for _, entry in ipairs(found) do
						table.insert(names, entry.name)
					end

					return names
				end
			end

			-- PvPSkippable
			do
				-- PvPSkippable(player): true for yourself, dead players, and teammates when "Skip Teammates" is on
				local LocalPlayer = game:GetService("Players").LocalPlayer

				getgenv().PvPSkippable = function(player)
					if player == LocalPlayer then
						return true
					end

					local character = player.Character
					local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")

					if not (humanoidRootPart and humanoid and humanoid.Health > 0) then
						return true
					end

					if getgenv().PvPSkipTeammates ~= false and getgenv().ESPIsTeammate then
						local ok, result = pcall(getgenv().ESPIsTeammate, player)

						if ok and result then
							return true
						end
					end

					return false
				end
			end

			-- RecordFruitTool
			do
				-- RecordFruitTool(toolName, stored): only the "stored" webhook part survived, the rest is missing
				local HttpService = game:GetService("HttpService")
				local localPlayer = game:GetService("Players").LocalPlayer

				local function fruitLog(...)
					local bmLog = getgenv().BMLog

					if bmLog then
						bmLog(...)
					end
				end

				-- rarity lookup built once from getgenv().FruitRarity
				local rarityByFruit = nil

				local function fruitRarity(name)
					if not rarityByFruit then
						rarityByFruit = {}

						for rarity, fruitNames in pairs(getgenv().FruitRarity or {}) do
							for _, fruitName in ipairs(fruitNames) do
								rarityByFruit[string.lower(fruitName)] = rarity
							end
						end
					end

					local front = getgenv().FruitFrontName(name)
					return front and rarityByFruit[string.lower(front)] or "Unknown"
				end

				-- discord webhook for a stored fruit
				local function sendFruitWebhook(shownName, name, kind)
					if not getgenv().FruitWebhook then
						return false
					end

					local webhookUrl = getgenv().FruitWebhookURL

					if not webhookUrl or webhookUrl == "" then
						fruitLog("[Fruit] the webhook is on but no URL is set - nothing was sent.")
						return false
					end

					local requestFn = http_request or request or (syn and syn.request)

					if not requestFn then
						fruitLog("[Fruit] this executor has no HTTP request function - the webhook cannot be sent.")
						return false
					end

					local kindText = tostring(kind or "Stored")
					local fruitText = tostring(name or shownName)
					local rarity = fruitRarity(fruitText)

					local allowedRarities = getgenv().NormalizeSelectedItems(getgenv().WebhookRarities)

					if #allowedRarities > 0 then
						local allowed = false

						for _, allowedRarity in ipairs(allowedRarities) do
							if string.lower(allowedRarity) == string.lower(rarity) then
								allowed = true
								break
							end
						end

						if not allowed then
							-- filtered out by rarity, don't send
							return false
						end
					end

					local pingEveryone = getgenv().PingEveryone == true
					local description = string.format("%s\n@%s\n```\n%s\n%s\n%s\n```\n", localPlayer.Name, localPlayer.DisplayName, fruitText, rarity, kindText)

					local payload = {
						username = "Tensen",
						content = pingEveryone and "@everyone" or nil,
						allowed_mentions = pingEveryone and { parse = { "everyone" } } or nil,
					}

					local embed = { title = kindText == "Stored" and "FRUIT STORED :" or "FRUIT FOUND :", description = description }
					local color = kindText == "Stored" and 65535

					-- everything below only runs for "Stored", other kinds send nothing
					if not color then
						return nil
					end

					embed.color = color
					embed.author = { name = "Tensen Hub \u{2022} Grand Piece Online" }
					embed.footer = { text = "stored on : " .. os.date("%d/%m/%Y %H:%M:%S", os.time()) }
					payload.embeds = { embed }

					local ok, response = pcall(function()
						return requestFn({
							Url = webhookUrl,
							Body = HttpService:JSONEncode(payload),
							Method = "POST",
							Headers = { ["Content-Type"] = "application/json" },
						})
					end)

					local why, code

					if not ok then
						why = "the request errored: " .. tostring(response)
						code = nil
					elseif type(response) == "table" then
						code = tonumber(response.StatusCode or response.Status or response.status_code)

						if code == 401 or code == 403 then
							why = code .. " - the token is wrong or the webhook was revoked"
						elseif code == 404 then
							why = code .. " - this webhook has been DELETED (make a new one and paste the URL again)"
						elseif code == 429 then
							why = code .. " - rate limited"
						else
							why = nil

							if code and (code < 200 or code >= 300) then
								why = tostring(code)
							end
						end
					else
						code = nil
						why = "the executor returned no response object"
					end

					ok = ok and (code == nil or (code >= 200 and code < 300))

					getgenv().FruitWebhookLast = {
						at = os.time(),
						code = code,
						ok = ok,
						why = why,
						fruit = tostring(shownName),
					}

					if ok then
						fruitLog(string.format("[Fruit] webhook sent for '%s' (HTTP %s).", tostring(shownName), code and tostring(code) or "unknown"))
					else
						fruitLog(string.format("[Fruit] the webhook FAILED for '%s': %s", tostring(shownName), tostring(why)))
					end

					return ok
				end

				getgenv().RecordFruitTool = function(name, stored)
					if stored then
						-- the display name part is a guess
						local shownName = getgenv().fruitFrontName and getgenv().fruitFrontName(name) or nil
						pcall(sendFruitWebhook, shownName or name, name, "Stored")
					end

					-- unknown what the non-stored call is supposed to do
				end
			end

			-- RefreshKeybindHud
			do
				-- keybind hud: defines RefreshKeybindHud and ResetKeybindHudPos, skips the build if the panel already exists

				local keybindHudBuilt = getgenv().__TensenKeybindHudModule

				if not (typeof(keybindHudBuilt) == "Instance" and keybindHudBuilt.Parent) then
					local HttpService = game:GetService("HttpService")
					local Players = game:GetService("Players")
					local UserInputService = game:GetService("UserInputService")
					local TextService = game:GetService("TextService")
					local LocalPlayer = Players.LocalPlayer

					-- default colours, themes override them
					local palette = {
						CardBg = Color3.fromRGB(24, 24, 24),
						White = Color3.fromRGB(255, 255, 255),
						TextGray = Color3.fromRGB(154, 154, 154),
						TrackBg = Color3.fromRGB(43, 43, 43),
						Accent = Color3.fromRGB(167, 200, 244),
					}
					-- state dot colours: on / off
					local dotOnColor = Color3.fromRGB(105, 166, 124)
					local dotOffColor = Color3.fromRGB(90, 90, 96)

					-- row layout (19 vs 22 might be swapped, not sure from the dump)
					local ROW_PITCH = 19
					local PAD = 12
					local ROW_TOP = 22

					if getgenv().ShowKeybindHud == nil then
						getgenv().ShowKeybindHud = true
					end

					getgenv().KeybindHudLocked = getgenv().KeybindHudLocked == true
					getgenv().KeybindList = getgenv().KeybindList or {}

					-- key display names table is missing, raw KeyCode names are shown
					local keyDisplayNames = {}

					local function keyName(keyCode)
						if typeof(keyCode) ~= "EnumItem" then
							return "None"
						end

						local name = keyCode.Name

						if name == "Unknown" then
							return "None"
						end

						return keyDisplayNames[name] or name
					end

					-- saved panel position
					local function getKeybindHudPos()
						if getgenv().KeybindHudPos then
							return getgenv().KeybindHudPos
						end

						pcall(function()
							if type(isfile) ~= "function" or not isfile("Tensen Hub/keybinds.json") then
								return
							end

							local data = HttpService:JSONDecode(readfile("Tensen Hub/keybinds.json"))

							if type(data) == "table" and tonumber(data.X) and tonumber(data.Y) then
								getgenv().KeybindHudPos = { X = tonumber(data.X), Y = tonumber(data.Y) }
							end
						end)

						return getgenv().KeybindHudPos
					end

					local function saveKeybindHudPos(x, y)
						getgenv().KeybindHudPos = { X = math.floor(x), Y = math.floor(y) }

						pcall(function()
							if type(writefile) ~= "function" then
								return
							end

							writefile("Tensen Hub/keybinds.json", HttpService:JSONEncode(getgenv().KeybindHudPos))
						end)
					end

					-- gui
					local hui = nil

					pcall(function()
						hui = gethui and gethui()
					end)

					local old = (hui or game:GetService("CoreGui")):FindFirstChild("TensenKeybinds")

					if old then
						old:Destroy()
					end

					local screenGui = Instance.new("ScreenGui")
					screenGui.Name = "TensenKeybinds"
					screenGui.IgnoreGuiInset = true
					screenGui.ResetOnSpawn = false
					screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
					screenGui.DisplayOrder = 6
					screenGui.Enabled = false

					local parentFailed = not pcall(function()
						screenGui.Parent = hui
					end) or not screenGui.Parent

					if parentFailed then
						screenGui.Parent = LocalPlayer:WaitForChild("PlayerGui")
					end

					getgenv().__TensenKeybindHudModule = screenGui

					local function create(className, props)
						local instance = Instance.new(className)

						for k, v in pairs(props) do
							if k ~= "Parent" then
								instance[k] = v
							end
						end

						instance.Parent = props.Parent
						return instance
					end

					local function corner(parent, radius)
						create("UICorner", { CornerRadius = UDim.new(0, radius), Parent = parent })
					end

					local function textWidth(text, size, font)
						local ok, result = pcall(function()
							return TextService:GetTextSize(text, size, font, Vector2.new(1000, 100))
						end)

						return ok and result.X or #text * size * 0.55
					end

					local panel = create("Frame", {
						Name = "Panel",
						Active = true,
						BorderSizePixel = 0,
						BackgroundColor3 = palette.CardBg,
						BackgroundTransparency = 0.08,
						Position = UDim2.fromOffset(18, 300),
						Size = UDim2.fromOffset(150, 60),
						ZIndex = 2,
						Parent = screenGui,
					})
					corner(panel, 6)

					-- the three below get recoloured on every refresh
					local stroke = create("UIStroke", { Color = palette.Accent, Transparency = 0.75, Thickness = 1, Parent = panel })

					local accentBar = create("Frame", {
						BackgroundColor3 = palette.Accent,
						BorderSizePixel = 0,
						Size = UDim2.new(0, 3, 1, 0),
						ZIndex = 3,
						Parent = panel,
					})
					corner(accentBar, 2)

					local titleLabel = create("TextLabel", {
						BackgroundTransparency = 1,
						Font = Enum.Font.GothamBold,
						Text = "KEYBINDS",
						TextSize = 10,
						TextColor3 = palette.TextGray,
						TextXAlignment = Enum.TextXAlignment.Left,
						Position = UDim2.fromOffset(12, 6),
						Size = UDim2.new(1, -PAD * 2, 0, 12),
						ZIndex = 3,
						Parent = panel,
					})

					-- one row per registered keybind: key chip, name, state dot
					local rows = {}

					local function getRow(index)
						local existing = rows[index]

						if existing then
							return existing
						end

						local holder = create("Frame", {
							BackgroundTransparency = 1,
							ZIndex = 3,
							Position = UDim2.fromOffset(12, ROW_TOP + (index - 1) * ROW_PITCH),
							Size = UDim2.new(1, -PAD * 2, 0, 19),
							Parent = panel,
						})

						local chip = create("Frame", {
							BackgroundColor3 = palette.TrackBg,
							BorderSizePixel = 0,
							Position = UDim2.fromOffset(0, 1),
							Size = UDim2.fromOffset(26, 15),
							ZIndex = 4,
							Parent = holder,
						})
						corner(chip, 4)

						local keyLabel = create("TextLabel", {
							BackgroundTransparency = 1,
							Font = Enum.Font.GothamBold,
							Text = "",
							TextSize = 10,
							TextColor3 = palette.White,
							Size = UDim2.fromScale(1, 1),
							ZIndex = 5,
							Parent = chip,
						})

						local nameLabel = create("TextLabel", {
							BackgroundTransparency = 1,
							Font = Enum.Font.Gotham,
							Text = "",
							TextSize = 11,
							TextColor3 = palette.White,
							TextXAlignment = Enum.TextXAlignment.Left,
							Size = UDim2.new(1, -40, 1, 0),
							ZIndex = 4,
							Parent = holder,
						})

						local dot = create("Frame", {
							AnchorPoint = Vector2.new(1, 0.5),
							BorderSizePixel = 0,
							BackgroundColor3 = dotOnColor,
							Position = UDim2.new(1, 0, 0.5, 0),
							Size = UDim2.fromOffset(6, 6),
							Visible = false,
							ZIndex = 4,
							Parent = holder,
						})
						corner(dot, 3)

						local row = { holder = holder, chip = chip, key = keyLabel, name = nameLabel, dot = dot }
						rows[index] = row
						return row
					end

					-- viewport / clamping / default position
					local function getViewport()
						local absoluteSize = screenGui.AbsoluteSize

						if absoluteSize.X > 10 and absoluteSize.Y > 10 then
							return absoluteSize
						end

						local currentCamera = workspace.CurrentCamera

						if currentCamera and currentCamera.ViewportSize.X > 10 then
							return currentCamera.ViewportSize
						end

						return Vector2.new(50496, 49744)
					end

					local function clampPanel()
						local viewport = getViewport()
						local absoluteSize = panel.AbsoluteSize

						if absoluteSize.X < 10 or absoluteSize.Y < 10 then
							return
						end

						local x = math.clamp(panel.Position.X.Offset, 0, math.max(0, viewport.X - absoluteSize.X))
						local y = math.clamp(panel.Position.Y.Offset, 0, math.max(0, viewport.Y - absoluteSize.Y))

						if x ~= panel.Position.X.Offset or y ~= panel.Position.Y.Offset then
							panel.Position = UDim2.fromOffset(x, y)
						end
					end

					local function defaultPos()
						return 18, math.floor(getViewport().Y * 0.35)
					end

					local function resetKeybindHudPos()
						local x, y = defaultPos()
						panel.Position = UDim2.fromOffset(x, y)
						saveKeybindHudPos(x, y)
						return x, y
					end

					getgenv().ResetKeybindHudPos = resetKeybindHudPos

					local savedPos = getKeybindHudPos()

					if savedPos then
						panel.Position = UDim2.fromOffset(savedPos.X, savedPos.Y)
					else
						local x, y = defaultPos()
						panel.Position = UDim2.fromOffset(x, y)
					end

					-- refresh
					local function refresh()
						local keybindList = getgenv().KeybindList or {}

						if getgenv().ShowKeybindHud == false or #keybindList == 0 then
							screenGui.Enabled = false
							return
						end

						screenGui.Enabled = true

						local tensenUILib = getgenv().TensenUILib
						local themeName = tensenUILib and tensenUILib.GetTheme and tensenUILib:GetTheme()
						local themeFound = tensenUILib and tensenUILib.Themes and themeName and tensenUILib.Themes[themeName]
						local theme = palette

						if themeFound then
							theme = tensenUILib.Themes[themeName]
						end

						local cardBg = theme.CardBg or palette.CardBg
						local white = theme.White or palette.White
						local textGray = theme.TextGray or palette.TextGray
						local trackBg = theme.TrackBg or palette.TrackBg
						local accent = theme.Accent or palette.Accent

						panel.BackgroundColor3 = cardBg
						stroke.Color = accent
						accentBar.BackgroundColor3 = accent
						titleLabel.TextColor3 = textGray

						local widestKey = 26
						local widestName = 40

						for i, bind in ipairs(keybindList) do
							local row = getRow(i)
							local ok, result = pcall(bind.key)
							local text = keyName(ok and result or nil)
							local stateOn = nil

							if bind.state then
								local stateOk, stateValue = pcall(bind.state)
								stateOn = nil

								if stateOk then
									stateOn = stateValue == true
								end
							end

							row.key.Text = text
							row.name.Text = tostring(bind.name)
							row.name.TextColor3 = stateOn == false and textGray or white
							row.chip.BackgroundColor3 = stateOn == true and accent or trackBg
							row.key.TextColor3 = stateOn == true and cardBg or white
							row.dot.Visible = stateOn ~= nil
							row.dot.BackgroundColor3 = stateOn and dotOnColor or dotOffColor

							row.holder.Visible = true
							row.holder.Position = UDim2.fromOffset(12, ROW_TOP + (i - 1) * ROW_PITCH)
							widestKey = math.max(widestKey, textWidth(text, 10, Enum.Font.GothamBold) + 12)
							widestName = math.max(widestName, textWidth(row.name.Text, 11, Enum.Font.Gotham))
						end

						for i = #keybindList + 1, #rows do
							rows[i].holder.Visible = false
						end

						for i = 1, #keybindList do
							local row = rows[i]
							row.chip.Size = UDim2.fromOffset(widestKey, 15)
							row.name.Position = UDim2.fromOffset(widestKey + 8, 0)
							row.name.Size = UDim2.new(1, -(widestKey + 8 + 0), 1, 0)
						end

						-- the rest of refresh (resizing the panel) was lost, the panel stays 150x60
					end

					local function isBoundKey(keyCode)
						for _, bind in ipairs(getgenv().KeybindList or {}) do
							local ok, result = pcall(bind.key)

							if ok and result == keyCode then
								return true
							end
						end

						return false
					end

					-- dragging
					local dragging = false
					local dragStart = nil
					local panelStart = nil

					panel.InputBegan:Connect(function(input)
						if getgenv().KeybindHudLocked == true then
							return
						end

						if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then
							return
						end

						dragging = true
						dragStart = input.Position
						panelStart = panel.Position

						input.Changed:Connect(function()
							if input.UserInputState == Enum.UserInputState.End and dragging then
								dragging = false
								saveKeybindHudPos(panel.Position.X.Offset, panel.Position.Y.Offset)
							end
						end)
					end)

					UserInputService.InputChanged:Connect(function(input)
						if not dragging then
							return
						end

						if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then
							return
						end

						local delta = input.Position - dragStart
						panel.Position = UDim2.fromOffset(panelStart.X.Offset + delta.X, panelStart.Y.Offset + delta.Y)
						clampPanel()
					end)

					getgenv().RefreshKeybindHud = function()
						return pcall(refresh)
					end

					-- refresh after a bound key, state changes land a frame later
					UserInputService.InputBegan:Connect(function(input, gameProcessed)
						if gameProcessed then
							return
						end

						if getgenv().ShowKeybindHud == false then
							return
						end

						if input.UserInputType ~= Enum.UserInputType.Keyboard then
							return
						end

						if not isBoundKey(input.KeyCode) then
							return
						end

						pcall(refresh)

						task.defer(function()
							pcall(refresh)
						end)

						task.delay(0.06, function()
							pcall(refresh)
						end)
					end)

					pcall(refresh)

					-- refresh loop, spawned so loading doesn't block
					task.spawn(function()
						while task.wait(0.25) do
							pcall(refresh)
						end
					end)
				end
			end

			-- RefreshNoScreenShake
			do
				-- RefreshNoScreenShake(): mutes shake remotes, hooks the game's shake functions, pins CameraOffset

				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local RunService = game:GetService("RunService")
				local localPlayer = Players.LocalPlayer

				-- state
				local applied = false
				local shakeConnection = nil
				local mutedConnections = {}
				local hookedOriginals = {}
				local savedCameraShake = nil

				local function log(message)
					if getgenv().BMLog then
						getgenv().BMLog(message)
					end
				end

				local function getShakeRemotes()
					local children = {}
					local events = ReplicatedStorage:FindFirstChild("Events")

					if not events then
						return children
					end

					for _, name in ipairs({"CameraShake", "camshake"}) do
						local child = events:FindFirstChild(name)

						if child and child:IsA("RemoteEvent") then
							children[#children + 1] = child
						end
					end

					return children
				end

				-- filter for the game's own connections (exact test is a guess)
				local function isGameConnection(connection)
					local callback = connection.Function

					if type(callback) ~= "function" then
						return false
					end

					local isLua = type(islclosure) == "function" and islclosure(callback)
					local isExecutor = type(is_synapse_function) == "function" and is_synapse_function(callback)

					return isLua and not isExecutor
				end

				-- returns how many connections got muted
				local function muteShakeRemotes()
					if type(getconnections) ~= "function" then
						return 0
					end

					local count = 0

					for _, remote in ipairs(getShakeRemotes()) do
						pcall(function()
							for _, connection in ipairs(getconnections(remote.OnClientEvent)) do
								if isGameConnection(connection) and pcall(function()
									connection:Disable()
								end) then
									mutedConnections[#mutedConnections + 1] = connection
									count += 1
								end
							end
						end)
					end

					return count
				end

				-- the game's client shake functions
				local function collectShakeFunctions()
					local functions = {}

					local function add(candidate)
						if type(candidate) == "function" then
							functions[#functions + 1] = candidate
						end
					end

					pcall(function()
						local util = ReplicatedStorage:FindFirstChild("Util")
						local shakeCamera = util and util:FindFirstChild("ShakeCamera")

						if not shakeCamera then
							return
						end

						local ok, result = pcall(require, shakeCamera)

						if ok then
							add(result)
						end
					end)

					pcall(function()
						local modules = ReplicatedStorage:FindFirstChild("Modules")
						local cameraShaker = modules and modules:FindFirstChild("CameraShaker")

						if not cameraShaker then
							return
						end

						local ok, result = pcall(require, cameraShaker)

						if not ok or type(result) ~= "table" then
							return
						end

						for _, key in ipairs({"Shake", "ShakeOnce", "ShakeSustain", "StartShake"}) do
							add(rawget(result, key))
						end
					end)

					for _, path in ipairs({
						{"Modules", "ForgeVFX", "effects", "camera_shake"},
						{"Modules", "ZiliEmitModule", "camera_shake"},
					}) do
						pcall(function()
							local child = ReplicatedStorage

							for _, name in ipairs(path) do
								child = child and child:FindFirstChild(name)
							end

							if not child then
								return
							end

							local ok, result = pcall(require, child)

							if ok and type(result) == "table" then
								add(rawget(result, "emit"))
							end
						end)
					end

					return functions
				end

				-- swaps one shake function for a stub, true if it worked
				local function hookShakeFunction(shakeFunction)
					if type(shakeFunction) ~= "function" or hookedOriginals[shakeFunction] then
						return false
					end

					local function stub()
						getgenv().ShakesBlocked = (getgenv().ShakesBlocked or 0) + 1
					end

					if type(newcclosure) == "function" then
						local ok, wrapped = pcall(newcclosure, stub)

						if ok and wrapped then
							stub = wrapped
						end
					end

					local ok, original = pcall(hookfunction, shakeFunction, stub)

					if ok and type(original) == "function" then
						hookedOriginals[shakeFunction] = original
						return true
					end

					return false
				end

				-- keeps Humanoid.CameraOffset at zero
				local function pinCameraOffset()
					if getgenv().NoScreenShake ~= true then
						return
					end

					local character = localPlayer.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")

					if humanoid and humanoid.CameraOffset.Magnitude > 0.01 then
						humanoid.CameraOffset = Vector3.zero
					end
				end

				-- returns (muted listeners, hooked functions)
				local function applyNoShake()
					if applied then
						return muteShakeRemotes(), 0
					end

					applied = true

					pcall(function()
						local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)
						local settings = stats and stats:FindFirstChild("Settings")
						local cameraShake = settings and settings:FindFirstChild("CameraShake")

						if cameraShake then
							savedCameraShake = cameraShake.Value
							cameraShake.Value = false
						end
					end)

					local muted = muteShakeRemotes()
					local hooked = 0

					if type(hookfunction) == "function" then
						for _, shakeFunction in ipairs(collectShakeFunctions()) do
							if hookShakeFunction(shakeFunction) then
								hooked += 1
							end
						end
					elseif getgenv().NoShakeHookWarned ~= true then
						getgenv().NoShakeHookWarned = true
						log("[Shake] this executor has no hookfunction - the server's shakes are still blocked, but effects that shake the camera on their own will get through.")
					end

					if getgenv().NoShakeCameraOffset ~= false and not shakeConnection then
						shakeConnection = RunService.RenderStepped:Connect(pinCameraOffset)
					end

					return muted, hooked
				end

				-- hands the shake functions back, returns how many
				local function restoreShakes()
					if not applied then
						return 0
					end

					applied = false

					if shakeConnection then
						pcall(function()
							shakeConnection:Disconnect()
						end)

						shakeConnection = nil
					end

					for _, connection in ipairs(mutedConnections) do
						pcall(function()
							connection:Enable()
						end)
					end

					mutedConnections = {}
					local restored = 0

					for shakeFunction, original in pairs(hookedOriginals) do
						if pcall(hookfunction, shakeFunction, original) then
							restored += 1
						end
					end

					hookedOriginals = {}

					if savedCameraShake ~= nil then
						pcall(function()
							local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)
							local settings = stats and stats:FindFirstChild("Settings")
							local cameraShake = settings and settings:FindFirstChild("CameraShake")

							if cameraShake then
								cameraShake.Value = savedCameraShake
							end
						end)

						savedCameraShake = nil
					end

					return restored
				end

				getgenv().RefreshNoScreenShake = function()
					if getgenv().NoScreenShake == true then
						local muted, hooked = applyNoShake()

						if getgenv().LogNoShake ~= false and hooked > 0 then
							log(string.format("[Shake] off - muted %d shake listener(s) and %d shake function(s).", muted or 0, hooked or 0))
						end

						return true
					end

					local wasApplied = applied
					local restored = restoreShakes()
					local shouldLog = getgenv().LogNoShake ~= false

					if not wasApplied then
						shouldLog = (restored or 0) > 0
					else
						shouldLog = shouldLog and (restored or 0) > 0
					end

					if shouldLog then
						log(string.format("[Shake] back on - %d function(s) handed back to the game.", restored))
					end

					return false
				end

				-- watcher, started once
				task.spawn(function()
					while task.wait(2) do
						if getgenv().NoScreenShake == true then
							applyNoShake()
						elseif applied then
							restoreShakes()
						end
					end
				end)
			end

			-- RefreshStreamerMode
			do
				-- streamer mode: also defines StreamerNamesFor (used by the esp) and StreamerInfo

				local Players = game:GetService("Players")
				local CoreGui = game:GetService("CoreGui")
				local RunService = game:GetService("RunService")
				local LocalPlayer = Players.LocalPlayer

				-- defaults
				getgenv().StreamerMode = getgenv().StreamerMode == true
				getgenv().StreamerHideMe = getgenv().StreamerHideMe ~= false
				getgenv().StreamerHideTeam = getgenv().StreamerHideTeam ~= false
				getgenv().StreamerHideAll = getgenv().StreamerHideAll == true
				getgenv().StreamerHideUserId = getgenv().StreamerHideUserId == true

				for _, key in ipairs({ "StreamerMaskMe", "StreamerMaskTeam", "StreamerMaskOther" }) do
					local value = getgenv()[key]

					if value == "You" or value == "Teammate" or value == "Player" then
						getgenv()[key] = nil
					end
				end

				getgenv().StreamerMaskMe = getgenv().StreamerMaskMe or "discord.gg/tensenhub"
				getgenv().StreamerMaskTeam = getgenv().StreamerMaskTeam or "discord.gg/tensenhub"
				getgenv().StreamerMaskOther = getgenv().StreamerMaskOther or "discord.gg/tensenhub"
				getgenv().StreamerMaskUserId = getgenv().StreamerMaskUserId or "kissmyass"
				getgenv().StreamerRate = getgenv().StreamerRate or 0.4
				getgenv().StreamerHidden = 0
				getgenv().StreamerCoreGuis = getgenv().StreamerCoreGuis or { "PlayerList", "ExperienceChat", "Chat", "BubbleChat" }
				getgenv().StreamerMinName = getgenv().StreamerMinName or 3

				-- state
				local active = false
				local sweeping = false -- re-entrancy flag of the sweep
				local lastNamesSignature = nil -- string of the covered names from the last sweep
				local settingsSignature = nil
				local masked = setmetatable({}, { __mode = "k" }) -- label -> { orig = original text, masked = replaced text }
				local checked = setmetatable({}, { __mode = "k" }) -- label -> text last checked without a match
				local touched = setmetatable({}, { __mode = "k" }) -- labels we replaced (restored by restoreAll)
				local hooked = setmetatable({}, { __mode = "k" }) -- labels with a Text-changed connection
				local rootsHooked = setmetatable({}, { __mode = "k" }) -- guis with a DescendantAdded connection
				local hot = setmetatable({}, { __mode = "k" }) -- labels whose text changed since the last render step

				-- log function isn't in this part of the dump, guessed
				local function log(text)
					pcall(print, text)
				end

				-- who gets covered
				local function maskFor(player)
					if player == LocalPlayer then
						if getgenv().StreamerHideMe == false then
							return nil
						end

						return getgenv().StreamerMaskMe or "discord.gg/tensenhub"
					end

					local isTeam = false

					if getgenv().ESPIsTeammate then
						local ok, result = pcall(getgenv().ESPIsTeammate, player)
						isTeam = ok and result == true
					end

					if isTeam then
						if getgenv().StreamerHideTeam == false then
							return nil
						end

						return getgenv().StreamerMaskTeam or "discord.gg/tensenhub"
					end

					if getgenv().StreamerHideAll ~= true then
						return nil
					end

					return getgenv().StreamerMaskOther or "discord.gg/tensenhub"
				end

				local function streamerNamesFor(player)
					if not player then
						return nil
					end

					if getgenv().StreamerMode ~= true then
						return player.DisplayName, player.Name
					end

					local mask = maskFor(player)

					if mask then
						return mask, mask
					end

					return player.DisplayName, player.Name
				end

				getgenv().StreamerNamesFor = streamerNamesFor

				-- list of { name, low, mask } to cover, longest name first
				local function getNames()
					local list = {}
					local seen = {}
					-- min name length, defaults to 3
					local minLen = tonumber(getgenv().StreamerMinName) or 3

					local function addName(name, mask)
						if type(name) ~= "string" or #name < minLen then
							return
						end

						local low = string.lower(name)

						if seen[low] then
							return
						end

						seen[low] = true
						list[#list + 1] = { name = name, low = low, mask = mask }
					end

					if getgenv().StreamerMode == true then
						for _, player in ipairs(Players:GetPlayers()) do
							local mask = maskFor(player)

							if mask then
								addName(player.Name, mask)
								addName(player.DisplayName, mask)
							end
						end
					end

					if getgenv().StreamerHideUserId == true then
						addName(tostring(LocalPlayer.UserId), getgenv().StreamerMaskUserId or "kissmyass")
					end

					table.sort(list, function(a, b)
						return #a.name > #b.name
					end)

					return list
				end

				-- the guis that are scanned
				local function getRoots()
					local roots = {}
					local playerGui = LocalPlayer:FindFirstChild("PlayerGui")

					if playerGui then
						for _, child in ipairs(playerGui:GetChildren()) do
							if child:IsA("LayerCollector") then
								roots[#roots + 1] = child
							end
						end
					end

					for _, name in ipairs(getgenv().StreamerCoreGuis or {}) do
						local ok, result = pcall(function()
							return CoreGui:FindFirstChild(name)
						end)

						if ok and result then
							roots[#roots + 1] = result
						end
					end

					for _, instance in ipairs(getgenv().TensenOwnGuis or {}) do
						if instance and instance.Parent then
							roots[#roots + 1] = instance
						end
					end

					return roots
				end

				-- text masking. tag ranges "<...>" in the text, nil if none
				local function findTags(text)
					if not string.find(text, "<", 1, true) then
						return nil
					end

					local ranges = {}
					local pos = 1

					while true do
						local s, e = string.find(text, "<[^<>]*>", pos)

						if not s then
							break
						end

						ranges[#ranges + 1] = { s, e }
						pos = e + 1
					end

					if #ranges == 0 then
						return nil
					end

					return ranges
				end

				local function inTag(ranges, s, e)
					if not ranges then
						return false
					end

					for _, range in ipairs(ranges) do
						if s <= range[2] and e >= range[1] then
							return true
						end
					end

					return false
				end

				-- returns the new text and whether anything was replaced
				local function maskText(text, names)
					if type(text) ~= "string" or text == "" or #text > 500 then
						return text, false
					end

					local tags = findTags(text)
					local lowered = string.lower(text)
					local changed = false

					for _, entry in ipairs(names) do
						local pieces = {}
						local pos = 1
						local hit = false

						while true do
							local s, e = string.find(lowered, entry.low, pos, true)

							if not s then
								break
							end

							local before = s > 1 and string.sub(text, s - 1, s - 1) or ""
							local after = e < #text and string.sub(text, e + 1, e + 1) or ""
							local wholeWord = (before == "" or not string.match(before, "[%w_]")) and (after == "" or not string.match(after, "[%w_]"))
							pieces[#pieces + 1] = string.sub(text, pos, s - 1)

							if wholeWord and not inTag(tags, s, e) then
								pieces[#pieces + 1] = entry.mask
								hit = true
							else
								pieces[#pieces + 1] = string.sub(text, s, e)
							end

							pos = e + 1
						end

						-- the end of this function was missing, this is the smallest tail that makes it work
						if hit then
							pieces[#pieces + 1] = string.sub(text, pos)
							text = table.concat(pieces)
							lowered = string.lower(text)
							changed = true
						end
					end

					return text, changed
				end

				-- mask one label if it has a covered name, true if masked
				local function applyLabel(instance, names)
					if not (instance and (instance:IsA("TextLabel") or instance:IsA("TextButton"))) then
						return false
					end

					names = names or getNames()

					if #names == 0 then
						return false
					end

					local entry = masked[instance]
					local text = instance.Text

					if entry and text == entry.masked then
						return true
					end

					if checked[instance] == text then
						return false
					end

					local newText, changed = maskText(text, names)

					if changed then
						checked[instance] = nil
						masked[instance] = { orig = text, masked = newText }

						pcall(function()
							instance.Text = newText
						end)

						touched[instance] = true
						return true
					end

					checked[instance] = text

					if entry then
						masked[instance] = nil
					end

					return false
				end

				-- keep a label masked when the game rewrites its Text
				local function hookLabel(instance)
					if hooked[instance] then
						return
					end

					hooked[instance] = true

					pcall(function()
						instance:GetPropertyChangedSignal("Text"):Connect(function()
							if getgenv().StreamerMode == true or getgenv().StreamerHideUserId == true then
								if masked[instance] then
									hot[instance] = true
								end

								pcall(applyLabel, instance)
							end
						end)
					end)
				end

				local function onDescendantAdded(instance)
					if getgenv().StreamerMode ~= true and getgenv().StreamerHideUserId ~= true then
						return
					end

					if not (instance:IsA("TextLabel") or instance:IsA("TextButton")) then
						return
					end

					task.defer(function()
						if getgenv().StreamerMode == true or getgenv().StreamerHideUserId == true then
							pcall(applyLabel, instance)
						end
					end)

					hookLabel(instance)
				end

				-- per-frame fix-up of labels that changed text since the last frame
				local cachedNames = nil
				local cachedNamesTime = 0

				RunService:BindToRenderStep("TensenStreamerHot", Enum.RenderPriority.Last.Value, function()
					local off = getgenv().StreamerMode ~= true and getgenv().StreamerHideUserId ~= true

					if off then
						return
					end

					if next(hot) == nil then
						return
					end

					local now = os.clock()

					if not cachedNames or now - cachedNamesTime > 0.5 then
						cachedNames = getNames()
						cachedNamesTime = now
					end

					local pending = hot
					hot = setmetatable({}, { __mode = "k" })

					for label in pairs(pending) do
						if not label.Parent then
							touched[label] = nil
							continue
						end

						local entry = masked[label]

						if not (entry and label.Text == entry.masked) then
							checked[label] = nil
							pcall(applyLabel, label, cachedNames)
						end
					end
				end)

				local function hookRoots()
					for _, root in ipairs(getRoots()) do
						if not rootsHooked[root] then
							rootsHooked[root] = true

							pcall(function()
								root.DescendantAdded:Connect(onDescendantAdded)
							end)
						end
					end
				end

				-- full sweep over every scanned gui, time-sliced
				local function sweep()
					if sweeping then
						return
					end

					local names = getNames()

					if #names == 0 then
						getgenv().StreamerHidden = 0
						return
					end

					local lows = {}

					for _, entry in ipairs(names) do
						lows[#lows + 1] = entry.low
					end

					local namesSignature = table.concat(lows, "~")

					if namesSignature ~= lastNamesSignature then
						lastNamesSignature = namesSignature
						table.clear(checked)
					end

					sweeping = true
					local deadline = os.clock() + (getgenv().StreamerBudget or 0.002)
					local hidden = 0

					for _, root in ipairs(getRoots()) do
						local ok, descendants = pcall(function()
							return root:GetDescendants()
						end)

						if not ok then
							continue
						end

						for i = 1, #descendants do
							local instance = descendants[i]

							if instance:IsA("TextLabel") or instance:IsA("TextButton") then
								hookLabel(instance)
								local entry = masked[instance]
								local text = instance.Text

								if entry and text == entry.masked then
									hidden += 1
								elseif checked[instance] ~= text then
									local newText, changed = maskText(text, names)

									if changed then
										checked[instance] = nil
										masked[instance] = { orig = text, masked = newText }

										pcall(function()
											instance.Text = newText
										end)

										touched[instance] = true
										hidden += 1
									else
										checked[instance] = text

										if entry then
											masked[instance] = nil
										end
									end
								end
							end

							if i % 128 == 0 and os.clock() > deadline then
								task.wait()
								deadline = os.clock() + (getgenv().StreamerBudget or 0.002)
							end
						end
					end

					sweeping = false
					getgenv().StreamerHidden = hidden
				end

				-- put every replaced label back; returns how many were restored
				local function restoreAll()
					local restored = 0

					for label in pairs(touched) do
						pcall(function()
							local entry = masked[label]

							if label.Parent and label.Text == entry.masked then
								label.Text = entry.orig
								restored += 1
							end
						end)
					end

					touched = setmetatable({}, { __mode = "k" })
					getgenv().StreamerHidden = 0
					return restored
				end

				-- only the first four parts survived, so the signature is just those joined
				local function updateSettingsSignature()
					settingsSignature = table.concat({
						tostring(getgenv().StreamerMode),
						tostring(getgenv().StreamerHideMe),
						tostring(getgenv().StreamerHideTeam),
						tostring(getgenv().StreamerHideAll),
					}, "|")
				end

				-- entry point
				local function refreshStreamerMode()
					if getgenv().StreamerMode == true or getgenv().StreamerHideUserId == true then
						active = true
						pcall(hookRoots)
						-- undo old replacements before sweeping again
						pcall(restoreAll)
						return pcall(sweep)
					end

					if active then
						active = false
						local ok, result = pcall(restoreAll)

						if ok and getgenv().StreamerLog ~= false and (result or 0) > 0 then
							log(string.format("[Streamer] off - put %d name(s) back.", result))
						end

						return ok
					end

					return true
				end

				getgenv().RefreshStreamerMode = refreshStreamerMode

				getgenv().StreamerInfo = function()
					local names = getNames()
					local lines = {}
					local state = getgenv().StreamerMode and "ON" or "off"
					local hidden = getgenv().StreamerHidden or 0

					lines[#lines + 1] = string.format(
						"[Streamer] %s | hiding %d label(s) right now | me=%s team=%s everyone=%s",
						state,
						hidden,
						tostring(getgenv().StreamerHideMe ~= false),
						tostring(getgenv().StreamerHideTeam ~= false),
						tostring(getgenv().StreamerHideAll == true)
					)

					for _, entry in ipairs(names) do
						lines[#lines + 1] = string.format("   %-24s -> %s", entry.name, entry.mask)
					end

					if #names == 0 then
						lines[#lines + 1] = "   (no names to cover with these settings)"
					end

					local text = table.concat(lines, "\n")
					log(text)
					return text
				end

				-- background loop, spawned so loading doesn't block
				task.spawn(function()
					local lastSweep = 0
					local lastSignature = nil

					while task.wait(getgenv().StreamerRate or 0.4) do
						if not (getgenv().StreamerMode == true or getgenv().StreamerHideUserId == true) then
							continue
						end

						active = true
						pcall(hookRoots)
						pcall(updateSettingsSignature)

						if settingsSignature ~= lastSignature or os.clock() - lastSweep >= (getgenv().StreamerSweepRate or 3) then
							lastSweep = os.clock()
							lastSignature = settingsSignature
							pcall(sweep)
						end

						continue

						-- what the original did when it's off is unknown, nothing here
					end
				end)
			end

			-- RehookAntiStun
			do
				-- RehookAntiStun(): hooks ChildAdded to strip stun objects while AntiStun is on

				local Players = game:GetService("Players")
				local localPlayer = Players.LocalPlayer

				local connections = {}

				local function onStunChild(instance)
					if getgenv().AntiStun ~= true then
						return
					end

					if not instance or not instance.Parent then
						return
					end

					local name = instance.Name

					if (getgenv().StunNames or {})[name] then
						if pcall(function()
							instance:Destroy()
						end) then
							getgenv().StunsCleared = (getgenv().StunsCleared or 0) + 1
						end

						return
					end

					if not (instance:IsA("BodyPosition") or instance:IsA("BodyVelocity") or instance:IsA("BodyGyro")) then
						return
					end

					if (getgenv().StunMoverWhitelist or {})[name] then
						return
					end

					local isScriptMover = getgenv().isScriptMover

					if type(isScriptMover) == "function" and isScriptMover(name) then
						return
					end

					local bmStale = getgenv().bmStale

					if type(bmStale) == "function" and bmStale() then
						return
					end

					if pcall(function()
						instance:Destroy()
					end) then
						getgenv().StunsCleared = (getgenv().StunsCleared or 0) + 1
					end
				end

				local function hook(instance)
					if not instance then
						return
					end

					table.insert(connections, instance.ChildAdded:Connect(onStunChild))
				end

				getgenv().RehookAntiStun = function()
					for _, connection in ipairs(connections) do
						pcall(function()
							connection:Disconnect()
						end)
					end

					connections = {}

					hook(localPlayer:FindFirstChildOfClass("Backpack"))
					hook(localPlayer.Character)
				end
			end

			-- TPToIsland
			do
				-- TPToIsland and the helpers it needs (TPNotice, DropToGround, LoopIslandTP), only set if missing. needs getgenv().tpCharacter and FloorUnder

				local function log(message)
					local bmLog = getgenv().BMLog
					if bmLog then
						bmLog(message)
					end
				end

				-- stops a running island tween first (the hub doesn't export its stop function, so this can be nil)
				local stopTween = getgenv().StopCurrentTween   -- hub tween stop

				-- TPNotice
				getgenv().TPNotice = getgenv().TPNotice or function(message)
					log("[TP] " .. tostring(message))

					pcall(function()
						game:GetService("StarterGui"):SetCore("SendNotification", {
							Title = "Teleport",
							Text = tostring(message),
							Duration = 6,
						})
					end)
				end

				-- DropToGround(character, lift, options): ray down and stand on the hit
				getgenv().DropToGround = getgenv().DropToGround or function(character, lift, options)
					options = options or {}
					character = character or getgenv().tpCharacter()
					local rootPart = character and character:FindFirstChild("HumanoidRootPart")

					if not (rootPart and rootPart.Parent) then
						return nil
					end

					local position = rootPart.Position
					local exclude = nil

					if not options.Include then
						exclude = { character }

						for _, instance in ipairs(options.Exclude or {}) do
							if instance then
								exclude[#exclude + 1] = instance
							end
						end
					end

					local hitPosition, hitInstance = getgenv().FloorUnder(position, { Include = options.Include, Exclude = exclude, Drop = options.Drop })

					if not hitPosition then
						return nil
					end

					local groundRayLift = lift or getgenv().GroundRayLift or 3
					local cframe = CFrame.new(hitPosition + Vector3.new(0, groundRayLift, 0))

					if not pcall(function()
						character:PivotTo(cframe)
					end) then
						return nil
					end

					getgenv().GroundDrops = (getgenv().GroundDrops or 0) + 1

					if getgenv().GroundRayLog ~= false and tick() - (getgenv().LastGroundRayLog or 0) >= 1 then
						getgenv().LastGroundRayLog = tick()
						log(string.format(
							"[Ground] Rayed down from Y %d, hit '%s' at Y %d - stood %d over it at Y %d (fell %d, x%d).",
							math.floor(position.Y),
							tostring(hitInstance and hitInstance.Name or "?"),
							math.floor(hitPosition.Y),
							math.floor(groundRayLift),
							math.floor(cframe.Position.Y),
							math.floor(position.Y - hitPosition.Y),
							getgenv().GroundDrops
						))
					end

					return cframe, hitInstance
				end

				-- LoopIslandTP: step() every frame, reset after TPIslandHold, keep going for TPIslandHoldAfter
				getgenv().LoopIslandTP = getgenv().LoopIslandTP or function(character, humanoid, rootPart, step)
					if not humanoid then
						getgenv().TPNotice("Your Humanoid is not ready to teleport yet")
						return false
					end

					-- new token cancels any older loop
					getgenv().TPIslandLoopToken = {}
					getgenv().StartTweenIsland = false
					local myToken = getgenv().TPIslandLoopToken

					local function stillCurrent()
						return getgenv().TPIslandLoopToken == myToken
							and getgenv().tpCharacter() == character
							and character.Parent
							and humanoid.Parent
							and rootPart.Parent
					end

					local healthTarget = tonumber(getgenv().TPIslandSetHP) or 100

					if healthTarget > 0 and humanoid.Health < healthTarget then
						local healthBefore = humanoid.Health

						local healed = pcall(function()
							humanoid.Health = math.min(healthTarget, humanoid.MaxHealth)
						end)

						getgenv().TPIslandHeals = (getgenv().TPIslandHeals or 0) + 1

						if healed and getgenv().TPIslandLog ~= false then
							log(string.format(
								"[TP] topped health up from %d to %d before moving (max %d, x%d).",
								math.floor(healthBefore),
								math.floor(humanoid.Health),
								math.floor(humanoid.MaxHealth),
								getgenv().TPIslandHeals
							))
						end
					end

					local startedAt = os.clock()

					repeat
						if not stillCurrent() or humanoid.Health <= 0 then
							return false
						end

						if not step() then
							return false
						end

						task.wait()
					until os.clock() - startedAt >= (getgenv().TPIslandHold or 0.38)

					if not stillCurrent() or humanoid.Health <= 0 then
						return false
					end

					local resetOk, resetError = pcall(function()
						humanoid.Health = 0
					end)

					if not resetOk then
						getgenv().TPNotice("Reset failed: " .. tostring(resetError))
					end

					local holdAfter = tonumber(getgenv().TPIslandHoldAfter) or 0.1

					if not (resetOk and holdAfter > 0) then
						return resetOk
					end

					local holdStart = os.clock()
					local frames = 0

					while stillCurrent() do
						if not step() then
							break
						end

						frames += 1
						task.wait()

						if holdAfter <= os.clock() - holdStart then
							break
						end
					end

					getgenv().TPIslandAfterHolds = (getgenv().TPIslandAfterHolds or 0) + 1

					if getgenv().TPIslandLog ~= false then
						log(string.format(
							"[TP] held the spot for another %.2fs (%d frames) through the reset, so the respawn is worked out from the island and not from wherever the body fell (x%d).",
							os.clock() - holdStart,
							frames,
							getgenv().TPIslandAfterHolds
						))
					end

					return resetOk
				end

				-- island name -> where to stand (+ how it was found)
				local function resolveIslandTarget(name)
					local islands = workspace:FindFirstChild("Islands")

					if not islands then
						return nil
					end

					local island = islands:FindFirstChild(name)

					if not island then
						log("Could not find island: " .. tostring(name))
						return nil
					end

					local pivotOk, pivot = pcall(function()
						return island:GetPivot()
					end)

					if not (pivotOk and pivot) then
						log("Could not find island: " .. tostring(name))
						return nil
					end

					local boxOk, boxCFrame, boxSize = pcall(function()
						return island:GetBoundingBox()
					end)

					if boxOk and boxCFrame and boxSize and boxSize.Y > 0 then
						local topMargin = getgenv().IslandTopMargin or 20
						local topY = boxCFrame.Position.Y + boxSize.Y / 2 + topMargin
						local rayDrop = boxSize.Y + topMargin + 200
						local groundRayLift = getgenv().GroundRayLift or 3

						-- the body of this logger was lost, does nothing
						local function logGround(reason)
							if getgenv().GroundRayLog == false then
								return
							end

							if tick() - (getgenv().LastIslandGroundLog or 0) < 1 then
								return
							end
						end

						-- 1) straight down from just above the pivot
						local hitPosition, hitInstance = getgenv().FloorUnder(pivot.Position + Vector3.new(0, 2, 0), { Include = { island }, Drop = rayDrop })

						if hitPosition then
							logGround("Rayed down from its pivot onto the ground")
							return CFrame.new(hitPosition + Vector3.new(0, groundRayLift, 0)), "island ground"
						end

						for _, origin in ipairs({ pivot.Position, boxCFrame.Position }) do
							local topHit, topInstance = getgenv().FloorUnder(Vector3.new(origin.X, topY, origin.Z), { Include = { island }, Drop = rayDrop })

							if topHit then
								logGround(
									string.format("Nothing standable straight down from its pivot, so rayed down from Y %d over its top instead and landed on top of", math.floor(topY))
								)
								return CFrame.new(topHit + Vector3.new(0, groundRayLift, 0)), "island ground"
							end
						end
					end

					local position = pivot.Position
					local waterSurfaceY = getgenv().waterSurfaceY and getgenv().waterSurfaceY()

					local airHover = getgenv().IslandAirHover or 30
					local surfaceDepth = getgenv().IslandSurfaceDepth or 150
					local underSea = type(waterSurfaceY) == "number" and position.Y < waterSurfaceY + airHover and position.Y > waterSurfaceY - surfaceDepth
					local how = "its pivot, waiting for it to stream in"

					if underSea then
						position = Vector3.new(position.X, waterSurfaceY + airHover, position.Z)
						getgenv().IslandSeaLifts = (getgenv().IslandSeaLifts or 0) + 1
						how = "hovering over the sea at its pivot, waiting for it to stream in"
					end

					if getgenv().GroundRayLog ~= false and tick() - (getgenv().LastIslandStreamLog or 0) >= 1 then
						getgenv().LastIslandStreamLog = tick()

						if position.Y ~= pivot.Position.Y then
							log(string.format(
								"[TP] '%s' has not streamed in yet, and its pivot at Y %d is %d studs UNDER the sea (Y %d) - not going in the water. Hovering %d over the surface at Y %d instead, and dropping onto the island the moment it loads (x%d).",
								tostring(name),
								math.floor(pivot.Position.Y),
								math.floor(waterSurfaceY - pivot.Position.Y),
								math.floor(waterSurfaceY),
								math.floor(airHover),
								math.floor(position.Y),
								getgenv().IslandSeaLifts or 0
							))
						else
							log(string.format(
								"[TP] '%s' has not streamed in yet (no parts to ray against) - holding at its pivot at Y %d, in the air, until it loads. Not dropping: the only thing under us out here is the sea.",
								tostring(name),
								math.floor(pivot.Position.Y)
							))
						end
					end

					return CFrame.new(position), how
				end

				-- TPToIsland(tpIsland)
				getgenv().TPToIsland = function(tpIsland)
					tpIsland = tpIsland or getgenv().TPIsland

					-- dropdown value is a one-element list
					if type(tpIsland) == "table" then
						tpIsland = tpIsland[1]
					end

					if not tpIsland or tpIsland == "" or tpIsland == "None" then
						getgenv().TPNotice("Pick a destination in Select Island (TP) first")
						return false
					end

					-- 1) where to go
					local fixedSpot = getgenv().tpFixedSpot(tpIsland)
					local target, how

					if fixedSpot then
						if typeof(fixedSpot) ~= "Vector3" then
							target = fixedSpot
						else
							target = CFrame.new(fixedSpot)
						end

						how = "a fixed spot, exactly"
					elseif tpIsland == "Fishman Teleporter" then
						local areaTeleporters = workspace:FindFirstChild("AreaTeleporters")
						local firstSea = areaTeleporters and areaTeleporters:FindFirstChild("FirstSea")
						local fishman = firstSea and firstSea:FindFirstChild("Fishman")
						local portalPart = fishman and fishman:FindFirstChild("Part2")

						if not (portalPart and portalPart:IsA("BasePart")) then
							portalPart = fishman and fishman:FindFirstChild("Part")
						end

						if not (portalPart and portalPart:IsA("BasePart")) then
							getgenv().TPNotice("Neither Fishman Part2 nor Part is loaded in this session")
							return false
						end

						target = portalPart.CFrame
						how = "the portal part, exactly"
					else
						target, how = resolveIslandTarget(tpIsland)
					end

					if not target then
						log(string.format("[TP] '%s' is not in workspace.Islands right now", tostring(tpIsland)))
						return false
					end

					if fixedSpot and getgenv().TPIslandLog ~= false then
						log(string.format("[TP] '%s' is a fixed spot at %s - going there exactly, no island to measure.", tostring(tpIsland), tostring(target.Position)))
					end

					if stopTween then
						pcall(stopTween)
					end

					-- 2) who is moving
					local character = getgenv().tpCharacter()
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					local rootPart = character and character:FindFirstChild("HumanoidRootPart")

					if not rootPart or not rootPart.Parent then
						getgenv().TPNotice("Your character is not ready to teleport yet")
						return false
					end

					local islands = workspace:FindFirstChild("Islands")
					local islandInstance = islands and islands:FindFirstChild(tpIsland) or nil
					local dropToGround = islandInstance ~= nil and not fixedSpot and tpIsland ~= "Fishman Teleporter" and getgenv().IslandDropToGround ~= false

					-- one frame of teleporting
					local function step()
						if dropToGround and how ~= "island ground" then
							local newTarget, newHow = resolveIslandTarget(tpIsland)

							if newTarget then
								target = newTarget
								how = newHow
							end
						end

						local ok, err = pcall(function()
							rootPart.CFrame = target
							rootPart.AssemblyLinearVelocity = Vector3.zero
							rootPart.AssemblyAngularVelocity = Vector3.zero
						end)

						if not ok then
							getgenv().TPNotice("Move failed: " .. tostring(err))
							return false
						end

						if dropToGround and how == "island ground" then
							local dropped = getgenv().DropToGround(character, nil, { Include = { islandInstance } })

							if dropped then
								target = dropped
							end
						end

						return true
					end

					-- 4) hold the spot, reset, hold again
					if not getgenv().LoopIslandTP(character, humanoid, rootPart, step) then
						return false
					end

					getgenv().TPIslandTrips = (getgenv().TPIslandTrips or 0) + 1

					if getgenv().TPIslandLog ~= false then
						log(string.format(
							"[TP] '%s' -> %s (%s) | health %s | x%d",
							tostring(tpIsland),
							tostring(target.Position),
							tostring(how or "?"),
							string.format("reset after %.2fs of repeated teleporting, then held %.2fs more", getgenv().TPIslandHold or 0.38, getgenv().TPIslandHoldAfter or 0.1),
							getgenv().TPIslandTrips
						))
					end

					return true
				end
			end

			-- TradeInfo
			do
				-- TradeInfo(): prints and returns a short summary of the auto trade state
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local HttpService = game:GetService("HttpService")
				local localPlayer = game:GetService("Players").LocalPlayer

				-- falls through to TradeItemAlt when TradeItemMain is nil (same as the dump)
				local function tradeItemNames(isMain)
					return getgenv().NormalizeSelectedItems(isMain and getgenv().TradeItemMain or getgenv().TradeItemAlt or {})
				end

				-- how many of `item` are in the inventory
				local function inventoryCount(item)
					local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)

					if not stats then
						return 0
					end

					local inventory = stats:FindFirstChild("Inventory")
					local inventoryValue = inventory and inventory:FindFirstChild("Inventory")

					if not inventoryValue or not inventoryValue.Value or inventoryValue.Value == "" then
						return 0
					end

					local ok, data = pcall(function()
						return HttpService:JSONDecode(inventoryValue.Value)
					end)

					if not ok or type(data) ~= "table" then
						return 0
					end

					if data[item] ~= nil then
						if type(data[item]) == "number" then
							return data[item]
						end

						if type(data[item]) == "table" and data[item].Amount then
							return data[item].Amount
						end

						return 1
					end

					local wanted = string.lower((string.gsub(item, "[%s%-_']", "")))

					for key, value in pairs(data) do
						if string.lower((string.gsub(tostring(key), "[%s%-_']", ""))) ~= wanted then
							continue
						end

						if type(value) == "number" then
							return value
						end

						if type(value) == "table" and value.Amount then
							return value.Amount
						end

						return 1
					end

					return 0
				end

				local function isMainAccount()
					return localPlayer.Name == getgenv().TradeMainAccount
				end

				getgenv().TradeInfo = function()
					local altItems = tradeItemNames(false)
					local mainItems = tradeItemNames(true)
					local altStock = {}

					for _, item in ipairs(altItems) do
						table.insert(altStock, string.format("%s x%d", item, inventoryCount(item)))
					end

					local text = string.format(
						"[Trade] %s | role: %s | trades %d, items added %d\n  alt sends: %s\n  main sends back: %s (x%d each)",
						getgenv().AutoTrade and "ON" or "OFF",
						isMainAccount() and "MAIN (receiving)" or "ALT (sending)",
						getgenv().TradesCompleted or 0,
						getgenv().TradeItemsAdded or 0,
						#altStock > 0 and table.concat(altStock, ", ") or "nothing ticked",
						#mainItems > 0 and table.concat(mainItems, ", ") or "nothing ticked",
						getgenv().TradeMainSendQty or 1
					)

					-- uses print, the hub's own loggers are no-ops here
					print(text)

					return text
				end
			end

			-- npcHasForceField
			do
				-- npcHasForceField(npc): true for npcs with a ForceField (trainers / safe zone), memoised 2s
				local memo = setmetatable({}, { __mode = "k" })

				getgenv().npcHasForceField = function(instance)
					if not (instance and instance.Parent) then
						return false
					end

					local cached = memo[instance]

					if cached and tick() - cached.t < 2 then
						return cached.v
					end

					-- starts false, set inside the pcall
					local hasForceField = false

					pcall(function()
						local forceFieldNames = getgenv().NPCForceFieldNames or {}

						for _, forceFieldName in ipairs(forceFieldNames) do
							if instance:FindFirstChild(forceFieldName, true) then
								hasForceField = true
								return
							end
						end

						hasForceField = instance:FindFirstChildOfClass("ForceField") ~= nil
					end)

					memo[instance] = { t = tick(), v = hasForceField }
					return hasForceField
				end
			end

			-- swordNameAllowed(name): only the PikaV2 sword when PikaV2 is wanted, everything else otherwise
			getgenv().swordNameAllowed = function(name)
				-- falls back to WeaponType == "PikaV2" if wantPikaV2 isn't there
				local wantPikaV = getgenv().wantPikaV2
				local wantsPika
				if type(wantPikaV) == "function" then
					wantsPika = wantPikaV()
				else
					wantsPika = getgenv().WeaponType == "PikaV2"
				end

				if wantsPika then
					return name == getgenv().PikaV2SwordName
				end

				return name ~= getgenv().PikaV2SwordName
			end

			-- tpCharacter
			do
				-- tpCharacter(): the local character or nil (best guess at which dump function this was)

				local localPlayer = game:GetService("Players").LocalPlayer

				getgenv().tpCharacter = function()
					local character = localPlayer.Character

					if character and character.Parent then
						return character
					end

					local playerCharacters = workspace:FindFirstChild("PlayerCharacters")

					if playerCharacters then
						local child = playerCharacters:FindFirstChild(localPlayer.Name)

						if child then
							return child
						end
					end

					return nil
				end
			end

			-- vertFaceMouse
			do
				-- vertFaceMouse(faceMouse): like sendFaceMouse but always fires the remote
				local ReplicatedStorage = game:GetService("ReplicatedStorage")

				getgenv().vertFaceMouse = function(faceMouse)
					if faceMouse and getgenv().faceMouseBanned and getgenv().faceMouseBanned() then
						faceMouse = false
					end

					local aimStanceEnv = getgenv().AimStanceEnv

					if not aimStanceEnv then
						aimStanceEnv = _G

						if type(getrenv) == "function" then
							pcall(function()
								aimStanceEnv = getrenv()._G
							end)
						end

						getgenv().AimStanceEnv = aimStanceEnv
					end

					aimStanceEnv.FaceMouse = faceMouse
					getgenv().AimStanceRemoteState = faceMouse
					getgenv().LastFaceMouseSend = os.clock()

					pcall(function()
						local events = ReplicatedStorage:FindFirstChild("Events")
						local faceMouseRemote = events and events:FindFirstChild("faceMouse")

						if faceMouseRemote then
							faceMouseRemote:FireServer(faceMouse)
						end
					end)
				end
			end

			-- wantPikaV2(): PikaV2 picked for farming or bosses
			getgenv().wantPikaV2 = function()
				return getgenv().WeaponType == "PikaV2" or getgenv().WeaponTypeBoss == "PikaV2"
			end

			-- farm helpers
			do
				-- helpers for the auto farm loop (level, peli, quest panel, boss checks, fishman route...), only set if missing
				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local localPlayer = Players.LocalPlayer
				local tweenState = getgenv().__TensenTweenState   -- hub tween state
				local stopTween = getgenv().StopCurrentTween   -- hub tween stop
				tweenState = tweenState or getgenv().__TensenTweenState or {Enabled = false}
				local FIRST_SEA = 3978370137
				local SECOND_SEA = 7465136166

				local function define(name, fn)
					if rawget(getgenv(), name) == nil then
						getgenv()[name] = fn
					end
				end

				local function stopNow()
					local f = stopTween or getgenv().StopCurrentTween

					if type(f) == "function" then
						pcall(f)
					end
				end

				local function tweenToCFrame(opts)
					local f = getgenv().TweenToCFrame

					if type(f) == "function" then
						return f(opts)
					end

					return false
				end

				local function playerGui()
					return localPlayer:FindFirstChild("PlayerGui")
				end

				local function rootAndHumanoid()
					local character = localPlayer.Character
					local root = character and character:FindFirstChild("HumanoidRootPart")
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					return root, humanoid
				end

				local function flog(text)
					local f = getgenv().BMLog

					if type(f) == "function" then
						pcall(f, text)
					end
				end

				local function Level()
					local gui = playerGui()
					local hud = gui and gui:FindFirstChild("HUD")
					local main = hud and hud:FindFirstChild("Main")
					local bars = main and main:FindFirstChild("Bars")
					local experience = bars and bars:FindFirstChild("Experience")
					local detail = experience and experience:FindFirstChild("Detail")
					local level = detail and detail:FindFirstChild("Level")

					if not level then
						return nil
					end

					return (tonumber(level.Text:match("%d+")))
				end

				local function PeliAmount()
					local gui = playerGui()
					local hud = gui and gui:FindFirstChild("HUD")
					local main = hud and hud:FindFirstChild("Main")
					local peli = main and main:FindFirstChild("Peli")
					local label = peli and peli:FindFirstChild("TextLabel")

					if not label then
						return 0
					end

					local digits = label.Text:gsub("[^%d]", "")
					return tonumber(digits) or 0
				end

				local function QuestPanelOpen()
					local gui = playerGui()
					local quest = gui and gui:FindFirstChild("Quest")
					local main = quest and quest:FindFirstChild("Main")
					return main and main.Visible == true
				end

				-- living npc with this name?
				local function BossAliveByName(name)
					local npcs = workspace:FindFirstChild("NPCs")

					if not npcs then
						return false
					end

					local lower = name and name:lower() or ""

					for _, child in pairs(npcs:GetChildren()) do
						if child.Name == name or lower ~= "" and string.find(child.Name:lower(), lower, 1, true) then
							local humanoid = child:FindFirstChildOfClass("Humanoid")
							local mobRoot = child:FindFirstChild("HumanoidRootPart") or child.PrimaryPart

							if humanoid and humanoid.Health > 0 and mobRoot then
								return true
							end
						end
					end

					return false
				end

				local function HasBusoHaki()
					local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)

					if stats then
						local skills = stats:FindFirstChild("Skills")

						if skills then
							for _, name in ipairs({"busoHaki", "BusoHaki", "buso", "Buso", "haki", "Haki", "busoshokuHaki", "BusoshokuHaki"}) do
								local skill = skills:FindFirstChild(name)

								if skill then
									skill = skill.Value == true or skill.Value == 1 or type(skill.Value) == "number" and skill.Value > 0
								end

								if skill then
									return true
								end
							end
						end

						local inner = stats:FindFirstChild("Stats")

						if inner then
							local buso = inner:FindFirstChild("Buso") or inner:FindFirstChild("buso")

							if buso then
								if buso.Value == true then
									buso = true
								elseif type(buso.Value) == "number" then
									buso = buso.Value > 0
								else
									buso = false
								end
							end

							if buso then
								return true
							end

							local mastery = inner:FindFirstChild("BusoMastery") or inner:FindFirstChild("busoMastery")

							if mastery and type(mastery.Value) == "number" and mastery.Value > 0 then
								return true
							end
						end
					end

					local character = localPlayer.Character

					if character then
						if character:FindFirstChild(localPlayer.Name .. "Buso") or character:FindFirstChild("Buso") or character:FindFirstChild("Haki") then
							return true
						end

						if character:GetAttribute("Buso") == true or character:GetAttribute("Haki") == true then
							return true
						end
					end

					-- last try: a buso / haki element on the hud
					local gui = playerGui()
					local hud = gui and gui:FindFirstChild("HUD")

					if not hud then
						return false
					end

					local main = hud:FindFirstChild("Main")

					if main then
						for _, descendant in ipairs(main:GetDescendants()) do
							if descendant:IsA("GuiObject") and (descendant.Name == "Buso" or descendant.Name == "busoHaki" or descendant.Name == "Haki") then
								return true
							end
						end
					end

					return false
				end

				-- roger or mihawk window open or opening within 180s. "already killed" flags come from RogerDoneWindow / MihawkDoneWindow if something sets them
				local function UmiBossComingUp()
					if game.PlaceId ~= SECOND_SEA then
						return false
					end

					local utc = os.date("!*t")
					local hour = (utc.hour + 3) % 24
					local rogerSecs = (hour * 3600 + utc.min * 60 + utc.sec) % 5400
					local rogerOpen = rogerSecs <= 900
					local rogerWait = rogerOpen and 0 or 5400 - rogerSecs
					local seconds = utc.min * 60 + utc.sec
					local mihawkOpen = hour % 2 == 1 and seconds <= 900
					local mihawkWait

					if mihawkOpen then
						mihawkWait = 0
					elseif hour % 2 == 1 then
						mihawkWait = 7200 - seconds
					else
						mihawkWait = 3600 - seconds
					end

					local mihawkPending = getgenv().AutoMihawkBoss and not getgenv().MihawkDoneWindow
					local rogerPending = getgenv().AutoRogerBoss and not getgenv().RogerDoneWindow

					return mihawkPending and (mihawkWait <= 180 or mihawkOpen) or rogerPending and (rogerWait <= 180 or rogerOpen) or false
				end

				-- travel. quest / spawn spot (first sea: fishman karate users, second sea: pj and the crazy wolves)
				local function TweenToSP()
					local cframe = nil

					if game.PlaceId == FIRST_SEA then
						cframe = CFrame.new(7830.51611, -2143.83179, -17298.5742, 0.0274390467, -2.41571457e-10, 0.999623477, -1.07395523e-10, 1, 2.44610388e-10, -0.999623477, -1.14066964e-10, 0.0274390467)
					elseif game.PlaceId == SECOND_SEA then
						cframe = CFrame.new(7116.44482, 56.272747, 10550.7393, -0.999996185, -6.44237774e-09, 0.00276109553, -6.63377708e-09, 1, -6.93109214e-08, -0.00276109553, -6.93289763e-08, -0.999996185)
					end

					if not cframe then
						return
					end

					tweenToCFrame({CFrame = cframe, Speed = getgenv().TweenSpeedMaster or 110, StopDistance = 3, TeleportOnClose = true, TeleportDistance = 10})
				end

				-- the two npc spots inside fishman island, which one is becky is a guess
				local function TweenFishmanSetSpawn()
					tweenToCFrame({
						CFrame = CFrame.new(7733.95508, -2175.83203, -17222.3984, -0.299589157, 4.20943245e-08, 0.954068303, -3.16457545e-08, 1, -5.40580238e-08, -0.954068303, -4.63874095e-08, -0.299589157),
						Speed = getgenv().TweenSpeedMaster or 110, StopDistance = 5, TeleportOnClose = true, TeleportDistance = 5
					})
				end

				local function TweenToBecky()
					tweenToCFrame({
						CFrame = CFrame.new(7978.89844, -2152.83203, -17073.1523, -0.594854772, -2.24747136e-08, -0.803833187, -4.58938798e-09, 1, -2.45631728e-08, 0.803833187, -1.09224185e-08, -0.594854772),
						Speed = getgenv().TweenSpeedMaster or 110, StopDistance = 5, TeleportOnClose = true, TeleportDistance = 5
					})
				end

				-- one of these two spots is the geppo trainer, not sure which, so it alternates until Yi shows up
				local geppoTries = 0

				local function TweenToGeppo()
					geppoTries += 1
					local cframe

					if geppoTries % 2 == 1 then
						cframe = CFrame.new(5871.71777, 9.257061, -10221.1016, 0.694255173, -2.45575009e-08, 0.719728947, 4.17829042e-08, 1, -6.18357099e-09, -0.719728947, 3.43653426e-08, 0.694255173)
					else
						cframe = CFrame.new(-3086.46582, 94.5435104, -11755.8984, -0.632746458, 4.36771952e-09, -0.774359047, -2.32661677e-08, 1, 2.46517491e-08, 0.774359047, 3.36146719e-08, -0.632746458)
					end

					tweenToCFrame({CFrame = cframe, Speed = getgenv().TweenSpeedMaster or 110, StopDistance = 5, TeleportOnClose = true, TeleportDistance = 5})
				end

				-- leave fishman island, wait until above Y 0
				local function TweenToLeaveFishman()
					stopNow()
					tweenToCFrame({
						CFrame = CFrame.new(1815.63843, 79.0749054, -12242.5322, 0.964179814, -1.52146686e-08, -0.265249491, 1.56775517e-08, 1, -3.72064934e-10, 0.265249491, -3.79972498e-09, 0.964179814),
						Speed = getgenv().TweenSpeedMaster or 110, StopDistance = 5, TeleportOnClose = true, TeleportDistance = 8, Raycast = true, WalkOnWater = true
					})
					local root

					repeat
						task.wait(0.1)
						root = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
					until not (tweenState.Enabled and root and not (root.Position.Y > 0))

					if tweenState.Enabled then
						stopNow()
					end
				end

				-- fishman island entry. the real threshold isn't known: inside is around Y -2150, everything else is above -100, so -1000
				local FISHMAN_INSIDE_Y = -1000

				local function insideFishman(part)
					if not part then
						return false
					end

					return part.Position.Y < (getgenv().FishmanInsideY or FISHMAN_INSIDE_Y)
				end

				-- the fishman portal part
				local function portalPart()
					local teleporters = workspace:FindFirstChild("AreaTeleporters")
					local firstSea = teleporters and teleporters:FindFirstChild("FirstSea")
					local fishman = firstSea and firstSea:FindFirstChild("Fishman")

					if fishman then
						local part = fishman:FindFirstChild("Part2")

						if not (part and part:IsA("BasePart")) then
							part = fishman:FindFirstChild("Part")
						end

						if part and part:IsA("BasePart") then
							return part
						end
					end

					local loose = workspace:FindFirstChild("Fishman")

					if loose then
						return loose:FindFirstChild("Part2") or loose:FindFirstChild("Part")
					end

					for _, child in ipairs(workspace:GetChildren()) do
						if child.Name:lower():find("fishman") and child:FindFirstChild("Part2") then
							return child.Part2
						end
					end

					return nil
				end

				-- wait for SpeedBypass to stop being negative (FishmanBypassWait, default 10s)
				local function FishmanWaitBypass(alive)
					local deadline = tick() + (getgenv().FishmanBypassWait or 10)
					local counted = false

					while tick() < deadline do
						if alive ~= nil then
							if not alive() then
								return false
							end
						elseif not getgenv().autofarm then
							return false
						end

						local character = localPlayer.Character
						local root = character and character:FindFirstChild("HumanoidRootPart")
						local humanoid = character and character:FindFirstChildOfClass("Humanoid")

						if not root or not humanoid or humanoid.Health <= 0 then
							return false
						end

						local attribute = character:GetAttribute("SpeedBypass")

						if type(attribute) ~= "number" or attribute >= 0 then
							return true
						end

						if not counted then
							counted = true
							getgenv().FishmanBypassWaits = (getgenv().FishmanBypassWaits or 0) + 1
						end

						task.wait(0.25)
					end

					return false
				end

				-- within 12 studs of the leg's cframe
				local function FishmanLegDone(cframe)
					local root = rootAndHumanoid()

					if not root or not cframe then
						return false
					end

					return (root.Position - cframe.Position).Magnitude <= (getgenv().FishmanLegReach or 12)
				end

				-- turn facingMouse off before a flat fishman flight, true when it's off
				local function FishmanFaceMouseOff()
					if getgenv().FishmanClearFaceMouse == false then
						return true
					end

					local facingMouseNow = getgenv().facingMouseNow

					if type(facingMouseNow) ~= "function" then
						return true
					end

					if facingMouseNow() ~= true then
						return true
					end

					getgenv().FishmanFaceClears = (getgenv().FishmanFaceClears or 0) + 1

					pcall(function()
						getgenv().releaseAimStance()
					end)

					pcall(function()
						getgenv().ToggleFaceMouse(false, true)
					end)

					local deadline = tick() + (getgenv().FishmanFaceWait or 1)

					while tick() < deadline do
						if facingMouseNow() ~= true then
							return true
						end

						task.wait(0.05)
					end

					getgenv().FishmanFaceStuck = (getgenv().FishmanFaceStuck or 0) + 1
					return false
				end

				-- tp onto the portal until we're inside the island
				local function EnterFishmanPortal()
					local root, humanoid = rootAndHumanoid()

					if not root or not humanoid or humanoid.Health <= 0 then
						return false
					end

					if insideFishman(root) then
						return true
					end

					local portal = portalPart()

					if not portal then
						getgenv().FishmanEnterFails = (getgenv().FishmanEnterFails or 0) + 1
						return false
					end

					if (getgenv().FishmanEnterRange or 80) < (portal.Position - root.Position).Magnitude then
						getgenv().FishmanEnterFails = (getgenv().FishmanEnterFails or 0) + 1
						return false
					end

					if tweenState.Enabled then
						stopNow()
					end

					if getgenv().FishmanFaceMouseOff then
						getgenv().FishmanFaceMouseOff()
					end

					local deadline = tick() + (getgenv().FishmanEnterTime or 8)
					local part, done

					repeat
						local humanoid
						part, humanoid = rootAndHumanoid()

						if not part or not humanoid or humanoid.Health <= 0 then
							return false
						end

						if not getgenv().autofarm then
							return false
						end

						if not portal.Parent then
							portal = portalPart()
						end

						if not portal then
							return false
						end

						pcall(function()
							part.CFrame = portal.CFrame
							part.AssemblyLinearVelocity = Vector3.zero
							part.AssemblyAngularVelocity = Vector3.zero
						end)
						task.wait(getgenv().FishmanEnterRate or 0.2)
						part = rootAndHumanoid()
						done = insideFishman(part) or tick() > deadline
					until done

					if insideFishman(part) then
						getgenv().FishmanEntries = (getgenv().FishmanEntries or 0) + 1
						return true
					end

					getgenv().FishmanEnterFails = (getgenv().FishmanEnterFails or 0) + 1
					return false
				end

				-- fly the route leg by leg, then walk through the portal. the original route list is missing, so it's one leg to 30 studs above the portal
				local function fishmanLegs()
					local portal = portalPart()

					if not portal then
						return {}
					end

					return {CFrame.new(portal.Position + Vector3.new(0, getgenv().FishmanApproachLift or 30, 0))}
				end

				local function TweenToFishManIsland()
					local legs = fishmanLegs()
					local yUpCheck = getgenv().YUpCheck

					if #legs == 0 then
						return
					end

					if getgenv().FishmanNoYUp ~= false then
						getgenv().YUpCheck = false
					end

					FishmanFaceMouseOff()

					for k, leg in ipairs(legs) do
						if not getgenv().autofarm then
							break
						end

						local raycast = k == 1 or k == 2
						local walkOnWater = getgenv().FishmanWalkOnWater ~= false

						if walkOnWater and getgenv().waterSurfaceY then
							local surface = getgenv().waterSurfaceY()
							local lift = getgenv().FishmanSurfaceLift or getgenv().WaterPlaneOffset or 8

							if type(surface) == "number" and leg.Position.Y > surface then
								local minY = surface + lift

								if leg.Position.Y < minY then
									leg = CFrame.new(leg.Position.X, minY, leg.Position.Z) * leg.Rotation
								end
							end
						end

						if k >= 2 then
							getgenv().ForceNoClipReal = true
						end

						local legMax = getgenv().FishmanLegMaxTime

						if legMax == nil then
							legMax = 15
						end

						if getgenv().FishmanLegLog ~= false then
							local root = rootAndHumanoid()
							flog(string.format("[Fishman] leg %d/%d -> Y %.1f (root Y %.1f) raycast=%s", k, #legs, leg.Position.Y, root and root.Position.Y or -1, tostring(raycast)))
						end

						local count = 0

						repeat
							count += 1
							FishmanFaceMouseOff()
							FishmanWaitBypass()

							if not getgenv().autofarm then
								break
							end

							tweenToCFrame({
								CFrame = leg,
								Speed = getgenv().TweenSpeedMaster or 50,
								StopDistance = getgenv().FishmanStopDistance or 1,
								TeleportOnClose = getgenv().FishmanTeleportOnClose ~= false,
								TeleportDistance = getgenv().FishmanTeleportDistance or 5,
								Raycast = raycast,
								WalkOnWater = walkOnWater
							})

							if tweenState.Enabled then
								local startedAt = tick()

								repeat
									task.wait()
								until not (tweenState.Enabled and getgenv().autofarm and not (legMax > 0 and tick() - startedAt > legMax))

								if tweenState.Enabled then
									stopNow()
								end
							else
								task.wait(getgenv().FishmanLegRetryWait or 0.5)
							end
						until not getgenv().autofarm or FishmanLegDone(leg) or count >= (getgenv().FishmanLegTries or 6)

						if getgenv().autofarm and not FishmanLegDone(leg) then
							getgenv().FishmanLegGiveUps = (getgenv().FishmanLegGiveUps or 0) + 1
						end

						getgenv().ForceNoClipReal = false
					end

					if getgenv().FishmanNoYUp ~= false then
						getgenv().YUpCheck = yUpCheck
					end

					if getgenv().autofarm and getgenv().EnterFishmanPortal then
						pcall(getgenv().EnterFishmanPortal)
					end
				end

				define("Level", Level)
				define("PeliAmount", PeliAmount)
				define("QuestPanelOpen", QuestPanelOpen)
				define("BossAliveByName", BossAliveByName)
				define("hasBusoHaki", HasBusoHaki)
				define("UmiBossComingUp", UmiBossComingUp)
				define("TweenToSP", TweenToSP)
				define("TweenFishmanSetSpawn", TweenFishmanSetSpawn)
				define("TweenToBecky", TweenToBecky)
				define("TweenToGeppo", TweenToGeppo)
				define("TweenToLeaveFishman", TweenToLeaveFishman)
				define("TweenToFishManIsland", TweenToFishManIsland)
				define("EnterFishmanPortal", EnterFishmanPortal)
				define("FishmanWaitBypass", FishmanWaitBypass)
				define("FishmanLegDone", FishmanLegDone)
				define("FishmanFaceMouseOff", FishmanFaceMouseOff)
			end

			-- auto farm
			do
				-- auto farm threads: quest/mob loop, geppo trainer, kaitun second sea trip, toggle-off watcher. reloading replaces the token so old threads stop
				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local localPlayer = Players.LocalPlayer
				local tweenState = getgenv().__TensenTweenState   -- hub tween state
				local stopTween = getgenv().StopCurrentTween   -- hub tween stop
				tweenState = tweenState or getgenv().__TensenTweenState or {Enabled = false}
				local FIRST_SEA = 3978370137
				local SECOND_SEA = 7465136166
				local loops = getgenv().__TensenFarmLoops

				if not loops then
					loops = {}
					getgenv().__TensenFarmLoops = loops
				end

				local token = {}
				loops["F1.AutoFarm"] = token

				local function stale()
					return loops["F1.AutoFarm"] ~= token
				end

				local function stopNow()
					local f = stopTween or getgenv().StopCurrentTween

					if type(f) == "function" then
						pcall(f)
					end
				end

				-- call a helper by name only if it exists
				local function call(name, ...)
					local f = getgenv()[name]

					if type(f) == "function" then
						return f(...)
					end

					return nil
				end

				local function waitUntil(done, step)
					repeat
						task.wait(step)
					until done() or stale()
				end

				-- alive character with a root part
				local function alive()
					local character = localPlayer.Character

					if not character then
						return false
					end

					local humanoid = character:FindFirstChild("Humanoid")
					local root = character:FindFirstChild("HumanoidRootPart")

					return (humanoid and humanoid.Health > 0 and root and true) or false
				end

				local function stopTweenIfRunning()
					if tweenState.Enabled then
						stopNow()

						tweenState.Enabled = false
					end
				end

				local function playerGui()
					return localPlayer:WaitForChild("PlayerGui")
				end

				local function questMainVisible()
					return playerGui():WaitForChild("Quest"):WaitForChild("Main").Visible
				end

				local function remotes()
					return ReplicatedStorage:WaitForChild("Events")
				end

				local function chat()
					if stale() then
						return
					end

					remotes():WaitForChild("Quest"):InvokeServer(unpack({{"npcChat", true}}))
				end

				local function takeQuest(name)
					if stale() then
						return
					end

					remotes():WaitForChild("Quest"):InvokeServer(unpack({{"takequest", name}}))
				end

				local function peli()
					return call("PeliAmount") or 0
				end

				local function level()
					return call("Level")
				end

				local function umiBossEngaged()
					return game.PlaceId == SECOND_SEA and (getgenv().AutoRogerBoss or getgenv().AutoMihawkBoss) and (call("UmiBossComingUp") or getgenv().UmiBossEngaged)
				end

				local function juzoUp()
					return getgenv().AutoJuzoBoss and call("BossAliveByName", "Juzo the Diamondback")
				end

				-- ===== 1. the Auto Farm loop =====
				task.spawn(function()
					task.wait()

					while task.wait() do
						if stale() then
							break
						end

						if not alive() then
							stopTweenIfRunning()
							continue
						end

						local humanoidRootPart = localPlayer.Character.HumanoidRootPart

						if not getgenv().autofarm then
							waitUntil(function()
								return getgenv().autofarm
							end)

							continue
						end

						local scrollHold = getgenv().ScrollHoldLive ~= nil and getgenv().ScrollHoldLive()

						if scrollHold then
							-- the scroll camper owns the character: step aside until it lets go
							if tweenState.Enabled then
								stopNow()
								tweenState.Enabled = false
							end

							getgenv().ScrollAckFarm = true

							while getgenv().ScrollHoldLive() and not stale() do
								task.wait(0.1)
							end

							getgenv().ScrollAckFarm = false
							task.wait(0.2)
							continue
						end

						if getgenv().AutoFishing then
							waitUntil(function()
								return not (getgenv().AutoFishing and alive() and not (getgenv().ScrollHoldLive ~= nil and getgenv().ScrollHoldLive()))
							end)

							continue
						end

						local merchant = ReplicatedStorage:FindFirstChild("CompassGuider") and ReplicatedStorage.CompassGuider:FindFirstChild("Traveling Merchant")

						if getgenv().AutoMerchant and merchant and not getgenv().AlreadyGoToMerchant then
							if tweenState.Enabled then
								stopNow()
								tweenState.Enabled = false
							end

							waitUntil(function()
								local merchant = ReplicatedStorage:FindFirstChild("CompassGuider") and ReplicatedStorage.CompassGuider:FindFirstChild("Traveling Merchant")
								return not (getgenv().AutoMerchant and merchant and not getgenv().AlreadyGoToMerchant and alive())
							end, 1)

							if not alive() or not getgenv().autofarm then
								continue
							end
						end

						if getgenv().Glide and game.PlaceId == FIRST_SEA then
							waitUntil(function()
								return not (getgenv().Glide and alive())
							end)
						end

						local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)
						local skills = stats and stats:FindFirstChild("Skills")
						local skyWalk = skills and skills:FindFirstChild("skyWalk")
						skyWalk = skyWalk and skyWalk.Value == true

						if getgenv().GetGeppo and game.PlaceId == FIRST_SEA and (level() or 0) >= 125 and peli() >= 50000 and not skyWalk then
							-- geppo first, the trainer thread does the walking
							repeat
								task.wait(0.1)
								local skill = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)
								skill = skill and skill:FindFirstChild("Skills")
								skill = skill and skill:FindFirstChild("skyWalk")

								if skill and skill.Value == true then
									skyWalk = true
								end
							until not (getgenv().GetGeppo and alive() and not skyWalk) or stale()

							if alive() and getgenv().autofarm then
								stopNow()
								call("releaseAimStance")
								task.wait(0.5)
							end
							continue
						end

						if not alive() then
							continue
						end

						if umiBossEngaged() or juzoUp() or getgenv().BossLootDwelling then
							-- a boss fight / loot dwell is running: stay out of its way
							waitUntil(function()
								return not ((umiBossEngaged() or juzoUp() or getgenv().BossLootDwelling) and alive() and getgenv().autofarm)
							end, 0.1)

							if not alive() or not getgenv().autofarm then
								continue
							end
						end

						local factory = (getgenv().AutoFactory or getgenv().AutoFarmGearCyborg) and game.PlaceId == SECOND_SEA

						if factory and call("FactoryPending") then
							waitUntil(function()
								return not ((getgenv().AutoFactory or getgenv().AutoFarmGearCyborg) and call("FactoryPending") and alive() and getgenv().autofarm)
							end, 0.1)

							if not alive() or not getgenv().autofarm then
								continue
							end
						end

						local myLevel = level()

						if not myLevel then
							continue
						end

						local hasHaki = call("hasBusoHaki")
						local onYetiQuest = call("IsOnYetiQuest")

						if getgenv().haki and game.PlaceId == FIRST_SEA and not hasHaki and (onYetiQuest or myLevel >= 80 and peli() >= 25000) then
							-- haki quest takes over until buso is owned
							if tweenState.Enabled then
								stopNow()
								tweenState.Enabled = false
							end

							repeat
								task.wait(0.1)
								hasHaki = call("hasBusoHaki")
							until not (getgenv().haki and alive() and not hasHaki) or stale()

							if alive() and getgenv().autofarm then
								stopNow()
								call("releaseAimStance")
								task.wait(0.5)
							end

							continue
						end

						call("FarmPreStep")

						if game.PlaceId == FIRST_SEA then
							local npcs = workspace:FindFirstChild("NPCs")

							if not npcs then
								continue
							end

							local islands = workspace:FindFirstChild("Islands")
							local fishmanIsland = islands and islands:FindFirstChild("Fishman Island")

							if not fishmanIsland then
								continue
							end

							local building = fishmanIsland:FindFirstChild("Building")
							local far = false

							if building and (humanoidRootPart.Position - building:GetPivot().Position).Magnitude > 2000 then
								far = true
							end

							if not building or far then
								-- not at fishman island yet: fly there, wait for it to load, set spawn
								if not getgenv().autofarm then
									continue
								end

								call("TweenToFishManIsland")

								waitUntil(function()
									return not (tweenState.Enabled ~= false and getgenv().autofarm and alive())
								end)

								if not getgenv().autofarm or not alive() then
									continue
								end

								repeat
									task.wait(0.2)

									if not getgenv().autofarm or not alive() then
										stopNow()
										tweenState.Enabled = false
										break
									end
								until fishmanIsland:FindFirstChild("Building") or stale()

								if not (getgenv().autofarm and alive()) then
									continue
								end

								call("TweenFishmanSetSpawn")

								waitUntil(function()
									return not (tweenState.Enabled ~= false and getgenv().autofarm and alive())
								end, 0.5)

								task.wait(3)

								if getgenv().autofarm and alive() then
									chat()
									task.wait(1.5)

									if not stale() then
										remotes():WaitForChild("SetSpawn"):FireServer()
									end

									task.wait(1)
								end
							else
								local questVisible = questMainVisible()

								if myLevel >= 190 and questVisible == false then
									tweenState.Enabled = false
									call("TweenToBecky")

									waitUntil(function()
										return not (tweenState.Enabled ~= false and getgenv().autofarm and alive())
									end, 0.1)

									if not getgenv().autofarm or not alive() then
										continue
									end

									chat()
									task.wait(0.5)
									takeQuest("Help becky")
									task.wait(0.5)
								end

								if npcs:FindFirstChild("Fishman Karate User") then
									call("TweenToMob", {
										MobName = "Fishman Karate User",
										Speed = getgenv().TweenSpeedMaster or 70,
										Offset = Vector3.new(0, 9, 0),
										Container = npcs
									})

									continue
								end

								if tweenState.Enabled == true then
									stopNow()
									tweenState.Enabled = false
								end

								task.wait(0.5)
								call("TweenToSP")
								local retryAt = tick()

								repeat
									task.wait(0.5)

									if not tweenState.Enabled and not npcs:FindFirstChild("Fishman Karate User") and tick() - retryAt >= (getgenv().FarmSpRetry or 3) then
										retryAt = tick()
										call("TweenToSP")
									end
								until not (not npcs:FindFirstChild("Fishman Karate User") and getgenv().autofarm and alive()) or stale()

								if tweenState.Enabled then
									stopNow()
									tweenState.Enabled = false
								end
							end
							continue
						end

						if game.PlaceId ~= SECOND_SEA then
							continue
						end

						local npcs = workspace:FindFirstChild("NPCs")

						if not npcs then
							continue
						end

						if questMainVisible() == false then
							-- no quest: walk to PJ, talk, take "Help PJ"
							if tweenState.Enabled then
								stopNow()
								tweenState.Enabled = false
							end

							call("TweenToSP")

							waitUntil(function()
								return not (tweenState.Enabled ~= false and getgenv().autofarm and alive())
							end, 0.1)

							if not getgenv().autofarm or not alive() then
								continue
							end

							chat()
							task.wait(0.5)
							takeQuest("Help PJ")
							task.wait(0.5)
						end

						if npcs:FindFirstChild("Crazy Wolf") then
							call("TweenToMob", {
								MobName = "Crazy Wolf",
								Speed = getgenv().TweenSpeedMaster or 70,
								Offset = Vector3.new(0, 9, 0),
								Container = npcs
							})

							continue
						end

						if tweenState.Enabled == true then
							stopNow()
							tweenState.Enabled = false
						end

						task.wait(0.5)
						call("TweenToSP")
						local retryAt = tick()

						repeat
							task.wait(0.5)

							if not tweenState.Enabled and not npcs:FindFirstChild("Crazy Wolf") and tick() - retryAt >= (getgenv().FarmSpRetry or 3) then
								retryAt = tick()
								call("TweenToSP")
							end
						until not (not npcs:FindFirstChild("Crazy Wolf") and getgenv().autofarm and alive()) or stale()

						if tweenState.Enabled then
							stopNow()
							tweenState.Enabled = false
						end
					end
				end)

				-- geppo trainer loop
				task.spawn(function()
					task.wait()

					while task.wait(0.5) do
						if stale() then
							break
						end

						if not (getgenv().GetGeppo and not getgenv().autofarm and not getgenv().haki and not getgenv().AutoFishing and not getgenv().AutoMerchant and not getgenv().Glide) then
							continue
						end

						local myLevel = call("Level") or 0
						local money = peli()

						if myLevel < 125 or money < 50000 then
							task.wait(1)
							continue
						end

						if tweenState.Enabled then
							continue
						end

						local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)

						if not stats then
							continue
						end

						local skills = stats:FindFirstChild("Skills")

						if not skills then
							continue
						end

						local skyWalk = skills:FindFirstChild("skyWalk")

						if not skyWalk then
							continue
						end

						if skyWalk.Value == true then
							continue
						end

						local npcs = workspace:FindFirstChild("NPCs")
						local yi = npcs and npcs:FindFirstChild("Yi")

						if yi and yi:FindFirstChild("HumanoidRootPart") then
							ReplicatedStorage:WaitForChild("Events"):WaitForChild("learnStyle"):FireServer(unpack({"skyWalkTrainer"}))
							continue
						end

						call("TweenToGeppo")

						repeat
							task.wait(1)
						until not (tweenState.Enabled and getgenv().GetGeppo) or stale()

						if not getgenv().GetGeppo then
							stopNow()
						end
					end
				end)

				-- kaitun: go to second sea at level 425 with a world scroll
				task.spawn(function()
					task.wait()
					local deadline = 0

					while task.wait(1) do
						if stale() or game.PlaceId ~= FIRST_SEA then
							break
						end

						if not (getgenv().autofarm and getgenv().AutoWorldScroll) then
							continue
						end

						-- scrolls in the bag
						local count = 0

						if type(getgenv().WorldScrollCount) == "function" then
							local ok, result = pcall(getgenv().WorldScrollCount)

							if ok then
								count = result or 0
							end
						end

						if (call("Level") or 0) < 425 or count < 1 then
							continue
						end

						-- the original had one more check here that couldn't be recovered
						if os.clock() < deadline then
							continue
						end

						deadline = os.clock() + 30
						local ok, result = pcall(function()
							getgenv().KaitunTravelSecondSea()
						end)

						if not ok then
							local logFn = getgenv().BMLog

							if type(logFn) == "function" then
								pcall(logFn, "[Kaitun] Second Sea teleport failed; retrying in 30s: " .. tostring(result))
							end
						end
					end
				end)

				-- toggle-off watcher. the hub's toggles lost their "stop the tween" call, so this stops it
				task.spawn(function()
					task.wait()
					local flags = {"autofarm", "haki", "AutoFactory", "AutoFarmGearCyborg", "AutoRogerBoss", "AutoMihawkBoss", "AutoJuzoBoss", "AutoFishing", "AutoMerchant", "StartTweenIsland", "TweenToNPC", "TweenToPlayer"}
					local previous = {}

					for _, name in ipairs(flags) do
						previous[name] = getgenv()[name] and true or false
					end

					while task.wait(0.15) do
						if stale() then
							break
						end

						for _, name in ipairs(flags) do
							local now = getgenv()[name] and true or false

							if previous[name] and not now and tweenState.Enabled then
								stopNow()
							end

							previous[name] = now
						end
					end
				end)
			end

			-- fishman aggro
			do
				-- resets the Aggro flag on fishman karate users / yetis that lost their target (every 2s). MarkMobAggro sets it, nothing in here calls that
				local loops = getgenv().__TensenFarmLoops

				if not loops then
					loops = {}
					getgenv().__TensenFarmLoops = loops
				end

				local token = {}
				loops["F1.Aggro"] = token
				local AGGRO_NAMES = {["Fishman Karate User"] = true, Yeti = true}

				local function MarkMobAggro(instances)
					for _, instance in ipairs(instances) do
						local parent = instance.Parent

						if parent and AGGRO_NAMES[parent.Name] then
							local aggro = parent:FindFirstChild("Aggro")

							if aggro then
								aggro.Value = true
								aggro:SetAttribute("LastAggro", tick())
							end
						end
					end
				end

				if rawget(getgenv(), "MarkMobAggro") == nil then
					getgenv().MarkMobAggro = MarkMobAggro
				end

				task.spawn(function()
					task.wait()

					while task.wait(2) do
						if loops["F1.Aggro"] ~= token then
							break
						end

						local npcs = workspace:FindFirstChild("NPCs")

						if not npcs then
							continue
						end

						for _, child in ipairs(npcs:GetChildren()) do
							if not AGGRO_NAMES[child.Name] then
								continue
							end

							local humanoid = child:FindFirstChildOfClass("Humanoid")
							local aggro = child:FindFirstChild("Aggro")

							if humanoid and aggro and aggro.Value then
								local last = aggro:GetAttribute("LastAggro") or 0

								if tick() - last > 4 then
									aggro.Value = false
								end
							end
						end
					end
				end)
			end

			-- combat core
			do
				-- combat helpers the farms call through getgenv (weapons, targets, range, feints)
				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local LocalPlayer = Players.LocalPlayer

				local function swordFolder()
					local ok, result = pcall(function()
						return ReplicatedStorage.Modules.SwordHandle.Swords
					end)
					if ok then
						return result
					end
					return nil
				end

				getgenv().Char = function()
					local character = LocalPlayer.Character
					if character then
						return character
					end
					local character
					repeat
						task.wait(getgenv().CharPollRate or 0.1)
						character = LocalPlayer.Character
					until character
					return character
				end

				-- melee unless it's a sword, rod, pickaxe or axe (MeleeTool / Category attributes override)
				getgenv().isMeleeTool = function(instance)
					if not instance or not instance:IsA("Tool") then
						return false
					end
					local attribute = instance:GetAttribute("MeleeTool")
					if attribute ~= nil then
						return attribute == true
					end
					local category = instance:GetAttribute("Category")
					if category ~= nil and category ~= "Weapons" then
						return false
					end
					local name = instance.Name:lower()
					if name:find("rod") or name:find("pick") or name:find("axe") then
						return false
					end
					local ok, result = pcall(function()
						return ReplicatedStorage.Modules.SwordHandle.Swords:FindFirstChild(instance.Name) ~= nil
					end)
					if ok and result then
						return false
					end
					return true
				end

				-- first melee tool in the character (or the given container)
				getgenv().equippedMelee = function(instance)
					if not instance then
						return nil
					end
					for _, child in ipairs(instance:GetChildren()) do
						if getgenv().isMeleeTool(child) then
							return child
						end
					end
					return nil
				end

				-- first melee tool in the backpack
				getgenv().backpackMelee = function()
					local backpack = LocalPlayer:FindFirstChild("Backpack")
					if not backpack then
						return nil
					end
					for _, child in ipairs(backpack:GetChildren()) do
						if getgenv().isMeleeTool(child) then
							return child
						end
					end
					return nil
				end

				-- name of the allowed sword in hand, else nil
				getgenv().equippedSword = function(instance)
					if not instance then
						return nil
					end
					local swords = swordFolder()
					if not swords then
						return nil
					end
					for _, child in ipairs(swords:GetChildren()) do
						if instance:FindFirstChild(child.Name) and getgenv().swordNameAllowed(child.Name) then
							return child.Name
						end
					end
					return nil
				end

				-- first allowed sword in the backpack
				getgenv().backpackSword = function()
					local backpack = LocalPlayer:FindFirstChild("Backpack")
					local swords = swordFolder()
					if not backpack or not swords then
						return nil
					end
					for _, child in ipairs(backpack:GetChildren()) do
						if child:IsA("Tool") and swords:FindFirstChild(child.Name) and getgenv().swordNameAllowed(child.Name) then
							return child
						end
					end
					return nil
				end

				-- what we're actually holding ("Sword" / "Melee"), falls back to the wanted type, cached for WeaponCacheTTL
				local weaponChar = nil
				local weaponAt = 0
				local weaponClass = nil

				getgenv().weaponNow = function(wanted)
					local character = LocalPlayer.Character
					if not character then
						return wanted
					end
					local now = os.clock()
					if character ~= weaponChar or now - weaponAt > (getgenv().WeaponCacheTTL or 0.2) then
						weaponChar = character
						weaponAt = now
						if getgenv().equippedSword(character) then
							weaponClass = "Sword"
						elseif getgenv().equippedMelee(character) then
							weaponClass = "Melee"
						else
							weaponClass = nil
						end
					end
					local result = weaponClass or wanted
					if result == "PikaV2" then
						result = "Sword"
					end
					return result
				end

				-- same routine for the farm weapon (WeaponType) and the boss weapon (WeaponTypeBoss)
				local function waitForTool(character, name)
					local deadline = os.clock() + 3 -- deadline added so a failed equip doesn't hang
					repeat
						task.wait()
					until character:FindFirstChild(name) or os.clock() > deadline or not LocalPlayer.Character
						or not LocalPlayer.Character:FindFirstChild("Humanoid") or LocalPlayer.Character.Humanoid.Health <= 0
				end

				local function equipWeapon(weaponType)
					local character = getgenv().Char()
					local humanoid = character and character:FindFirstChild("Humanoid")
					if not character or not humanoid or humanoid.Health <= 0 then
						return
					end
					if not weaponType then
						weaponType = "Melee"
					end
					if weaponType == "Melee" then
						if getgenv().equippedMelee(character) then
							return
						end
						if not getgenv().backpackMelee() then
							-- no melee tool anywhere: keep a held sword or pull one from the bag
							if getgenv().equippedSword(character) then
								return
							end
							local sword = getgenv().backpackSword()
							if sword then
								pcall(function()
									humanoid:EquipTool(sword)
								end)
							end
							return
						end
						if character:FindFirstChildOfClass("Tool") then
							pcall(function()
								humanoid:UnequipTools()
							end)
							task.wait(0.15)
						end
						local melee = getgenv().backpackMelee()
						if not melee then
							return
						end
						task.wait(0.25)
						pcall(function()
							humanoid:EquipTool(melee)
						end)
						waitForTool(character, melee.Name)
						return
					end
					if not (weaponType == "Sword" or weaponType == "PikaV2") then
						return
					end

					local swords = swordFolder()
					if swords then
						for _, child in ipairs(swords:GetChildren()) do
							if character:FindFirstChild(child.Name) and getgenv().swordNameAllowed(child.Name) then
								return
							end
						end
					end
					-- the rest of this branch was missing, mirrors the melee branch above
					local sword = getgenv().backpackSword()
					if not sword then
						return
					end
					if character:FindFirstChildOfClass("Tool") then
						pcall(function()
							humanoid:UnequipTools()
						end)
						task.wait(0.15)
					end
					task.wait(0.25)
					pcall(function()
						humanoid:EquipTool(sword)
					end)
					waitForTool(character, sword.Name)
				end

				-- names made up, the originals were unnamed
				getgenv().equipFarmWeapon = function()
					return equipWeapon(getgenv().WeaponType)
				end

				getgenv().equipBossWeapon = function()
					return equipWeapon(getgenv().WeaponTypeBoss)
				end

				-- releases the aim stance before a swing
				getgenv().dropAimStance = function()
					local release = getgenv().releaseAimStance
					if release then
						return release()
					end
				end

				-- true while dodging / retreating on low health / replaying, the m1 loops hold fire
				getgenv().combatPaused = function()
					return (getgenv().EvadingBoss or getgenv().EvadingKing or getgenv().EvadingUlt or getgenv().EvadingDive or getgenv().EvadingAfterImage or getgenv().LowHealthActive or getgenv().LowHealthAnchored
						or getgenv().PerchedOnBarrier or getgenv().PerchEngaging or getgenv().BarrierFlightActive or getgenv().ReplayRunning) == true
				end

				-- the player Tween To Player fights
				getgenv().PvPTarget = function()
					local character = LocalPlayer.Character
					local root = character and character:FindFirstChild("HumanoidRootPart")
					if not root then
						return nil
					end
					if getgenv().PvPAutoTarget == false then
						local selected = getgenv().SelectedPlayer
						if type(selected) == "table" then
							selected = selected[1]
						end
						if not selected or selected == "None" then
							return nil
						end
						local player = Players:FindFirstChild(selected)
						if player and not getgenv().PvPSkippable(player) then
							return player
						end
						return nil
					end
					local range = tonumber(getgenv().PvPRange) or 2000
					local bestDistance = math.huge
					local best = nil
					for _, player in ipairs(Players:GetPlayers()) do
						if not getgenv().PvPSkippable(player) then
							local distance = (player.Character:FindFirstChild("HumanoidRootPart").Position - root.Position).Magnitude
							if distance <= range and distance < bestDistance then
								bestDistance = distance
								best = player
							end
						end
					end
					return best
				end

				-- nearest living npc with that name -> model, studs, how many are alive. only if nothing set it already
				if getgenv().findNearestAlive == nil then
					getgenv().findNearestAlive = function(name)
						local npcs = workspace:FindFirstChild("NPCs")
						local character = LocalPlayer.Character
						local root = character and character:FindFirstChild("HumanoidRootPart")
						if not (npcs and root) then
							return nil
						end
						local bestDistance = math.huge
						local alive = 0
						local best = nil
						for _, child in ipairs(npcs:GetChildren()) do
							if child.Name ~= name then
								continue
							end
							local humanoid = child:FindFirstChildOfClass("Humanoid")
							local npcRoot = child:FindFirstChild("HumanoidRootPart") or child.PrimaryPart
							if humanoid and npcRoot and humanoid.Health > 0 then
								alive += 1
								local distance = (npcRoot.Position - root.Position).Magnitude
								if distance < bestDistance then
									bestDistance = distance
									best = child
								end
							end
						end
						return best, math.floor(bestDistance), alive
					end
				end

				-- m1 reach, kill aura and the tween farms widen it (never below 15)
				getgenv().combatRange = function()
					local range = 15
					if getgenv().KillAura then
						range = math.max(tonumber(getgenv().KillAuraRange) or 15, 15)
					end
					local range2
					if getgenv().TweenToNPC then
						range2 = math.max((tonumber(getgenv().NPCOffsetY) or 9) + 6, range)
					else
						range2 = range
					end
					local range
					if getgenv().TweenToPlayer then
						range = math.max((tonumber(getgenv().PvPOffsetY) or 9) + 6, range2)
					else
						range = range2
					end
					return range
				end

				-- root parts of everything the m1 loops can hit within `distance`, nearest first
				getgenv().targetsInRange = function(distance)
					local parts = {}
					local character = LocalPlayer.Character
					local root = character and character:FindFirstChild("HumanoidRootPart")
					local npcs = workspace:FindFirstChild("NPCs")
					if npcs and root then
						for _, child in ipairs(npcs:GetChildren()) do
							local name = child.Name:lower()
							local selected = getgenv().TweenToNPC and getgenv().SelectedNPC and child.Name == getgenv().SelectedNPC
							if not (getgenv().KillAura and not getgenv().npcHasForceField(child) or selected or name:find("scient") or name:find("law")
								or child.Name == "Donmingo Family" or child.Name == "Fishman Karate User" or child.Name == "Yeti" or child.Name == "Crazy Wolf"
								or child.Name == "Juzo the Diamondback" or child.Name == "Roger" or child.Name == "Hawk Eye") then
								continue
							end
							local npcRoot = child:FindFirstChild("HumanoidRootPart")
							local humanoid = child:FindFirstChildOfClass("Humanoid")
							if npcRoot and humanoid and humanoid.Health > 0 and (npcRoot.Position - root.Position).Magnitude <= distance then
								table.insert(parts, npcRoot)
							end
						end
					end
					if getgenv().TweenToPlayer and root then
						local playerRange = math.min(distance, tonumber(getgenv().PvPRange) or 2000)
						for _, player in ipairs(Players:GetPlayers()) do
							if not getgenv().PvPSkippable(player) then
								local playerRoot = player.Character:FindFirstChild("HumanoidRootPart")
								if (playerRoot.Position - root.Position).Magnitude <= playerRange then
									table.insert(parts, playerRoot)
								end
							end
						end
					end
					if (getgenv().AutoFactory or getgenv().AutoFarmGearCyborg) and root then
						local env = workspace:FindFirstChild("Env")
						local factoryPool = env and env:FindFirstChild("FactoryPool")
						local hitbox = factoryPool and factoryPool:FindFirstChild("hitbox")
						local barrelHP = factoryPool and factoryPool:FindFirstChild("barrelHP")
						if hitbox and hitbox:IsA("BasePart") and (not barrelHP or barrelHP.Value and barrelHP.Value > 0) and (hitbox.Position - root.Position).Magnitude <= 50 then
							table.insert(parts, hitbox)
						end
					end
					if root and #parts > 1 then
						local origin = root.Position
						table.sort(parts, function(a, b)
							return (a.Position - origin).Magnitude < (b.Position - origin).Magnitude
						end)
					end
					return parts
				end

				-- same as the big mom module's targetBlocking, used when that one isn't there
				local function localTargetBlocking(instance)
					if not (instance and instance.Parent) then
						return false
					end
					if getgenv().isNPCBlocking and getgenv().isNPCBlocking(instance) then
						return true, "a Blocking flag"
					end
					local ok, result = pcall(function()
						return instance:GetAttribute("IsBlocking")
					end)
					if ok and result == true then
						return true, "IsBlocking"
					end
					local humanoid = instance:FindFirstChildOfClass("Humanoid")
					local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
					if animator then
						local blockAnim = nil
						pcall(function()
							for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
								local animation = track.Animation
								local animationId = animation and string.match(tostring(animation.AnimationId), "%d+")
								if animationId and (getgenv().BlockAnimIds or {})[animationId] then
									blockAnim = getgenv().BlockAnimIds[animationId]
									return
								end
								if animation and string.find(string.lower(animation.Name or ""), "block", 1, true) then
									blockAnim = animation.Name
									return
								end
							end
						end)
						if blockAnim then
							return true, "the " .. tostring(blockAnim) .. " animation"
						end
					end
					return false
				end

				local function targetBlocking(instance)
					local fn = getgenv().targetBlocking or localTargetBlocking
					return fn(instance)
				end

				-- fake m1 on block per farm mode, FeintOnBlock = false still wins
				local function feintEnabled()
					if getgenv().FeintOnBlock == false then
						return false
					end
					if getgenv().TweenToPlayer then
						return getgenv().PvPFeintOnBlock ~= false
					end
					return getgenv().NPCFeintOnBlock ~= false
				end

				-- target blocking: fake swing, wait FeintRetry, true = don't hit now
				local feintState = setmetatable({}, { __mode = "k" })

				getgenv().farmFeint = function(part, weaponType, index, animation)
					local model = part and part.Parent
					-- per-boss fake m1 settings (bossFeint) decide when the model has a key
					local keyed, keyFor = getgenv().bossFeint, getgenv().bossKeyFor
					if keyed and keyFor and model and keyFor(model) then
						return keyed(part, weaponType, index, animation) == true
					end
					if not feintEnabled() then
						return false
					end
					if not model then
						return false
					end
					local blocking, why = targetBlocking(model)
					if not blocking then
						if feintState[model] and getgenv().FeintLog ~= false and getgenv().BMLog then
							getgenv().BMLog(string.format("[Feint] '%s' dropped the block after %.1fs - m1ing for real.", tostring(model.Name), tick() - feintState[model].since))
						end
						feintState[model] = nil
						return false
					end
					local last = feintState[model]
					if last and tick() - last.at < (getgenv().FeintRetry or 5) then
						return true
					end
					pcall(function()
						ReplicatedStorage.Events.CombatRegister:InvokeServer({ "swingsfx", weaponType, index, "Ground", false, animation, 2, 1.5 })
					end)
					feintState[model] = { at = tick(), since = last and last.since or tick() }
					getgenv().Feints = (getgenv().Feints or 0) + 1
					if getgenv().FeintLog ~= false and getgenv().BMLog then
						getgenv().BMLog(string.format("[Feint] '%s' is blocking (%s) - fake m1, no damage. Waiting for the unblock, feinting again in %ds if it holds (x%d).",
							tostring(model.Name), tostring(why), math.floor(getgenv().FeintRetry or 5), getgenv().Feints))
					end
					return true
				end

				-- first target, skipping blockers when fake m1 is off (nil if all are blocking)
				getgenv().pickAttackTarget = function(list)
					for _, part in ipairs(list) do
						if part and part.Parent and (feintEnabled() or not targetBlocking(part.Parent)) then
							return part
						end
					end
					return nil
				end
			end

			-- vertical tp
			do
				-- vertical tp for TweenToCFrame: big height changes (over VerticalTpStep, 900) are done in hops with facingMouse on
				local Players = game:GetService("Players")
				local RunService = game:GetService("RunService")
				local LocalPlayer = Players.LocalPlayer

				local function vtpLog(message)
					if getgenv().BMLog then
						getgenv().BMLog(message)
					end
				end

				-- wait for the facingMouse stance (up to VerticalTpFaceWait)
				getgenv().ensureVertFaceMouse = function(character)
					getgenv().VertOffToken = (getgenv().VertOffToken or 0) + 1 -- cancels a pending vertFaceMouseOff loop
					character = character or LocalPlayer.Character
					if not character then
						return false
					end
					if character:GetAttribute("facingMouse") == true then
						return true
					end
					getgenv().vertFaceMouse(true)
					local deadline = os.clock() + (getgenv().VerticalTpFaceWait or 1.5)
					repeat
						task.wait(0.05)
					until character:GetAttribute("facingMouse") == true or os.clock() > deadline
					return character:GetAttribute("facingMouse") == true
				end

				-- turn the stance off and keep sending "off" until it drops
				getgenv().vertFaceMouseOff = function()
					getgenv().VertOffToken = (getgenv().VertOffToken or 0) + 1
					local token = getgenv().VertOffToken
					pcall(function()
						local env = getgenv().AimStanceEnv
						if env then
							env.FaceMouse = false
						end
					end)
					task.spawn(function()
						local deadline = os.clock() + (getgenv().VerticalTpOffWait or 3)
						local character
						repeat
							if getgenv().VertOffToken ~= token then
								return
							end
							getgenv().vertFaceMouse(false)
							task.wait(0.3)
							character = LocalPlayer.Character
						until not character or character:GetAttribute("facingMouse") ~= true or os.clock() > deadline
					end)
				end

				getgenv().stepVerticalTP = function(part, targetY, label, stillActive)
					local step = getgenv().VerticalTpStep or 900
					local hops = 0
					while part and part.Parent and (not stillActive or stillActive()) do
						if not getgenv().ensureVertFaceMouse(part.Parent) then
							vtpLog(string.format("[VTP] %s: facingMouse would not turn on - not hopping.", tostring(label)))
							return false, hops
						end
						local gap = targetY - part.Position.Y
						if math.abs(gap) <= step then
							return true, hops
						end
						local hopY = part.Position.Y + math.sign(gap) * step
						part.CFrame = CFrame.new(part.Position.X, hopY, part.Position.Z) * part.CFrame.Rotation
						part.AssemblyLinearVelocity = Vector3.zero
						hops += 1
						getgenv().VerticalTpHops = (getgenv().VerticalTpHops or 0) + 1
						-- hold still for VerticalTpHold and see how far the server pulls back
						local pulledBack = 0
						local connection = RunService.Heartbeat:Connect(function()
							if not part.Parent then
								return
							end
							part.AssemblyLinearVelocity = Vector3.zero
							local drift = math.abs(part.Position.Y - hopY)
							if drift > pulledBack then
								pulledBack = drift
							end
						end)
						local deadline = os.clock() + (getgenv().VerticalTpHold or 2)
						repeat
							task.wait(0.1)
						until os.clock() >= deadline or stillActive and not stillActive()
						connection:Disconnect()
						if stillActive and not stillActive() then
							return false, hops
						end
						if pulledBack > 50 then
							vtpLog(string.format("[VTP] %s: hop %d got pulled back %d studs - stopping.", tostring(label), hops, math.floor(pulledBack)))
							return false, hops
						end
						vtpLog(string.format("[VTP] %s: hop %d %+d to Y %d held, %d left (x%d)", tostring(label), hops, math.sign(gap) * step, math.floor(hopY),
							math.floor(math.abs(targetY - hopY)), getgenv().VerticalTpHops))
					end
					return false, hops
				end
			end

			-- tween engine
			do
				-- movement engine: TweenToCFrame, TweenToMob, TweenToMob2. a few bits are rebuilt by hand (marked), the hub helpers it calls are optional
				local Players = game:GetService("Players")
				local RunService = game:GetService("RunService")
				local LocalPlayer = Players.LocalPlayer

				-- movers the script owns, the anti-stun / anti-knockback code leaves these alone
				local scriptMoverNames = {
					BM_ReactVel = true,
					BM_DodgeGyro = true,
					BM_MochiHold = true,
					KD_TweenGyro = true,
					KD_TweenVel = true,
					KD_CFrameGyro = true,
					KD_CFrameVel = true,
					KD_AttachGyro = true,
					KD_AttachVel = true,
				}

				if getgenv().isScriptMover == nil then
					getgenv().isScriptMover = function(name)
						if scriptMoverNames[name] then
							return true
						end
						if type(name) == "string" and (name:sub(1, 3) == "KD_" or name:sub(1, 3) == "BM_") then
							return true
						end
						return false
					end
				end

				local function tweenState()
					local state = getgenv().__TensenTweenState
					if not state then
						state = { Enabled = false, Gyro = nil, Vel = nil, Conn = nil, Gen = 0, AtGoal = false }
						getgenv().__TensenTweenState = state
					end
					return state
				end

				-- used by the movement smoothing and the knockback loops
				if getgenv().ScriptOwnsMovement == nil then
					getgenv().ScriptOwnsMovement = function(root, humanoid)
						if tweenState().Enabled then
							return true
						end
						if root then
							for _, child in ipairs(root:GetChildren()) do
								if (child:IsA("BodyVelocity") or child:IsA("BodyGyro")) and getgenv().isScriptMover(child.Name) then
									return true
								end
							end
						end
						return false
					end
				end

				local function bmLog(message)
					if getgenv().BMLog then
						getgenv().BMLog(message)
					end
				end

				-- own noclip, turns itself off when the tween ends
				local noclipParts = {}
				local noclipConn = nil

				local function setNoclip(on)
					if on then
						if noclipConn then
							return
						end
						noclipConn = RunService.Stepped:Connect(function()
							if not tweenState().Enabled then
								-- the tween ended without calling us (StopCurrentTween): release
								if noclipConn then
									noclipConn:Disconnect()
									noclipConn = nil
								end
								for part, original in pairs(noclipParts) do
									if part.Parent then
										part.CanCollide = original
									end
									noclipParts[part] = nil
								end
								return
							end
							local character = LocalPlayer.Character
							if not character then
								return
							end
							for _, part in ipairs(character:GetDescendants()) do
								if part:IsA("BasePart") and part.CanCollide then
									if noclipParts[part] == nil then
										noclipParts[part] = true
									end
									part.CanCollide = false
								end
							end
						end)
						return
					end

					if noclipConn then
						noclipConn:Disconnect()
						noclipConn = nil
					end
					for part, original in pairs(noclipParts) do
						if part.Parent then
							part.CanCollide = original
						end
						noclipParts[part] = nil
					end
				end

				-- m1 back and forth per boss key (rebuilt the same way as the big mom module's m1ShuffleOffset)
				local shuffleStates = {}

				if getgenv().bossShuffleOffset == nil then
					getgenv().bossShuffleOffset = function(key, mobRoot)
						if type(key) ~= "string" or getgenv()[key .. "Shuffle"] ~= true or not mobRoot then
							return Vector3.zero
						end
						local character = LocalPlayer.Character
						local root = character and character:FindFirstChild("HumanoidRootPart")
						if not root then
							return Vector3.zero
						end
						local studs = tonumber(getgenv()[key .. "ShuffleStuds"]) or 12
						local period = tonumber(getgenv()[key .. "ShufflePeriod"]) or 0.4
						local shuffle = shuffleStates[key]
						if not shuffle then
							shuffle = { at = 0, phase = 1, dir = nil }
							shuffleStates[key] = shuffle
						end
						local flat = Vector3.new(root.Position.X - mobRoot.Position.X, 0, root.Position.Z - mobRoot.Position.Z)
						local now = tick()
						if now - shuffle.at >= period then
							shuffle.at = now
							shuffle.phase = shuffle.phase == 1 and -1 or 1
							shuffle.dir = nil
						end
						if not (shuffle.dir and shuffle.dir.Magnitude > 0.001) then
							shuffle.dir = flat.Magnitude > 0.001 and flat.Unit or Vector3.new(0, 0, 1)
						end
						if getgenv().M1ShuffleThrough ~= false then
							if shuffle.phase == 1 then
								return shuffle.dir * studs
							end
							return Vector3.zero
						end
						return shuffle.dir * (studs * shuffle.phase)
					end
				end

				-- rebuilt helpers for the cframe step (the originals weren't in the dump). bias: zero, steer straight at the goal
				local function bias()
					return Vector3.zero
				end

				local function blocked(position, ignore)
					-- anything solid within 2 studs?
					local params = RaycastParams.new()
					params.FilterType = Enum.RaycastFilterType.Exclude
					params.FilterDescendantsInstances = ignore or {}
					for _, direction in ipairs({ Vector3.new(2, 0, 0), Vector3.new(-2, 0, 0), Vector3.new(0, 0, 2), Vector3.new(0, 0, -2), Vector3.new(0, 3, 0) }) do
						local hit = workspace:Raycast(position, direction, params)
						if hit and hit.Instance and hit.Instance.CanCollide then
							return true
						end
					end
					return false
				end

				local function freeSpot(position, ignore, radius)
					-- nearest free point around the spot (rings of r/4, r/2, r), the spot itself if nothing is free
					for _, ring in ipairs({ radius / 4, radius / 2, radius }) do
						for i = 0, 7 do
							local angle = i * math.pi / 4
							local candidate = position + Vector3.new(math.cos(angle) * ring, 0, math.sin(angle) * ring)
							if not blocked(candidate, ignore) then
								return candidate
							end
						end
					end
					return position
				end

				local function clearance(position, maxStep, params)
					-- how far up we need to go for a short forward ray to clear what's in front
					local character = LocalPlayer.Character
					local root = character and character:FindFirstChild("HumanoidRootPart")
					local look = root and root.CFrame.LookVector or Vector3.new(0, 0, -1)
					local flatLook = Vector3.new(look.X, 0, look.Z)
					if flatLook.Magnitude < 0.01 then
						return 0
					end
					flatLook = flatLook.Unit
					local rise = 0
					local increment = math.max(0.5, maxStep / 8)
					while rise <= maxStep do
						local hit = workspace:Raycast(position + Vector3.new(0, rise, 0), flatLook * 6, params)
						if not (hit and hit.Instance) then
							return rise
						end
						rise += increment
					end
					return maxStep
				end

				-- nearest living mob by name (rebuilt), prefers ones that aren't aggro'd when needAggro is set
				local function findMob(root, mobName, container, needAggro, exclude)
					local best, bestDistance = nil, math.huge
					for _, model in ipairs(container:GetChildren()) do
						if not (model.Name == mobName and model ~= exclude) then
							continue
						end

						local humanoid = model:FindFirstChildOfClass("Humanoid")
						local part = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
						if part and part.Parent and not (humanoid and humanoid.Health <= 0 and humanoid.MaxHealth > 0) then
							local aggro = model:FindFirstChild("Aggro")
							if not (needAggro and aggro and aggro.Value == true) then
								local distance = (part.Position - root.Position).Magnitude
								if distance < bestDistance then
									best, bestDistance = model, distance
								end
							end
						end
					end
					return best
				end

				-- look / right / up of a cframe
				local function axes(cf)
					local look = cf.LookVector
					local right = cf.RightVector or Vector3.new(-look.Z, 0, look.X)
					local up = cf.UpVector or Vector3.new(0, 1, 0)
					return look, right, up
				end

				local function hawkEyeDodging()
					local stamp = getgenv().HawkEyeDodging
					return stamp and tick() - stamp < 2
				end

				local function isDowned(character)
					local fn = getgenv().isCharacterDowned or getgenv().isStunned
					if fn then
						local ok, result = pcall(fn, character)
						return ok and result == true
					end
					return false
				end

				-- the engine. spec = { kind = "cframe" | "mob", mobKind, name, cfg, speed, noclip, walkOnWater, maxTime, ... }
				local function startEngine(spec)
					if getgenv().EvadingBoss or getgenv().LowHealthAnchored then
						return false
					end
					if getgenv().LowHealthActive and not getgenv().LowHealthSelfTween then
						return false
					end
					local state = tweenState()
					if state.Enabled == true then
						return false
					end
					if getgenv().combatPaused and getgenv().combatPaused() then
						return false
					end
					local character = LocalPlayer.Character
					local root = character and character:FindFirstChild("HumanoidRootPart")
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					if not root or not humanoid or humanoid.Health <= 0 then
						return false
					end
					local isMob = spec.kind == "mob"
					local mob = nil
					if isMob then
						mob = findMob(root, spec.mobName, spec.container, false, nil)
						if not mob then
							return false
						end
					end

					if getgenv().RecordTweenRequest then
						pcall(getgenv().RecordTweenRequest, isMob and "mob" or "cframe", spec.cfg)
					end
					setNoclip(false)
					if getgenv().releaseAimStance then
						pcall(getgenv().releaseAimStance)
					end
					local stop = getgenv().StopCurrentTween
					if stop then
						stop()
					end
					state.Enabled = true
					state.AtGoal = false
					state.Attached = false
					state.ClimbStartTime = nil
					state.ClimbTpUsed = nil
					state.IsMobTween = isMob or nil
					state.BossKey = spec.bossKey
					setNoclip(spec.noclip)
					getgenv().NoclipOverride = isMob
					getgenv().OverrideType = isMob and "Noclip" or ""
					getgenv().WaterOverride = true
					getgenv().WaterOverrideType = spec.walkOnWater and "Collide" or "NoCollide"
					humanoid.PlatformStand = true
					humanoid.AutoRotate = false
					if not (getgenv().firebreathMovementHeld and getgenv().firebreathMovementHeld()) then
						root.Anchored = false
					end

					local gyro = Instance.new("BodyGyro")
					gyro.Name = isMob and "KD_TweenGyro" or "KD_CFrameGyro"
					gyro.P = 200000
					gyro.D = isMob and (getgenv().ChaseGyroD or 1000) or 1000
					gyro.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
					gyro.CFrame = root.CFrame
					gyro.Parent = root
					local velocity = Instance.new("BodyVelocity")
					velocity.Name = isMob and "KD_TweenVel" or "KD_CFrameVel"
					velocity.MaxForce = Vector3.new(1e9, 1e9, 1e9)
					velocity.Velocity = Vector3.zero
					velocity.Parent = root
					state.Gyro = gyro
					state.Vel = velocity

					local myGen = state.Gen
					local connection = nil
					local startCharacter = character
					local startClock = tick()
					local vtpPhase = nil -- nil | "run" | "done"
					local usedVtp = false

					local raycastParams = RaycastParams.new()
					raycastParams.FilterType = Enum.RaycastFilterType.Exclude
					raycastParams.FilterDescendantsInstances = { character }

					local function cleanup(arrived)
						pcall(function()
							velocity.Velocity = Vector3.zero
						end)
						pcall(function()
							gyro:Destroy()
						end)
						pcall(function()
							velocity:Destroy()
						end)
						if state.Conn == connection and connection then
							state.Conn = nil
						end
						if connection then
							connection:Disconnect()
						end
						if state.Gen == myGen then
							state.Enabled = false
							state.Gyro = nil
							state.Vel = nil
							state.IsMobTween = nil
							state.Attached = false
							state.ClimbStartTime = nil
							state.AtGoal = arrived == true
							if arrived and getgenv().MarkTweenArrived then
								pcall(getgenv().MarkTweenArrived)
							end
						end
						setNoclip(false)
						if usedVtp and getgenv().vertFaceMouseOff then
							pcall(getgenv().vertFaceMouseOff)
						end
						pcall(function()
							root.AssemblyLinearVelocity = Vector3.zero
							root.AssemblyAngularVelocity = Vector3.zero
						end)
						pcall(function()
							humanoid.PlatformStand = false
							humanoid.AutoRotate = true
						end)
						getgenv().WaterOverride = false
						getgenv().NoclipOverride = false
					end

					-- TweenToCFrame step
					local lastProgress = tick()
					local lastFlat = Vector3.new(root.Position.X, 0, root.Position.Z)
					local stuckUntil = 0
					local stunStart = nil
					local currentCharacter = character

					local function cframeStep(dt)
						local cfg = spec.cfg
						local speed = spec.speed
						if getgenv().firebreathMovementHeld and getgenv().firebreathMovementHeld() then
							-- firebreath hold: stand still, the clock does not run
							velocity.Velocity = Vector3.zero
							startClock += dt
							lastProgress = tick()
							return
						end
						if vtpPhase == "run" then
							velocity.Velocity = Vector3.zero
							startClock += dt
							return
						end
						local timedOut = tick() - startClock >= spec.maxTime
						if not state.Enabled or getgenv().EvadingBoss or getgenv().LowHealthAnchored or timedOut then
							if timedOut and state.Enabled then
								-- the dump returned here without cleaning up, which would hang callers waiting for Enabled == false
								getgenv().TweenNeedsRetween = true
								bmLog(string.format("[Tween] Timed out after %ds still %d studs from the goal - NOT an arrival.", math.floor(spec.maxTime),
									math.floor((spec.cframe.Position + spec.offset - root.Position).Magnitude)))
							end
							cleanup(false)
							return
						end
						if getgenv().holdAboveWater then
							getgenv().holdAboveWater(root)
						end

						local character = LocalPlayer.Character
						if not character or not character.Parent then
							return -- skips the frame, does not end the tween
						end
						if not root or root.Parent ~= character then
							root = character:FindFirstChild("HumanoidRootPart")
						end
						if not humanoid or humanoid.Parent ~= character then
							humanoid = character:FindFirstChildOfClass("Humanoid")
						end
						if not root or not humanoid then
							return
						end
						if currentCharacter ~= character then
							currentCharacter = character
							raycastParams.FilterDescendantsInstances = { currentCharacter }
						end
						if gyro.Parent ~= root then
							gyro.Parent = root -- the movers follow the root part
						end
						if velocity.Parent ~= root then
							velocity.Parent = root
						end

						-- added: dead humanoid ends the tween
						if humanoid.Health <= 0 then
							cleanup(false)
							return
						end

						-- stun hold
						local isStunned = getgenv().isStunned or getgenv().isCharacterDowned
						if isStunned and isStunned(character) then
							velocity.Velocity = Vector3.zero
							pcall(function()
								root.AssemblyLinearVelocity = Vector3.zero
								root.AssemblyAngularVelocity = Vector3.zero
							end)
							if not stunStart then
								stunStart = tick()
								getgenv().subStatus = "Stunned - holding the tween"
							end
							local limit = cfg.StunHoldMax or getgenv().TweenStunHoldMax or 6
							if limit < tick() - stunStart then
								bmLog(string.format("[Tween] Held by a stun for %ds - dropping the tween so it can be re-fired.", math.floor(tick() - stunStart)))
								getgenv().TweenNeedsRetween = true
								cleanup(false)
								return
							end
							startClock += dt -- the stun does not count against MaxTime
							return
						end
						if stunStart then
							stunStart = nil
							humanoid.PlatformStand = true
							humanoid.AutoRotate = false
							if not (getgenv().firebreathMovementHeld and getgenv().firebreathMovementHeld()) then
								root.Anchored = false
							end
							-- the dump is cut here, falls through to the normal flow
						end

						-- stuck: under 4 studs of progress in 1.5s -> 0.6s of climbing
						local now = tick()
						local flat = Vector3.new(root.Position.X, 0, root.Position.Z)
						if (flat - lastFlat).Magnitude > 4 then
							lastFlat = flat
							lastProgress = now
						elseif 1.5 < now - lastProgress then
							lastProgress = now
							stuckUntil = now + 0.6
						end

						-- goal and steering point
						local goal = spec.cframe.Position + spec.offset
						local steer = goal + bias()
						local position = root.Position

						-- look-ahead: five rays, first hit decides the Y adjustment
						local reach = math.max(5, speed * dt * 2.5)
						local look, right, up = axes(root.CFrame)
						local sideReach = math.max(3, reach - 2)
						local p = root.Position
						local hit = nil
						for _, ray in ipairs({
							{ p, look * reach },
							{ p + right * 1.5, look * sideReach },
							{ p - right * 1.5, look * sideReach },
							{ p + up * 1.5, look * sideReach },
							{ p - up * 1.5, look * sideReach },
						}) do
							hit = workspace:Raycast(ray[1], ray[2], raycastParams)
							if hit and hit.Instance then
								break
							end
							hit = nil
						end
						if hit and hit.Instance then
							local instance = hit.Instance
							local normal = hit.Normal
							local isBarrier = tostring(instance.CollisionGroup or ""):match("Barrier") ~= nil
								or string.find(string.lower(instance:GetFullName()), "barrier", 1, true) ~= nil
							local floorLike = math.abs(normal:Dot(Vector3.new(0, 1, 0))) >= 0.75
							local parent = instance.Parent
							local isCharacter = parent ~= nil
								and (parent:FindFirstChild("Humanoid") ~= nil or (parent.Parent ~= nil and parent.Parent:FindFirstChild("Humanoid") ~= nil))
							local landing = nil
							if not floorLike and not isCharacter and getgenv().climbLanding then
								local okLanding, result = pcall(getgenv().climbLanding, root, position, normal, instance, raycastParams, { currentCharacter }, "TweenToCFrame")
								if okLanding then
									landing = result
								end
							end
							if landing then
								if landing.Y - root.Position.Y > (getgenv().TweenClimbLogMin or 8) and getgenv().LogTweenClimb then
									pcall(getgenv().LogTweenClimb, "TweenToCFrame", instance.Name, isBarrier, root.Position.Y, landing.Y)
								end
								position = landing -- snap up / over the obstacle
							else
								position = Vector3.new(position.X, root.Position.Y + clearance(root.Position, 10, raycastParams), position.Z)
							end
						end

						-- vertical placement for this frame
						if now < stuckUntil then
							position = Vector3.new(position.X, root.Position.Y + clearance(root.Position, math.max(1.5, speed * dt), raycastParams), position.Z)
						else
							local down = workspace:Raycast(position, Vector3.new(0, -2000, 0), raycastParams)
							if down and down.Instance then
								local spot = Vector3.new(position.X, down.Position.Y + 5, position.Z)
								if blocked(spot, { currentCharacter }) then
									spot = freeSpot(spot, { currentCharacter }, 20)
								end
								if getgenv().SnapGroundY then
									local okSnap, snapped = pcall(getgenv().SnapGroundY, "TweenToCFrame", root, spot, down.Instance)
									position = okSnap and snapped or spot
								else
									position = spot
								end
							end
						end
						if getgenv().TweenInstantY ~= false and now >= stuckUntil and goal.Y - position.Y > (tonumber(getgenv().TweenInstantYGap) or 6) then
							position = Vector3.new(position.X, goal.Y, position.Z) -- far below the goal: jump straight to its height
						end
						if getgenv().clampYUp then
							local okClamp, clamped = pcall(getgenv().clampYUp, root, position, "TweenToCFrame")
							if okClamp and typeof(clamped) == "Vector3" then
								position = clamped
							end
						end
						if not (getgenv().firebreathMovementHeld and getgenv().firebreathMovementHeld()) then
							root.CFrame = CFrame.new(position) * root.CFrame.Rotation -- the per-frame snap (rotation kept)
						end
						root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, 0, root.AssemblyLinearVelocity.Z)

						-- facing, arrival, horizontal velocity
						local toSteer = steer - root.Position
						local toGoal = goal - root.Position
						local flatToGoal = Vector3.new(toGoal.X, 0, toGoal.Z).Magnitude
						if flatToGoal == 0 then
							flatToGoal = 0.001
						end
						local step = speed * dt -- one frame of travel
						local snapRadius = math.max(1, step * 1.5)
						local arriveRadius = math.max(0.5, step * 1.2)
						local face = Vector3.new(steer.X, root.Position.Y, steer.Z)
						if (face - root.Position).Magnitude > 0.001 then
							gyro.CFrame = CFrame.new(root.Position, face)
						end
						if not (spec.teleportOnClose and flatToGoal <= snapRadius) then
							if flatToGoal <= arriveRadius then -- arrived without a snap
								getgenv().WaterOverride = false
								velocity.Velocity = Vector3.zero
								root.AssemblyLinearVelocity = Vector3.zero
								root.AssemblyAngularVelocity = Vector3.zero
								local landedAt = root.Position
								cleanup(true) -- MarkTweenArrived, tear down, Enabled = false
								if getgenv().landAfterTween then
									pcall(getgenv().landAfterTween, landedAt, "TweenToCFrame")
								end
							else
								local dir = Vector3.new(toSteer.X, 0, toSteer.Z)
								if dir.Magnitude == 0 then
									dir = Vector3.new(1, 0, 0)
								end
								velocity.Velocity = dir.Unit * speed -- constant horizontal speed, no ramp
								local velocity = root.AssemblyLinearVelocity
								if velocity.Magnitude > speed * 2 then
									root.AssemblyLinearVelocity = velocity.Unit * (speed * 2)
								end
							end
							return
						end
						-- close enough: snap onto the goal and finish
						getgenv().ForceDisableFastWalk = true
						getgenv().WaterOverride = false
						if not (getgenv().firebreathMovementHeld and getgenv().firebreathMovementHeld()) then
							root.CFrame = CFrame.new(goal) * root.CFrame.Rotation
						end
						root.AssemblyLinearVelocity = Vector3.zero
						root.AssemblyAngularVelocity = Vector3.zero
						velocity.Velocity = Vector3.zero
						cleanup(true)
						if getgenv().landAfterTween then
							pcall(getgenv().landAfterTween, goal, "TweenToCFrame")
						end
						task.delay(0.05, function()
							getgenv().ForceDisableFastWalk = false
						end)
					end

					-- TweenToMob2 / TweenToMob step
					local lastRetarget = 0

					local function mobStep(dt)
						local cfg = spec.cfg
						local speed = spec.speed
						if vtpPhase == "run" then
							return
						end
						if spec.maxTime and tick() - startClock >= spec.maxTime then
							cleanup(false) -- MaxTime: plain cleanup, no TweenNeedsRetween here
							return
						end
						local character = LocalPlayer.Character
						local humanoid = character and character:FindFirstChild("Humanoid")
						if not character or not humanoid or humanoid.Health <= 0 or character ~= startCharacter then
							cleanup(false) -- the character changed or died: end the tween
							return
						end
						if not state.Attached and isDowned(character) then
							cleanup(false)
							return
						end
						if getgenv().IsStunnedOverride then -- stunned: stand still, keep the tween
							velocity.Velocity = Vector3.zero
							return
						end

						-- re-target at most once a second when the mob is gone
						local now = tick()
						local mobHumanoid = mob and mob:FindFirstChildOfClass("Humanoid")
						local needRetarget, needAggro = false, false
						if not mob or not mob.Parent or not mobHumanoid or mobHumanoid.Health <= 0 then
							needRetarget = true
						elseif spec.mobKind == 1 then
							local aggro = mob:FindFirstChild("Aggro")
							if aggro and aggro.Value == true then
								local other = findMob(root, spec.mobName, spec.container, true, mob)
								if other then
									needRetarget, needAggro = true, true
								end
							end
						end
						if needRetarget and 1 <= now - lastRetarget then
							-- the dump calls stopTween(false) here, but that would kill the movers used right below, so the tween only ends (further down) when no mob is left
							lastRetarget = now
							mob = findMob(root, spec.mobName, spec.container, needAggro, needAggro and mob or nil) or (needAggro and mob or nil)
						end
						if not mob or not mob.Parent then
							cleanup(false)
							return
						end
						local mobRoot = mob:FindFirstChild("HumanoidRootPart") or mob.PrimaryPart
						if not mobRoot then
							return
						end

						-- behind distance and hover offset
						local behind = spec.behind
						local offsetVector = spec.offset
						if mob.Name == "Hawk Eye" or spec.mobName == "Hawk Eye" then
							if hawkEyeDodging() then
								behind = 18 -- 18 behind, 15 up while Hawk Eye dodges
								offsetVector = Vector3.new(0, 15, 0)
							else
								behind = 8 -- 8 behind, 14 up
								offsetVector = Vector3.new(0, 14, 0)
							end
						end
						local shuffle = Vector3.zero
						if spec.mobKind == 2 and cfg.BossKey then
							local dodging = cfg.BossKey == "Mihawk" and hawkEyeDodging()
							local y = tonumber(getgenv()[cfg.BossKey .. "OffsetY"]) -- "<Key>OffsetY" slider replaces the hover height
							if y and not dodging then
								offsetVector = Vector3.new(offsetVector.X, y, offsetVector.Z)
							end
							if not dodging and getgenv().bossShuffleOffset then
								shuffle = getgenv().bossShuffleOffset(cfg.BossKey, mobRoot)
							end
						end
						local goal = mobRoot.Position + -mobRoot.CFrame.LookVector * behind + offsetVector + shuffle
						local toGoal = goal - root.Position
						if getgenv().holdAboveWater then
							getgenv().holdAboveWater(root, goal.Y)
						end
						local teleportDistance = cfg.TeleportDistance or 15
						local away = root.Position - goal
						local climbBoost = 0

						-- raycast on and farther than TeleportDistance: look ahead (5 rays for TweenToMob2, 9 for TweenToMob)
						if spec.raycastEnabled and not (away.Magnitude <= teleportDistance) then
							local p = root.Position
							local look, right, up = axes(root.CFrame)
							local reach = math.max(5, speed * dt * 2.5)
							local sideReach = math.max(3, reach - 2)
							raycastParams.FilterDescendantsInstances = { LocalPlayer.Character or startCharacter }
							local rays = {
								{ p, look * reach },
								{ p + right * 1.5, look * sideReach },
								{ p - right * 1.5, look * sideReach },
								{ p + up * 1.5, look * sideReach },
								{ p - up * 1.5, look * sideReach },
							}
							if spec.mobKind == 1 then
								rays[#rays + 1] = { p + right * 1.2, (look + right * 0.75).Unit * reach }
								rays[#rays + 1] = { p - right * 1.2, (look - right * 0.75).Unit * reach }
								rays[#rays + 1] = { p + look * 0.5, right * 2.8 }
								rays[#rays + 1] = { p + look * 0.5, -right * 2.8 }
							end
							local hit = nil
							for _, ray in ipairs(rays) do
								hit = workspace:Raycast(ray[1], ray[2], raycastParams)
								if hit and hit.Instance then
									break
								end
								hit = nil
							end
							if hit and hit.Instance then
								local instance = hit.Instance
								local isBarrier = tostring(instance.CollisionGroup or ""):match("Barrier") ~= nil
								local parent = instance.Parent
								local isCharacter = parent ~= nil and (parent:FindFirstChild("Humanoid") ~= nil or (parent.Parent ~= nil and parent.Parent:FindFirstChild("Humanoid") ~= nil))
								if getgenv().LogTweenClimb and (isBarrier or not isCharacter) then
									pcall(getgenv().LogTweenClimb, spec.name, instance.Name, isBarrier, root.Position.Y, root.Position.Y + reach)
								end
								-- rebuilt: something solid that isn't a character gets climbed (extra upward speed this frame)
								if not isCharacter and instance.CanCollide ~= false then
									climbBoost = speed
									state.ClimbStartTime = state.ClimbStartTime or now
								end
							else
								state.ClimbStartTime = nil
							end
						end

						-- ---- steering ----
						local flatDistance = Vector3.new(toGoal.X, 0, toGoal.Z).Magnitude
						local distance = toGoal.Magnitude
						if distance == 0 then
							distance = 0.001
						end
						local aim = Vector3.new(goal.X, root.Position.Y, goal.Z) -- face the goal horizontally
						if (aim - root.Position).Magnitude > 0.001 then
							gyro.CFrame = CFrame.new(root.Position, aim)
						end

						if cfg.TeleportOnClose ~= false and distance <= teleportDistance then
							-- close: snap onto the hover point (keep rotation), stop, mark attached. the position logging hooks are left out
							root.CFrame = CFrame.new(goal) * root.CFrame.Rotation
							root.AssemblyLinearVelocity = Vector3.zero
							root.AssemblyAngularVelocity = Vector3.zero
							velocity.Velocity = Vector3.zero
							state.Attached = true
							return
						end

						if distance <= spec.stopDistance or (spec.raycastEnabled and flatDistance <= 4) then
							velocity.Velocity = Vector3.zero
							root.AssemblyLinearVelocity = Vector3.zero
							state.Attached = true
							return
						end

						state.Attached = false
						if getgenv().releaseAimStance then
							getgenv().releaseAimStance()
						end
						if not spec.raycastEnabled then
							velocity.Velocity = toGoal.Unit * speed -- full 3-D direction, constant speed, no ramp
							return
						end
						local flat = Vector3.new(toGoal.X, 0, toGoal.Z) -- raycast on: horizontal only, height is held by PlatformStand / holdAboveWater
						if flat.Magnitude > 0.001 then
							velocity.Velocity = flat.Unit * speed + Vector3.new(0, climbBoost, 0)
						else
							velocity.Velocity = Vector3.new(0, climbBoost, 0)
						end
					end

					local step = isMob and mobStep or cframeStep
					connection = RunService.Heartbeat:Connect(function(dt)
						-- stopped from outside (StopCurrentTween bumps Gen and already removed the movers) or replaced
						if state.Gen ~= myGen or state.Conn ~= connection then
							cleanup(false)
							return
						end
						local ok, err = pcall(step, dt)
						if not ok then
							bmLog("[Tween] step failed: " .. tostring(err))
							cleanup(false)
						end
					end)
					state.Conn = connection

					-- TweenToCFrame: height changes over VerticalTpStep (900) are hopped first, then the flight starts. smaller ones don't touch the stance
					if not isMob and getgenv().stepVerticalTP then
						local goalPosition = spec.cframe.Position + spec.offset
						if math.abs(goalPosition.Y - root.Position.Y) > (getgenv().VerticalTpStep or 900) then
							vtpPhase = "run"
							usedVtp = true
							task.spawn(function()
								local ok, done = pcall(getgenv().stepVerticalTP, root, goalPosition.Y, "TweenToCFrame", function()
									return state.Enabled and state.Conn == connection
								end)
								if ok and done and state.Enabled and state.Conn == connection then
									vtpPhase = "done"
								else
									vtpPhase = nil
									if state.Conn == connection then
										cleanup(false)
									end
								end
							end)
						end
					end
					return true
				end

				-- entry points
				-- TweenToCFrame. cfg: CFrame, Speed (60), Offset, TeleportOnClose (true), WalkOnWater (true), Noclip (true), MaxTime (20), StunHoldMax
				-- StopDistance / TeleportDistance are accepted but unused (arrives at 1.2 frames of travel, snaps at 1.5)
				local function tweenToCFrame(cfg)
					cfg = cfg or {}
					local cframe = cfg.CFrame
					if typeof(cframe) == "Vector3" then
						cframe = CFrame.new(cframe)
					end
					if not cframe then
						return false
					end
					return startEngine({
						kind = "cframe",
						cfg = cfg,
						name = "TweenToCFrame",
						cframe = cframe,
						offset = cfg.Offset or Vector3.zero,
						speed = cfg.Speed or 60,
						noclip = cfg.Noclip ~= false,
						walkOnWater = cfg.WalkOnWater ~= false,
						teleportOnClose = cfg.TeleportOnClose ~= false,
						maxTime = cfg.MaxTime or 20,
					})
				end

				-- TweenToMob and TweenToMob2 (TweenToMob2 adds BehindDistance and BossKey)
				-- cfg: MobName ("Fishman Karate User"), Speed (70), Offset, Container (workspace), StopDistance (3), Raycast (true), WalkOnWater (true), BehindDistance (0),
				-- TeleportOnClose (true), TeleportDistance (15), MaxTime (none), BossKey
				local function mobTween(cfg, mobKind)
					cfg = cfg or {}
					return startEngine({
						kind = "mob",
						mobKind = mobKind,
						cfg = cfg,
						name = mobKind == 1 and "TweenToMob" or "TweenToMob2",
						bossKey = cfg.BossKey,
						mobName = cfg.MobName or "Fishman Karate User",
						container = cfg.Container or workspace,
						offset = cfg.Offset or Vector3.zero,
						behind = mobKind == 2 and (cfg.BehindDistance or 0) or 0,
						speed = cfg.Speed or 70,
						noclip = true,
						walkOnWater = cfg.WalkOnWater ~= false,
						stopDistance = cfg.StopDistance or 3,
						raycastEnabled = cfg.Raycast ~= false,
						maxTime = cfg.MaxTime,
					})
				end

				local function tweenToMob(cfg)
					return mobTween(cfg, 1)
				end

				local function tweenToMob2(cfg)
					return mobTween(cfg, 2)
				end

				-- always in getgenv().__F2Tween, the public names only if nothing defined them before
				getgenv().__F2Tween = { TweenToCFrame = tweenToCFrame, TweenToMob = tweenToMob, TweenToMob2 = tweenToMob2 }

				if rawget(getgenv(), "TweenToCFrame") == nil then
					getgenv().TweenToCFrame = tweenToCFrame
				end

				if rawget(getgenv(), "TweenToMob") == nil then
					getgenv().TweenToMob = tweenToMob
				end

				if rawget(getgenv(), "TweenToMob2") == nil then
					getgenv().TweenToMob2 = tweenToMob2
				end
			end

			-- m1 loops
			do
				-- the two attack loops all farms share. kill aura isn't a loop, it widens combatRange() and makes targetsInRange() return every npc around
				-- PikaV2 counts as a sword ("Sword" in weaponNow). each loop just yields every frame while no farm is on or the weapon type doesn't match
				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")

				local loops = getgenv().__TensenFarmLoops
				if not loops then
					loops = {}
					getgenv().__TensenFarmLoops = loops
				end

				-- fake m1 on block. targets with a settings key (Juzo / Roger / Mihawk, the selected npc, a player in Tween To Player) use bossFeint
				-- (boss tab <Key>FeintOnBlock / <Key>FeintRetry), everything else uses farmFeint. true = don't hit now
				local function feint(g, part, weaponType, index, animation)
					local model = part and part.Parent
					if model and g.bossKeyFor and g.bossFeint and g.bossKeyFor(model) then
						return g.bossFeint(part, weaponType, index, animation)
					end
					return g.farmFeint(part, weaponType, index, animation)
				end

				local function anyFarm(g)
					return g.autofarm or g.haki or g.KillAura or g.TweenToNPC or g.TweenToPlayer
				end

				local function anyBoss(g)
					return g.AutoJuzoBoss or g.AutoRogerBoss or g.AutoMihawkBoss or g.AutoFactory or g.AutoFarmGearCyborg
				end

				local function anyFlag(g)
					return g.autofarm or g.haki or g.AutoJuzoBoss or g.AutoMihawkBoss or g.AutoRogerBoss or g.AutoFactory or g.AutoFarmGearCyborg or g.KillAura
						or g.TweenToNPC or g.TweenToPlayer
				end

				-- combos: index sent to the server + animation name (same as the big mom module)
				local meleeCombo = {
					{ anim = "Punch1", index = 1 },
					{ anim = "Punch2", index = 2 },
					{ anim = "Punch3", index = 3 },
					{ anim = "GroundPunch4", index = 4 },
				}

				local swordCombo = {
					{ anim = "Slash1", index = 1 },
					{ anim = "Slash2", index = 2 },
					{ anim = "Slash3", index = 3 },
					{ anim = "GroundSlash4", index = 4 },
				}

				local function combatRemote()
					local events = ReplicatedStorage:FindFirstChild("Events")
					return events and events:FindFirstChild("CombatRegister")
				end

				local function hitDelay(g)
					local fn = anyBoss(g) and g.bossHitDelay or g.farmHitDelay
					if type(fn) == "function" then
						local ok, value = pcall(fn)
						if ok and type(value) == "number" then
							return value
						end
					end
					return tonumber(g.HitWait) or 0.4
				end

				local function startLoop(key, step)
					local token = {}
					loops[key] = token
					task.spawn(function()
						task.wait()
						while task.wait() do
							if loops[key] ~= token then
								break
							end
							local ok, err = pcall(step)
							if not ok and getgenv().BMLog and os.clock() - (getgenv().__F2LastLoopErr or 0) > 10 then
								getgenv().__F2LastLoopErr = os.clock()
								getgenv().BMLog("[F2] " .. key .. " step failed: " .. tostring(err))
							end
						end
					end)
				end

				-- melee
				do
					local combo = 1
					local lastSwing = 0

					startLoop("F2.M1Melee", function()
						if not anyFlag(getgenv()) then
							combo = 1
							return
						end
						local meleeFarm = getgenv().weaponNow(getgenv().WeaponType) == "Melee" and anyFarm(getgenv())
						local meleeBoss = getgenv().weaponNow(getgenv().WeaponTypeBoss) == "Melee" and anyBoss(getgenv())
						if not (meleeFarm or meleeBoss) then
							return
						end
						local character = getgenv().Char()
						if getgenv().combatPaused() then
							return
						end
						if not getgenv().equippedMelee(character) then
							return
						end
						if tick() - lastSwing < hitDelay(getgenv()) then
							return
						end
						local root = character:FindFirstChild("HumanoidRootPart")
						if not root then
							return
						end
						local targets = getgenv().targetsInRange(getgenv().combatRange())
						if #targets == 0 then
							combo = 1
							return
						end
						local target = getgenv().pickAttackTarget(targets)
						if not target then
							getgenv().AttacksAllBlocking = (getgenv().AttacksAllBlocking or 0) + 1
							return
						end
						if not (target.Position and root.Position) then
							return
						end
						local step = meleeCombo[combo]
						if not step then
							combo = 1
							return
						end
						getgenv().dropAimStance()
						local animation = ReplicatedStorage.CombatAnimations.Melee[step.anim]
						if feint(getgenv(), target, "Melee", step.index, animation) then
							lastSwing = tick()
							return
						end
						local remote = combatRemote()
						if not remote then
							return
						end
						remote:InvokeServer({ "swingsfx", "Melee", step.index, "Ground", false, animation, 2, 1.5 })
						local offset = target.Position - root.Position
						if offset.Magnitude == 0 then
							offset = root.CFrame.LookVector
						end
						remote:InvokeServer({
							"damage",
							targets,
							"Melee",
							{ step.index, "Ground", "Melee" },
							true,
							CFrame.new(target.Position - offset.Unit * 5 + Vector3.new(0, 1, 0), target.Position),
							aircombo = "Ground",
						})
						lastSwing = tick()
						combo += 1
						if combo > 4 then
							combo = 1
						end
					end)
				end

				-- sword
				do
					local combo = 1
					local lastSwing = 0

					startLoop("F2.M1Sword", function()
						if not anyFlag(getgenv()) then
							combo = 1
							return
						end
						local swordFarm = getgenv().weaponNow(getgenv().WeaponType) == "Sword" and anyFarm(getgenv())
						local swordBoss = getgenv().weaponNow(getgenv().WeaponTypeBoss) == "Sword" and anyBoss(getgenv())
						if not (swordFarm or swordBoss) then
							return
						end
						local character = getgenv().Char()
						if getgenv().combatPaused() then
							return
						end
						local swords = ReplicatedStorage.Modules.SwordHandle.Swords
						local swordName = nil
						for _, child in pairs(swords:GetChildren()) do
							if character:FindFirstChild(child.Name) and getgenv().swordNameAllowed(child.Name) then
								swordName = child.Name
								break
							end
						end
						if not swordName then
							return
						end
						if tick() - lastSwing < hitDelay(getgenv()) then
							return
						end
						local root = character:FindFirstChild("HumanoidRootPart")
						if not root then
							return
						end
						local targets = getgenv().targetsInRange(getgenv().combatRange())
						if #targets == 0 then
							combo = 1
							return
						end
						local target = getgenv().pickAttackTarget(targets)
						if not target then
							getgenv().AttacksAllBlocking = (getgenv().AttacksAllBlocking or 0) + 1
							return
						end
						if not (target.Position and root.Position) then
							return
						end
						local step = swordCombo[combo]
						if not step then
							combo = 1
							return
						end
						getgenv().dropAimStance()
						local slash = swords[swordName].Slashes[step.anim]
						if feint(getgenv(), target, "Sword", step.index, slash) then
							lastSwing = tick()
							return
						end
						local remote = combatRemote()
						if not remote then
							return
						end
						remote:InvokeServer({ "swingsfx", "Sword", step.index, "Ground", false, slash, 2, 1.5 })
						if not target.Position or not root.Position then
							return
						end
						local offset = target.Position - root.Position
						if offset.Magnitude == 0 then
							offset = root.CFrame.LookVector
						end
						remote:InvokeServer({
							"damage",
							targets,
							"Sword",
							{ step.index, "Ground", "Sword" },
							true,
							CFrame.new(target.Position - offset.Unit * 5 + Vector3.new(0, 1, 0), target.Position),
							aircombo = "Ground",
						})
						lastSwing = tick()
						combo += 1
						if combo > 4 then
							combo = 1
						end
					end)
				end

				-- kill aura weapon keeper
				-- once a second: kill aura on (not fishing / storing a fruit / touring an npc) and something in range -> make sure the farm weapon is out
				-- the pcall here is assumed to be the farm weapon equip, nothing else would equip for kill aura
				local token = {}
				loops["F2.KillAuraEquip"] = token
				task.spawn(function()
					task.wait()
					while task.wait(1) do
						if loops["F2.KillAuraEquip"] ~= token then
							break
						end
						pcall(function()
							if getgenv().KillAura and not getgenv().TweenToNPC and not getgenv().AutoFishing and not getgenv().StoringFruit and #getgenv().targetsInRange(getgenv().combatRange()) > 0 then
								pcall(getgenv().equipFarmWeapon)
							end
						end)
					end
				end)
			end

			-- tween to npc / player
			do
				-- "Tween To NPC" and "Tween To Player" loops. they only chase, the m1 loops do the hitting and widen their reach for these two modes
				-- both stand down while another farm runs. tween state = getgenv().__TensenTweenState, stop = getgenv().StopCurrentTween,
				-- equip = getgenv().equipFarmWeapon (name is a guess), findNearestAlive, PvPTarget
				-- the dump had two empty `if flag then end`, filled in as "stop our tween" (otherwise turning the toggle off leaves you flying at the last target)
				local Players = game:GetService("Players")
				local LocalPlayer = Players.LocalPlayer

				local loops = getgenv().__TensenFarmLoops
				if not loops then
					loops = {}
					getgenv().__TensenFarmLoops = loops
				end

				local function tweenState()
					return getgenv().__TensenTweenState or { Enabled = false }
				end

				local function stopTween()
					local stop = getgenv().StopCurrentTween
					if stop then
						stop()
					end
				end

				local function startLoop(key, interval, step)
					local token = {}
					loops[key] = token
					task.spawn(function()
						task.wait()
						while task.wait(interval) do
							if loops[key] ~= token then
								break
							end
							local ok, err = pcall(step)
							if not ok and getgenv().BMLog and os.clock() - (getgenv().__F2LastLoopErr or 0) > 10 then
								getgenv().__F2LastLoopErr = os.clock()
								getgenv().BMLog("[F2] " .. key .. " step failed: " .. tostring(err))
							end
						end
					end)
				end

				-- Tween To NPC
				do
					local running = false

					startLoop("F2.TweenToNPC", 0.5, function()
						local otherFarm = getgenv().autofarm or getgenv().haki or getgenv().AutoJuzoBoss or getgenv().AutoMihawkBoss or getgenv().AutoRogerBoss or getgenv().AutoFishing or getgenv().AutoMerchant or getgenv().StartTweenIsland
						if not (getgenv().TweenToNPC and getgenv().SelectedNPC and getgenv().SelectedNPC ~= "None") or otherFarm then
							if running and tweenState().Enabled and tweenState().IsMobTween then
								stopTween()
							end
							running = false
							return
						end
						local character = LocalPlayer.Character
						local humanoid = character and character:FindFirstChildOfClass("Humanoid")
						running = true
						if not humanoid or humanoid.Health <= 0 then
							return
						end
						if getgenv().NPCAutoEquip ~= false then
							pcall(getgenv().equipFarmWeapon)
						end
						if not tweenState().Enabled and getgenv().findNearestAlive(getgenv().SelectedNPC) then
							getgenv().TweenToMob2({
								MobName = getgenv().SelectedNPC,
								BossKey = "NPC",
								Speed = getgenv().TweenSpeedMaster or 70,
								Offset = Vector3.new(0, tonumber(getgenv().NPCOffsetY) or 9, 0),
								Container = workspace:FindFirstChild("NPCs") or workspace,
							})
						end
					end)
				end

				-- Tween To Player
				local running = false
				local targetName = nil

				startLoop("F2.TweenToPlayer", 0.4, function()
					local otherFarm = getgenv().autofarm or getgenv().haki or getgenv().AutoJuzoBoss or getgenv().AutoMihawkBoss or getgenv().AutoRogerBoss or getgenv().AutoFishing or getgenv().AutoMerchant or getgenv().StartTweenIsland
						or getgenv().TweenToNPC
					if not getgenv().TweenToPlayer or otherFarm then
						if running and tweenState().Enabled and tweenState().IsMobTween then
							stopTween()
						end
						running = false
						targetName = nil
						return
					end
					local character = LocalPlayer.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					if not humanoid or humanoid.Health <= 0 then
						if tweenState().Enabled then
							stopTween()
						end
						running = true
						targetName = nil
						return
					end
					local player = getgenv().PvPTarget()
					if not player or (targetName and targetName ~= player.Name) then
						if tweenState().Enabled then
							stopTween()
						end
						running = true
						targetName = nil
						if not player then
							return
						end
					end
					if getgenv().PvPAutoEquip ~= false then
						pcall(getgenv().equipFarmWeapon)
					end
					running = true
					if tweenState().Enabled then
						return
					end

					targetName = player.Name
					getgenv().TweenToMob2({
						MobName = player.Name,
						BossKey = "PvP",
						Speed = getgenv().TweenSpeedMaster or 70,
						Offset = Vector3.new(0, tonumber(getgenv().PvPOffsetY) or 9, 0),
						Container = player.Character and player.Character.Parent or workspace,
					})
				end)
			end

			-- buso keeper
			do
				-- "Keep Buso Haki on" (getgenv().Buso) and auto buso while a farm runs (BusoFarmAutoOn, on by default)
				-- the big mom module has its own keeper for that fight, this one is for every other farm
				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local LocalPlayer = Players.LocalPlayer

				local loops = getgenv().__TensenFarmLoops
				if not loops then
					loops = {}
					getgenv().__TensenFarmLoops = loops
				end

				local function busoLog(message)
					if getgenv().BMLog then
						getgenv().BMLog(message)
					end
				end

				-- buso bar fill 0..1, nil if it can't be read
				getgenv().busoCharge = function()
					local stats = ReplicatedStorage:FindFirstChild("Stats" .. LocalPlayer.Name)
					local bar = stats and stats:FindFirstChild(getgenv().BusoBarName or "BusoBar")
					if not bar then
						return nil
					end
					local ok, value, maxValue = pcall(function()
						return bar.Value, bar.MaxValue
					end)
					if not ok or type(value) ~= "number" or type(maxValue) ~= "number" or maxValue <= 0 then
						return nil
					end
					return math.clamp(value / maxValue, 0, 1)
				end

				-- true while the buso aura is on the character, nil with no character
				getgenv().busoIsUp = function(character)
					local char = character or LocalPlayer.Character
					if not char or not char.Parent then
						return nil
					end
					return char:FindFirstChild(LocalPlayer.Name .. "Buso") ~= nil
				end

				-- press haki (Events.Haki:FireServer("Buso")), at most once per BusoPressGap
				getgenv().pressBuso = function(state)
					if os.clock() - (getgenv().LastBusoPress or 0) < (getgenv().BusoPressGap or 1) then
						return false
					end
					getgenv().LastBusoPress = os.clock()
					getgenv().BusoPresses = (getgenv().BusoPresses or 0) + 1
					pcall(function()
						ReplicatedStorage:WaitForChild("Events"):WaitForChild("Haki"):FireServer("Buso")
					end)
					if getgenv().BusoLog ~= false then
						busoLog(string.format("[Buso] pressed the haki button to turn it %s (x%d)", tostring(state), getgenv().BusoPresses))
					end
					return true
				end

				-- a fighting farm is running (BusoFarmAutoOn = false turns this off)
				getgenv().busoFarmActive = function()
					if getgenv().BusoFarmAutoOn == false then
						return false
					end
					return getgenv().autofarm == true or getgenv().KillAura == true or getgenv().TweenToNPC == true or getgenv().TweenToPlayer == true or getgenv().AutoJuzoBoss == true
						or getgenv().AutoMihawkBoss == true or getgenv().AutoRogerBoss == true or getgenv().AutoFactory == true or getgenv().AutoFarmGearCyborg == true
				end

				getgenv().busoWanted = function()
					return getgenv().Buso == true or getgenv().busoFarmActive()
				end

				-- every 0.3s: buso wanted and aura down -> press (unless the bar is under BusoRechargeFrac, then wait for it)
				local token = {}
				loops["F2.Buso"] = token
				task.spawn(function()
					task.wait()
					while task.wait(0.3) do
						if loops["F2.Buso"] ~= token then
							break
						end
						pcall(function()
							if not getgenv().busoWanted() then
								return
							end
							local character = LocalPlayer.Character
							if not (character and character.Parent) then
								return
							end
							local humanoid = character:FindFirstChildOfClass("Humanoid")
							if not (humanoid and humanoid.Health > 0) then
								return
							end
							local up = getgenv().busoIsUp(character)
							if up == nil or up then
								return
							end
							local charge = getgenv().busoCharge()
							local recharge = getgenv().BusoRechargeFrac or 0.5
							if charge ~= nil and charge < recharge then
								getgenv().BusoWaitedForBar = (getgenv().BusoWaitedForBar or 0) + 1
								if getgenv().BusoLog ~= false and os.clock() - (getgenv().LastBusoWaitLog or 0) >= 3 then
									getgenv().LastBusoWaitLog = os.clock()
									busoLog(string.format("[Buso] ran out - waiting for the bar to reach %d%% before re-enabling (now %d%%).", math.floor(recharge * 100), math.floor(charge * 100)))
								end
							else
								getgenv().pressBuso("ON")
							end
						end)
					end
				end)
			end

			-- boss state
			do
				-- shared state and small helpers for Auto Juzo / Auto Roger / Auto Mihawk. all in getgenv() so the loops look them up when called

				-- "killed this spawn window" flags, shared by the farm loop, the schedules, umiBossComingUp and BossStatusText. engagedAt = when the fight started
				local state = getgenv().__TensenBossState
				if type(state) ~= "table" then
					state = {mihawkDone = false, rogerDone = false, engagedAt = nil}
					getgenv().__TensenBossState = state
				end

				-- where the umi trips go. the farm loop falls back to this exact spot when it's nil. the default itself is my pick, the dump only reads it
				if getgenv().UmiInstantCF == nil and CFrame then
					getgenv().UmiInstantCF = CFrame.new(12512.18359375, 6.5736985206604, 2761.882080078125)
				end

				-- mihawk window: UTC+3, odd hours, open the first 900s. outside the window the done flag is cleared
				-- returns untilOpen, secondsIntoHour, windowOpen
				getgenv().MihawkSchedule = function()
					local t = os.date("!*t")
					local hour = (t.hour + 3) % 24
					local intoHour = t.min * 60 + t.sec
					if hour % 2 == 1 then
						if intoHour <= 900 then
							return 0, intoHour, true
						end
						state.mihawkDone = false
						return 7200 - intoHour, intoHour, false
					end
					state.mihawkDone = false
					return 3600 - intoHour, intoHour, false
				end

				-- roger window: 5400s cycle on the UTC+3 clock, open the first 900s
				getgenv().RogerSchedule = function()
					local t = os.date("!*t")
					local intoCycle = ((t.hour + 3) % 24 * 3600 + t.min * 60 + t.sec) % 5400
					if intoCycle <= 900 then
						return 0, intoCycle, true
					end
					state.rogerDone = false
					return 5400 - intoCycle, intoCycle, false
				end

				-- second sea only. true while a wanted umi boss (toggle on, not done yet) is in its window or opens within 180s
				getgenv().umiBossComingUp = function()
					if game.PlaceId ~= 7465136166 then
						return false
					end
					local mihawkUntil, _, mihawkOpen = getgenv().MihawkSchedule()
					local rogerUntil, _, rogerOpen = getgenv().RogerSchedule()
					local mihawkWanted = getgenv().AutoMihawkBoss and not state.mihawkDone
					local rogerWanted = getgenv().AutoRogerBoss and not state.rogerDone
					return mihawkWanted and (mihawkUntil <= 180 or mihawkOpen) or rogerWanted and (rogerUntil <= 180 or rogerOpen)
				end

				-- living npc called `name`? exact or case-insensitive substring, needs Health > 0 and a root part
				getgenv().npcAlive = function(name)
					local npcs = workspace:FindFirstChild("NPCs")
					if not npcs then
						return false
					end
					local lowered = name and name:lower() or ""
					for _, child in pairs(npcs:GetChildren()) do
						if child.Name == name or lowered ~= "" and string.find(child.Name:lower(), lowered, 1, true) then
							local humanoid = child:FindFirstChildOfClass("Humanoid")
							local root = child:FindFirstChild("HumanoidRootPart") or child.PrimaryPart
							if humanoid and humanoid.Health > 0 and root then
								return true
							end
						end
					end
					return false
				end

				-- <key>AutoEquip (Juzo / Roger / Mihawk) pulls out the boss weapon, one equip at a time
				-- assumed to be equipBossWeapon (WeaponTypeBoss), the dump only shows a pcall'd call
				local equipBusy = false
				getgenv().bossAutoEquip = function(key)
					if getgenv()[key .. "AutoEquip"] == false then
						return
					end
					if equipBusy then
						return
					end
					equipBusy = true
					task.spawn(function()
						pcall(function()
							local equip = getgenv().equipBossWeapon
							if equip then
								equip()
							end
						end)
						equipBusy = false
					end)
				end

				-- tween to juzo's island door
				getgenv().TweenToJuzoEntrance = function()
					getgenv().TweenToCFrame({
						CFrame = CFrame.new(1770.34546, 36.0756149, -10659.0898, 0.98101902, 3.78205867e-09, -0.193911418, -4.64293626e-09, 1, -3.98506605e-09, 0.193911418, 4.80974416e-09, 0.98101902),
						Speed = getgenv().TweenSpeedAutoBoss or 110,
						StopDistance = 5,
						Raycast = true,
						TeleportOnClose = true,
						TeleportDistance = 5,
						CupidStyle = false,
						MaxTime = getgenv().BossTweenMaxTime or 10,
						HoverHeight = getgenv().BossTravelHoverHeight or 5,
					})
				end

				-- tween to the umi spot (getgenv().UmiInstantCF)
				getgenv().TweenToUmiForRogerandMihawk = function()
					getgenv().TweenToCFrame({
						CFrame = getgenv().UmiInstantCF,
						Speed = getgenv().TweenSpeedAutoBoss or 110,
						StopDistance = 5,
						Raycast = true,
						TeleportOnClose = true,
						TeleportDistance = 5,
						CupidStyle = false,
						MaxTime = getgenv().BossTweenMaxTime or 10,
						HoverHeight = getgenv().BossTravelHoverHeight or 5,
					})
				end
			end

			-- boss keys
			do
				-- per-boss settings that the boss tabs write ("Juzo" / "Roger" / "Mihawk" prefix)
				--   bossKeyFor(model)          -> "Juzo" | "Roger" | "Mihawk" | "NPC" | "PvP" | nil (by name, NPC/PvP only while that tween mode is on)
				--   bossTargetBlocking(model)  -> Blocking/Block child, Blocking/IsBlocking attribute, or an animation named *block* playing
				--   bossFeint(part, weaponType, index, animation) -> if the target has a key with <Key>FeintOnBlock not false and it's blocking,
				--       send a "swingsfx" swing with no damage and wait <Key>FeintRetry (default 5). true = don't hit now
				-- the m1 loops skip the hit when bossFeint returns true. the big mom module has its own FeintOnBlock copy

				getgenv().bossKeyFor = getgenv().bossKeyFor or function(model)
					local name = model and model.Name
					if name == "Juzo the Diamondback" then
						return "Juzo"
					end
					if name == "Roger" then
						return "Roger"
					end
					if name == "Hawk Eye" or name == "Mihawk" then
						return "Mihawk"
					end
					if getgenv().TweenToNPC and name ~= nil and name == getgenv().SelectedNPC then
						return "NPC"
					end
					if getgenv().TweenToPlayer and name ~= nil and game:GetService("Players"):FindFirstChild(name) then
						return "PvP"
					end
					return nil
				end

				getgenv().bossTargetBlocking = getgenv().bossTargetBlocking or function(instance)
					if not (instance and instance.Parent) then
						return false
					end
					if instance:FindFirstChild("Blocking") or instance:FindFirstChild("Block") then
						return true
					end
					local ok, result = pcall(function()
						return instance:GetAttribute("Blocking") or instance:GetAttribute("IsBlocking")
					end)
					if ok and result == true then
						return true
					end
					local humanoid = instance:FindFirstChildOfClass("Humanoid")
					local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
					local blocking = false
					if animator then
						pcall(function()
							for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
								local animation = track.Animation
								if animation and string.find(string.lower(animation.Name or ""), "block", 1, true) then
									blocking = true
									return
								end
							end
						end)
					end
					return blocking
				end

				local lastFeint = setmetatable({}, {__mode = "k"})

				getgenv().bossFeint = getgenv().bossFeint or function(part, weaponType, index, animation)
					local model = part and part.Parent
					local key = model and getgenv().bossKeyFor(model)
					if not key or getgenv()[key .. "FeintOnBlock"] == false then
						return false
					end
					if not getgenv().bossTargetBlocking(model) then
						lastFeint[model] = nil
						return false
					end
					local last = lastFeint[model]
					if last and tick() - last < (tonumber(getgenv()[key .. "FeintRetry"]) or 5) then
						return true
					end
					pcall(function()
						game:GetService("ReplicatedStorage").Events.CombatRegister:InvokeServer({"swingsfx", weaponType, index, "Ground", false, animation, 2, 1.5})
					end)
					lastFeint[model] = tick()
					return true
				end
			end

			-- boss farm
			do
				-- boss farm loop for Auto Juzo / Auto Roger / Auto Mihawk
				-- every 0.5s: nothing on -> idle, fishing/merchant on -> idle, dead -> wait. roger/mihawk on and their umi window up (or already fighting)
				-- -> go to umi, fight whoever is alive and not done. otherwise juzo -> go to his island, fight, loot wait, death wait
				-- TweenToMob2 and the m1 loops do the fighting, this loop only decides where to be and when a fight starts / ends
				local JUZO_ISLAND = Vector3.new(1770.34546, 36.0756149, -10659.0898)
				local UMI_FALLBACK = Vector3.new(12512.18359375, 6.5736985206604, 2761.882080078125)

				local KEY = "F3.BossMain"
				local loops = getgenv().__TensenFarmLoops
				if not loops then
					loops = {}
					getgenv().__TensenFarmLoops = loops
				end
				local token = {}
				loops[KEY] = token

				local phase = nil -- "Turtle" (to Juzo) | "Turtle_Fight" | "Umi" | "Umi_Fight" | nil

				local function stale()
					return loops[KEY] ~= token
				end

				local function log(msg)
					local f = getgenv().BMLog
					if f then
						pcall(f, msg)
					end
				end

				local function tweenState()
					return getgenv().__TensenTweenState
				end

				local function stopTween()
					return getgenv().StopCurrentTween()
				end

				-- leave whatever phase we were in (stop the tween if one is running)
				local function resetPhase()
					if phase ~= nil then
						phase = nil
						if tweenState().Enabled then
							stopTween()
						end
					end
				end

				-- switch to a travel/fight phase: stop a running tween the first time
				local function enterPhase(name)
					if phase ~= name then
						if tweenState().Enabled then
							stopTween()
						end
						phase = name
					end
				end

				-- loot wait after a boss dies (BossLootDwell, default 8s). BossLootDwelling tells the other loops to stay put
				local function lootDwell()
					getgenv().BossLootDwelling = true
					local dwell = getgenv().BossLootDwell or 8
					task.wait(dwell)
					getgenv().BossLootDwelling = false
				end

				local function step()
					local state = getgenv().__TensenBossState

					if not (getgenv().AutoJuzoBoss or getgenv().AutoRogerBoss or getgenv().AutoMihawkBoss) then
						resetPhase()
						task.wait(0.5)
						return
					end
					if getgenv().AutoFishing or getgenv().AutoMerchant then
						resetPhase()
						task.wait(1)
						return
					end

					local player = game:GetService("Players").LocalPlayer
					local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
					local humanoid = player.Character and player.Character:FindFirstChild("Humanoid")
					if not root or not humanoid or humanoid.Health <= 0 then
						task.wait(1)
						return
					end

					local npcs = workspace:FindFirstChild("NPCs")
					if not npcs then
						return
					end

					-- roger / mihawk first while their window is up or we're already on one
					local umiMode = (getgenv().AutoRogerBoss or getgenv().AutoMihawkBoss) and (getgenv().umiBossComingUp() or getgenv().UmiBossEngaged)
					local umiPos = getgenv().UmiInstantCF and getgenv().UmiInstantCF.Position or UMI_FALLBACK

					if umiMode then
						local umiDist = (root.Position - umiPos).Magnitude
						if umiDist > 150 then
							-- not at Umi yet: travel
							state.engagedAt = nil
							enterPhase("Umi")
							if not tweenState().Enabled then
								getgenv().TweenToUmiForRogerandMihawk()
							end
							return
						end

						-- at Umi
						if not state.engagedAt then
							state.engagedAt = tick()
						end
						local _, _, mihawkWindowOpen = getgenv().MihawkSchedule()
						local _, _, rogerWindowOpen = getgenv().RogerSchedule()
						local mihawkTarget = getgenv().AutoMihawkBoss and not state.mihawkDone and getgenv().npcAlive("Hawk Eye")
						local rogerTarget = getgenv().AutoRogerBoss and not state.rogerDone and getgenv().npcAlive("Roger")

						-- window open but the boss never showed up within 120s of arriving -> counts as done
						local mihawkExpired = getgenv().AutoMihawkBoss and mihawkWindowOpen and not mihawkTarget and state.engagedAt and tick() - state.engagedAt >= 120
						if mihawkExpired then
							state.mihawkDone = true
							state.engagedAt = nil
						end
						local rogerExpired = getgenv().AutoRogerBoss and rogerWindowOpen and not rogerTarget and state.engagedAt and tick() - state.engagedAt >= 120
						if rogerExpired then
							state.rogerDone = true
							state.engagedAt = nil
						end

						if mihawkTarget then
							-- ---- Mihawk ("Hawk Eye")
							getgenv().UmiBossEngaged = true
							if phase ~= "Umi_Fight" and tweenState().Enabled then
								stopTween()
							end
							getgenv().bossAutoEquip("Mihawk")
							local tweenToMob = getgenv().TweenToMob2
							local cfg = {MobName = "Hawk Eye", BossKey = "Mihawk", Raycast = false}
							cfg.Speed = getgenv().TweenSpeedAutoBoss or 70
							cfg.Offset = Vector3.new(0, 10, 0)
							cfg.Container = npcs
							tweenToMob(cfg)
							local fightOver
							repeat
								task.wait(0.15)
								getgenv().bossAutoEquip("Mihawk")
								local hawkEye = npcs:FindFirstChild("Hawk Eye")
								if hawkEye then
									hawkEye = getgenv().isHawkEyeCasting(hawkEye)
								end
								if hawkEye then
									getgenv().mihawkDodge()
								end
								fightOver = not tweenState().Enabled or not getgenv().AutoMihawkBoss or not getgenv().npcAlive("Hawk Eye")
							until fightOver or stale()
							if stale() then
								return
							end
							local bossDown = not getgenv().npcAlive("Hawk Eye")
							stopTween()
							state.mihawkDone = true
							state.engagedAt = nil
							getgenv().UmiBossEngaged = false
							if not getgenv().AutoMihawkBoss then
								phase = nil
							else
								if bossDown then
									lootDwell()
								end
								phase = "Umi_Fight"
							end
						elseif rogerTarget then
							-- ---- Roger
							getgenv().UmiBossEngaged = true
							if phase ~= "Umi_Fight" and tweenState().Enabled then
								stopTween()
							end
							getgenv().bossAutoEquip("Roger")
							local tweenToMob = getgenv().TweenToMob2
							local cfg = {MobName = "Roger", BossKey = "Roger", Raycast = false}
							cfg.Speed = getgenv().TweenSpeedAutoBoss or 70
							cfg.Offset = Vector3.new(0, getgenv().BossHoverOffsetY or 10, 0)
							cfg.BehindDistance = getgenv().BossBehindDist or 0
							cfg.Container = npcs
							tweenToMob(cfg)
							local fightOver
							repeat
								task.wait(0.5)
								getgenv().bossAutoEquip("Roger")
								fightOver = not tweenState().Enabled or not getgenv().AutoRogerBoss or not getgenv().npcAlive("Roger")
							until fightOver or stale()
							if stale() then
								return
							end
							local bossDown = not getgenv().npcAlive("Roger")
							stopTween()
							state.rogerDone = true
							state.engagedAt = nil
							getgenv().UmiBossEngaged = false
							if not getgenv().AutoRogerBoss then
								phase = nil
							else
								if bossDown then
									lootDwell()
								end
								phase = "Umi_Fight"
							end
						else
							-- nobody to fight right now
							if not getgenv().umiBossComingUp() then
								-- window over (or never wanted): release the Umi lock
								state.engagedAt = nil
								getgenv().UmiBossEngaged = false
								resetPhase()
							else
								enterPhase("Umi")
								if not tweenState().Enabled and umiDist > 15 then
									getgenv().TweenToUmiForRogerandMihawk()
								end
							end
						end
						return
					end

					-- ---- Juzo
					if not getgenv().AutoJuzoBoss then
						resetPhase()
						return
					end
					state.engagedAt = nil
					local juzoDist = (root.Position - JUZO_ISLAND).Magnitude
					if juzoDist > 150 then
						enterPhase("Turtle")
						if not tweenState().Enabled then
							getgenv().TweenToJuzoEntrance()
						end
						return
					end
					if not getgenv().npcAlive("Juzo the Diamondback") then
						-- at the island, waiting for him to spawn
						enterPhase("Turtle")
						if not tweenState().Enabled and juzoDist > 15 then
							getgenv().TweenToJuzoEntrance()
						end
						return
					end

					-- he is up: fight
					if phase ~= "Turtle_Fight" and tweenState().Enabled then
						stopTween()
					end
					getgenv().bossAutoEquip("Juzo")
					getgenv().JuzoFighting = true
					local diedMidFight = false
					while true do
						local fighting = getgenv().AutoJuzoBoss and getgenv().npcAlive("Juzo the Diamondback")
						if fighting then
							local myHumanoid = player.Character and player.Character:FindFirstChild("Humanoid")
							if not (not myHumanoid or myHumanoid.Health <= 0) then
								if not tweenState().Enabled then
									local tweenToMob = getgenv().TweenToMob2
									local cfg = {MobName = "Juzo the Diamondback", BossKey = "Juzo", Raycast = true}
									cfg.Speed = getgenv().TweenSpeedAutoBoss or 70
									cfg.Offset = Vector3.new(0, getgenv().BossHoverOffsetY or 9.5, 0)
									cfg.BehindDistance = getgenv().BossBehindDist or 0
									cfg.TeleportDistance = getgenv().BossTeleportDistance or 20
									cfg.MaxTime = getgenv().BossFightTweenMaxTime
									cfg.Container = npcs
									tweenToMob(cfg)
								end
								getgenv().bossAutoEquip("Juzo")
								task.wait(0.5)
								if stale() then
									getgenv().JuzoFighting = false
									return
								end
								continue
							end
							diedMidFight = true
						end
						break
					end

					getgenv().JuzoFighting = false
					local bossDown = not getgenv().npcAlive("Juzo the Diamondback")
					stopTween()
					if not getgenv().AutoJuzoBoss then
						phase = nil
						return
					end
					if diedMidFight then
						-- we died: wait for the respawn (no loot dwell), then regroup
						getgenv().BossDeaths = (getgenv().BossDeaths or 0) + 1
						log(string.format("[Juzo] we died mid fight (%d this session) - waiting for the respawn, no loot dwell", getgenv().BossDeaths))
						local diedAt = tick()
						local respawned
						repeat
							task.wait(0.5)
							local myHumanoid = player.Character and player.Character:FindFirstChild("Humanoid")
							local myRoot = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
							respawned = myHumanoid and myRoot
							if not myHumanoid then
								respawned = myHumanoid
							end
							if respawned then
								respawned = myHumanoid.Health > 0
							end
							if not respawned then
								respawned = not getgenv().AutoJuzoBoss
							end
							if not respawned then
								local waited = tick() - diedAt
								respawned = waited > (getgenv().BossRespawnWait or 30)
							end
						until respawned or stale()
						if stale() then
							return
						end
						if not getgenv().AutoJuzoBoss then
							phase = nil
						else
							task.wait(getgenv().BossRegroupWait or 2)
							getgenv().bossAutoEquip("Juzo")
							phase = nil
						end
					else
						if bossDown then
							lootDwell()
						end
						phase = "Turtle_Fight"
					end
				end

				task.spawn(function()
					task.wait()
					while task.wait(0.5) do
						if stale() then
							break
						end
						local ok, err = pcall(step)
						if not ok then
							getgenv().JuzoFighting = false
							if os.clock() - (getgenv().__F3LastBossErr or 0) > 10 then
								getgenv().__F3LastBossErr = os.clock()
								log("[F3] boss loop step failed: " .. tostring(err))
							end
						end
					end
				end)
			end

			-- juzo re-tween
			do
				-- keeps the juzo chase tween going. does nothing unless getgenv().BossReTween is set (nothing sets it by default)
				-- once a second while JuzoFighting: juzo alive, we're alive and the tween is idle (or BossReTweenAlways) -> restart the chase with the main loop's settings
				local KEY = "F3.BossReTween"
				local loops = getgenv().__TensenFarmLoops
				if not loops then
					loops = {}
					getgenv().__TensenFarmLoops = loops
				end
				local token = {}
				loops[KEY] = token

				task.spawn(function()
					task.wait()
					while task.wait(1) do
						if loops[KEY] ~= token then
							break
						end
						pcall(function()
							if not getgenv().JuzoFighting then
								return
							end
							if not getgenv().BossReTween then
								return
							end
							local npcs = workspace:FindFirstChild("NPCs")
							if not npcs then
								return
							end
							local character = game:GetService("Players").LocalPlayer.Character
							local humanoid = character and character:FindFirstChild("Humanoid")
							if not (humanoid and not (humanoid.Health <= 0)) then
								return
							end
							if not (getgenv().npcAlive("Juzo the Diamondback") and not (getgenv().BossReTweenAlways ~= true and getgenv().__TensenTweenState.Enabled)) then
								return
							end

							getgenv().BossReTweens = (getgenv().BossReTweens or 0) + 1
							getgenv().StopCurrentTween()
							getgenv().TweenToMob2({
								MobName = "Juzo the Diamondback",
								BossKey = "Juzo",
								Raycast = true,
								Speed = getgenv().TweenSpeedAutoBoss or 70,
								Offset = Vector3.new(0, getgenv().BossHoverOffsetY or 9.5, 0),
								BehindDistance = getgenv().BossBehindDist or 0,
								TeleportDistance = getgenv().BossTeleportDistance or 20,
								MaxTime = getgenv().BossFightTweenMaxTime,
								Container = npcs,
							})
						end)
					end
				end)
			end

			-- juzo fight helpers
			do
				-- two threads, only active while getgenv().JuzoFighting
				--   F3.JuzoBackstep  taps S every frame (down, 0.1s, up)
				--   F3.BossAutoBlock BossAutoBlock (default false): hold block while juzo plays an attack anim, max 5s
				local loops = getgenv().__TensenFarmLoops
				if not loops then
					loops = {}
					getgenv().__TensenFarmLoops = loops
				end

				-- key press through VirtualInputManager
				local function sendKey(down, keyCode)
					pcall(function()
						game:GetService("VirtualInputManager"):SendKeyEvent(down, keyCode, false, game)
					end)
				end

				-- juzo alive and playing an Action anim (over 0.4s long, weight over 0.1)
				local function juzoAttacking()
					local npcs = workspace:FindFirstChild("NPCs")
					local juzo = npcs and npcs:FindFirstChild("Juzo the Diamondback")
					if not juzo then
						return false
					end
					local humanoid = juzo:FindFirstChildOfClass("Humanoid")
					if not humanoid or humanoid.Health <= 0 then
						return false
					end
					local animator = humanoid:FindFirstChildOfClass("Animator")
					if not animator then
						return false
					end
					for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
						if (track.Priority == Enum.AnimationPriority.Action or track.Priority == Enum.AnimationPriority.Action2 or track.Priority == Enum.AnimationPriority.Action3 or track.Priority == Enum.AnimationPriority.Action4) and track.Length > 0.4 and track.WeightCurrent > 0.1 then
							return true
						end
					end
					return false
				end
				getgenv().juzoAttacking = juzoAttacking

				do
					local KEY = "F3.JuzoBackstep"
					local token = {}
					loops[KEY] = token
					task.spawn(function()
						task.wait()
						while task.wait() do
							if loops[KEY] ~= token then
								break
							end
							if getgenv().JuzoFighting then
								sendKey(true, Enum.KeyCode.S)
								task.wait(0.1)
								sendKey(false, Enum.KeyCode.S)
							end
						end
					end)
				end

				local KEY = "F3.BossAutoBlock"
				local token = {}
				loops[KEY] = token
				-- not sure about this one: the press/release calls look like sendKey with a fixed key. F is block in gpo, BossBlockKey (an Enum.KeyCode) overrides it
				local function blockKey()
					return getgenv().BossBlockKey or Enum.KeyCode.F
				end
				task.spawn(function()
					task.wait()
					while task.wait(0.1) do
						if loops[KEY] ~= token then
							break
						end
						if not getgenv().JuzoFighting then
							continue
						end
						if not getgenv().BossAutoBlock then
							continue
						end
						if not juzoAttacking() then
							continue
						end
						sendKey(true, blockKey())
						local pressedAt = tick()
						repeat
							task.wait()
						until not (juzoAttacking() and not (tick() - pressedAt > 5)) or loops[KEY] ~= token
						sendKey(false, blockKey())
					end
				end)
			end

			-- mihawk dodge
			do
				-- hawk eye dodge
				--   isHawkEyeCasting(model)  child named yoru/slash/stance/slice/barrage, or an Action anim (> 0.4s, weight > 0.1)
				--   mihawkDodge()            dash 15 up / 18 behind hawk eye (every 0.6s max, within 120 studs, auto mihawk on)
				--   mihawkWatchChild(child)  a new child with yoru/giant/slice/slash/thousand in the name triggers the dodge
				--   F3.MihawkWatch           the hookup for mihawkWatchChild wasn't in the dump, this thread does it (existing children, then ChildAdded)
				--                            while auto mihawk is on. MihawkChildDodge = false turns it off
				local loops = getgenv().__TensenFarmLoops
				if not loops then
					loops = {}
					getgenv().__TensenFarmLoops = loops
				end

				getgenv().isHawkEyeCasting = function(instance)
					if not instance then
						return false
					end
					for _, child in ipairs(instance:GetChildren()) do
						local name = child.Name:lower()
						if name:find("yoru") or name:find("slash") or name:find("stance") or name:find("slice") or name:find("barrage") then
							return true
						end
					end
					local humanoid = instance:FindFirstChildOfClass("Humanoid")
					local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
					if animator then
						for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
							if (track.Priority == Enum.AnimationPriority.Action or track.Priority == Enum.AnimationPriority.Action2 or track.Priority == Enum.AnimationPriority.Action3 or track.Priority == Enum.AnimationPriority.Action4) and track.Length > 0.4 and track.WeightCurrent > 0.1 then
								return true
							end
						end
					end
					return false
				end

				local lastDodge = 0
				getgenv().mihawkDodge = function()
					if not getgenv().AutoMihawkBoss then
						return
					end
					if tick() - lastDodge < 0.6 then
						return
					end
					local player = game:GetService("Players").LocalPlayer
					local character = player.Character
					local root = character and character:FindFirstChild("HumanoidRootPart")
					local humanoid = character and character:FindFirstChild("Humanoid")
					if not root or not humanoid or humanoid.Health <= 0 then
						return
					end
					local npcs = workspace:FindFirstChild("NPCs")
					local hawkEye = npcs and (npcs:FindFirstChild("Hawk Eye") or npcs:FindFirstChild("Mihawk"))
					local hawkRoot = hawkEye and (hawkEye:FindFirstChild("HumanoidRootPart") or hawkEye.PrimaryPart)
					if not (hawkRoot and (hawkRoot.Position - root.Position).Magnitude <= 120) then
						return
					end

					lastDodge = tick()
					getgenv().HawkEyeDodging = tick()
					local target = hawkRoot.CFrame * CFrame.new(0, 15, 18)
					local events = game:GetService("ReplicatedStorage"):FindFirstChild("Events")
					local takestam = events and events:FindFirstChild("takestam")
					if takestam then
						takestam:FireServer(0.505, "dash", target)
					end
					root.CFrame = target
					root.AssemblyLinearVelocity = Vector3.zero
				end

				getgenv().mihawkWatchChild = function(child)
					if not getgenv().AutoMihawkBoss then
						return
					end
					local name = child and child.Name
					if not name then
						return
					end
					local lowered = name:lower()
					if lowered:find("yoru") or lowered:find("giant") or lowered:find("slice") or lowered:find("slash") or lowered:find("thousand") then
						getgenv().mihawkDodge()
					end
				end

				local KEY = "F3.MihawkWatch"
				local token = {}
				loops[KEY] = token
				local watched = nil
				local connection = nil
				task.spawn(function()
					task.wait()
					while task.wait(1) do
						if loops[KEY] ~= token then
							if connection then
								pcall(function()
									connection:Disconnect()
								end)
							end
							break
						end
						if not (getgenv().AutoMihawkBoss and getgenv().MihawkChildDodge ~= false) then
							continue
						end

						local npcs = workspace:FindFirstChild("NPCs")
						local hawkEye = npcs and (npcs:FindFirstChild("Hawk Eye") or npcs:FindFirstChild("Mihawk"))
						if hawkEye == watched then
							continue
						end

						if connection then
							pcall(function()
								connection:Disconnect()
							end)
							connection = nil
						end
						watched = hawkEye
						if hawkEye then
							for _, child in ipairs(hawkEye:GetChildren()) do
								getgenv().mihawkWatchChild(child)
							end
							connection = hawkEye.ChildAdded:Connect(function(child)
								getgenv().mihawkWatchChild(child)
							end)
						end
					end
				end)
			end

			-- boss status text
			do
				-- BossStatusText(boss), boss = "Juzo" | "Mihawk" | "Roger". returns the line shown in each boss tab's Status paragraph ("off" when the toggle is off)

				-- uses the shared done flags and schedules from boss state, so the farm loop's rogerDone / mihawkDone show up here. this definition is the one that sticks

				local Players = game:GetService("Players")
				local localPlayer = Players.LocalPlayer -- only used as .Character

				-- same flags and schedule functions the boss farm loop uses
				local function state()
					return getgenv().__TensenBossState
				end
				local function umiBossComingUp()
					return getgenv().umiBossComingUp()
				end
				local function rogerSchedule()
					return getgenv().RogerSchedule()
				end
				local function mihawkSchedule()
					return getgenv().MihawkSchedule()
				end

				-- m:ss
				local function clock(seconds)
					local total = math.max(0, math.floor(seconds))
					return string.format("%d:%02d", math.floor(total / 60), total % 60)
				end

				getgenv().BossStatusText = function(boss)
					if not (boss == "Juzo" and getgenv().AutoJuzoBoss or boss == "Roger" and getgenv().AutoRogerBoss or boss == "Mihawk" and getgenv().AutoMihawkBoss) then
						return "off"
					end

					if game.PlaceId ~= 7465136166 then
						return "only works in Second Sea"
					end

					if getgenv().BossFarmDisabled then
						return "held off - BossFarmDisabled is set"
					end

					local paused = getgenv().AutoFishing or getgenv().AutoMerchant

					if paused then
						return "paused - Auto Fishing or Auto Merchant is on"
					end

					local label = boss == "Juzo" and "Juzo" or boss == "Roger" and "Roger" or "Mihawk"
					local npcName = boss == "Juzo" and "Juzo the Diamondback" or boss == "Roger" and "Roger" or "Hawk Eye"
					local character = localPlayer.Character
					local rootPart = character and character:FindFirstChild("HumanoidRootPart")
					local npcs = workspace:FindFirstChild("NPCs")
					local bossModel = npcs and npcs:FindFirstChild(npcName)
					local bossHumanoid = bossModel and bossModel:FindFirstChildOfClass("Humanoid")
					local bossRoot = bossModel and (bossModel:FindFirstChild("HumanoidRootPart") or bossModel.PrimaryPart)
					local bossAlive = bossHumanoid and bossRoot and bossHumanoid.Health > 0

					-- "fighting ..." line
					local function fightingLine()
						local studs = rootPart and (rootPart.Position - bossRoot.Position).Magnitude or -1
						local blocking = getgenv().bossTargetBlocking and getgenv().bossTargetBlocking(bossModel)

						-- not sure if the %s name should be npcName or `boss`, went with npcName. only affects the text
						return string.format(
							"fighting %s - %d studs away - HP %d/%d%s",
							npcName,
							math.floor(studs),
							math.floor(bossHumanoid.Health),
							math.floor(bossHumanoid.MaxHealth),
							blocking and (getgenv()[label .. "FeintOnBlock"] ~= false and " - blocking so fake m1" or " - blocking") or ""
						)
					end

					if boss == "Juzo" then
						if bossAlive and getgenv().JuzoFighting then
							return fightingLine()
						end

						if getgenv().BossLootDwelling and not bossAlive then
							return "Juzo is down - picking up the loot"
						end

						if (getgenv().AutoRogerBoss or getgenv().AutoMihawkBoss) and (umiBossComingUp() or getgenv().UmiBossEngaged) then
							return "waiting - Roger/Mihawk is up first"
						end

						local studs

						if rootPart then
							studs = (rootPart.Position - Vector3.new(1770.34546, 36.0756149, -10659.0898)).Magnitude
						end

						studs = studs or 0

						if studs > 150 then
							return string.format("heading to Juzo's island (%d studs)", math.floor(studs))
						end

						return "at Juzo's island - waiting for him to spawn"
					end

					local untilOpen, intoCycle, windowOpen, done

					if boss == "Roger" then
						untilOpen, intoCycle, windowOpen = rogerSchedule()
						done = state().rogerDone
					else
						untilOpen, intoCycle, windowOpen = mihawkSchedule()
						done = state().mihawkDone
					end

					if bossAlive and getgenv().UmiBossEngaged then
						return fightingLine()
					end

					if getgenv().BossLootDwelling and not bossAlive then
						return label .. " is down - picking up the loot"
					end

					local studs

					if rootPart then
						studs = (rootPart.Position - Vector3.new(12642.7695, 144.162933, 2898.39746)).Magnitude
					end

					studs = studs or 0

					if windowOpen then
						if done then
							return string.format("%s is done this cycle - next spawn in %s", label, clock(boss == "Roger" and 5400 - intoCycle or 7200 - intoCycle))
						end

						if studs > 150 then
							return string.format("%s is up - heading to Umi (%d studs)", label, math.floor(studs))
						end

						return string.format("at Umi - waiting for %s (window closes in %s)", label, clock(900 - intoCycle))
					end

					if untilOpen <= 180 then
						if studs > 150 then
							return string.format("%s spawns in %s - heading to Umi (%d studs)", label, clock(untilOpen), math.floor(studs))
						end

						return string.format("at Umi - %s spawns in %s", label, clock(untilOpen))
					end

					return string.format("waiting - %s spawns in %s", label, clock(untilOpen))
				end
			end

			-- scroll helpers
			do
				-- helpers for "Auto Get Scroll" (getgenv().AutoWorldScroll, Lvl 325+, First Sea). shared with the loop through getgenv().__TensenF4

				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local HttpService = game:GetService("HttpService")
				local localPlayer = Players.LocalPlayer

				local F4 = getgenv().__TensenF4
				if not F4 then
					F4 = {}
					getgenv().__TensenF4 = F4
				end

				-- first sea place id. same id the status text uses for "First Sea"
				local FIRST_SEA = 3978370137

				function F4.log(message)
					local fn = getgenv().BMLog
					if type(fn) == "function" then
						pcall(fn, message)
					else
						print(message)
					end
				end

				-- Level() = the number in HUD.Main.Bars.Experience.Detail.Level, nil without the hud. only if nobody defined it
				if type(getgenv().Level) ~= "function" then
					getgenv().Level = function()
						local gui = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:FindFirstChild("PlayerGui")
						local hud = gui and gui:FindFirstChild("HUD")
						local main = hud and hud:FindFirstChild("Main")
						local bars = main and main:FindFirstChild("Bars")
						local experience = bars and bars:FindFirstChild("Experience")
						local detail = experience and experience:FindFirstChild("Detail")
						local level = detail and detail:FindFirstChild("Level")
						if not level then
							return nil
						end
						return (tonumber(level.Text:match("%d+")))
					end
				end

				local function currentLevel()
					local fn = getgenv().Level
					if type(fn) ~= "function" then
						return nil
					end
					local ok, value = pcall(fn)
					return ok and value or nil
				end

				-- character with a living humanoid and a root part
				function F4.isAlive()
					local character = localPlayer.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					local root = character and character:FindFirstChild("HumanoidRootPart")
					return (humanoid and humanoid.Health > 0 and root ~= nil and true) or false
				end

				-- world scrolls in the bag. Stats<Name>.Inventory.Inventory is a json string of {item = count}
				local function rawScrollCount()
					local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)
					local inventory = stats and stats:FindFirstChild("Inventory")
					inventory = inventory and inventory:FindFirstChild("Inventory")
					if not inventory then
						return 0
					end
					local value = inventory.Value
					if not value or value == "" then
						return 0
					end
					local ok, result = pcall(function()
						return HttpService:JSONDecode(value)
					end)
					if not ok or type(result) ~= "table" then
						return 0
					end
					return tonumber(result["World Scroll"]) or 0
				end

				-- same count, cached for ScrollCountCache seconds (default 1). starts at -1 / time 0
				local cachedCount, cachedAt = -1, 0
				local function scrollCount()
					if cachedCount >= 0 and tick() - cachedAt < (getgenv().ScrollCountCache or 1) then
						return cachedCount
					end
					local value = rawScrollCount()
					cachedCount = value
					cachedAt = tick()
					return cachedCount
				end
				F4.scrollCount = scrollCount
				if getgenv().WorldScrollCount == nil then
					getgenv().WorldScrollCount = scrollCount
				end

				-- still need a scroll?
				local function scrollNeeded()
					return scrollCount() < (tonumber(getgenv().ScrollWantCount) or 1)
				end
				F4.scrollNeeded = scrollNeeded
				if getgenv().ScrollNeeded == nil then
					getgenv().ScrollNeeded = scrollNeeded
				end

				-- level gate (ScrollMinLevel, default 325, <= 0 turns it off)
				local function levelOk()
					local minLevel = getgenv().ScrollMinLevel or 325
					if minLevel <= 0 then
						return true
					end
					return (currentLevel() or 0) >= minLevel
				end
				F4.levelOk = levelOk

				local function placeOk()
					return game.PlaceId == FIRST_SEA
				end
				F4.placeOk = placeOk

				-- all the checks at once (toggle on, first sea, level, still needed)
				local function scrollEligible()
					return getgenv().AutoWorldScroll == true and placeOk() and levelOk() and scrollNeeded()
				end
				F4.scrollEligible = scrollEligible
				if getgenv().ScrollEligible == nil then
					getgenv().ScrollEligible = scrollEligible
				end

				-- a grab is running and its heartbeat is fresh (ScrollStaleMax, default 10s). the auto farm loop and the fruit storer check this
				local function scrollHoldLive()
					if getgenv().ScrollHold ~= true then
						return false
					end
					if getgenv().GettingScroll ~= true then
						return false
					end
					return tick() - (getgenv().ScrollHeartbeat or 0) < (getgenv().ScrollStaleMax or 10)
				end
				F4.scrollHoldLive = scrollHoldLive
				getgenv().ScrollHoldLive = scrollHoldLive

				-- key held to pick it up (ScrollHoldKey, default LeftAlt)
				local function holdKey()
					local key = getgenv().ScrollHoldKey
					if typeof(key) == "EnumItem" then
						return key
					end
					return Enum.KeyCode.LeftAlt
				end

				-- press / release a key through VirtualInputManager
				local function sendKey(key, down)
					pcall(function()
						game:GetService("VirtualInputManager"):SendKeyEvent(down, key, false, game)
					end)
				end

				-- the world scroll (workspace.Effects["World Scroll"], else workspace["World Scroll"])
				local function findScroll()
					local effects = workspace:FindFirstChild("Effects")
					local worldScroll = effects and effects:FindFirstChild("World Scroll")
					if worldScroll then
						return worldScroll
					end
					return workspace:FindFirstChild("World Scroll")
				end
				F4.findScroll = findScroll

				-- how close you need to be (ScrollRange, default 18, capped by the prompt's MaxActivationDistance)
				local function grabRange(prompt)
					local range = getgenv().ScrollRange or 18
					if prompt then
						pcall(function()
							local maxActivationDistance = prompt.MaxActivationDistance
							if maxActivationDistance and maxActivationDistance > 0 then
								range = math.min(range, maxActivationDistance)
							end
						end)
					end
					return range
				end

				-- the instance's ProximityPrompt (itself or first descendant)
				local function findPrompt(instance)
					if not instance then
						return nil
					end
					if instance:IsA("ProximityPrompt") then
						return instance
					end
					local prompt = nil
					pcall(function()
						prompt = instance:FindFirstChildWhichIsA("ProximityPrompt", true)
					end)
					return prompt
				end

				-- a part to measure against (the instance itself, else its first BasePart descendant)
				local function basePartOf(instance)
					if not instance then
						return nil
					end
					if instance:IsA("BasePart") then
						return instance
					end
					for _, descendant in ipairs(instance:GetDescendants()) do
						if descendant:IsA("BasePart") then
							return descendant
						end
					end
					return nil
				end
				F4.basePartOf = basePartOf

				-- can the scroll be grabbed right now? returns ok, reason, gone
				local function scrollPickable()
					local effects = workspace:FindFirstChild("Effects")
					local worldScroll = effects and effects:FindFirstChild("World Scroll")
					if not worldScroll or not worldScroll.Parent then
						return false, "no scroll in the world", true
					end
					local prompt = worldScroll:FindFirstChild("ProximityPrompt") or findPrompt(worldScroll)
					if not prompt then
						return false, "the scroll has no prompt", false
					end
					local active = true
					pcall(function()
						if prompt.Enabled == false then
							active = false
						end
					end)
					if not active then
						return false, "the prompt is not active yet", false
					end
					local part = basePartOf(worldScroll)
					local character = localPlayer.Character
					local root = character and character:FindFirstChild("HumanoidRootPart")
					if not part or not root then
						return false, "cannot tell how far the scroll is", false
					end
					local distance = (part.Position - root.Position).Magnitude
					if distance > grabRange(prompt) then
						return false, string.format("too far to grab it (%d studs)", math.floor(distance)), false
					end
					return true, nil, false
				end
				F4.scrollPickable = scrollPickable

				-- hold the key on the scroll until the bag count goes up. true if we got one
				local function pickUpScroll()
					local pickable, blockReason = scrollPickable()
					if not pickable then
						getgenv().ScrollBlockReason = blockReason
						return false
					end
					local before = scrollCount()
					local key = holdKey()
					local holdSeconds = tonumber(getgenv().ScrollHoldSeconds) or 5
					getgenv().ScrollBlockReason = "holding ALT to pick it up"
					local tries = getgenv().ScrollFireTries or 12
					for _ = 1, tries do
						if not getgenv().AutoWorldScroll then
							break
						end
						if not F4.isAlive() then
							sendKey(key, false)
							getgenv().ScrollBlockReason = "died before grabbing it"
							return false
						end
						local stillPickable, reason, gone = scrollPickable()
						if not stillPickable then
							sendKey(key, false)
							task.wait(0.5)
							if before < scrollCount() then
								getgenv().ScrollsTaken = (getgenv().ScrollsTaken or 0) + 1
								getgenv().ScrollBlockReason = "got the scroll"
								return true
							end
							getgenv().ScrollBlockReason = gone and "someone else took it" or reason
							return false
						end
						sendKey(key, true)
						local deadline = tick() + holdSeconds
						while true do
							getgenv().ScrollHeartbeat = tick()
							task.wait(0.25)
							if before < scrollCount() then
								break
							end
							if not (tick() >= deadline) and getgenv().AutoWorldScroll and F4.isAlive() then
								continue
							end
							break
						end
						sendKey(key, false)
						if scrollCount() > before then
							getgenv().ScrollsTaken = (getgenv().ScrollsTaken or 0) + 1
							getgenv().ScrollBlockReason = "got the scroll"
							return true
						end
						task.wait(0.25)
					end
					sendKey(key, false)
					getgenv().ScrollFails = (getgenv().ScrollFails or 0) + 1
					getgenv().ScrollBlockReason = "holding ALT gave nothing"
					return false
				end
				F4.pickUpScroll = pickUpScroll

				-- within ScrollCampRange (default 25) of the camp spot WorldScrollCF
				local function atCamp()
					local character = localPlayer.Character
					local root = character and character:FindFirstChild("HumanoidRootPart")
					local campCF = getgenv().WorldScrollCF
					if not root or not campCF then
						return false
					end
					return (campCF.Position - root.Position).Magnitude <= (getgenv().ScrollCampRange or 25)
				end
				F4.atCamp = atCamp

				-- tween onto an instance (stops 4 studs short, tps when within 5). does nothing while another tween runs
				local tweenState = getgenv().__TensenTweenState   -- hub tween state
				local function moveOnto(instance)
					local part = basePartOf(instance)
					if not part then
						return
					end
					local state = tweenState or getgenv().__TensenTweenState
					if state and state.Enabled then
						return
					end
					local tween = getgenv().TweenToCFrame
					if type(tween) ~= "function" then
						return
					end
					pcall(tween, {
						CFrame = CFrame.new(part.Position),
						Speed = getgenv().TweenSpeedMaster or 110,
						StopDistance = 4,
						TeleportOnClose = true,
						TeleportDistance = 5,
					})
				end
				F4.moveOnto = moveOnto

				-- go to the camp spot. WorldScrollCF is set somewhere outside this code
				local function tweenToWorldScroll()
					local tween = getgenv().TweenToCFrame
					if type(tween) ~= "function" or not getgenv().WorldScrollCF then
						return
					end
					tween({
						CFrame = getgenv().WorldScrollCF,
						Speed = getgenv().TweenSpeedMaster or 110,
						StopDistance = 5,
						TeleportOnClose = true,
						TeleportDistance = 5,
					})
				end
				if getgenv().TweenToWorldScroll == nil then
					getgenv().TweenToWorldScroll = tweenToWorldScroll
				end
			end

			-- auto get scroll
			do
				-- "Auto Get Scroll" thread (getgenv().AutoWorldScroll, Lvl 325+, First Sea)
				-- camps the scroll spot, pauses the other farms while waiting (they answer with ScrollAckFarm / ScrollAckFish),
				-- walks onto the scroll as soon as it spawns and holds ALT until the bag count goes up
				-- the loop stops once the scroll is in the bag. ScrollHoldLive is only for the other loops

				local F4 = getgenv().__TensenF4
				local loops = getgenv().__TensenFarmLoops
				if not loops then
					loops = {}
					getgenv().__TensenFarmLoops = loops
				end

				local tweenState = getgenv().__TensenTweenState   -- hub tween state
				local stopTween = getgenv().StopCurrentTween   -- hub tween stop

				local function tween()
					return tweenState or getgenv().__TensenTweenState
				end

				local function stop()
					local fn = stopTween or getgenv().StopCurrentTween
					if type(fn) == "function" then
						pcall(fn)
					end
				end

				-- added: WorldScrollCF isn't in the code. until it's set, remember where the first scroll showed up so camping has a spot.
				-- getgenv().ScrollLearnSpot = false turns it off
				local function learnSpot(scroll)
					if getgenv().WorldScrollCF ~= nil or getgenv().ScrollLearnSpot == false then
						return
					end
					local part = F4.basePartOf(scroll)
					if part then
						getgenv().WorldScrollCF = CFrame.new(part.Position)
						F4.log("[Scroll] no camp spot recorded - using the place the scroll spawned at: " .. tostring(part.Position))
					end
				end

				local token = {}
				loops["F4.AutoScroll"] = token

				task.spawn(function()
					task.wait()
					while task.wait(getgenv().ScrollRate or 2) do
						if loops["F4.AutoScroll"] ~= token then
							break
						end
						local ok, err = pcall(function()
							if getgenv().GettingScroll then
								return
							end

							if not getgenv().AutoWorldScroll then
								return
							end

							if not F4.placeOk() then
								return
							end

							if not F4.levelOk() then
								getgenv().ScrollBlockReason = "level is too low"
								return
							elseif not F4.scrollNeeded() then
								getgenv().ScrollBlockReason = "you already have a scroll"
								return
							end

							if not F4.isAlive() then
								return
							end

							getgenv().ScrollHeartbeat = tick()
							getgenv().GettingScroll = true
							getgenv().ScrollHold = true
							getgenv().ScrollCampStart = tick()
							getgenv().ScrollBlockReason = "pausing the other farms"
							local waitStart = tick()

							-- wait for the running farms to ack the pause (or ScrollAckWait / 15s, or the grab isn't wanted anymore)
							repeat
								getgenv().ScrollHeartbeat = tick()
								task.wait(0.1)
							until ((not getgenv().autofarm or getgenv().ScrollAckFarm) and (not getgenv().AutoFishing or getgenv().ScrollAckFish) or tick() - waitStart > (getgenv().ScrollAckWait or 15))
								or not F4.scrollEligible()

							if tween().Enabled then
								stop()
							end

							if getgenv().EndFishingSession then
								pcall(getgenv().EndFishingSession)
							end

							task.wait(0.2)

							while F4.scrollEligible() do
								getgenv().ScrollHeartbeat = tick()

								if not F4.isAlive() then
									getgenv().ScrollBlockReason = "waiting to respawn"

									if tween().Enabled then
										stop()
									end

									task.wait(1)
									continue
								end

								local scroll = F4.findScroll()

								if scroll and F4.scrollPickable() then
									if tween().Enabled then
										stop()
									end

									learnSpot(scroll)
									pcall(F4.pickUpScroll)
									task.wait(getgenv().ScrollCampRate or 0.5)
									continue
								elseif scroll then
									getgenv().ScrollBlockReason = "a scroll is out - moving onto it"
									learnSpot(scroll)
									F4.moveOnto(scroll)
									task.wait(getgenv().ScrollCampRate or 0.5)
									continue
								end

								if F4.atCamp() then
									getgenv().ScrollBlockReason = "camping the spot - no scroll yet"
									task.wait(getgenv().ScrollCampRate or 0.5)
									continue
								end

								getgenv().ScrollBlockReason = "heading to the scroll spot"

								if not tween().Enabled then
									pcall(getgenv().TweenToWorldScroll)
								end

								local travelStart = tick()

								repeat
									getgenv().ScrollHeartbeat = tick()
									task.wait(0.25)
								until not (not (F4.atCamp() or F4.findScroll()) and tween().Enabled and F4.isAlive() and not (tick() - travelStart > (getgenv().ScrollTravelMax or 45)) and F4.scrollEligible())

								if F4.atCamp() and tween().Enabled then
									stop()
								end

								task.wait(0.2)
							end

							if tween().Enabled then
								stop()
							end

							if not F4.scrollNeeded() then
								getgenv().ScrollBlockReason = "got the scroll - back to farming"
							end

							getgenv().GettingScroll = false
							getgenv().ScrollHold = false
							getgenv().ScrollHeartbeat = 0
							getgenv().AlreadyTweenFishing = false
						end)

						if not ok then
							-- a failed step shouldn't leave the other farms paused
							getgenv().GettingScroll = false
							getgenv().ScrollHold = false
							getgenv().ScrollHeartbeat = 0
							if getgenv().BMLog and os.clock() - (getgenv().__F4LastLoopErr or 0) > 10 then
								getgenv().__F4LastLoopErr = os.clock()
								getgenv().BMLog("[F4] auto scroll step failed: " .. tostring(err))
							end
						end
					end
				end)
			end

			-- haki helpers
			do
				-- helpers for "Auto Haki" (getgenv().haki, Lvl 80+ and 25k peli: the yeti quest "Road to Armament" that unlocks buso)
				-- shared with the haki loop through getgenv().__TensenF4

				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local localPlayer = Players.LocalPlayer

				local F4 = getgenv().__TensenF4
				if not F4 then
					F4 = {}
					getgenv().__TensenF4 = F4
				end
				if not F4.log then
					function F4.log(message)
						local fn = getgenv().BMLog
						if type(fn) == "function" then
							pcall(fn, message)
						else
							print(message)
						end
					end
				end

				local function playerGui()
					return localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:FindFirstChild("PlayerGui")
				end

				-- does the player have buso? checks Stats<Name>.Skills / Stats<Name>.Stats, then the character, then the hud
				-- the hud is looked up in PlayerGui first, then in LocalPlayer
				local function hasBusoHaki()
					local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)

					if stats then
						local skills = stats:FindFirstChild("Skills")

						if skills then
							for _, name in ipairs({ "busoHaki", "BusoHaki", "buso", "Buso", "haki", "Haki", "busoshokuHaki", "BusoshokuHaki" }) do
								local skill = skills:FindFirstChild(name)

								if skill then
									skill = skill.Value == true or skill.Value == 1 or type(skill.Value) == "number" and skill.Value > 0
								end

								if skill then
									return true
								end
							end
						end

						local inner = stats:FindFirstChild("Stats")

						if inner then
							local buso = inner:FindFirstChild("Buso") or inner:FindFirstChild("buso")

							if buso then
								if buso.Value == true then
									buso = true
								elseif type(buso.Value) == "number" then
									buso = buso.Value > 0
								else
									buso = false
								end
							end

							if buso then
								return true
							end

							local mastery = inner:FindFirstChild("BusoMastery") or inner:FindFirstChild("busoMastery")

							if mastery and type(mastery.Value) == "number" and mastery.Value > 0 then
								return true
							end
						end
					end

					local character = localPlayer.Character

					if character then
						if character:FindFirstChild(localPlayer.Name .. "Buso") or character:FindFirstChild("Buso") or character:FindFirstChild("Haki") then
							return true
						end

						if character:GetAttribute("Buso") == true or character:GetAttribute("Haki") == true then
							return true
						end
					end

					local hud = playerGui() and playerGui():FindFirstChild("HUD")
					hud = hud or localPlayer:FindFirstChild("HUD")

					if not hud then
						return false
					end

					local main = hud:FindFirstChild("Main")

					if main then
						for _, descendant in ipairs(main:GetDescendants()) do
							if descendant:IsA("GuiObject") and (descendant.Name == "Buso" or descendant.Name == "busoHaki" or descendant.Name == "Haki") then
								return true
							end
						end
					end

					return false
				end
				F4.hasBusoHaki = hasBusoHaki
				if getgenv().hasBusoHaki == nil then
					getgenv().hasBusoHaki = hasBusoHaki
				end

				-- peli on the hud, 0 if the label is missing
				local function getPeli()
					local gui = playerGui()
					local hud = gui and gui:FindFirstChild("HUD")
					local main = hud and hud:FindFirstChild("Main")
					local peli = main and main:FindFirstChild("Peli")
					local label = peli and peli:FindFirstChild("TextLabel")

					if not label then
						return 0
					end

					local digits = label.Text:gsub("[^%d]", "")
					return tonumber(digits) or 0
				end
				F4.getPeli = getPeli
				if getgenv().getPeli == nil then
					getgenv().getPeli = getPeli
				end

				-- quest panel up and its Progress text mentions the yeti (FarmStatusText reads genv.IsOnYetiQuest)
				local function isOnYetiQuest()
					local gui = playerGui()
					local quest = (gui and gui:FindFirstChild("Quest", true)) or localPlayer:FindFirstChild("Quest", true)

					if not quest then
						return false
					end

					local main = quest:FindFirstChild("Main", true)

					if not main or not main.Visible then
						return false
					end

					local info = quest:FindFirstChild("Info", true)
					local progress = info and info:FindFirstChild("Progress", true)
					return string.find(string.lower(progress and progress.Text or ""), "yeti") ~= nil
				end
				F4.isOnYetiQuest = isOnYetiQuest
				if getgenv().IsOnYetiQuest == nil then
					getgenv().IsOnYetiQuest = isOnYetiQuest
				end

				-- before a haki trip, make sure SpeedBypass isn't blocking tweens. false (and HakiBypassBlocks++) if it didn't clear
				-- FishmanWaitBypass / FishmanFaceMouseOff come from the fishman route, without them it just returns true
				getgenv().HakiTravelReady = function(label)
					if getgenv().HakiClearBypass == false then
						return true
					end

					if getgenv().FishmanFaceMouseOff then
						pcall(getgenv().FishmanFaceMouseOff)
					end

					local ready = true

					if getgenv().FishmanWaitBypass then
						ready = getgenv().FishmanWaitBypass(getgenv().HakiTravelWanted) == true
					end

					if not ready then
						getgenv().HakiBypassBlocks = (getgenv().HakiBypassBlocks or 0) + 1

						if getgenv().LogHaki ~= false then
							local bypass = "not set"
							if type(getgenv().yBypassValue) == "function" then
								bypass = tostring(getgenv().yBypassValue())
							end
							F4.log(string.format("[Haki] %s is held up - SpeedBypass reads %s, and every tween is refused outright while it is negative. Waited %ds for it to clear and it did not (x%d).", tostring(label or "travel"), bypass, math.floor(getgenv().FishmanBypassWait or 10), getgenv().HakiBypassBlocks))
						end
					end

					return ready
				end

				-- "inside fishman island" = root Y below this. the real value isn't known, getgenv().FishmanInsideY can set it.
				-- without it the check is skipped (nobody gets sent out of fishman)
				local function insideFishman(root)
					local limit = getgenv().FishmanInsideY
					return root ~= nil and type(limit) == "number" and root.Position.Y < limit
				end
				F4.insideFishman = insideFishman

				local function rootOf()
					local character = localPlayer.Character
					return character and character:FindFirstChild("HumanoidRootPart")
				end

				local function alive()
					local character = localPlayer.Character
					local humanoid = character and character:FindFirstChild("Humanoid")
					return character ~= nil and humanoid ~= nil and humanoid.Health > 0
				end

				-- tween to the spot in front of the yeti, leaves fishman island first if we're in it
				local function tweenToYetiSafePlace()
					local cframe = CFrame.new(-4253.10254, 169.4823, -2957.52173, -0.216795787, 5.73387808e-08, 0.976216972, 7.7749398e-08, 1, -4.14693062e-08, -0.976216972, 6.69099123e-08, -0.216795787)

					if insideFishman(rootOf()) then
						if type(getgenv().TweenToLeaveFishman) == "function" then
							getgenv().TweenToLeaveFishman()
						end

						if not getgenv().haki then
							return
						end

						if not alive() then
							return
						end
					end

					if getgenv().HakiTravelReady then
						getgenv().HakiTravelReady("the trip to the Yeti spot")
					end

					getgenv().TweenToCFrame({
						CFrame = cframe,
						Speed = getgenv().TweenSpeedMaster or 110,
						StopDistance = 5,
						TeleportOnClose = true,
						TeleportDistance = 5,
					})
				end
				if getgenv().TweenToYetiSafePlace == nil then
					getgenv().TweenToYetiSafePlace = tweenToYetiSafePlace
				end

				-- tween to the Road to Armament quest giver
				local function tweenToHaki()
					local cframe = CFrame.new(-4248.22461, 169.4823, -2992.00049, -0.862066627, 6.65524595e-08, -0.506794989, 8.61429186e-08, 1, -1.52102313e-08, 0.506794989, -5.67690286e-08, -0.862066627)

					if insideFishman(rootOf()) then
						if type(getgenv().TweenToLeaveFishman) == "function" then
							getgenv().TweenToLeaveFishman()
						end

						if not getgenv().haki then
							return
						end

						if not alive() then
							return
						end
					end

					if getgenv().HakiTravelReady then
						getgenv().HakiTravelReady("the trip to the haki quest giver")
					end

					getgenv().TweenToCFrame({
						CFrame = cframe,
						Speed = getgenv().TweenSpeedMaster or 110,
						StopDistance = 5,
						TeleportOnClose = true,
						TeleportDistance = 5,
					})
				end
				if getgenv().TweenToHaki == nil then
					getgenv().TweenToHaki = tweenToHaki
				end
			end

			-- auto haki
			do
				-- "Auto Haki" thread (getgenv().haki, First Sea, Lvl 80 + 25k peli). one pass every 0.3s:
				--   haki off              -> wait until it's on
				--   already has buso      -> drop the tween, idle until haki is off or buso is gone
				--   fishing/merchant on   -> wait for them
				--   no yeti quest and (Lv < 80 or peli < 25000) -> let auto farm grind until it's enough or the quest shows up
				--   panel shows another quest -> quit it (remote + the panel's Quit button)
				--   no quest panel        -> walk to the quest giver, talk ("npcChat"), take "Road to Armament"
				--   yeti quest running    -> yeti up: chase it with TweenToMob2 (m1 loops hit). not up: wait at the staging spot

				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local localPlayer = Players.LocalPlayer

				local F4 = getgenv().__TensenF4
				local KEY = "F4.AutoHaki"
				local loops = getgenv().__TensenFarmLoops
				if not loops then
					loops = {}
					getgenv().__TensenFarmLoops = loops
				end

				local tweenState = getgenv().__TensenTweenState   -- hub tween state
				local stopTween = getgenv().StopCurrentTween   -- hub tween stop

				local token = {}
				loops[KEY] = token

				local function stale()
					return loops[KEY] ~= token
				end

				local function tween()
					return tweenState or getgenv().__TensenTweenState
				end

				local function stop()
					local fn = stopTween or getgenv().StopCurrentTween
					if type(fn) == "function" then
						pcall(fn)
					end
				end

				local function hasBuso()
					return F4.hasBusoHaki()
				end

				local function level()
					local fn = getgenv().Level
					if type(fn) ~= "function" then
						return 0
					end
					local ok, value = pcall(fn)
					return ok and value or 0
				end

				local function rootOf()
					local character = localPlayer.Character
					return character and character:FindFirstChild("HumanoidRootPart")
				end

				local function playerAlive()
					local character = localPlayer.Character
					local humanoid = character and character:FindFirstChild("Humanoid")
					return character ~= nil and humanoid ~= nil and humanoid.Health > 0
				end

				-- called once per pass before looking at npcs and before talking to the quest giver. probably the farm weapon equip, skipped if not defined
				local function equipWeapon()
					local fn = getgenv().equipFarmWeapon
					if type(fn) == "function" then
						pcall(fn)
					end
				end

				local function questInvoke(...)
					local args = { ... }
					pcall(function()
						ReplicatedStorage.Events.Quest:InvokeServer(args)
					end)
				end

				local function bypassText()
					if type(getgenv().yBypassValue) == "function" then
						return tostring(getgenv().yBypassValue())
					end
					return "not set"
				end

				-- the two "trip refused" waits (SpeedBypass negative so the tween didn't start): log, wait HakiBypassRetry (default 1s), retry next pass
				local function refusedWait(text)
					F4.log(string.format(text, bypassText(), getgenv().HakiBypassBlocks or 0))
					task.wait(getgenv().HakiBypassRetry or 1)
				end

				local function leaveFishman()
					if type(getgenv().TweenToLeaveFishman) == "function" then
						getgenv().TweenToLeaveFishman()
					end
				end

				-- one pass of the loop. return = next pass
				local function step()
					-- switched off -> wait for it to come back on
					if not getgenv().haki then
						repeat
							task.wait(0.5)
						until getgenv().haki or stale()
						return
					end

					-- already has Buso Haki
					if hasBuso() then
						if tween().Enabled then
							stop()
							tween().Enabled = false
						end

						repeat
							task.wait(0.1)
						until not getgenv().haki or not hasBuso() or stale()
						return
					end

					-- don't fight fishing / the merchant for the character
					if getgenv().AutoFishing then
						repeat
							task.wait()
						until not getgenv().AutoFishing or stale()
					end

					if getgenv().AutoMerchant then
						repeat
							task.wait()
						until not getgenv().AutoMerchant or stale()
					end

					equipWeapon()
					local npCs = workspace:FindFirstChild("NPCs")

					if not npCs then
						return
					end

					-- not on the quest yet -> need Lv 80 and 25k peli first, auto farm gets them
					if not F4.isOnYetiQuest() and ((level() or 0) < 80 or F4.getPeli() < 25000) then
						if getgenv().autofarm then
							local ready
							repeat
								task.wait(0.1)
								ready = not getgenv().autofarm or (level() or 0) >= 80 and F4.getPeli() >= 25000 or F4.isOnYetiQuest()
							until ready or stale()
						end

						return
					end

					-- read the quest panel
					local gui = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:FindFirstChild("PlayerGui")
					local quest = gui and gui:FindFirstChild("Quest", true)

					if not quest then
						return
					end

					local main = quest:FindFirstChild("Main", true)

					if not main then
						return
					end

					local info = quest:FindFirstChild("Info", true)

					if not info then
						task.wait(0.5)
						info = quest:FindFirstChild("Info", true)
					end

					if not info then
						return
					end

					local progress = info:FindFirstChild("Progress", true)

					if not progress then
						return
					end

					local quit = quest:FindFirstChild("Quit", true)
					local visible = main.Visible

					local onYeti = string.find(string.lower(progress.Text or ""), "yeti") ~= nil

					-- panel shows another quest -> quit it (remote, then the button's connections)
					if visible and not onYeti then
						if tween().Enabled then
							stop()
							tween().Enabled = false
						end

						pcall(function()
							ReplicatedStorage:WaitForChild("Events"):WaitForChild("Quest"):InvokeServer({ "quit" })
						end)

						if quit then
							pcall(function()
								for _, signal in ipairs({ quit.Activated, quit.MouseButton1Click, quit.MouseButton1Down }) do
									pcall(function()
										for _, connection in ipairs(getconnections(signal)) do
											connection:Fire()
										end
									end)
								end
							end)
						end

						task.wait(1)
						return
					end

					-- no quest panel -> take the quest
					if not visible then
						if F4.insideFishman(rootOf()) then
							leaveFishman()

							if not getgenv().haki or hasBuso() then
								stop()
								return
							end

							if not playerAlive() then
								return
							end
						end

						equipWeapon()
						tween().Enabled = false
						getgenv().TweenToHaki()

						local refused = not tween().Enabled and getgenv().haki and not hasBuso()

						if refused then
							refusedWait("[Haki] the travel tween was refused - SpeedBypass reads %s, so waiting for it to clear instead of talking to the quest giver from the wrong place (x%d).")
							return
						end

						repeat
							task.wait(0.1)
						until not tween().Enabled or not getgenv().haki or hasBuso() or stale()

						if not getgenv().haki or hasBuso() then
							stop()
							return
						end

						task.wait(2)
						questInvoke("npcChat", true)
						task.wait(0.5)
						questInvoke("takequest", "Road to Armament")
						task.wait(1)
						return
					end

					-- the Yeti quest is running
					if not onYeti then
						return
					end

					if npCs:FindFirstChild("Yeti") then
						-- chase the Yeti
						if tween().Enabled then
							return
						end

						stop()

						if getgenv().HakiTravelReady then
							getgenv().HakiTravelReady("the chase after the Yeti")
						end

						local speed = getgenv().TweenSpeedMaster
						getgenv().TweenToMob2({
							MobName = "Yeti",
							Speed = speed or 70,
							Offset = Vector3.new(0, 10, 2),
							Container = npCs,
						})

						repeat
							task.wait()
						until not tween().Enabled or not getgenv().haki or hasBuso() or not npCs:FindFirstChild("Yeti") or stale()

						if hasBuso() or not getgenv().haki or not npCs:FindFirstChild("Yeti") then
							stop()
						end

						return
					end

					-- yeti not spawned -> wait at the staging spot
					if tween().Enabled then
						stop()
					end

					if F4.insideFishman(rootOf()) then
						leaveFishman()

						if not getgenv().haki or hasBuso() then
							stop()
							return
						end

						if not playerAlive() then
							return
						end
					end

					getgenv().TweenToYetiSafePlace()

					local refused = not tween().Enabled and getgenv().haki and not hasBuso()

					if refused then
						refusedWait("[Haki] the trip to the Yeti spot was refused - SpeedBypass reads %s, so waiting for it to clear instead of standing here (x%d).")
						return
					end

					repeat
						task.wait(0.1)
					until not tween().Enabled or not getgenv().haki or hasBuso() or stale()

					if not getgenv().haki or hasBuso() then
						stop()
						return
					end

					local spawned
					repeat
						task.wait(0.5)
						local yeti = npCs:FindFirstChild("Yeti")
						spawned = yeti or not getgenv().haki or hasBuso()
					until spawned or stale()
				end

				task.spawn(function()
					task.wait()

					while task.wait(0.3) do
						if stale() then
							break
						end

						local ok, err = pcall(step)

						if not ok and getgenv().BMLog and os.clock() - (getgenv().__F4LastLoopErr or 0) > 10 then
							getgenv().__F4LastLoopErr = os.clock()
							getgenv().BMLog("[F4] auto haki step failed: " .. tostring(err))
						end
					end
				end)
			end

			-- kaitun scroll travel
			do
				-- kaitun hop: "Lvl 425 + scroll goes to second sea". first sea, auto farm and auto get scroll on, Lv 425+ with a world scroll
				-- -> getgenv().KaitunTravelSecondSea(), at most once per 30s

				local F4 = getgenv().__TensenF4
				local loops = getgenv().__TensenFarmLoops
				if not loops then
					loops = {}
					getgenv().__TensenFarmLoops = loops
				end

				local token = {}
				loops["F4.KaitunScrollTravel"] = token

				local function ready()
					return type(getgenv().KaitunTravelSecondSea) == "function" and F4.isAlive()
				end

				task.spawn(function()
					task.wait()
					local deadline = 0

					while task.wait(1) do
						if loops["F4.KaitunScrollTravel"] ~= token then
							break
						end

						if game.PlaceId ~= 3978370137 then
							break
						end

						if not (getgenv().autofarm and getgenv().AutoWorldScroll) then
							continue
						end

						local levelFn = getgenv().Level
						local level = type(levelFn) == "function" and levelFn() or 0

						if (level or 0) < 425 or F4.scrollCount() < 1 then
							continue
						end

						if not (ready() and not (os.clock() < deadline)) then
							continue
						end

						deadline = os.clock() + 30
						local ok, result = pcall(function()
							getgenv().KaitunTravelSecondSea()
						end)

						if not ok then
							F4.log("[Kaitun] Second Sea teleport failed; retrying in 30s: " .. tostring(result))
						end
					end
				end)
			end

			-- auto fishing + auto merchant (Fishing tab)
			--   main loop: fishing, merchant trip, shop buying
			--   rod: findRod, hasRod, equipRod, UnequipRod, atFishingSpot
			--   travel: TweenToFishing, TweenToRodShop, tweenToMerchant, TweenToLeaveFishman
			--   session: EndFishingSession, ForceClearFishingSession, fishing Action remote, ReleaseFishingHook, fishDebug, FishingInfo
			--   merchant: MerchantReady, visit done / failed, MerchantShouldKeepGoing, stock id + loops, camera loop, shop gui + buying, marker
			--   bait: current bait
			-- guesses are marked "-- guess:"
			do
				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local HttpService = game:GetService("HttpService")
				local localPlayer = Players.LocalPlayer

				local function spawnLoop(name, body)
					local loops = getgenv().__TensenLoops
					if type(loops) ~= "table" then
						loops = {}
						getgenv().__TensenLoops = loops
					end
					local token = {}
					loops[name] = token
					task.spawn(function()
						task.wait()
						body(function()
							return loops[name] == token
						end)
					end)
				end

				local function log(msg)
					local f = getgenv().BMLog
					if f then
						pcall(f, msg)
					else
						print(msg)
					end
				end

				-- hub objects: tween state, tween stop, the options-table tween function
				local function tweenState()
					return getgenv().__TensenTweenState or { Enabled = false }
				end
				local function stopTween()
					local f = getgenv().StopCurrentTween
					if f then
						pcall(f)
					end
				end
				local warnedTween = false
				local function tweenTo(opts)
					local f = getgenv().TweenToCFrame
					if type(f) ~= "function" then
						if not warnedTween then
							warnedTween = true
							log("[Tensen] getgenv().TweenToCFrame is not exported by the hub - fishing / merchant travel is disabled")
						end
						return
					end
					return f(opts)
				end

				-- the toggle callbacks lost their "stop the tween" line, so the loop does it for its own tweens
				local ownsTween = false

				-- small helpers
				local function describe(v)
					if type(v) == "table" then
						local parts = {}
						for k, x in pairs(v) do
							parts[#parts + 1] = tostring(k) .. "=" .. tostring(x)
							if #parts >= 6 then
								break
							end
						end
						table.sort(parts)
						return "{" .. table.concat(parts, ", ") .. "}"
					end
					return tostring(v)
				end

				local function shortKey(k)
					if k == nil then
						return "nil"
					end
					local s = tostring(k)
					if #s > 10 then
						s = s:sub(1, 10) .. ".."
					end
					return s
				end

				local function toList(value) -- list of names or {name = true}
					local list = {}
					if type(value) == "table" then
						for k, v in pairs(value) do
							if type(k) == "number" and type(v) == "string" then
								table.insert(list, v)
							elseif type(k) == "string" and v == true then
								table.insert(list, k)
							end
						end
					elseif type(value) == "string" then
						table.insert(list, value)
					end
					return list
				end

				local function inventoryData()
					local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)
					local inventory = stats and stats:FindFirstChild("Inventory") and stats.Inventory:FindFirstChild("Inventory")
					if not inventory or not inventory.Value or inventory.Value == "" then
						return nil
					end
					local ok, result = pcall(function()
						return HttpService:JSONDecode(inventory.Value)
					end)
					if ok and type(result) == "table" then
						return result
					end
					return nil
				end

				-- how many `name` the inventory has (status text and the throw-refused log call getgenv().baitCount(name))
				local function baitCount(name)
					local data = inventoryData()
					if not data then
						return 0
					end
					local function amountOf(v)
						if type(v) == "number" then
							return v
						end
						if type(v) == "table" and v.Amount then
							return v.Amount
						end
						return 1
					end
					if data[name] ~= nil then
						return amountOf(data[name])
					end
					local wanted = string.lower((string.gsub(tostring(name), "[%s%-_']", "")))
					for key, v in pairs(data) do
						if string.lower((string.gsub(tostring(key), "[%s%-_']", ""))) == wanted then
							return amountOf(v)
						end
					end
					return 0
				end
				getgenv().baitCount = getgenv().baitCount or baitCount

				local function peli()
					local hud = localPlayer.PlayerGui:FindFirstChild("HUD")
					local main = hud and hud:FindFirstChild("Main")
					local peliFrame = main and main:FindFirstChild("Peli")
					local label = peliFrame and peliFrame:FindFirstChild("TextLabel")
					if not label then
						return 0
					end
					return tonumber((label.Text:gsub("[^%d]", ""))) or 0
				end

				-- debug line per block reason, rate limited
				local function fishDebug(reason, fmt, ...)
					getgenv().FishingBlockReason = reason
					if getgenv().LogFishing == false then
						return
					end
					local last = getgenv().FishingDebugLast or {}
					getgenv().FishingDebugLast = last
					local now = tick()
					if now - (last[reason] or 0) < (getgenv().FishingDebugRate or 5) then
						return
					end
					last[reason] = now
					local suffix = ""
					if fmt then
						local ok, result = pcall(string.format, fmt, ...)
						if ok then
							suffix = " " .. result
						end
					end
					log("[Fishing] " .. reason .. suffix)
				end
				getgenv().fishDebug = getgenv().fishDebug or fishDebug

				-- fishing session
				local function fishAction(action, sessionKey, actionKey)
					local response
					pcall(function()
						local remotes = ReplicatedStorage:FindFirstChild("Fishing") and ReplicatedStorage.Fishing:FindFirstChild("Remotes")
						local remote = remotes and remotes:FindFirstChild("Action")
						if not remote then
							return
						end
						response = remote:InvokeServer({ Action = action, SessionKey = sessionKey, ActionKey = actionKey })
					end)
					if getgenv().LogFishing ~= false then
						log(string.format("[Fishing] %s -> %s", action, describe(response)))
					end
					return response
				end

				-- remove the BodyPosition etc. holding the hook (workspace.Effects["<name>'s hook"])
				local function releaseFishingHook()
					local released = false
					pcall(function()
						local effects = workspace:FindFirstChild("Effects")
						local hook = effects and effects:FindFirstChild(localPlayer.Name .. "'s hook")
						if not hook then
							return
						end
						for _, descendant in ipairs(hook:GetDescendants()) do
							if descendant:IsA("BodyPosition") or descendant:IsA("BodyGyro") or descendant:IsA("BodyVelocity") or descendant:IsA("AlignPosition") then
								descendant:Destroy()
								released = true
							end
						end
						if hook:IsA("BasePart") then
							for _, child in ipairs(hook:GetChildren()) do
								if child:IsA("BodyPosition") or child:IsA("BodyGyro") or child:IsA("BodyVelocity") or child:IsA("AlignPosition") then
									child:Destroy()
									released = true
								end
							end
							hook.AssemblyLinearVelocity = Vector3.zero
						end
					end)
					if released then
						getgenv().HooksReleased = (getgenv().HooksReleased or 0) + 1
					end
					return released
				end
				getgenv().ReleaseFishingHook = getgenv().ReleaseFishingHook or releaseFishingHook

				-- close the session (Reel / HookReturning / Cancel) and clear the flags
				local function endFishingSession()
					getgenv().IsFishing = false
					getgenv().FishingBusy = false
					getgenv().ReleaseFishingHook()
					local sessionKey = getgenv().CurrentFishingSessionKey
					local actionKey = getgenv().CurrentFishingActionKey
					if sessionKey or actionKey then
						getgenv().FishingSessionsClosed = (getgenv().FishingSessionsClosed or 0) + 1
						getgenv().LastFishingSessionKey = sessionKey
						getgenv().LastFishingActionKey = actionKey
						for _, name in ipairs({ "Reel", "HookReturning", "Cancel" }) do
							local response = fishAction(name, sessionKey, actionKey)
							if type(response) == "table" and response.ActionKey then
								actionKey = response.ActionKey
							end
							task.wait(0.05)
						end
						getgenv().LastFishingActionKey = actionKey
					end
					getgenv().FishingReeled = false
					getgenv().CurrentFishingSessionKey = nil
					getgenv().CurrentFishingActionKey = nil
					local character = localPlayer.Character
					local root = character and character:FindFirstChild("HumanoidRootPart")
					if root then
						for _, name in ipairs({ "Medium", "Large", "Small", "Giant" }) do
							local sound = root:FindFirstChild(name)
							if sound then
								sound:Destroy()
							end
						end
					end
				end
				getgenv().EndFishingSession = getgenv().EndFishingSession or endFishingSession

				local function forceClearFishingSession()
					getgenv().ForcedClears = (getgenv().ForcedClears or 0) + 1
					getgenv().ReleaseFishingHook()
					local sessionKey = getgenv().CurrentFishingSessionKey or getgenv().LastFishingSessionKey
					local actionKey = getgenv().CurrentFishingActionKey or getgenv().LastFishingActionKey
					if sessionKey or actionKey then
						log("[Fishing] forcing the old session shut with the keys we still remember")
						for _, name in ipairs({ "Landed", "Reel", "HookReturning", "Cancel" }) do
							local response = fishAction(name, sessionKey, actionKey)
							if type(response) == "table" and response.ActionKey then
								actionKey = response.ActionKey
							end
							task.wait(0.05)
						end
						getgenv().LastFishingActionKey = actionKey
					else
						log("[Fishing] no session keys left to cancel with - unequipping the rod instead")
					end
					local humanoid = localPlayer.Character and localPlayer.Character:FindFirstChild("Humanoid")
					if humanoid then
						pcall(function()
							humanoid:UnequipTools()
						end)
					end
					getgenv().IsFishing = false
					getgenv().FishingBusy = false
					getgenv().FishingReeled = false
					getgenv().CurrentFishingSessionKey = nil
					getgenv().CurrentFishingActionKey = nil
				end
				getgenv().ForceClearFishingSession = getgenv().ForceClearFishingSession or forceClearFishingSession

				-- rod
				-- a Tool with "rod" in the name
				local function findRod(container)
					if not container then
						return nil
					end
					for _, child in ipairs(container:GetChildren()) do
						if child:IsA("Tool") and string.find(child.Name:lower(), "rod") then
							return child
						end
					end
					return nil
				end

				-- (true, tool) if a rod is in the backpack, (true, nil, name) if the inventory json has one, false otherwise
				local function hasRod()
					local backpack = localPlayer:FindFirstChild("Backpack")
					if backpack then
						for _, child in ipairs(backpack:GetChildren()) do
							if child:IsA("Tool") and child.Name:lower():find("rod") then
								return true, child
							end
						end
					end
					local data = inventoryData()
					if data then
						for k, v in pairs(data) do
							if v > 0 and k:lower():find("rod") then
								return true, nil, k
							end
						end
					end
					return false
				end

				local function equipRod()
					local character = localPlayer.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					if not character or not humanoid then
						return false
					end
					if findRod(character) then
						return true
					end
					local backpack = localPlayer:FindFirstChild("Backpack")
					if not backpack then
						return false
					end
					local tool = findRod(backpack)
					if not tool then
						local _, _, name = hasRod()
						ReplicatedStorage:WaitForChild("Events"):WaitForChild("Tools"):InvokeServer("equip", name or "Fishing Rod")
						return false
					end
					humanoid:EquipTool(tool)
					local deadline = tick() + 2
					repeat
						task.wait()
					until not (not (findRod(character) or tick() > deadline) and getgenv().AutoFishing)
					return findRod(character) ~= nil
				end

				-- put the rod away for a trip (RodTravelHold stops the loop from pulling it out again before the fishing spot)
				local function unequipRod(reason)
					getgenv().RodTravelHold = true
					local character = localPlayer.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					if not (character and humanoid) then
						return false
					end
					if not findRod(character) then
						return true
					end
					pcall(function()
						humanoid:UnequipTools()
					end)
					local deadline = tick() + 1
					repeat
						task.wait(0.05)
					until not (findRod(character) and not (tick() > deadline))
					local gone = findRod(character) == nil
					getgenv().RodUnequips = (getgenv().RodUnequips or 0) + 1
					if getgenv().LogRodTravel ~= false then
						log(string.format("[Rod] %s - rod %s for the trip (x%d). It goes back on at the fishing spot, not before.", tostring(reason or "travelling"), gone and "put away" or "would NOT go away", getgenv().RodUnequips))
					end
					return gone
				end
				getgenv().UnequipRod = getgenv().UnequipRod or unequipRod

				local function atFishingSpot()
					local spot = getgenv().FishingSpotCF
					if not spot then
						return true
					end
					local root = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
					if not root then
						return false
					end
					return (spot.Position - root.Position).Magnitude <= (getgenv().FishingSpotRange or 25)
				end

				-- fishman exit
				-- the exit portal inside is at Y = -2138 and the sea is around 0..30, so anything way below the surface is "inside". FishmanInsideY overrides it
				local function insideY()
					return tonumber(getgenv().FishmanInsideY) or -1000
				end
				local function isInsideFishman(root)
					return root ~= nil and root.Position.Y < insideY()
				end

				-- first sea only: tween to the exit portal inside fishman island and touch it until we're back above the threshold
				local function tweenToLeaveFishman()
					local root = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
					if not root or not isInsideFishman(root) then
						return
					end
					ownsTween = true
					local portal = CFrame.new(8577.102539, -2138.832031, -17091.052734, -0.098748, 0, -0.995112, 0, 1, 0, 0.995112, 0, -0.098748)
					local inner = CFrame.new(8585.81641, -2136.12305, -17087.8145)
					local function touchPortal()
						local fishman = workspace:FindFirstChild("Fishman")
						local part = fishman and (fishman:FindFirstChild("Part2") or fishman:FindFirstChild("Part"))
						if not part then
							for _, child in ipairs(workspace:GetChildren()) do
								if child.Name:lower():find("fishman") and child:FindFirstChild("Part2") then
									part = child.Part2
									break
								end
							end
						end
						local r = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
						if part and r and firetouchinterest then
							firetouchinterest(r, part, 0)
							task.wait(0.05)
							firetouchinterest(r, part, 1)
						end
					end
					stopTween()
					tweenTo({ CFrame = portal, Speed = getgenv().TweenSpeedMaster or 110, StopDistance = 4, TeleportOnClose = true, TeleportDistance = 6, Raycast = true, WalkOnWater = true })
					local r
					repeat
						task.wait(0.1)
						r = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
					until not (tweenState().Enabled and r and isInsideFishman(r))
					if not r or isInsideFishman(r) then
						-- guess: the original probably hands off to TweenAboveFishman here (not in the dump), callers retry every second instead
						return
					end
					stopTween()
					tweenTo({ CFrame = inner, Speed = getgenv().TweenSpeedMaster or 110, StopDistance = 2, TeleportOnClose = true, TeleportDistance = 4, Raycast = true, WalkOnWater = true })
					local count = 0
					while true do
						task.wait(0.2)
						count += 1
						touchPortal()
						local r2 = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
						if r2 and (not isInsideFishman(r2) or count >= 25) then
							break
						end
						if not r2 then
							break
						end
					end
					stopTween()
				end
				getgenv().TweenToLeaveFishman = getgenv().TweenToLeaveFishman or tweenToLeaveFishman

				-- travel
				-- TweenToFishing: sets FishingSpotCF for this place, leaves fishman if needed, tweens to the spot
				local function tweenToFishing()
					local cframe
					if game.PlaceId == 7465136166 then
						cframe = CFrame.new(-6763.41016, 27.0749931, 9203.70215, 0.225092813, -7.1990506e-08, -0.974337339, 1.40619028e-08, 1, -7.06380376e-08, 0.974337339, 2.19907736e-09, 0.225092813)
					elseif game.PlaceId == 116480749200627 then
						cframe = CFrame.new(-15.0580778, 4.21153259, -1423.65332, 0.0755246133, -1.45095393e-08, -0.997143924, 8.17793619e-08, 1, -8.35705283e-09, 0.997143924, -8.09146314e-08, 0.0755246133)
					elseif game.PlaceId == 3978370137 then
						cframe = CFrame.new(-1343.58374, 4.12497234, -4965.4873, 0.300642163, 0.000258832733, 0.953736961, -0.000639897247, 0.999999821, -6.96760326e-05, -0.953736782, -0.000589346106, 0.300642252)
					else
						getgenv().FishingSpotCF = nil
						return
					end
					getgenv().FishingSpotCF = cframe
					if getgenv().UnequipRod then
						pcall(getgenv().UnequipRod, "heading back to the fishing spot")
					else
						getgenv().RodTravelHold = true
					end
					local root = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
					if game.PlaceId == 3978370137 and isInsideFishman(root) then
						local gaveUp = false
						local tries = 0
						local r
						repeat
							if not tweenState().Enabled then
								getgenv().TweenToLeaveFishman()
							end
							task.wait(1)
							r = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
							if not (localPlayer.Character and localPlayer.Character:FindFirstChild("Humanoid") and not (localPlayer.Character.Humanoid.Health <= 0)) then
								break
							end
							tries += 1
							if not gaveUp and r and isInsideFishman(r) and tries >= (getgenv().FishingLeaveMaxTries or 3) then
								gaveUp = true
								if getgenv().LogFishing ~= false then
									log(string.format("[Fishing] still in Fishman after %d exit tries - resetting to get out.", tries))
								end
								stopTween()
								pcall(function()
									local humanoid = localPlayer.Character and localPlayer.Character:FindFirstChildOfClass("Humanoid")
									if humanoid then
										humanoid.Health = 0
									end
								end)
								local now = tick()
								repeat
									task.wait(0.5)
									r = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
								until (r and not isInsideFishman(r)) or not getgenv().AutoFishing or tick() - now > 15
							end
						until not (not (r and not isInsideFishman(r)) and getgenv().AutoFishing)
						if not getgenv().AutoFishing then
							return
						end
						local character = localPlayer.Character
						if not character or not character:FindFirstChild("Humanoid") or character.Humanoid.Health <= 0 then
							return
						end
					end
					if getgenv().FishingTravelReady then
						getgenv().FishingTravelReady("the trip to the fishing spot")
					end
					ownsTween = true
					tweenTo({ CFrame = cframe, Speed = getgenv().TweenSpeedFishing or 110, StopDistance = 5, TeleportOnClose = true, TeleportDistance = 5 })
				end
				getgenv().TweenToFishing = getgenv().TweenToFishing or tweenToFishing

				-- guess: the per-place rod shop spot (RodShopCF / RodShopHere) isn't in the dump, so it's taken from the workspace.BuyableItems
				-- "Fishing Rod" model (the loop itself uses getClosestShop("Fishing Rod") to buy)
				local function rodShopModel()
					local f = getgenv().getClosestShop
					if not f then
						return nil
					end
					local ok, model = pcall(f, "Fishing Rod")
					if ok then
						return model
					end
					return nil
				end
				local function rodShopHere()
					if getgenv().RodShopCF ~= nil then
						return true
					end
					local model = rodShopModel()
					local part = model and model:FindFirstChild("ShopPart")
					if part then
						getgenv().RodShopCF = part.CFrame
						return true
					end
					return false
				end
				getgenv().RodShopHere = getgenv().RodShopHere or rodShopHere

				local function tweenToRodShop()
					if not getgenv().RodShopHere() then
						return
					end
					local rodShopCF = getgenv().RodShopCF
					local root = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
					if isInsideFishman(root) then
						while true do
							if not tweenState().Enabled then
								getgenv().TweenToLeaveFishman()
							end
							task.wait(1)
							local r = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
							if localPlayer.Character and localPlayer.Character:FindFirstChild("Humanoid") and not (localPlayer.Character.Humanoid.Health <= 0) and not (r and not isInsideFishman(r)) and getgenv().AutoFishing then
								continue
							end
							break
						end
						if not getgenv().AutoFishing then
							return
						end
						if not localPlayer.Character or not localPlayer.Character:FindFirstChild("Humanoid") or localPlayer.Character.Humanoid.Health <= 0 then
							return
						end
					end
					if getgenv().FishingTravelReady then
						getgenv().FishingTravelReady("the trip to the rod shop")
					end
					ownsTween = true
					tweenTo({ CFrame = rodShopCF, Speed = getgenv().TweenSpeedFishing or 110, StopDistance = 5, TeleportOnClose = true, TeleportDistance = 5 })
					repeat
						task.wait()
					until not (tweenState().Enabled and getgenv().AutoFishing)
					if not getgenv().AutoFishing then
						stopTween()
					end
				end
				getgenv().TweenToRodShop = getgenv().TweenToRodShop or tweenToRodShop

				-- merchant helpers
				local function merchantMarker()
					local guider = ReplicatedStorage:FindFirstChild("CompassGuider")
					return guider and guider:FindFirstChild("Traveling Merchant")
				end

				local function merchantGuiMarker() -- PlayerGui.Compass.Compass.Guiders["Traveling Merchant"] (hud arrow, shown when the merchant is out and on screen)
					local compass = localPlayer.PlayerGui:FindFirstChild("Compass")
					return compass and compass:FindFirstChild("Compass") and compass.Compass:FindFirstChild("Guiders") and compass.Compass.Guiders:FindFirstChild("Traveling Merchant")
				end

				-- restock counter, one id per 30 min (UTC). guess: the real anchor date isn't known, any half-hour aligned one works since only changes matter
				local STOCK_ANCHOR = { year = 2024, month = 1, day = 1, hour = 0, min = 0, sec = 0 }
				local function getCurrentMerchantStockId()
					local elapsed = os.time(os.date("!*t")) - os.time(STOCK_ANCHOR)
					if elapsed < 0 then
						return 1
					end
					return 1 + math.floor(elapsed / 1800)
				end
				getgenv().getCurrentMerchantStockId = getgenv().getCurrentMerchantStockId or getCurrentMerchantStockId

				local function merchantReady()
					if getgenv().AlreadyGoToMerchant then
						return false
					end
					if tick() < (getgenv().MerchantRetryAt or 0) then
						return false
					end
					return true
				end
				getgenv().MerchantReady = getgenv().MerchantReady or merchantReady
				local function merchantVisitDone()
					getgenv().MerchantVisits = (getgenv().MerchantVisits or 0) + 1
					getgenv().AlreadyGoToMerchant = true
					getgenv().MerchantRetryAt = 0
				end
				local function merchantVisitFailed(why)
					getgenv().MerchantFails = (getgenv().MerchantFails or 0) + 1
					getgenv().MerchantRetryAt = tick() + (getgenv().MerchantRetryDelay or 60)
					log(string.format("[Auto Merchant] visit failed (%s) - retrying in %ds (fail #%d)", tostring(why), getgenv().MerchantRetryDelay or 60, getgenv().MerchantFails))
				end

				-- keep re-tweening while the merchant is still far (and the trip hasn't gone over MerchantTravelMax)
				local function merchantShouldKeepGoing(marker)
					if not marker then
						return false
					end
					local elapsed = tick() - (getgenv().MerchantTravelStart or 0)
					if (getgenv().MerchantTravelMax or 300) <= elapsed then
						return false
					end
					local character = localPlayer.Character
					local root = character and character:FindFirstChild("HumanoidRootPart")
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					if not root or not humanoid or humanoid.Health <= 0 then
						return false
					end
					local position = marker.Value
					if typeof(position) == "CFrame" then
						position = position.Position
					end
					if typeof(position) ~= "Vector3" then
						return false
					end
					return (root.Position - position).Magnitude > (getgenv().MerchantReachDist or 60)
				end
				getgenv().MerchantShouldKeepGoing = getgenv().MerchantShouldKeepGoing or merchantShouldKeepGoing

				-- head to the merchant (rod away, tween to the CompassGuider marker)
				local function tweenToMerchant()
					if getgenv().EndFishingSession then
						pcall(getgenv().EndFishingSession)
					else
						getgenv().IsFishing = false
					end
					if getgenv().UnequipRod then
						pcall(getgenv().UnequipRod, "heading to the merchant")
					else
						getgenv().RodTravelHold = true
					end
					local marker = merchantMarker()
					if not marker then
						return
					end
					local cframe
					if marker:IsA("CFrameValue") then
						cframe = marker.Value
					elseif marker:IsA("Vector3Value") then
						cframe = CFrame.new(marker.Value)
					else
						log("Unknown Traveling Merchant value type: " .. marker.ClassName)
						return
					end
					local maxTime = tonumber(getgenv().MerchantTweenMaxTime) or 0
					if getgenv().FishingTravelReady then
						getgenv().FishingTravelReady("the trip to the merchant")
					end
					ownsTween = true
					tweenTo({
						CFrame = cframe,
						Speed = getgenv().TweenSpeedMerchant or 110,
						StopDistance = 5,
						TeleportOnClose = true,
						TeleportDistance = 5,
						MaxTime = maxTime > 0 and maxTime or nil,
					})
					task.spawn(function()
						repeat
							task.wait()
						until tweenState().Enabled == false
						if getgenv().releaseAimStance then
							getgenv().releaseAimStance()
						end
						if getgenv().facingMouseNow and (getgenv().facingMouseNow() == true or getgenv().FaceMouseState == true) and getgenv().ToggleFaceMouse then
							getgenv().ToggleFaceMouse(false, true)
						end
						getgenv().AlreadyTweenFishing = false
					end)
				end

				local function findShopGui()
					local playerGui = localPlayer:FindFirstChild("PlayerGui")
					if not playerGui then
						return nil
					end
					return playerGui:FindFirstChild("MerchentShop", true) or playerGui:FindFirstChild("MerchantShop", true) or playerGui:FindFirstChild("MerchentShop") or playerGui:FindFirstChild("MerchantShop")
				end
				local function guiEnabled(gui)
					local ok, result = pcall(function()
						return gui.Enabled
					end)
					if not ok or result == nil then
						return true
					end
					return result == true
				end
				local function clickButton(button)
					if not button then
						return false
					end
					if firesignal then
						pcall(firesignal, button.Activated)
						pcall(firesignal, button.MouseButton1Click)
					end
					for _, signal in ipairs({ button.Activated, button.MouseButton1Click, button.MouseButton1Down }) do
						pcall(function()
							for _, connection in ipairs(getconnections(signal)) do
								connection:Fire()
							end
						end)
					end
					return true
				end
				local function findItemButton(name, gui)
					local instance = gui or findShopGui()
					if not instance or not guiEnabled(instance) then
						return nil
					end
					local main = instance:FindFirstChild("Main") or instance
					local list = main:FindFirstChild("List") or main
					local redeemables = list:FindFirstChild("Redeemables") or list:FindFirstChild("Items") or list
					if not redeemables then
						return nil
					end
					local function norm(s)
						return string.lower((string.gsub(tostring(s), "[%s%-_']", "")))
					end
					local entry = redeemables:FindFirstChild(name)
					if not entry then
						local want = norm(name)
						for _, child in ipairs(redeemables:GetChildren()) do
							if child:IsA("UIListLayout") or child:IsA("UIGridLayout") or child:IsA("UIPadding") then
								continue
							end
							local have = norm(child.Name)
							if have == want or string.find(have, want, 1, true) or string.find(want, have, 1, true) then
								entry = child
								break
							end
							for _, descendant in ipairs(child:GetDescendants()) do
								if descendant:IsA("TextLabel") and descendant.Text and descendant.Text ~= "" then
									local text = norm(descendant.Text)
									if text == want or string.find(text, want, 1, true) then
										entry = child
										break
									end
								end
							end
							if entry then
								break
							end
						end
					end
					if not entry then
						return nil
					end
					local inner = entry:FindFirstChild("Main")
					local button = inner and inner:FindFirstChild("Button")
					button = button or entry:FindFirstChild("Button", true)
					if not button then
						for _, descendant in ipairs(entry:GetDescendants()) do
							if descendant:IsA("GuiButton") then
								button = descendant
								break
							end
						end
					end
					return button
				end
				local function clickItem(name, gui)
					local button = findItemButton(name, gui)
					if not button then
						return false
					end
					return clickButton(button)
				end
				local function itemCount(name)
					local data = inventoryData()
					return data and tonumber(data[name]) or 0
				end

				-- buy one item over and over (until it's out / MerchantBuyMax / MerchantBuyTime / MerchantBuyFails clicks with nothing)
				local function buyItem(name, gui)
					local startCount = itemCount(name)
					local bought = 0
					local cap = tonumber(getgenv().MerchantBuyMax) or 100
					local maxFails = tonumber(getgenv().MerchantBuyFails) or 2
					local deadline = tick() + (tonumber(getgenv().MerchantBuyTime) or 180)
					local fails = 0
					local lastCount = startCount
					local exitTo
					while true do
						if not (getgenv().AutoMerchant and bought < cap) then
							exitTo = 1
							break
						end
						if deadline < tick() then
							exitTo = 2
							break
						end
						bought += 1
						if not clickItem(name, gui) then
							exitTo = 1
							break
						end
						local shopGone = false
						local started = tick()
						while tick() - started < 1.5 do
							task.wait(0.1)
							-- not sure: the original stops buying on some check here, the shop gui being closed fits best
							if not (gui and gui.Parent and guiEnabled(gui)) then
								shopGone = true
								break
							end
						end
						if shopGone then
							break
						end
						task.wait(0.5)
						local now = itemCount(name)
						if lastCount < now then
							fails = 0
							lastCount = now
						else
							if not clickItem(name, gui) then
								exitTo = 1
								break
							end
							fails += 1
						end
						if maxFails <= fails then
							exitTo = 1
							break
						end
					end
					if exitTo == 2 then
						log(string.format("[Auto Merchant] '%s' - %ds spent on this one item, moving on (bought %d so far).", name, math.floor(tonumber(getgenv().MerchantBuyTime) or 180), lastCount - startCount))
					end
					if cap <= bought then
						log(string.format("[Auto Merchant] '%s' - hit the %d buy cap and it is still in stock. Raise getgenv().MerchantBuyMax if you want more in one visit.", name, cap))
					end
				end

				-- the actual merchant visit
				local function visitMerchant()
					getgenv().MerchantTravelStart = tick()
					local arrived = false
					repeat
						task.wait(0.2)
						local marker = merchantMarker()
						if not marker then
							arrived = true
						end
						if not getgenv().AutoMerchant or arrived or getgenv().CraftingTrip then
							if tweenState().Enabled then
								stopTween()
							end
							break
						end
						if not tweenState().Enabled and getgenv().MerchantShouldKeepGoing(marker) then
							getgenv().MerchantLegs = (getgenv().MerchantLegs or 0) + 1
							tweenToMerchant()
						end
					until not tweenState().Enabled
					if not getgenv().AutoMerchant or arrived or getgenv().CraftingTrip then
						getgenv().AlreadyTweenFishing = false
						return
					end
					-- wait for the merchant NPC model to stream in
					local npc = nil
					local started = tick()
					local timedOut = false
					repeat
						local npcs = workspace:FindFirstChild("NPCs")
						if npcs then
							npc = npcs:FindFirstChild("Traveling Merchant") or npcs:FindFirstChild("Travelling Merchant")
						end
						npc = npc or workspace:FindFirstChild("Traveling Merchant") or workspace:FindFirstChild("Travelling Merchant")
						task.wait(0.1)
						if tick() - started > 12 then
							timedOut = true
							break
						end
					until not (not npc and getgenv().AutoMerchant)
					if not getgenv().AutoMerchant then
						return
					end
					if npc and not timedOut then
						local settled = tick()
						repeat
							task.wait(0.1)
						until not (not (npc:FindFirstChild("HumanoidRootPart") or not npc.Parent or tick() - settled > (tonumber(getgenv().MerchantSettleWait) or 3)) and getgenv().AutoMerchant)
						local root = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
						local npcRoot = npc:FindFirstChild("HumanoidRootPart") or npc.PrimaryPart or npc:FindFirstChildWhichIsA("BasePart")
						if root and npcRoot then
							local tries = tonumber(getgenv().ShopOpenTries) or 5
							local wait = tonumber(getgenv().ShopOpenWait) or 1.5
							local gui = nil
							for i = 1, tries do
								if not getgenv().AutoMerchant then
									break
								end
								if not npc.Parent then
									break
								end
								local r = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
								local nr = npc:FindFirstChild("HumanoidRootPart") or npc.PrimaryPart or npc:FindFirstChildWhichIsA("BasePart")
								if not (r and nr) then
									break
								end
								if (r.Position - nr.Position).Magnitude > 20 then
									r.CFrame = nr.CFrame * CFrame.new(0, 0, -4) * CFrame.Angles(0, 3.1415926535897931, 0)
									task.wait(0.5)
								end
								pcall(function()
									ReplicatedStorage:WaitForChild("Events"):WaitForChild("TravelingMerchentRemote"):InvokeServer("OpenShop")
								end)
								local asked = tick()
								repeat
									task.wait(0.1)
									gui = findShopGui()
								until not (not (gui and guiEnabled(gui) or tick() - asked > wait) and getgenv().AutoMerchant)
								if gui and guiEnabled(gui) then
									break
								end

								log(string.format("[Auto Merchant] the shop did not open on try %d/%d - asking again", i, tries))
							end
							local opened = gui and guiEnabled(gui)
							if opened then
								task.wait(0.5)
								getgenv().stockId = getgenv().getCurrentMerchantStockId()
								for _, item in ipairs(toList(getgenv().SelectedMerchantItems)) do
									if not getgenv().AutoMerchant then
										break
									end
									buyItem(item, gui)
								end
							end
							task.wait(0.5)
							pcall(function() -- close the shop window
								local close = gui and (gui:FindFirstChild("Close", true) or gui:FindFirstChild("CloseButton", true) or gui:FindFirstChild("X", true))
								if not close then
									return
								end

								local fire = firesignal or fireclickdetector
								if fire then
									pcall(fire, close.Activated)
									pcall(fire, close.MouseButton1Click)
								end
								for _, signal in ipairs({ close.Activated, close.MouseButton1Click, close.MouseButton1Down }) do
									pcall(function()
										for _, connection in ipairs(getconnections(signal)) do
											connection:Fire()
										end
									end)
								end
							end)
							if opened then
								-- this is the success path, without saving the visit the loop would keep driving back to the merchant
								merchantVisitDone()
							else
								merchantVisitFailed("shop GUI never opened")
							end
						else
							merchantVisitFailed("merchant NPC had no root part")
						end
					else
						merchantVisitFailed("merchant NPC never appeared")
					end
				end

				-- bait
				local function currentBait()
					local data = inventoryData() or {}
					local wanted = {}
					local selected = type(getgenv().CurrentFishBait) == "table" and getgenv().CurrentFishBait or {}
					for k, v in pairs(selected) do
						if type(k) == "number" and type(v) == "string" then
							wanted[v] = true
						elseif type(k) == "string" and v == true then
							wanted[k] = true
						end
					end
					local first = nil
					for _, name in ipairs({ "Legendary Fish Bait", "Rare Fish Bait", "Common Fish Bait" }) do
						if wanted[name] then
							first = first or name
							if data[name] and data[name] > 0 then
								return name
							end
						end
					end
					return first or "Common Fish Bait"
				end
				getgenv().__TensenCurrentBait = currentBait

				-- guess: where the line goes. the real goal function isn't in the dump, so root position + LookVector * FishingCastDistance.
				-- getgenv().FishingCastGoal = function(root) ... end overrides it
				local function castGoal(root)
					local custom = getgenv().FishingCastGoal
					if type(custom) == "function" then
						local ok, result = pcall(custom, root)
						if ok and typeof(result) == "Vector3" then
							return result
						end
					end
					local goal = root.Position + root.CFrame.LookVector * (tonumber(getgenv().FishingCastDistance) or 40)
					-- the hook's BodyPosition only has Y force, so the goal Y is the float height: water surface if the hub knows it
					local surface = getgenv().waterSurfaceY and getgenv().waterSurfaceY()
					if type(surface) == "number" then
						goal = Vector3.new(goal.X, surface, goal.Z)
					end
					return goal
				end

				local function fishingInfo()
					local character = localPlayer.Character
					local text = string.format(
						"[Fishing] %s | IsFishing=%s FishingBusy=%s | tween=%s craftTrip=%s | at spot=%s rod=%s\n  throws: %d accepted, %d refused | last cast %ds ago | last block: %s\n  arrival fails %d | dead casts %d | sessions closed %d | travel flag=%s\n  reeled=%s | hooks released %d | forced clears %d | session key: %s",
						getgenv().AutoFishing and "ON" or "OFF", tostring(getgenv().IsFishing), tostring(getgenv().FishingBusy), tostring(tweenState().Enabled), tostring(getgenv().CraftingTrip),
						tostring(atFishingSpot()), tostring(character and findRod(character) ~= nil), getgenv().ThrowsAccepted or 0, getgenv().ThrowsRefused or 0,
						math.floor(tick() - (getgenv().LastCastAt or tick())), tostring(getgenv().FishingBlockReason), getgenv().FishingArrivalFails or 0, getgenv().FishingDeadCasts or 0,
						getgenv().FishingSessionsClosed or 0, tostring(getgenv().AlreadyTweenFishing), tostring(getgenv().FishingReeled), getgenv().HooksReleased or 0, getgenv().ForcedClears or 0,
						getgenv().CurrentFishingSessionKey and "live" or (getgenv().LastFishingSessionKey and "remembered" or "none")
					)
					log(text)
					return text
				end
				getgenv().FishingInfo = getgenv().FishingInfo or fishingInfo

				local function soundsOn(root)
					if not root then
						return false
					end
					for _, name in ipairs({ "Medium", "Large", "Small", "Giant" }) do
						local sound = root:FindFirstChild(name)
						if sound and sound:IsA("Sound") then
							return true
						end
					end
					return false
				end

				-- stock bookkeeping loops and the merchant camera loop
				spawnLoop("MerchantStockId", function(alive)
					while alive() do
						task.wait(0.3)
						getgenv().newStockId = getgenv().getCurrentMerchantStockId()
					end
				end)
				spawnLoop("MerchantStockReset", function(alive)
					while alive() do
						task.wait(0.3)
						if getgenv().stockId ~= getgenv().newStockId then
							getgenv().stockId = getgenv().newStockId
							getgenv().AlreadyGoToMerchant = false
							getgenv().MerchantRetryAt = 0
						end
					end
				end)
				spawnLoop("MerchantCamera", function(alive)
					while alive() do
						task.wait(0.3)
						local marker = merchantMarker()
						if not (getgenv().AutoMerchant and marker and marker.Value and peli() > 0) then
							continue
						end

						local camera = workspace.CurrentCamera
						if camera then
							local target = marker.Value
							if typeof(target) == "CFrame" then
								target = target.Position
							end
							pcall(function()
								camera.CFrame = CFrame.new(camera.CFrame.Position, target)
							end)
						end
						task.wait(5)
					end
				end)

				-- main loop
				spawnLoop("FishingMerchant", function(alive)
					while alive() do
						task.wait()
						local ok, err = pcall(function()
							if not getgenv().IsFishing then
								getgenv().FishingBusy = false
							end
							local scrollHold = getgenv().ScrollHoldLive ~= nil and getgenv().ScrollHoldLive()
							if getgenv().FruitHold or scrollHold then
								getgenv().EndFishingSession()
								if getgenv().FruitHold then
									getgenv().FruitHoldAck = true
								end
								if scrollHold then
									getgenv().ScrollAckFish = true
								end
								local started = tick()
								while getgenv().FruitHold and getgenv().StoringFruit and tick() - started < (getgenv().FruitHoldMax or 30) or getgenv().ScrollHoldLive ~= nil and getgenv().ScrollHoldLive() do
									task.wait(0.1)
								end
								getgenv().FruitHoldAck = false
								getgenv().ScrollAckFish = false
								getgenv().FruitHold = false
								task.wait(0.2)
								return
							end
							if getgenv().AutoFishing and not getgenv().IsFishing and not getgenv().CraftingTrip and getgenv().LogFishing ~= false and tick() - (getgenv().LastCastAt or 0) > (getgenv().FishingStallWarn or 20) and tick() - (getgenv().LastStallReport or 0) > (getgenv().FishingStallWarn or 20) then
								getgenv().LastStallReport = tick()
								log(string.format("[Fishing] no bait has gone out for %ds - dumping state", math.floor(tick() - (getgenv().LastCastAt or 0))))
								pcall(getgenv().FishingInfo)
							end
							if not getgenv().AutoMerchant and not getgenv().AutoFishing then
								getgenv().AlreadyTweenFishing = false
								if getgenv().IsFishing then
									getgenv().EndFishingSession()
								end
								if ownsTween and tweenState().Enabled then
									stopTween()
									ownsTween = false
								end
								task.wait(0.1)
								return
							end
							if getgenv().StoringFruit and not getgenv().IsFishing then
								task.wait(0.1)
								return
							end
							if getgenv().CraftingTrip then
								getgenv().AlreadyTweenFishing = false
								task.wait(0.2)
								return
							end
							local character = localPlayer.Character
							local root = character and character:FindFirstChild("HumanoidRootPart")
							local humanoid = character and character:FindFirstChild("Humanoid")
							if not character or not root or not humanoid or humanoid.Health <= 0 then
								task.wait(1)
								return
							end
							if getgenv().FishingLastCharacter ~= character then
								getgenv().FishingLastCharacter = character
								getgenv().AlreadyTweenFishing = false
								if getgenv().IsFishing then
									getgenv().EndFishingSession()
								end
								if tweenState().Enabled then
									stopTween()
								end
								task.wait(1)
								return
							end

							-- merchant trip
							local guiMarker = merchantGuiMarker()
							if getgenv().AutoMerchant then
								if isInsideFishman(root) then
									while true do
										if not tweenState().Enabled and not getgenv().CraftingTrip then
											getgenv().TweenToLeaveFishman()
										end
										task.wait(1)
										local r = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
										if localPlayer.Character and localPlayer.Character:FindFirstChild("Humanoid") and not (localPlayer.Character.Humanoid.Health <= 0) and not (r and not isInsideFishman(r)) and getgenv().AutoMerchant then
											continue
										end
										break
									end
									if not getgenv().AutoMerchant then
										return
									end
									if not localPlayer.Character or not localPlayer.Character:FindFirstChild("Humanoid") or localPlayer.Character.Humanoid.Health <= 0 then
										return
									end
								end
								if peli() > 0 and guiMarker and guiMarker.Visible == true and merchantMarker() and getgenv().MerchantReady() then
									if getgenv().CraftingTrip then
										return
									end
									tweenToMerchant()
									visitMerchant()
									if not getgenv().AutoMerchant then
										return
									end
								end
							end
							if not getgenv().AutoMerchant and not getgenv().AutoFishing then
								return
							end
							if getgenv().AutoMerchant and not getgenv().AutoFishing then
								return
							end

							-- rod
							if not hasRod() then
								if getgenv().CraftingTrip then
									return
								end
								getgenv().TweenToRodShop()
								while true do
									task.wait(1)
									if localPlayer.Character and localPlayer.Character:FindFirstChild("Humanoid") and not (localPlayer.Character.Humanoid.Health <= 0) and tweenState().Enabled ~= false and getgenv().AutoFishing and not getgenv().CraftingTrip then
										continue
									end
									break
								end
								if not localPlayer.Character or not localPlayer.Character:FindFirstChild("Humanoid") or localPlayer.Character.Humanoid.Health <= 0 then
									return
								end
								if not getgenv().AutoFishing then
									return
								end
								local started = tick()
								repeat
									task.wait(1)
									local r = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
									local shopCF = getgenv().RodShopCF
									if (r and shopCF and (r.Position - shopCF.Position).Magnitude or math.huge) > (getgenv().RodShopRange or 25) then
										if not tweenState().Enabled then
											getgenv().TweenToRodShop()
										end
										continue
									end

									local shop = getgenv().getClosestShop and getgenv().getClosestShop("Fishing Rod")
									if shop then
										pcall(function()
											ReplicatedStorage:WaitForChild("Events"):WaitForChild("Shop"):InvokeServer(shop, 1)
										end)
									end
								until not (not (hasRod() or not getgenv().AutoFishing or tick() - started > 20) and getgenv().RodShopHere())
								if not getgenv().AutoFishing then
									return
								end
							end
							if atFishingSpot() and not getgenv().RodTravelHold and not equipRod() then
								fishDebug("the rod would not equip", "- retrying in 1s")
								task.wait(1)
								return
							end
							task.wait(0.15)

							-- travel to the spot
							if not getgenv().AlreadyTweenFishing then
								if getgenv().CraftingTrip then
									return
								end
								getgenv().TweenToFishing()
								if not tweenState().Enabled and getgenv().AutoFishing and not atFishingSpot() then
									fishDebug("the travel tween was refused", "- SpeedBypass reads %s, so waiting for it to clear instead of counting an arrival fail", tostring(getgenv().yBypassValue()))
									task.wait(getgenv().FishingBypassRetry or 1)
									return
								end
								while true do
									task.wait(1)
									local marker = merchantGuiMarker()
									if not getgenv().AutoFishing then
										if tweenState().Enabled then
											stopTween()
										end
										break
									end
									if localPlayer.Character and localPlayer.Character:FindFirstChild("Humanoid") and not (localPlayer.Character.Humanoid.Health <= 0) and not (tweenState().Enabled == false or getgenv().CraftingTrip or marker and marker.Visible == true and getgenv().AutoMerchant and not getgenv().AlreadyGoToMerchant) then
										continue
									end
									break
								end
								local marker = merchantGuiMarker()
								if marker and marker.Visible == true and getgenv().AutoMerchant and not getgenv().AlreadyGoToMerchant and getgenv().stockId ~= getgenv().newStockId then
									stopTween()
									return
								end
								if not getgenv().AutoFishing and not getgenv().AutoMerchant then
									getgenv().AlreadyTweenFishing = false
									return
								end
								local c = localPlayer.Character
								if not c or not c:FindFirstChild("Humanoid") or c.Humanoid.Health <= 0 then
									return
								end
								getgenv().EndFishingSession()
								task.wait(0.5)
								if not atFishingSpot() then
									getgenv().FishingArrivalFails = (getgenv().FishingArrivalFails or 0) + 1
									if getgenv().LogFishing ~= false then
										local r = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
										local spot = getgenv().FishingSpotCF
										log(string.format("[Fishing] tween ended but we are %s studs from the spot - not casting, going again (x%d)", r and spot and tostring(math.floor((spot.Position - r.Position).Magnitude)) or "?", getgenv().FishingArrivalFails))
									end
									getgenv().AlreadyTweenFishing = false
									task.wait(0.5)
									return
								end
							end
							if not atFishingSpot() then
								fishDebug("drifted away from the fishing spot", "- travelling again")
								getgenv().AlreadyTweenFishing = false
								return
							end
							if tweenState().Enabled then
								fishDebug("a tween is still running", "- cannot cast while moving")
								return
							end
							if getgenv().RodTravelHold then
								getgenv().RodTravelHold = false
								if getgenv().LogRodTravel ~= false then
									log("[Rod] Back on the fishing spot - taking the rod out again.")
								end
							end
							if not equipRod() then
								fishDebug("the rod would not equip", "- retrying in 1s")
								task.wait(1)
								return
							end

							-- cast
							local character = localPlayer.Character
							local root = character and character:FindFirstChild("HumanoidRootPart")
							local humanoid = character and character:FindFirstChild("Humanoid")
							if not character or not root or not root.Parent or not humanoid or humanoid.Health <= 0 then
								getgenv().AlreadyTweenFishing = false
								task.wait(0.5)
								return
							end
							getgenv().AlreadyTweenFishing = true
							getgenv().FishingBusy = true
							if not getgenv().IsFishing then
								if getgenv().CraftingTrip then
									fishDebug("a craft trip took over", "- not casting")
									return
								end
								if getgenv().CurrentFishingSessionKey or getgenv().CurrentFishingActionKey then
									getgenv().StaleSessions = (getgenv().StaleSessions or 0) + 1
									log(string.format("[Fishing] a session was still open with no line out - closing it before casting (x%d)", getgenv().StaleSessions))
									getgenv().EndFishingSession()
									task.wait(0.2)
								end
								if getgenv().releaseAimStance then
									getgenv().releaseAimStance()
								end
								local facing = getgenv().facingMouseNow and getgenv().facingMouseNow()
								if facing == true or facing == nil and getgenv().FaceMouseState == true then
									getgenv().StanceDrops = (getgenv().StanceDrops or 0) + 1
									log(string.format("[Fishing] the aiming stance is still on from a tween - dropping it before casting (x%d)", getgenv().StanceDrops))
									if getgenv().ToggleFaceMouse then
										getgenv().ToggleFaceMouse(false, true)
									end
									task.wait(0.2)
								end
								getgenv().ReleaseFishingHook()
								task.wait(0.1)
								local goal = castGoal(root)
								local remotes = ReplicatedStorage:WaitForChild("Fishing"):WaitForChild("Remotes")
								local action = remotes:WaitForChild("Action")
								local bait = currentBait()
								local response = action:InvokeServer({ Action = "Throw", Goal = goal, Bait = bait })
								if type(response) == "table" and response.Accepted == true then
									local sessionKey = response.SessionKey
									local actionKey = response.ActionKey
									getgenv().CurrentFishingSessionKey = sessionKey
									getgenv().CurrentFishingActionKey = actionKey
									if getgenv().LogFishing ~= false then
										log(string.format("[Fishing] Throw ACCEPTED - session %s, action %s (accepted #%d)", shortKey(sessionKey), shortKey(actionKey), (getgenv().ThrowsAccepted or 0) + 1))
									end
									task.spawn(function() -- pin the hook at the goal
										local effects = workspace:FindFirstChild("Effects")
										local hook = effects and effects:WaitForChild(localPlayer.Name .. "'s hook", 3)
										if hook then
											hook.CFrame = CFrame.new(goal)
											local bodyPosition = Instance.new("BodyPosition")
											bodyPosition.MaxForce = Vector3.new(0, 2e9, 0)
											bodyPosition.Position = goal
											bodyPosition.Parent = hook
											hook.AssemblyLinearVelocity = Vector3.zero
										end
									end)
									-- guess: "Landed" gets a few retries (the log says "Landed after %d try(s)" but the retry loop wasn't there)
									local landed, accepted, sound = false, false, false
									local replyText = "no reply yet"
									local tries = 0
									local maxTries = tonumber(getgenv().LandedTries) or 5
									while tries < maxTries and not landed do
										tries += 1
										local reply = action:InvokeServer({ Action = "Landed", SessionKey = sessionKey, ActionKey = actionKey })
										replyText = describe(reply)
										if type(reply) == "table" then
											if reply.Accepted == true then
												landed = true
												accepted = true
											end
											if reply.ActionKey then
												actionKey = reply.ActionKey
												getgenv().CurrentFishingActionKey = reply.ActionKey
											end
										else
											task.wait(0.1)
										end
										if soundsOn(root) then
											if not accepted then
												sound = true
											end
											landed = true
										end
										if not landed then
											task.wait(0.2)
										end
									end
									if not landed then
										log("[Fishing] the line never landed - closing the session")
										getgenv().EndFishingSession()
										task.wait(0.5)
										return
									end
									if getgenv().LogFishing ~= false then
										log(string.format("[Fishing] Landed after %d try(s): first reply %s | %s | action now %s", tries, replyText, accepted and "server accepted" or sound and "NOT accepted - a bite sound ended the wait" or "never landed", shortKey(actionKey)))
									end
									getgenv().LastAcceptedGoal = goal
									getgenv().IsFishing = true
									getgenv().FishingReeled = false
									getgenv().FishingCastAt = tick()
									getgenv().LastCastAt = tick()
									getgenv().ThrowsAccepted = (getgenv().ThrowsAccepted or 0) + 1
									getgenv().ThrowRefusedStreak = 0
									getgenv().FishingBlockReason = "cast is out"
								else
									getgenv().ThrowsRefused = (getgenv().ThrowsRefused or 0) + 1
									getgenv().ThrowRefusedStreak = (getgenv().ThrowRefusedStreak or 0) + 1
									local why
									if type(response) ~= "table" then
										why = "the server returned " .. typeof(response)
									else
										why = "Accepted=" .. tostring(response.Accepted)
										if response.Reason then
											why ..= ", Reason=" .. tostring(response.Reason)
										end
										if response.Message then
											why ..= ", Message=" .. tostring(response.Message)
										end
									end
									local spot = getgenv().FishingSpotCF
									local away = spot and math.floor((spot.Position - root.Position).Magnitude) or -1
									local lastGoal = getgenv().LastAcceptedGoal
									fishDebug("the Throw was refused", "- %s | bait '%s' x%d | refused %d of %d\n  goal %s | standing %s (%d studs from the spot)\n  last accepted goal %s", why, tostring(bait), getgenv().baitCount and getgenv().baitCount(bait) or -1, getgenv().ThrowsRefused, (getgenv().ThrowsAccepted or 0) + getgenv().ThrowsRefused, tostring(goal), tostring(root.Position), away, lastGoal and tostring(lastGoal) or "none yet")
									local streak = getgenv().ThrowRefusedStreak or 1
									local resetAfter = getgenv().ThrowResetAfter or 3
									if streak >= resetAfter and streak % resetAfter == 0 then
										fishDebug("clearing the session after repeated refusals", "- the server may still think a line is out (try #%d)", math.floor(streak / resetAfter))
										getgenv().ForceClearFishingSession()
									end
									task.wait(math.min(streak * 1.5, getgenv().ThrowMaxBackoff or 20))
								end
							end

							-- wait for the bite and reel
							if not findRod(character) then
								getgenv().EndFishingSession()
								return
							end
							if not getgenv().IsFishing then
								return
							end

							local elapsed = tick() - (getgenv().FishingCastAt or tick())
							if (getgenv().FishingCastMaxLife or 45) < elapsed then
								getgenv().FishingDeadCasts = (getgenv().FishingDeadCasts or 0) + 1
								log(string.format("[Fishing] the line has been out %ds with no bite - that cast is dead, reeling in (x%d)", math.floor(elapsed), getgenv().FishingDeadCasts))
								getgenv().EndFishingSession()
								return
							end
							if not (soundsOn(root) and getgenv().IsFishing) then
								return
							end

							getgenv().FishingReeled = true
							local started = tick()
							repeat
								task.wait(0.2)
							until tick() - started >= 8 or not getgenv().AutoFishing
							local reelStarted = tick()
							local action = ReplicatedStorage:WaitForChild("Fishing"):WaitForChild("Remotes"):WaitForChild("Action")
							repeat
								local response = action:InvokeServer({ Action = "Reel", SessionKey = getgenv().CurrentFishingSessionKey, ActionKey = getgenv().CurrentFishingActionKey })
								if type(response) == "table" and response.ActionKey then
									getgenv().CurrentFishingActionKey = response.ActionKey
								end
								task.wait(0.1)
								if not character or not humanoid then
									break
								end
								if not findRod(character) then
									getgenv().IsFishing = false
									break
								end
								for _, name in ipairs({ "Medium", "Large", "Small", "Giant" }) do
									local sound = root:FindFirstChild(name)
									if sound then
										sound:Destroy()
									end
								end
								local done = not soundsOn(root) or not getgenv().IsFishing or not getgenv().AutoFishing
							until done or tick() - reelStarted > 5
							task.wait(0.1)
							local response = action:InvokeServer({ Action = "HookReturning", SessionKey = getgenv().CurrentFishingSessionKey, ActionKey = getgenv().CurrentFishingActionKey })
							if type(response) == "table" and response.ActionKey then
								getgenv().CurrentFishingActionKey = response.ActionKey
							end
							task.wait(0.1)
							action:InvokeServer({ Action = "Cancel", SessionKey = getgenv().CurrentFishingSessionKey, ActionKey = getgenv().CurrentFishingActionKey })
							getgenv().LastFishingSessionKey = getgenv().CurrentFishingSessionKey
							getgenv().LastFishingActionKey = getgenv().CurrentFishingActionKey
							getgenv().CurrentFishingSessionKey = nil
							getgenv().CurrentFishingActionKey = nil
							getgenv().IsFishing = false
							getgenv().FishingReeled = false
						end)
						if not ok then
							if getgenv().LogFishing ~= false then
								fishDebug("the fishing loop hit an error", "- %s", tostring(err))
							end
							task.wait(1)
						end
					end
				end)
			end

			-- fruit manager (Fruit tab: Auto Store Fruit / Store Every Fruit / Drop Unlisted / Drop On Fail)
			--   pass: store or drop every wanted fruit, pauses fishing through FruitHold
			--   nextFruit, classify, drop cooldown, storeFruit, dropFruit, after-fail / unlisted handling, backpack/character watcher
			-- the big mom module has its own store loop and helpers (fruitNameSet, findFruitTool, noteFruitStoreFail, ...), reused here
			-- the dump stops where the store call starts. the remote call + check below is the same as big mom's AutoStore
			-- (FruitStorage:InvokeServer(true) with the tool in hand, then check it left the bag)
			-- guess: the toggle callbacks that started a pass are lost, a slow poll (AutoStoreRate) does it instead
			do
				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local localPlayer = Players.LocalPlayer

				local function spawnLoop(name, body)
					local loops = getgenv().__TensenLoops
					if type(loops) ~= "table" then
						loops = {}
						getgenv().__TensenLoops = loops
					end
					local token = {}
					loops[name] = token
					task.spawn(function()
						task.wait()
						body(function()
							return loops[name] == token
						end)
					end)
				end

				local function log(msg)
					local f = getgenv().BMLog
					if f then
						pcall(f, msg)
					else
						print(msg)
					end
				end

				local function toList(value)
					local list = {}
					if type(value) == "table" then
						for k, v in pairs(value) do
							if type(k) == "number" and type(v) == "string" then
								table.insert(list, v)
							elseif type(k) == "string" and v == true then
								table.insert(list, k)
							end
						end
					elseif type(value) == "string" then
						table.insert(list, value)
					end
					return list
				end

				local failedNames = {}     -- lower-case fruit name -> true (store failed)
				local dropState = {}       -- lower-case fruit name -> { count, at }
				local droppedAt = {}       -- lower-case front name -> tick() of the last unlisted drop

				local function fails()
					local t = getgenv().FruitStoreFails
					if type(t) ~= "table" then
						t = setmetatable({}, { __mode = "k" })
						getgenv().FruitStoreFails = t
					end
					return t
				end

				local function enabled()
					return getgenv().AutoStoreFruit == true or getgenv().DropUnlistedFruit == true
				end

				-- (is it a fruit to store, its name)
				local function classify(tool)
					local front = getgenv().FruitFrontName(tool.Name)
					if not front then
						return false, nil
					end
					local names = getgenv().fruitNameSet()
					if not (names[tool.Name] or names[front]) then
						return false, nil
					end
					if getgenv().StoreAllFruit then
						return true, front
					end
					for _, picked in ipairs(toList(getgenv().SelectedFruitToStore or {})) do
						local pickedFront = getgenv().FruitFrontName(picked)
						if pickedFront and string.lower(pickedFront) == string.lower(front) then
							return true, front
						end
					end
					return false, front
				end

				local function dropAllowed(key)
					local state = dropState[key]
					if not state then
						return true
					end
					if (getgenv().DropFruitMaxTries or 3) <= state.count then
						return false
					end
					return tick() - state.at > (getgenv().DropFruitCooldown or 1)
				end

				-- (tool, name, drop it?, unlisted?)
				local function nextFruit()
					local character = localPlayer.Character
					local backpack = localPlayer:FindFirstChildOfClass("Backpack")
					local failMax = getgenv().FruitStoreFailMax or 1
					local bags = {}
					if character then
						table.insert(bags, character)
					end
					if backpack then
						table.insert(bags, backpack)
					end
					local failTable = fails()
					for _, bag in ipairs(bags) do
						for _, child in ipairs(bag:GetChildren()) do
							if not child:IsA("Tool") then
								continue
							end
							local selected, front = classify(child)
							local key = front and string.lower(front)
							if selected and getgenv().AutoStoreFruit then
								if not ((failTable[child] or 0) >= failMax or failedNames[key] == true) then
									return child, front, false, false
								end
								if getgenv().DropFruitOnFail and dropAllowed(key) then
									return child, front, true, false
								end
								continue
							end
							if front and not selected and getgenv().DropUnlistedFruit and dropAllowed(key) then
								return child, front, true, true
							end
						end
					end
					return nil
				end

				-- put the fruit in hand, call the storage remote, check it left the bag (the end part is rebuilt)
				local function storeFruit(tool)
					local name = tool.Name
					local character = localPlayer.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					if not character or not humanoid then
						return false
					end
					local events = ReplicatedStorage:FindFirstChild("Events")
					if not (events and events:FindFirstChild("FruitStorage")) then
						return
					end
					log(string.format("[Fruit] '%s' is in the bag - storing it.", name))
					local started = tick()
					local inHand = true
					if getgenv().FruitEquipBeforeStore ~= false then
						inHand = tool.Parent == character
						local tries = tonumber(getgenv().FruitEquipTries) or 3
						for i = 1, tries do
							if inHand then
								break
							end
							pcall(function()
								humanoid:UnequipTools()
							end)
							local deadline = tick() + (getgenv().FruitUnequipWait or 0.15)
							while character:FindFirstChildOfClass("Tool") and tick() < deadline do
								task.wait()
							end
							pcall(function()
								humanoid:EquipTool(tool)
							end)
							local deadline = tick() + (getgenv().FruitEquipWait or 0.6)
							while tool.Parent ~= character and tick() < deadline do
								task.wait()
							end
							inHand = tool.Parent == character
							if not inHand then
								log(string.format("[Fruit] '%s' did not go into the hand on try %d/%d - trying the equip again.", name, i, tries))
							end
						end
					end
					local elapsed = tick() - started
					if not inHand then
						local failTable = fails()
						local fails = (failTable[tool] or 0) + 1
						failTable[tool] = fails
						log(string.format("[Fruit] '%s' would not equip after %.2fs - NOT asking the storage remote, because it only stores what is in your hand and a nil answer would look like a refusal (try %d/%d).", name, elapsed, fails, getgenv().FruitStoreFailMax or 5))
						return false
					end
					-- rebuilt part, see the top of this section
					local ok, result = pcall(function()
						return events.FruitStorage:InvokeServer(true)
					end)
					task.wait(0.3)
					local parent = tool.Parent
					local backpack = localPlayer:FindFirstChildOfClass("Backpack")
					local stillThere = parent ~= nil and (parent == character or (backpack ~= nil and parent == backpack))
					if ok and not stillThere then
						log(string.format("[Fruit] Stored '%s'.", name))
						fails()[tool] = nil
						getgenv().FruitsStored = (getgenv().FruitsStored or 0) + 1
						if getgenv().RecordFruitTool then
							pcall(getgenv().RecordFruitTool, name, true)
						end
						return true
					end
					if not ok then
						log(string.format("[Fruit] FruitStorage remote errored: %s", tostring(result)))
					end
					if getgenv().noteFruitStoreFail then
						getgenv().noteFruitStoreFail(tool)
					end
					return false
				end

				-- take the fruit out of the bag with Events.Tools:InvokeServer("drop", tool)
				local function dropFruit(tool)
					local name = tool.Name
					local character = localPlayer.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					if not character or not humanoid then
						return false
					end
					local backpack = localPlayer:FindFirstChildOfClass("Backpack")
					local function inBag()
						local parent = tool.Parent
						return parent ~= nil and (parent == character or (backpack ~= nil and parent == backpack))
					end
					if tool.Parent == character then
						pcall(function()
							humanoid:UnequipTools()
						end)
						local deadline = tick() + (getgenv().FruitUnequipWait or 0.15)
						while tool.Parent == character and tick() < deadline do
							task.wait()
						end
						if tool.Parent == character then
							log(string.format("[Fruit] '%s' is still in hand - the drop remote wants it in the backpack, so this one will not go.", name))
						end
					end
					local tools
					pcall(function()
						local events = ReplicatedStorage:FindFirstChild("Events")
						tools = events and events:FindFirstChild("Tools")
					end)
					if not tools then
						log(string.format("[Fruit] no Events.Tools remote to drop '%s' with - leaving it in the bag.", name))
						return false
					end
					local tries = getgenv().DropFruitRemoteTries or 1
					for i = 1, tries do
						local ok, err = pcall(function()
							tools:InvokeServer("drop", tool)
						end)
						if not ok then
							log(string.format("[Fruit] the Tools 'drop' remote errored on '%s' (try %d/%d): %s", name, i, tries, tostring(err)))
						end
						local deadline = tick() + (getgenv().DropFruitWait or 0.4)
						while inBag() and tick() < deadline do
							task.wait()
						end
						if not inBag() then
							log(string.format("[Fruit] dropped '%s' on the floor.", name))
							return true
						end
					end
					log(string.format("[Fruit] the drop remote did not take '%s' out of the bag after %d tries - it stays there.", name, tries))
					return false
				end

				-- unlisted -> drop. failed store -> remember it and (DropFruitOnFail) drop it, give up after DropFruitMaxTries
				local function handleDrop(tool, front, unlisted)
					local name = tool.Name
					local key = string.lower(front or name)
					if unlisted then
						droppedAt[key] = tick()
						log(string.format("[Fruit] '%s' is not in the list - dropping it.", name))
						dropFruit(tool)
						return
					end

					failedNames[key] = true
					if not getgenv().DropFruitOnFail then
						return
					end

					local state = dropState[key] or { count = 0, at = 0 }
					state.count += 1
					state.at = tick()
					dropState[key] = state
					dropFruit(tool)
					if (getgenv().DropFruitMaxTries or 3) <= state.count then
						log(string.format("[Fruit] '%s' has been put on the floor %d times and keeps coming back - leaving it alone now.", name, state.count))
					end
				end

				-- one pass over the bag
				local function runPass()
					if not enabled() then
						return 0
					end
					if getgenv().StoringFruit then
						return 0
					end
					local character = localPlayer.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					if not character or not humanoid or humanoid.Health <= 0 then
						return 0
					end
					if not nextFruit() then
						return 0
					end
					getgenv().StoringFruit = true
					getgenv().FruitPasses = (getgenv().FruitPasses or 0) + 1
					local held = false
					local fishing = getgenv().AutoFishing or getgenv().IsFishing or getgenv().FishingBusy
					if fishing then
						getgenv().FruitHold = true
						local started = tick()
						local maxWait = getgenv().StoreFishingWait or 20
						repeat
							task.wait(0.1)
						until not (not (getgenv().FruitHoldAck or not getgenv().AutoFishing and not getgenv().IsFishing and not getgenv().FishingBusy or tick() - started > maxWait) and enabled())
						if getgenv().IsFishing or getgenv().FishingBusy then
							getgenv().FruitCutIns = (getgenv().FruitCutIns or 0) + 1
							pcall(getgenv().EndFishingSession)
						end
						task.wait(getgenv().FruitStoreSettle or 0.4)
						held = true
					end
					local handled = 0
					while enabled() do
						local tool, front, drop, unlisted = nextFruit()
						if not tool then
							break
						end
						character = localPlayer.Character
						humanoid = character and character:FindFirstChildOfClass("Humanoid")
						if not character or not humanoid or humanoid.Health <= 0 or not tool.Parent then
							break
						end
						local ok
						if drop then
							ok = pcall(handleDrop, tool, front, unlisted)
						else
							local result
							ok, result = pcall(storeFruit, tool)
							if ok and result ~= true and failedNames[string.lower(front or tool.Name)] and tool.Parent ~= nil then
								ok = pcall(handleDrop, tool, front, false)
							end
						end
						if not ok then
							log("[Fruit] the fruit pass errored - it will try again.")
							break
						end
						handled += 1
						if tool.Parent ~= nil then
							local deadline = tick() + (getgenv().FruitGoneWait or 0.5)
							while tool.Parent ~= nil and tick() < deadline do
								task.wait()
							end
							if tool.Parent ~= nil then
								log(string.format("[Fruit] '%s' was handled but is still in the bag - ending this pass so it cannot loop on the same one.", tostring(tool.Name)))
								break
							end
						end
						if handled >= (getgenv().FruitPassMax or 25) then
							log(string.format("[Fruit] handled %d in one pass - stopping here so nothing can spin forever.", handled))
							break
						end
					end
					getgenv().StoringFruit = false
					if held then
						getgenv().FruitHold = false
					end
					if handled > 0 and getgenv().autofarm then
						local equip = getgenv().equipWeapon
						if equip then
							pcall(equip, "ForceEquipTool")
						end
					end
					return handled
				end
				getgenv().__TensenFruitPass = runPass

				-- a tool landing in the backpack / character starts a pass
				local function onChild(child)
					if getgenv().FruitWatch == false then
						return
					end
					if not enabled() then
						return
					end
					if not (child and child:IsA("Tool")) then
						return
					end
					local selected, front = classify(child)
					if not front then
						return
					end
					if not selected and not getgenv().DropUnlistedFruit then
						return
					end
					if selected then
						log(string.format("[Fruit] '%s' picked up", front))
					end
					if getgenv().StoringFruit then
						return
					end
					getgenv().FruitNudges = (getgenv().FruitNudges or 0) + 1
					task.spawn(runPass)
				end
				local function watch(container)
					if not container then
						return
					end
					for _, child in ipairs(container:GetChildren()) do
						onChild(child)
					end
					container.ChildAdded:Connect(onChild)
				end
				local watched = {}
				local function watchPlayer()
					local backpack = localPlayer:FindFirstChildOfClass("Backpack")
					if backpack and not watched[backpack] then
						watched[backpack] = true
						watch(backpack)
					end
					local character = localPlayer.Character
					if character and not watched[character] then
						watched[character] = true
						watch(character)
					end
				end
				spawnLoop("FruitWatch", function(alive)
					watchPlayer()
					localPlayer.CharacterAdded:Connect(function()
						task.wait(1)
						watchPlayer()
					end)
					while alive() do
						task.wait(2)
						pcall(watchPlayer)
					end
				end)

				-- guess: the toggles used to start a pass themselves, poll instead
				spawnLoop("FruitPoll", function(alive)
					while alive() do
						task.wait(getgenv().AutoStoreRate or 5)
						if enabled() and not getgenv().StoringFruit then
							pcall(runPass)
						end
					end
				end)
			end

			-- auto add stats (Stats tab)
			-- five `while task.wait(0.1) do if getgenv().AddX then addX() end end` loops (Strength, Stamina, Defense, Gun, Sword). the bodies were
			-- the same except the row name and the *Limit setting, so it's one function now: press Statistics > Main > Stats.<Stat>.Add while
			-- AvailableSP > 0 and <Stat>.Amount is under the limit (0 = no limit)
			do
				local Players = game:GetService("Players")
				local localPlayer = Players.LocalPlayer

				-- starting a loop replaces its token, so an older copy stops at its next check
				local function spawnLoop(name, body)
					local loops = getgenv().__TensenLoops
					if type(loops) ~= "table" then
						loops = {}
						getgenv().__TensenLoops = loops
					end
					local token = {}
					loops[name] = token
					task.spawn(function()
						task.wait()
						body(function()
							return loops[name] == token
						end)
					end)
				end

				local function log(msg)
					local f = getgenv().BMLog
					if f then
						pcall(f, msg)
					end
				end

				-- { flag, limit setting, row name in Statistics.Main.Stats }
				local STATS = {
					Strength = { flag = "AddStrength", limit = "StrengthLimit", row = "Strength" },
					Stamina = { flag = "AddStamina", limit = "StaminaLimit", row = "Stamina" },
					Defense = { flag = "AddDefense", limit = "DefenseLimit", row = "Defense" },
					Gun = { flag = "AddGun", limit = "GunLimit", row = "GunMastery" },
					Sword = { flag = "AddSword", limit = "SwordLimit", row = "SwordMastery" },
				}

				local function addStat(def)
					local statistics = localPlayer.PlayerGui:FindFirstChild("Statistics")
					if not statistics then
						return
					end
					local main = statistics:FindFirstChild("Main", true)
					if not main then
						return
					end
					local row = main.Stats:FindFirstChild(def.row)
					if not row then
						return
					end
					local amount = row:FindFirstChild("Amount")
					if not amount or not amount.Text then
						return
					end
					local limit = tonumber(getgenv()[def.limit]) or 0
					if limit > 0 and (tonumber(amount.Text:match("%d+")) or 0) >= limit then
						return
					end
					local add = row:FindFirstChild("Add")
					if not add or not add:IsA("TextButton") then
						return
					end
					local availableSP = main.TopOptions:FindFirstChild("AvailableSP")
					if not availableSP or not availableSP.Text then
						return
					end
					local points = tonumber(availableSP.Text:match("%d+"))
					if not points or points <= 0 then
						return
					end
					local pressed = false
					for _, signal in ipairs({ add.Activated, add.MouseButton1Click, add.MouseButton1Down }) do
						for _, connection in ipairs(getconnections(signal)) do
							if connection.Function then
								connection.Function()
								pressed = true
							end
						end
					end
					if not pressed then
						log("Could not find ANY connections.")
					end
				end
				getgenv().__TensenAddStat = addStat

				for name, def in pairs(STATS) do
					spawnLoop("AddStat_" .. name, function(alive)
						while alive() do
							task.wait(0.1)
							if getgenv()[def.flag] then
								pcall(addStat, def)
								task.wait(0.1)
							end
						end
					end)
				end
			end

			-- auto buy common bait / auto sell fish / auto equip best fishing title / auto watch ads
			--   BuyBait   buy when under LowerThan, nearest "Common Fish Bait" shop
			--   SellFish  sell the picked fish one by one until peli >= 1,000,000
			--   AutoTitle equip the best of Godly / Master / Skilled / Novice Fisherman
			--   AutoAds   open the shop module's ad shop and press every ad button
			-- AdProducts / AdPlacements / AdProductFallback aren't in the code, so only the module/gui path (ClaimAdsByModule) can work.
			-- that's why AdUseModule gets turned on when nobody set it (guess, the real default isn't known)
			do
				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local HttpService = game:GetService("HttpService")
				local localPlayer = Players.LocalPlayer

				local function spawnLoop(name, body)
					local loops = getgenv().__TensenLoops
					if type(loops) ~= "table" then
						loops = {}
						getgenv().__TensenLoops = loops
					end
					local token = {}
					loops[name] = token
					task.spawn(function()
						task.wait()
						body(function()
							return loops[name] == token
						end)
					end)
				end

				-- peli in HUD.Main.Peli.TextLabel
				local function peli()
					local hud = localPlayer.PlayerGui:FindFirstChild("HUD")
					local main = hud and hud:FindFirstChild("Main")
					local peliFrame = main and main:FindFirstChild("Peli")
					local label = peliFrame and peliFrame:FindFirstChild("TextLabel")
					if not label then
						return 0
					end
					return tonumber((label.Text:gsub("[^%d]", ""))) or 0
				end

				-- inventory json ({["Common Fish Bait"] = 12, ...}) is in ReplicatedStorage.Stats<Name>.Inventory.Inventory
				local function inventoryData()
					local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)
					local inventory = stats and stats:FindFirstChild("Inventory") and stats.Inventory:FindFirstChild("Inventory")
					if not inventory or not inventory.Value or inventory.Value == "" then
						return nil
					end
					local ok, result = pcall(function()
						return HttpService:JSONDecode(inventory.Value)
					end)
					if ok and type(result) == "table" then
						return result
					end
					return nil
				end

				-- buy bait
				local function getClosestShop(name)
					local buyableItems = workspace:FindFirstChild("BuyableItems")
					if not buyableItems then
						return nil
					end
					local root = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
					if not root then
						return nil
					end
					local best, bestDist = nil, math.huge
					for _, child in ipairs(buyableItems:GetChildren()) do
						if child:IsA("Model") and child.Name == name and child:FindFirstChild("ShopPart") then
							local dist = (root.Position - child.ShopPart.Position).Magnitude
							if dist < bestDist then
								bestDist = dist
								best = child
							end
						end
					end
					return best, bestDist
				end
				if not getgenv().getClosestShop then
					getgenv().getClosestShop = getClosestShop
				end

				local function commonBaitCount()
					local data = inventoryData()
					if not data then
						return 0
					end
					return data["Common Fish Bait"] or 0
				end

				local function buyBaitIfLow()
					local count = commonBaitCount()
					local lowerThan = getgenv().LowerThan or 10
					local amount = getgenv().BaitAmount or 10
					if not (count < lowerThan) then
						return
					end

					if not workspace:FindFirstChild("BuyableItems") then
						return
					end
					local shop = (getgenv().getClosestShop or getClosestShop)("Common Fish Bait")
					if not shop then
						return
					end
					ReplicatedStorage:WaitForChild("Events"):WaitForChild("Shop"):InvokeServer(shop, amount)
				end

				-- same gate as the original (`AutoFishing and BuyBait or AutoMerchant`)
				spawnLoop("BuyBait", function(alive)
					while alive() do
						task.wait(1)
						if getgenv().AutoFishing and getgenv().BuyBait or getgenv().AutoMerchant then
							pcall(buyBaitIfLow)
						end
					end
				end)

				-- sell fish
				-- picked fish that are actually in the inventory
				local function sellableFish()
					local data = inventoryData()
					local list = {}
					if not data or not getgenv().SelectedFish then
						return list
					end
					for k, v in pairs(getgenv().SelectedFish) do
						local name = type(k) == "string" and k or v
						local amount = data[name]
						if amount and amount > 0 then
							table.insert(list, name)
						end
					end
					return list
				end

				local function sellFish()
					local list = sellableFish()
					if not list or #list == 0 then
						return
					end
					for _, fish in ipairs(list) do
						if peli() >= 1000000 then
							return
						end
						ReplicatedStorage:WaitForChild("FishingShopRemote"):InvokeServer({ Fish = fish, All = false, Method = "SellFish" })
						task.wait(0.1)
					end
				end
				getgenv().__TensenSellFish = sellFish

				spawnLoop("SellFish", function(alive)
					while alive() do
						task.wait(1)
						if getgenv().SellFish and not (peli() >= 1000000) then
							pcall(sellFish)
						end
					end
				end)

				-- auto title
				local function equipBestFishingTitle()
					local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)
					local titles = stats and stats:FindFirstChild("Titles")
					local allTitles = titles and titles:FindFirstChild("AllTitles")
					if not allTitles then
						return
					end
					local value = allTitles.Value
					if not value or value == "" then
						return
					end
					local data = HttpService:JSONDecode(value)
					for _, title in ipairs({ "Godly Fisherman", "Master Fisherman", "Skilled Fisherman", "Novice Fisherman" }) do
						if data[title] then
							ReplicatedStorage:WaitForChild("Events"):WaitForChild("Titles"):InvokeServer(title)
							return true
						end
					end
					return false
				end

				spawnLoop("AutoTitle", function(alive)
					while alive() do
						task.wait(1)
						if getgenv().AutoTitle then
							pcall(equipBestFishingTitle)
							task.wait(1)
						end
					end
				end)

				-- auto ads
				local function clickButton(button)
					if not button then
						return false
					end
					if firesignal then
						pcall(firesignal, button.Activated)
						pcall(firesignal, button.MouseButton1Click)
					end
					for _, signal in ipairs({ button.Activated, button.MouseButton1Click, button.MouseButton1Down }) do
						pcall(function()
							for _, connection in ipairs(getconnections(signal)) do
								connection:Fire()
							end
						end)
					end
					return true
				end

				-- client Shop module, required on first use
				local shopModule
				local function getShopModule()
					if shopModule == nil then
						shopModule = false
						pcall(function()
							shopModule = require(ReplicatedStorage:WaitForChild("Modules"):WaitForChild("Client"):WaitForChild("UIController"):WaitForChild("Guis"):WaitForChild("Core"):WaitForChild("Shop"))
						end)
					end
					return shopModule or nil
				end

				-- the Button of every entry in PlayerGui.Shop.Main.List.ADShop
				local function adButtons()
					local buttons = {}
					pcall(function()
						local shop = localPlayer.PlayerGui:FindFirstChild("Shop")
						local main = shop and shop:FindFirstChild("Main")
						local list = main and main:FindFirstChild("List")
						local adShop = list and list:FindFirstChild("ADShop")
						if not adShop then
							return
						end
						for _, child in ipairs(adShop:GetChildren()) do
							local inner = child:FindFirstChild("Main")
							local button = inner and inner:FindFirstChild("Button")
							if button and button:IsA("GuiButton") then
								buttons[#buttons + 1] = button
							end
						end
					end)
					return buttons
				end

				local function claimAdsByModule()
					local module = getShopModule()
					if not module then
						return false
					end
					local canWatch = false
					pcall(function()
						canWatch = module:CanWatchAd()
					end)
					if not canWatch then
						return false
					end
					pcall(function()
						module:OpenADShop()
					end)
					task.wait(getgenv().AdOpenWait or 0.5)
					local count = 0
					for _, button in ipairs(adButtons()) do
						if clickButton(button) then
							count += 1
							getgenv().AdsClicked = (getgenv().AdsClicked or 0) + 1
							task.wait(getgenv().AdClickGap or 0.3)
						end
					end
					return count > 0
				end
				if not getgenv().ClaimAdsByModule then
					getgenv().ClaimAdsByModule = claimAdsByModule
				end

				-- product id for an ad placement (Products module :GetProductIdByPlace, else AdProductFallback)
				local productsModule
				local function adProductId(place)
					if productsModule == nil then
						pcall(function()
							productsModule = require(ReplicatedStorage:WaitForChild("Modules"):WaitForChild("Shared"):WaitForChild("Marketplace"):WaitForChild("Products"))
						end)
						if productsModule == nil then
							productsModule = false
						end
					end
					local id = nil
					if productsModule then
						pcall(function()
							id = productsModule:GetProductIdByPlace(place)
						end)
					end
					return tonumber(id) or (getgenv().AdProductFallback or {})[place]
				end

				local function claimAd(place)
					local productId = adProductId(place)
					local placement = (getgenv().AdPlacements or {})[place]
					if not productId or not placement then
						return false
					end
					local ok = pcall(function()
						ReplicatedStorage:WaitForChild("Events"):WaitForChild("ADShop"):FireServer(productId, placement)
					end)
					if ok then
						getgenv().AdsFired = (getgenv().AdsFired or 0) + 1
					end
					return ok
				end
				if not getgenv().ClaimAd then
					getgenv().ClaimAd = claimAd
				end

				-- guess: the tables above don't exist, without AdUseModule the loop below has nothing to claim
				if getgenv().AdUseModule == nil then
					getgenv().AdUseModule = true
				end

				spawnLoop("AutoAds", function(alive)
					local index = 1
					while alive() do
						task.wait(getgenv().AdRate or 10)
						if not getgenv().autoad then
							continue
						end

						local handled = false
						if getgenv().AdUseModule then
							local ok, result = pcall(getgenv().ClaimAdsByModule)
							handled = ok and result == true
						end
						if handled then
							continue
						end

						local products = getgenv().AdProducts or {}
						if #products ~= 0 then
							if #products < index then
								index = 1
							end
							pcall(getgenv().ClaimAd, products[index])
							index += 1
						end
					end
				end)
			end

			-- tween to island (Tween tab)
			-- loop: while StartTweenIsland and CurrentIsland -> TweenToCFrame to the island until it's off. the island resolver was a local in the loader,
			-- the same one is already in TPToIsland so it's copied here
			-- the real Select Island callback also did a single-pick filter: CurrentIsland = keepSinglePick(value, CurrentIsland, <island names>)
			-- logGround was only debug output, it's a no-op here
			do
				local Players = game:GetService("Players")

				local function spawnLoop(name, body)
					local loops = getgenv().__TensenLoops
					if type(loops) ~= "table" then
						loops = {}
						getgenv().__TensenLoops = loops
					end
					local token = {}
					loops[name] = token
					task.spawn(function()
						task.wait()
						body(function()
							return loops[name] == token
						end)
					end)
				end

				local function log(msg)
					local f = getgenv().BMLog
					if f then
						pcall(f, msg)
					else
						print(msg)
					end
				end

				-- island name -> cframe to stand at, and how it was found
				local function resolveIslandTarget(name)
					local islands = workspace:FindFirstChild("Islands")
					if not islands then
						return nil
					end
					local island = islands:FindFirstChild(name)
					if not island then
						log("Could not find island: " .. tostring(name))
						return nil
					end
					local pivotOk, pivot = pcall(function()
						return island:GetPivot()
					end)
					if not (pivotOk and pivot) then
						log("Could not find island: " .. tostring(name))
						return nil
					end
					local boxOk, boxCFrame, boxSize = pcall(function()
						return island:GetBoundingBox()
					end)
					if boxOk and boxCFrame and boxSize and boxSize.Y > 0 then
						local topMargin = getgenv().IslandTopMargin or 20
						local topY = boxCFrame.Position.Y + boxSize.Y / 2 + topMargin
						local rayDrop = boxSize.Y + topMargin + 200
						local lift = getgenv().GroundRayLift or 3
						local floorUnder = getgenv().FloorUnder
						if floorUnder then
							-- 1) straight down from just above the pivot
							local hitPosition = floorUnder(pivot.Position + Vector3.new(0, 2, 0), { Include = { island }, Drop = rayDrop })
							if hitPosition then
								return CFrame.new(hitPosition + Vector3.new(0, lift, 0)), "island ground"
							end
							-- 2) straight down from above the island's top, over the pivot and over the box center
							for _, origin in ipairs({ pivot.Position, boxCFrame.Position }) do
								local topHit = floorUnder(Vector3.new(origin.X, topY, origin.Z), { Include = { island }, Drop = rayDrop })
								if topHit then
									return CFrame.new(topHit + Vector3.new(0, lift, 0)), "island ground"
								end
							end
						end
					end
					-- 3) nothing to raycast against yet: stand at the pivot, raised above the sea if it's under it
					local position = pivot.Position
					local waterSurfaceY = getgenv().waterSurfaceY and getgenv().waterSurfaceY()
					local airHover = getgenv().IslandAirHover or 30
					local surfaceDepth = getgenv().IslandSurfaceDepth or 150
					local underSea = type(waterSurfaceY) == "number" and position.Y < waterSurfaceY + airHover and position.Y > waterSurfaceY - surfaceDepth
					local how = "its pivot, waiting for it to stream in"
					if underSea then
						position = Vector3.new(position.X, waterSurfaceY + airHover, position.Z)
						getgenv().IslandSeaLifts = (getgenv().IslandSeaLifts or 0) + 1
						how = "hovering over the sea at its pivot, waiting for it to stream in"
					end
					return CFrame.new(position), how
				end

				local function tweenState()
					return getgenv().__TensenTweenState or { Enabled = false }
				end

				local startedByUs = false
				spawnLoop("TweenToIsland", function(alive)
					while alive() do
						task.wait()
						if not getgenv().StartTweenIsland then
							if startedByUs and tweenState().Enabled and getgenv().StopCurrentTween then
								-- the toggle callback's "stop the tween" is lost, so stop our own tween here
								pcall(getgenv().StopCurrentTween)
							end
							startedByUs = false
							task.wait(0.1)
							continue
						end
						local island = getgenv().CurrentIsland
						if type(island) == "table" then
							island = island[1]
						end
						if not island or island == "" or island == "None" then
							task.wait(0.5)
							continue
						end
						local target = getgenv().tpFixedSpot and getgenv().tpFixedSpot(island)
						if typeof(target) == "Vector3" then
							target = CFrame.new(target)
						end
						target = target or (resolveIslandTarget(island))
						if not target then
							task.wait(1)
							continue
						end
						local tweenTo = getgenv().TweenToCFrame
						if type(tweenTo) ~= "function" then
							task.wait(1)
							continue
						end
						startedByUs = true
						tweenTo({
							CFrame = target,
							Speed = getgenv().TweenSpeedIsland or 70,
							StopDistance = 5,
							TeleportOnClose = true,
							TeleportDistance = 5,
						})
						repeat
							task.wait()
						until not (tweenState().Enabled and getgenv().StartTweenIsland)
						if not getgenv().StartTweenIsland then
							if getgenv().StopCurrentTween then
								pcall(getgenv().StopCurrentTween)
							end
							startedByUs = false
						end
					end
				end)
			end

			-- movement + protection tab loops
			--   Infinite Jump            space held / JumpRequest in the air -> geppo/stamina trigger + upward velocity FakeGeppoPower
			--   Anti Ragdoll / Knockback Heartbeat step
			--   Fix Stuck Climb Noclip
			--   Dash tab                 No/Spoof Dash Cooldown, Dash Cooldown (ms), No Grab Cooldown, No Climb Cooldown, Air Dash, Air Dash On Ground, Custom Dash
			-- guesses (marked): dashCdCustom() == SpoofDashCooldown on, airDashEffectModule() found like the hub's scanAirDashFX.
			-- ClimbNoclipGroups isn't in the code, so the climb fix does nothing until a table is set
			do
				local Players = game:GetService("Players")
				local RunService = game:GetService("RunService")
				local UserInputService = game:GetService("UserInputService")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local localPlayer = Players.LocalPlayer

				local function spawnLoop(name, body)
					local loops = getgenv().__TensenLoops
					if type(loops) ~= "table" then
						loops = {}
						getgenv().__TensenLoops = loops
					end
					local token = {}
					loops[name] = token
					task.spawn(function()
						task.wait()
						body(function()
							return loops[name] == token
						end)
					end)
					return function()
						return loops[name] == token
					end
				end

				-- one connection per load, the older copy goes idle once a newer load takes its token
				local function guard(name)
					local loops = getgenv().__TensenLoops
					if type(loops) ~= "table" then
						loops = {}
						getgenv().__TensenLoops = loops
					end
					local token = {}
					loops[name] = token
					return function()
						return loops[name] == token
					end
				end

				local function log(msg)
					local f = getgenv().BMLog
					if f then
						pcall(f, msg)
					else
						print(msg)
					end
				end

				-- infinite jump
				do
					local alive = guard("InfiniteJump")
					local spaceHeld = false
					local function jump(fromJumpRequest)
						if not alive() then
							return
						end
						if getgenv().FakeGeppo ~= true then
							return
						end
						if UserInputService:GetFocusedTextBox() then
							return
						end
						local character = localPlayer.Character
						local root = character and character:FindFirstChild("HumanoidRootPart")
						local humanoid = character and character:FindFirstChildOfClass("Humanoid")
						if not (character and root and humanoid) or humanoid.Health <= 0 then
							return
						end
						local owns = getgenv().ScriptOwnsMovement
						if type(owns) == "function" and owns(root, humanoid) == true then
							return
						end
						if humanoid.FloorMaterial ~= Enum.Material.Air then
							return
						end
						if humanoid.PlatformStand then
							return
						end
						if humanoid:GetState() == Enum.HumanoidStateType.Seated then
							return
						end
						pcall(function()
							if fromJumpRequest and getgenv().TriggerGeppoOrStam then
								getgenv().TriggerGeppoOrStam(root.CFrame)
							end
						end)
						pcall(function()
							local velocity = root.AssemblyLinearVelocity
							root.AssemblyLinearVelocity = Vector3.new(velocity.X, tonumber(getgenv().FakeGeppoPower) or 60, velocity.Z)
						end)
						getgenv().FakeGeppoJumps = (getgenv().FakeGeppoJumps or 0) + 1
					end
					UserInputService.InputBegan:Connect(function(input, gameProcessed)
						if input.KeyCode == Enum.KeyCode.Space and not gameProcessed then
							spaceHeld = true
						end
					end)
					UserInputService.InputEnded:Connect(function(input)
						if input.KeyCode == Enum.KeyCode.Space then
							spaceHeld = false
						end
					end)
					UserInputService.WindowFocusReleased:Connect(function()
						spaceHeld = false
					end)
					UserInputService.JumpRequest:Connect(function()
						jump(true)
					end)
					RunService.Heartbeat:Connect(function()
						if spaceHeld then
							jump(false)
						end
					end)
				end

				-- anti ragdoll + anti knockback
				do
					local alive = guard("AntiRagdollKnockback")
					local lastWalkSpeed = 16
					local nextScan = 0
					RunService.Heartbeat:Connect(function()
						if not alive() then
							return
						end
						local ragdollOn = getgenv().AntiRagdoll == true
						local knockbackOn = getgenv().AntiKnockback == true
						if not ragdollOn and getgenv().__RagdollClientDisabled then
							local client = getgenv().__RagdollClient
							pcall(function()
								if client and client.Parent then
									client.Disabled = false
								end
							end)
							getgenv().__RagdollClientDisabled = false
							getgenv().__RagdollClient = nil
						end
						if not ragdollOn and not knockbackOn then
							return
						end
						local character = localPlayer.Character
						local root = character and character:FindFirstChild("HumanoidRootPart")
						local humanoid = character and character:FindFirstChildOfClass("Humanoid")
						if not (character and root and humanoid) or humanoid.Health <= 0 then
							return
						end
						local scriptMoving = false
						local owns = getgenv().ScriptOwnsMovement
						if type(owns) == "function" then
							scriptMoving = owns(root, humanoid) == true
						end
						if not scriptMoving and getgenv().ClimbingNow then
							local ok, result = pcall(getgenv().ClimbingNow)
							if ok and result then
								scriptMoving = true
							end
						end
						local now = tick()
						local scanNow = now >= nextScan
						if scanNow then
							nextScan = now + (getgenv().AntiRagdollScanRate or 0.2)
						end
						if ragdollOn then
							if scanNow then
								local playerScripts = localPlayer:FindFirstChild("PlayerScripts")
								local ragdolls = playerScripts and playerScripts:FindFirstChild("Ragdolls")
								local client = ragdolls and ragdolls:FindFirstChild("Ragdoll_Client")
								if client and (client:IsA("LocalScript") or client:IsA("Script")) and client.Disabled ~= true and pcall(function()
									client.Disabled = true
								end) then
									getgenv().__RagdollClient = client
									getgenv().__RagdollClientDisabled = true
									getgenv().RagdollClientKills = (getgenv().RagdollClientKills or 0) + 1
								end
								local ragdoll = character:FindFirstChild("Ragdoll")
								if ragdoll and pcall(function()
									ragdoll:Destroy()
								end) then
									getgenv().RagdollsCleared = (getgenv().RagdollsCleared or 0) + 1
								end
								pcall(function()
									if character:GetAttribute("Ragdoll") == true then
										character:SetAttribute("Ragdoll", false)
									end
								end)
							end
							if not scriptMoving then
								pcall(function()
									if humanoid.PlatformStand then
										humanoid.PlatformStand = false
									end
									if not humanoid.AutoRotate then
										humanoid.AutoRotate = true
									end
									local state = humanoid:GetState()
									if state == Enum.HumanoidStateType.Physics or state == Enum.HumanoidStateType.FallingDown or state == Enum.HumanoidStateType.Ragdoll then
										humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
									end
								end)
							end
						end
						if not knockbackOn then
							return
						end
						if scanNow then
							local stun = character:FindFirstChild("Stun") or localPlayer:FindFirstChild("Stun")
							local removed = false
							if stun then
								removed = pcall(function()
									stun:Destroy()
								end)
							end
							if removed then
								getgenv().StunsCleared = (getgenv().StunsCleared or 0) + 1
							end
							pcall(function()
								-- the original only checks for attribute support here, attributes exist in this client
								if character:GetAttribute("Stun") == true then
									character:SetAttribute("Stun", false)
								end
							end)
						end
						if humanoid.WalkSpeed > 0 then
							lastWalkSpeed = humanoid.WalkSpeed
						elseif not scriptMoving then
							pcall(function()
								humanoid.WalkSpeed = lastWalkSpeed
							end)
						end
						if scriptMoving then
							return
						end
						local limit = tonumber(getgenv().AntiKnockMaxSpeed) or 80
						local velocity = root.AssemblyLinearVelocity
						if not (Vector3.new(velocity.X, 0, velocity.Z).Magnitude > limit) then
							return
						end

						local isScriptMover = getgenv().isScriptMover
						for _, child in ipairs(root:GetChildren()) do
							if (child:IsA("BodyVelocity") or child:IsA("BodyThrust") or child:IsA("BodyForce") or child:IsA("BodyPosition") or child:IsA("LinearVelocity") or child:IsA("VectorForce") or child:IsA("BodyAngularVelocity"))
								and not (type(isScriptMover) == "function" and isScriptMover(child.Name)) and pcall(function()
									child:Destroy()
								end) then
								getgenv().KnockbacksKilled = (getgenv().KnockbacksKilled or 0) + 1
							end
						end
						pcall(function()
							root.AssemblyLinearVelocity = Vector3.new(0, velocity.Y, 0)
							root.AssemblyAngularVelocity = Vector3.zero
						end)
					end)
				end

				-- fix stuck climb noclip
				spawnLoop("ClimbNoclipFix", function(alive)
					local since = nil
					while alive() do
						task.wait(0.5)
						if getgenv().ClimbNoclipFix == false then
							since = nil
							continue
						end
						local character = localPlayer.Character
						local humanoid = character and character:FindFirstChildOfClass("Humanoid")
						if not character or not humanoid or humanoid.Health <= 0 then
							since = nil
							continue
						end
						local climbing, state = false, nil
						if getgenv().ClimbingNow then
							local ok, result, extra = pcall(getgenv().ClimbingNow)
							if ok then
								climbing = result
								state = extra
							end
						end
						if climbing then
							since = nil
							continue
						end
						local groups = getgenv().ClimbNoclipGroups or {}
						local stuck = {}
						for _, part in ipairs(character:GetDescendants()) do
							if part:IsA("BasePart") and groups[part.CollisionGroup] then
								stuck[#stuck + 1] = part
							end
						end
						if #stuck == 0 then
							since = nil
							continue
						end
						since = since or tick()
						if tick() - since < (getgenv().ClimbNoclipGrace or 1.5) then
							continue
						end
						local home = getgenv().ClimbNoclipHome or "Players"
						local group = stuck[1].CollisionGroup
						for _, part in ipairs(stuck) do
							pcall(function()
								part.CollisionGroup = home
							end)
						end
						if type(state) == "table" then
							pcall(function()
								state.CollisionApplied = false
							end)
						end
						getgenv().ClimbNoclipFixes = (getgenv().ClimbNoclipFixes or 0) + 1
						log(string.format("[Climb] %d part(s) were left on the '%s' collision group with no climb running - a stuck noclip, not something you switched on. Put back on '%s' (x%d).", #stuck, tostring(group), tostring(home), getgenv().ClimbNoclipFixes))
						since = nil
					end
				end)

				-- dash tab
				-- guess: the Dash Cooldown slider says "Needs Spoof Dash Cooldown on"
				if not getgenv().dashCdCustom then
					getgenv().dashCdCustom = function()
						return getgenv().SpoofDashCooldown == true
					end
				end

				-- guess: the "...Dash" ModuleScript in ReplicatedStorage.Effects.DevilFruits.<AirDashEffectName> (same place scanAirDashFX looks)
				if not getgenv().airDashEffectModule then
					getgenv().airDashEffectModule = function()
						local name = getgenv().AirDashEffectName
						if not name or name == "None" or name == "" then
							return nil
						end
						local effects = ReplicatedStorage:FindFirstChild("Effects")
						local fruits = effects and effects:FindFirstChild("DevilFruits")
						local folder = fruits and fruits:FindFirstChild(name)
						if not folder then
							return nil
						end
						for _, child in ipairs(folder:GetChildren()) do
							if child:IsA("ModuleScript") and string.sub(child.Name, -4) == "Dash" then
								return child
							end
						end
						return nil
					end
				end

				if not getgenv().doAirDash then
					getgenv().doAirDash = function()
						local now = os.clock()
						if now - (getgenv().LastAirDash or 0) < (getgenv().AirDashCooldown or 0.08) then
							return false
						end
						local character = localPlayer.Character
						local root = character and character:FindFirstChild("HumanoidRootPart")
						local humanoid = character and character:FindFirstChildOfClass("Humanoid")
						if not (character and root and humanoid) or humanoid.Health <= 0 then
							return false
						end
						local owns = getgenv().ScriptOwnsMovement
						if type(owns) == "function" and owns(root, humanoid) == true then
							return false
						end
						local direction = humanoid.MoveDirection
						if direction.Magnitude < 0.05 then
							direction = root.CFrame.LookVector
						end
						local flat = Vector3.new(direction.X, 0, direction.Z)
						if flat.Magnitude < 0.05 then
							return false
						end
						local unit = flat.Unit
						local distance = tonumber(getgenv().AirDashDistance) or 15
						local params = RaycastParams.new()
						local include = {}
						for _, name in ipairs({ "Islands", "Ships", "Env" }) do
							local folder = workspace:FindFirstChild(name)
							if folder then
								include[#include + 1] = folder
							end
						end
						if #include > 0 then
							params.FilterType = Enum.RaycastFilterType.Include
							params.FilterDescendantsInstances = include
						else
							params.FilterType = Enum.RaycastFilterType.Exclude
							params.FilterDescendantsInstances = { character }
						end
						params.IgnoreWater = true
						pcall(function()
							params.RespectCanCollide = true
						end)
						local hit = workspace:Raycast(root.Position, unit * distance, params)
						if hit then
							distance = math.max(0, hit.Distance)
						end
						if distance < 2 then
							return false
						end
						getgenv().LastAirDash = now
						pcall(function()
							local events = ReplicatedStorage:FindFirstChild("Events")
							local takestam = events and events:FindFirstChild("takestam")
							if takestam then
								takestam:FireServer(tonumber(getgenv().AirDashStamAmt) or 1.125, "dash", root.CFrame)
							end
						end)
						local startCF = root.CFrame
						local nudge = hit and Vector3.new(0, getgenv().AirDashUpNudge or 1, 0) or Vector3.zero
						local target = root.Position + unit * distance + nudge
						local targetCF = CFrame.lookAt(target, target + unit)
						pcall(function()
							character:PivotTo(targetCF * character:GetPivot():ToObjectSpace(root.CFrame):Inverse())
							root.AssemblyLinearVelocity = Vector3.zero
						end)
						getgenv().AirDashes = (getgenv().AirDashes or 0) + 1
						if getgenv().CustomDash == true then
							task.spawn(function()
								pcall(function()
									local moduleScript = getgenv().airDashEffectModule and getgenv().airDashEffectModule()
									if moduleScript and moduleScript:IsA("ModuleScript") then
										local effect = require(moduleScript)
										if type(effect) == "table" and type(effect.start) == "function" then
											effect:start(startCF, targetCF)
										end
									end
								end)
							end)
						end
						return true
					end
				end

				-- wrap PC_Activate of Backpack.InputCallbacks.<name> so dash / grab cooldowns can be removed or changed
				local hooked = setmetatable({}, { __mode = "k" })
				local function setField(handler, field, value)
					pcall(function()
						handler[field] = value
					end)
				end
				local function hookMove(name, field, kind)
					local backpack = localPlayer:FindFirstChildOfClass("Backpack")
					local callbacks = backpack and backpack:FindFirstChild("InputCallbacks")
					local moduleScript = callbacks and callbacks:FindFirstChild(name)
					if not moduleScript then
						return
					end
					local ok, result = pcall(require, moduleScript)
					if not ok or type(result) ~= "table" then
						return
					end
					local original = rawget(result, "PC_Activate")
					if type(original) ~= "function" then
						return
					end
					if hooked[result] == original then
						return
					end
					local function wrapped(handler, ...)
						if kind == "dash" then
							local airOrCustom = getgenv().AirDash == true or getgenv().GroundDash == true or getgenv().CustomDash == true
							if airOrCustom then
								local character = localPlayer.Character
								local humanoid = character and character:FindFirstChildOfClass("Humanoid")
								local onGround = humanoid ~= nil and humanoid.FloorMaterial ~= Enum.Material.Air
								local wanted = getgenv().GroundDash == true or getgenv().CustomDash == true or getgenv().AirDash == true and not onGround
								if (humanoid and humanoid.Health > 0) and wanted and getgenv().doAirDash() then
									return
								end
							end
							if getgenv().NoDashCooldown == true then
								setField(handler, field, false)
								local packed = table.pack(original(handler, ...))
								task.defer(setField, handler, field, false)
								return table.unpack(packed, 1, packed.n)
							end
							if getgenv().dashCdCustom() then
								local now = os.clock()
								local wait = math.max(tonumber(getgenv().DashCooldownMs) or 0, 0) / 1000
								if now - (getgenv().__DashLast or 0) < wait then
									return
								end
								getgenv().__DashLast = now
								getgenv().__DashCdHandler = handler
								setField(handler, field, false)
								local packed = table.pack(original(handler, ...))
								task.defer(setField, handler, field, false)
								return table.unpack(packed, 1, packed.n)
							end
							local packed = table.pack(original(handler, ...))
							return table.unpack(packed, 1, packed.n)
						end
						if getgenv().NoGrabCooldown ~= true then
							return original(handler, ...)
						end
						setField(handler, field, false)
						local packed = table.pack(original(handler, ...))
						task.defer(setField, handler, field, false)
						return table.unpack(packed, 1, packed.n)
					end
					result.PC_Activate = wrapped
					hooked[result] = wrapped
					getgenv().MoveCooldownClears = (getgenv().MoveCooldownClears or 0) + 1
				end
				getgenv().__TensenHookMove = hookMove

				-- keeps the hooks in and the cooldown fields cleared
				local alive = guard("MoveCooldowns")
				local lastRehook = 0
				RunService.Heartbeat:Connect(function()
					if not alive() then
						return
					end
					local dashWanted = getgenv().NoDashCooldown == true
					local dashAny = dashWanted or getgenv().dashCdCustom() or getgenv().AirDash == true or getgenv().GroundDash == true or getgenv().CustomDash == true
					local climbOn = getgenv().NoClimbCooldown == true
					local grabOn = getgenv().NoGrabCooldown == true
					if not (dashAny or climbOn or grabOn) then
						return
					end
					local character = localPlayer.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					if not humanoid or humanoid.Health <= 0 then
						return
					end
					if climbOn then
						pcall(function()
							local backpack = localPlayer:FindFirstChildOfClass("Backpack")
							local callbacks = backpack and backpack:FindFirstChild("InputCallbacks")
							local climb = callbacks and callbacks:FindFirstChild("Climb")
							if climb then
								local climbModule = require(climb)
								if type(climbModule) == "table" then
									climbModule.climbCD = false
								end
							end
						end)
					end
					if getgenv().dashCdCustom() and getgenv().__DashCdHandler then
						setField(getgenv().__DashCdHandler, "dashcd", false)
					end
					local now = os.clock()
					if now - lastRehook < (getgenv().MoveCooldownRehookRate or 0.5) then
						return
					end
					lastRehook = now
					if dashAny then
						hookMove("Dash", "dashcd", "dash")
					end
					if grabOn then
						hookMove("Carry", "carrycd", "grab")
						hookMove("Grip", "carrycd", "grab")
					end
				end)
			end

			-- auto trade (Trade tab, the guis only exist in the trade place)
			--   alt loop   request a trade with the main, wait for TradeGUI, add the picked items, accept, wait until it closes
			--   main loop  accept the pending trade, add the "main sends back" items, accept, wait
			-- tradeStockFor(isMain) is rebuilt from its callers. one call before pressing Accept couldn't be identified and is skipped.
			-- logs go to BMLog / print with "[Trade] "
			do
				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local HttpService = game:GetService("HttpService")
				local localPlayer = Players.LocalPlayer

				local function spawnLoop(name, body)
					local loops = getgenv().__TensenLoops
					if type(loops) ~= "table" then
						loops = {}
						getgenv().__TensenLoops = loops
					end
					local token = {}
					loops[name] = token
					task.spawn(function()
						task.wait()
						body(function()
							return loops[name] == token
						end)
					end)
				end

				local function log(fmt, ...)
					local text = "[Trade] " .. (select("#", ...) > 0 and string.format(fmt, ...) or fmt)
					local f = getgenv().BMLog
					if f then
						pcall(f, text)
					else
						print(text)
					end
				end

				local function toList(value)
					local list = {}
					local normalize = getgenv().NormalizeSelectedItems
					if type(normalize) == "function" then
						local ok, result = pcall(normalize, value)
						if ok and type(result) == "table" then
							return result
						end
					end
					if type(value) == "table" then
						for k, v in pairs(value) do
							if type(k) == "number" and type(v) == "string" then
								table.insert(list, v)
							elseif type(k) == "string" and v == true then
								table.insert(list, k)
							end
						end
					elseif type(value) == "string" then
						table.insert(list, value)
					end
					return list
				end

				local function pickedNames(isMain)
					return toList(isMain and getgenv().TradeItemMain or getgenv().TradeItemAlt or {})
				end

				-- see TradeInfo
				local function inventoryCount(item)
					local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)
					if not stats then
						return 0
					end
					local inventory = stats:FindFirstChild("Inventory")
					local value = inventory and inventory:FindFirstChild("Inventory")
					if not value or not value.Value or value.Value == "" then
						return 0
					end
					local ok, data = pcall(function()
						return HttpService:JSONDecode(value.Value)
					end)
					if not ok or type(data) ~= "table" then
						return 0
					end
					local function amountOf(v)
						if type(v) == "number" then
							return v
						end
						if type(v) == "table" and v.Amount then
							return v.Amount
						end
						return 1
					end
					if data[item] ~= nil then
						return amountOf(data[item])
					end
					local wanted = string.lower((string.gsub(item, "[%s%-_']", "")))
					for key, v in pairs(data) do
						if string.lower((string.gsub(tostring(key), "[%s%-_']", ""))) == wanted then
							return amountOf(v)
						end
					end
					return 0
				end

				local function isMainAccount()
					return localPlayer.Name == getgenv().TradeMainAccount
				end

				local function enabled()
					if not getgenv().AutoTrade then
						return false
					end
					if getgenv().TradeMainAccount == "" then
						return false
					end
					return true
				end

				-- how many items this side still has to send
				local function stockFor(isMain)
					local total = 0
					for _, name in ipairs(pickedNames(isMain)) do
						local count = inventoryCount(name)
						if isMain then
							count = math.min(count, tonumber(getgenv().TradeMainSendQty) or 1)
						end
						total += count
					end
					return total
				end
				if not getgenv().tradeStockFor then
					getgenv().tradeStockFor = stockFor
				end

				local function clickButton(button)
					if not button then
						return false
					end
					if firesignal then
						pcall(firesignal, button.Activated)
						pcall(firesignal, button.MouseButton1Click)
					end
					for _, signal in ipairs({ button.Activated, button.MouseButton1Click, button.MouseButton1Down }) do
						pcall(function()
							for _, connection in ipairs(getconnections(signal)) do
								connection:Fire()
							end
						end)
					end
					return true
				end

				local function tradeGui()
					local playerGui = localPlayer:FindFirstChild("PlayerGui")
					return playerGui and playerGui:FindFirstChild("TradeGUI")
				end

				local function requestTrade()
					local playerGui = localPlayer:FindFirstChild("PlayerGui")
					local menu = playerGui and playerGui:FindFirstChild("TradeMenu")
					menu = menu and menu:FindFirstChild("Main")
					menu = menu and menu:FindFirstChild("Menu")
					local send = menu and menu:FindFirstChild("SendTrades")
					local user = send and send:FindFirstChild("User")
					local input = user and user:FindFirstChild("Input")
					local trade = send and send:FindFirstChild("Trade")
					if not input or not input:IsA("TextBox") or not trade then
						return false
					end
					input.Text = getgenv().TradeMainAccount
					if input.Text ~= getgenv().TradeMainAccount then
						return false
					end
					log("requesting a trade with %s", tostring(getgenv().TradeMainAccount))
					return clickButton(trade)
				end

				-- accept every pending trade request
				local function acceptPending()
					local playerGui = localPlayer:FindFirstChild("PlayerGui")
					local menu = playerGui and playerGui:FindFirstChild("TradeMenu")
					menu = menu and menu:FindFirstChild("Main")
					menu = menu and menu:FindFirstChild("Menu")
					local pending = menu and menu:FindFirstChild("PendingTrades")
					local list = pending and pending:FindFirstChild("List")
					if not list then
						return false
					end
					local any = false
					for _, child in ipairs(list:GetChildren()) do
						if child:IsA("ImageLabel") then
							local accept = child:FindFirstChild("Accept")
							if accept then
								clickButton(accept)
								any = true
							end
						end
					end
					return any
				end

				-- add up to `count` of one item through ReplicatedStorage.trade
				local function addItem(name)
					if not name or name == "" then
						return 0
					end
					local have = inventoryCount(name)
					if have <= 0 then
						log("nothing to add - no '%s' in the inventory", tostring(name))
						return 0
					end
					local count = have
					if isMainAccount() then
						count = math.min(tonumber(getgenv().TradeMainSendQty) or 1, have)
					end
					local trade = ReplicatedStorage:FindFirstChild("trade")
					if not trade then
						log("ReplicatedStorage.trade remote is missing")
						return 0
					end
					local added = 0
					for _ = 1, count do
						if not getgenv().AutoTrade then
							break
						end
						if not tradeGui() then
							break
						end
						pcall(function()
							trade:FireServer({ { addItem = name } })
						end)
						added += 1
						getgenv().TradeItemsAdded = (getgenv().TradeItemsAdded or 0) + 1
						task.wait(getgenv().TradeAddDelay or 0.5)
					end
					log("added %d x %s", added, tostring(name))
					return added
				end

				local function addItems(isMain)
					local names = pickedNames(isMain)
					if #names == 0 then
						log("nothing is ticked for the %s to send", isMain and "MAIN" or "ALT")
						return 0
					end
					local total = 0
					for _, name in ipairs(names) do
						if not (getgenv().AutoTrade and tradeGui()) then
							break
						end

						total += addItem(name)
					end
					return total
				end

				local function acceptAndWait()
					local gui = tradeGui()
					local main = gui and gui:FindFirstChild("Main")
					if main then
						local player = main:FindFirstChild("Player")
						if player and player:IsA("ImageLabel") then
							task.wait(1)
							local buttons = main:FindFirstChild("Buttons")
							local accept = buttons and buttons:FindFirstChild("Accept")
							if accept then
								log("accepting the trade window")
								clickButton(accept)
							end
						end
					end
					local started = tick()
					repeat
						task.wait(0.2)
					until not (tradeGui() and getgenv().AutoTrade and not (tick() - started > 120))
				end

				-- alt side
				spawnLoop("TradeAlt", function(alive)
					while alive() do
						task.wait(1)
						if not enabled() then
							continue
						end
						if isMainAccount() then
							continue
						end
						if stockFor(false) <= 0 then
							continue
						end
						local started = tick()
						local timeout = (getgenv().TradeTimeout or 1) * 60
						if not requestTrade() then
							continue
						end
						local gui
						repeat
							task.wait(1)
							gui = tradeGui()
						until not (not (gui or tick() - started > timeout) and getgenv().AutoTrade)
						if not gui then
							log("%s never opened a window within %ds - retrying", tostring(getgenv().TradeMainAccount), math.floor(timeout))
						else
							addItems(false)
							acceptAndWait()
							getgenv().TradesCompleted = (getgenv().TradesCompleted or 0) + 1
							log("trade #%d done, %d left across %s", getgenv().TradesCompleted, stockFor(false), table.concat(pickedNames(false), ", "))
						end
					end
				end)

				-- main side
				spawnLoop("TradeMain", function(alive)
					while alive() do
						task.wait(1)
						if not enabled() then
							continue
						end
						if not isMainAccount() then
							continue
						end

						acceptPending()
						task.wait(1)
						if tradeGui() then
							addItems(true)
							acceptAndWait()
							getgenv().TradesCompleted = (getgenv().TradesCompleted or 0) + 1
							log("trade #%d done", getgenv().TradesCompleted)
						end
					end
				end)
			end

			-- auto craft bait (Fishing tab, "Craft Bait")
			--   loop, craft one bait (CraftingRemote:InvokeServer), batch, amounts, selected baits
			--   plan = min(amount, craftable, room), npc = workspace.NPCs[CraftNPCName or "Blacksmith Sen"]
			-- used by FarmStatusText: getgenv().craftableCount(bait), getgenv().craftWorkPending(), getgenv().baitCount
			-- missing pieces:
			--  * the fish rarity table (fish name -> "Common" | "Rare" | "Legendary") isn't in the code. getgenv().FishRarity is used if set, otherwise
			--    it looks for a ModuleScript in ReplicatedStorage with "fish" in the name (guess). with no table the loop says "no <rarity> fish to spend"
			--    and waits CraftRetryDelay (60s), it never sends a wrong CraftingRemote call
			--  * going to the blacksmith and crafting was missing after the "left before the trip could start" check: tween next to the npc, wait,
			--    craft the plan. nearCraftNPC = within CraftNPCRange (20) of the npc (guess)
			do
				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local HttpService = game:GetService("HttpService")
				local localPlayer = Players.LocalPlayer

				local function spawnLoop(name, body)
					local loops = getgenv().__TensenLoops
					if type(loops) ~= "table" then
						loops = {}
						getgenv().__TensenLoops = loops
					end
					local token = {}
					loops[name] = token
					task.spawn(function()
						task.wait()
						body(function()
							return loops[name] == token
						end)
					end)
				end

				local function log(msg)
					local f = getgenv().BMLog
					if f then
						pcall(f, msg)
					else
						print(msg)
					end
				end

				local function tweenState()
					return getgenv().__TensenTweenState or { Enabled = false }
				end
				local function stopTween()
					local f = getgenv().StopCurrentTween
					if f then
						pcall(f)
					end
				end
				local function tweenTo(opts)
					local f = getgenv().TweenToCFrame
					if type(f) == "function" then
						return f(opts)
					end
				end

				local function toList(value)
					local list = {}
					if type(value) == "table" then
						for k, v in pairs(value) do
							local name = type(k) == "string" and k or v
							if type(name) == "string" and v then
								table.insert(list, name)
							end
						end
					elseif type(value) == "string" then
						table.insert(list, value)
					end
					return list
				end

				local function inventoryData()
					local stats = ReplicatedStorage:FindFirstChild("Stats" .. localPlayer.Name)
					local inventory = stats and stats:FindFirstChild("Inventory") and stats.Inventory:FindFirstChild("Inventory")
					if not inventory or not inventory.Value or inventory.Value == "" then
						return nil
					end
					local ok, result = pcall(function()
						return HttpService:JSONDecode(inventory.Value)
					end)
					if ok and type(result) == "table" then
						return result
					end
					return nil
				end

				local function baitCount(name)
					if getgenv().baitCount then
						return getgenv().baitCount(name)
					end
					local data = inventoryData()
					return data and tonumber(data[name]) or 0
				end

				-- fish rarity (missing, see above)
				local RARITIES = { Common = true, Rare = true, Legendary = true }
				local function rarityOf(entry)
					if type(entry) == "string" then
						return entry
					end
					if type(entry) == "table" then
						if type(entry[1]) == "string" then
							return entry[1]
						end
						local r = entry.Rarity or entry.rarity
						if type(r) == "string" then
							return r
						end
					end
					return nil
				end
				local discovered, discoveredAt = nil, 0
				local function discoverRarity()
					local result = {}
					local scanned = 0
					local ok = pcall(function()
						for _, descendant in ipairs(ReplicatedStorage:GetDescendants()) do
							if not (descendant:IsA("ModuleScript") and string.find(descendant.Name:lower(), "fish")) then
								continue
							end

							scanned += 1
							if scanned > 40 then
								break
							end
							local loaded, module = pcall(require, descendant)
							if not (loaded and type(module) == "table") then
								continue
							end

							local function walk(t, depth)
								for k, v in pairs(t) do
									if type(k) == "string" then
										local r = rarityOf(v)
										if r and RARITIES[r] then
											result[k] = { r }
										elseif type(v) == "table" and depth < 2 then
											walk(v, depth + 1)
										end
									elseif type(v) == "table" and depth < 2 then
										walk(v, depth + 1)
									end
								end
							end
							walk(module, 0)
						end
					end)
					if ok and next(result) ~= nil then
						return result
					end
					return nil
				end
				local function rarityTable()
					local given = getgenv().FishRarity
					if type(given) == "table" and next(given) ~= nil then
						return given
					end
					if discovered == nil and tick() - discoveredAt > 60 then
						discoveredAt = tick()
						discovered = discoverRarity() or nil
						if discovered then
							log("[Craft] fish rarities read from the game's own fish module")
						end
					end
					return discovered or {}
				end

				-- numbers
				local function baitRarity(bait)
					return (string.gsub(bait, " Fish Bait", ""))
				end

				local function fishCount(rarity, inventory)
					local total = 0
					for name, entry in pairs(rarityTable()) do
						if rarityOf(entry) == rarity then
							total += tonumber(inventory[name]) or 0
						end
					end
					return total
				end

				local function craftableCount(bait, inventory)
					inventory = inventory or inventoryData()
					if type(inventory) ~= "table" then
						return 0
					end
					local rarity = baitRarity(bait)
					local spare = fishCount(rarity, inventory)
					if rarity == "Rare" then
						return math.floor(spare / 2)
					end
					return spare
				end
				getgenv().craftableCount = getgenv().craftableCount or craftableCount

				local function craftAmount(bait)
					local rarity = baitRarity(bait)
					if rarity == "Rare" then
						return getgenv().CraftAmountRare or 50
					end
					if rarity == "Legendary" then
						return getgenv().CraftAmountLegendary or 50
					end
					return getgenv().CraftAmountCommon or 50
				end

				local function toCraft(bait, inventory) -- (how many to make now, craftable, have)
					local max = getgenv().CraftMaxBait or 300
					local have = tonumber(inventory[bait]) or 0
					local room = max - have
					if room <= 0 then
						return 0, 0, have -- the original had an anti-tamper check here that always took this return
					end
					local craftable = craftableCount(bait, inventory)
					return math.min(craftAmount(bait), craftable, room), craftable, have
				end

				local function selectedBaits()
					return toList(getgenv().CurrentFishBaitToCraft)
				end

				-- builds the plan (the name is mine), used by the loop and craftWorkPending
				local function craftPlan()
					local inventory = inventoryData()
					if not inventory then
						return false
					end
					local plan, any = {}, false
					for _, bait in ipairs(selectedBaits()) do
						local n = toCraft(bait, inventory)
						if n > 0 then
							plan[bait] = n
							any = true
						end
					end
					if not any then
						return false
					end
					return true, plan
				end
				getgenv().craftWorkPending = getgenv().craftWorkPending or function()
					return (craftPlan()) == true
				end

				-- npc
				local function npcName()
					return tostring(getgenv().CraftNPCName or "Blacksmith Sen")
				end
				local function getCraftNPC()
					local npcs = workspace:FindFirstChild("NPCs")
					if not npcs then
						return nil
					end
					return npcs:FindFirstChild(getgenv().CraftNPCName or "Blacksmith Sen")
				end
				local function npcRoot(npc)
					return npc and (npc:FindFirstChild("HumanoidRootPart") or npc.PrimaryPart or npc:FindFirstChildWhichIsA("BasePart"))
				end
				local function nearCraftNPC() -- guess, not in the original
					local root = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
					local target = npcRoot(getCraftNPC())
					if not root or not target then
						return false
					end
					return (root.Position - target.Position).Magnitude <= (getgenv().CraftNPCRange or 20)
				end

				-- crafting
				local function craftOne(bait) -- returns ok, message, amount gained
					local rarity = baitRarity(bait)
					local inventory = inventoryData()
					if type(inventory) ~= "table" then
						return false, "inventory unreadable"
					end
					local have = tonumber(inventory[bait]) or 0
					if (getgenv().CraftMaxBait or 300) <= have then
						return false, "bait is full"
					end
					local spare = {}
					for name, entry in pairs(rarityTable()) do
						if rarityOf(entry) == rarity and (tonumber(inventory[name]) or 0) > 0 then
							table.insert(spare, name)
						end
					end
					table.sort(spare)
					if #spare == 0 then
						return false, string.format("no %s fish to spend", string.lower(rarity))
					end
					local extra = {}
					if rarity == "Rare" then
						local count = 0
						for _, name in ipairs(spare) do
							extra[name] = "Rare Fish"
							count += 1
							if count >= 2 then
								break
							end
						end
						if count < 2 then
							local n = tonumber(inventory[spare[1]]) or 0
							if n < 2 then
								return false, string.format("only %d rare fish spare, 2 are needed", n)
							end
						end
					else
						extra[rarity .. " Fish"] = spare[1]
					end
					local ok = pcall(function()
						ReplicatedStorage:WaitForChild("CraftingRemote"):InvokeServer({ BlueprintItem = bait, Method = "Craft", ExtraData = extra, Count = getgenv().CraftPerInvoke or 1 })
					end)
					if not ok then
						return false, "CraftingRemote rejected the call"
					end
					local deadline = tick() + (getgenv().CraftConfirmWait or 3)
					local now
					repeat
						task.wait(0.2)
						now = baitCount(bait)
					until now > have or tick() > deadline
					local gained = now - have
					if gained <= 0 then
						return false, "the server took the call but gave no bait back"
					end
					getgenv().BaitsCrafted = (getgenv().BaitsCrafted or 0) + gained
					return true, "crafted", gained
				end

				local function craftBatch(plan)
					local max = getgenv().CraftMaxBait or 300
					local total = 0
					local names = {}
					for name in pairs(plan) do
						table.insert(names, name)
					end
					table.sort(names)
					for _, bait in ipairs(names) do
						local want = plan[bait]
						local done, tries = 0, 0
						while done < want and tries < want do
							tries += 1
							if not getgenv().AutoCraftSelectedBait then
								break
							end
							if getgenv().CraftNeedsTrip ~= false and not nearCraftNPC() then
								log("[Craft] drifted away from " .. npcName() .. " - stopping this batch")
								break
							end
							if max <= baitCount(bait) then
								break
							end
							local ok, why, gained = craftOne(bait)
							if not ok then
								if getgenv().LogCrafting then
									log(string.format("[Craft] %s stopped after %d: %s", bait, done, tostring(why)))
								end
								break
							end
							done += gained or 1
							task.wait(getgenv().CraftDelay or 1)
						end
						total += done
						if done > 0 then
							-- the original keeps going after `if n3 > 0 then` but that part is missing, a log line is the safe choice
							log(string.format("[Craft] %s: made %d", bait, done))
						end
					end
					return total
				end

				-- the loop
				local function waitForFishing()
					if not (getgenv().IsFishing or getgenv().FishingBusy) then
						return
					end
					if getgenv().LogCrafting then
						log("[Craft] a cast is out - letting the fishing loop finish it before the trip")
					end
					local started = tick()
					local finished
					repeat
						task.wait(0.2)
						finished = not getgenv().FishingBusy or tick() - started > (getgenv().CraftFishingWait or 20)
						finished = finished or not getgenv().AutoCraftSelectedBait
					until finished
					if getgenv().FishingBusy or getgenv().IsFishing then
						getgenv().CraftCutIns = (getgenv().CraftCutIns or 0) + 1
						log(string.format("[Craft] the line was still out after %ds - reeling it in myself (x%d)", math.floor(tick() - started), getgenv().CraftCutIns))
						if getgenv().EndFishingSession then
							pcall(getgenv().EndFishingSession)
							task.wait(0.3)
						end
					elseif getgenv().LogCrafting then
						log(string.format("[Craft] the fishing loop finished on its own after %.1fs - session left clean", tick() - started))
					end
				end

				local function backOff(why)
					local delay = getgenv().CraftRetryDelay or 60
					getgenv().CraftRetryAt = tick() + delay
					log(string.format("%s - backing off for %ds", why, delay))
				end

				spawnLoop("CraftBait", function(alive)
					while alive() do
						task.wait(1)
						if not getgenv().AutoCraftSelectedBait then
							continue
						end
						if getgenv().CraftingTrip then
							continue
						end
						local character = localPlayer.Character
						local humanoid = character and character:FindFirstChildOfClass("Humanoid")
						if not (character and humanoid and not (humanoid.Health <= 0)) then
							continue
						end
						local ok, plan = craftPlan()
						if not ok then
							continue
						end
						if tick() < (getgenv().CraftRetryAt or 0) then
							continue
						end
						if tweenState().Enabled then
							if getgenv().LogCrafting and not getgenv().CraftWaitedTween then
								getgenv().CraftWaitedTween = true
								log("[Craft] something else is travelling - holding off until it lands")
							end
							continue
						end
						getgenv().CraftWaitedTween = false
						local near = getgenv().CraftNeedsTrip == false or nearCraftNPC()
						if near then
							-- craft in place
							getgenv().CraftingTrip = true
							waitForFishing()
							local made = 0
							local good, err = pcall(function()
								made = craftBatch(plan)
							end)
							getgenv().AlreadyTweenFishing = false
							getgenv().CraftingTrip = false
							if not good then
								log("[Craft] crafting in place broke: " .. tostring(err))
							elseif made == 0 then
								backOff("[Craft] nothing could be made here")
							end
							continue
						end
						if not getCraftNPC() then
							if getgenv().LogCrafting and not getgenv().CraftNPCMissingWarned then
								getgenv().CraftNPCMissingWarned = true
								log(string.format("[Craft] %s is not in workspace.NPCs right now", npcName()))
							end
							continue
						end
						getgenv().CraftNPCMissingWarned = false
						if not character:FindFirstChild("HumanoidRootPart") then
							continue
						end
						getgenv().CraftingTrip = true
						waitForFishing()
						local list = {}
						for bait, n in pairs(plan) do
							table.insert(list, string.format("%d x %s", n, bait))
						end
						table.sort(list)
						getgenv().CraftTrips = (getgenv().CraftTrips or 0) + 1
						log(string.format("[Craft] trip #%d to %s - %s", getgenv().CraftTrips, npcName(), table.concat(list, ", ")))
						local made = 0
						local good, err = pcall(function()
							stopTween()
							task.wait(0.1)
							local npc = getCraftNPC()
							if not npc or not npc.Parent then
								log(string.format("[Craft] %s left before the trip could start", npcName()))
								return
							end
							-- rebuilt middle of the trip: go next to the npc, then craft
							local root = npcRoot(npc)
							if root then
								tweenTo({ CFrame = root.CFrame, Speed = getgenv().TweenSpeedMaster or 110, StopDistance = 8, TeleportOnClose = true, TeleportDistance = 8 })
								repeat
									task.wait(0.2)
								until not tweenState().Enabled or not getgenv().AutoCraftSelectedBait
							end
							made = craftBatch(plan)
						end)
						pcall(stopTween)
						getgenv().AlreadyTweenFishing = false
						getgenv().CraftingTrip = false
						if not good then
							log(string.format("[Craft] trip #%d broke: %s - handing back to fishing", getgenv().CraftTrips, tostring(err)))
						elseif made == 0 then
							backOff(string.format("[Craft] trip #%d made nothing", getgenv().CraftTrips))
						else
							log(string.format("[Craft] trip #%d done (%d bait), handing back to fishing", getgenv().CraftTrips, made))
						end
					end
				end)
			end

			-- jump power keep
			do
				-- re-applies the "Jump Power" slider (getgenv().CustomJumpPower) on every new character
				-- the slider callback only sets the current character. a respawn resets JumpPower, so this hook keeps it (written from that,
				-- not copied from anything). KeepJumpPower = false turns it off. 0 = game default, like the slider says
				local Players = game:GetService("Players")
				local localPlayer = Players.LocalPlayer

				local function apply(character)
					task.wait()
					if getgenv().KeepJumpPower == false then
						return
					end
					local power = tonumber(getgenv().CustomJumpPower) or 0
					if power <= 0 then
						return
					end
					local humanoid = character and (character:FindFirstChild("Humanoid") or character:WaitForChild("Humanoid", 5))
					if humanoid then
						pcall(function()
							humanoid.JumpPower = power
						end)
					end
				end

				-- a second load replaces the connection instead of adding another
				local old = getgenv().__TensenJumpPowerConn
				if old then
					pcall(function()
						old:Disconnect()
					end)
				end
				getgenv().__TensenJumpPowerConn = localPlayer.CharacterAdded:Connect(function(character)
					task.spawn(apply, character)
				end)
			end

			-- esp renderer (Player ESP + Island ESP)
			-- the ESP tab and ESPIsTeammate are in the hub, the renderer wasn't. this has:
			--   the "TensenESP" ScreenGui, theme lookup, getInstance, corner/colour helpers (rainbow / menu accent), text width cache,
			--   distance format, card builder, card scale, bar width, gradients, ESPSetProp, card updater, per-player entries + PlayerRemoving cleanup
			--   the RenderStepped step: refresh-rate gate, idle gate, player loop (card, highlight, tracer), island loop (card, pin, ring),
			--   then the battle royale markers
			--   stamina, held tool name, fruit text, island position
			-- rebuilt by hand (marked): second half of the card updater (hp fill, alpha / scale / glow / gradient, stamina colours),
			-- the non-tracer branch of the player loop, the island pin / ring builder, the bag-fruit lookup
			-- other code gets to the cards through getgenv().__TensenESPApi
			do
				local Players = game:GetService("Players")
				local RunService = game:GetService("RunService")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local TextService = game:GetService("TextService")
				local localPlayer = Players.LocalPlayer

				getgenv().ESP = getgenv().ESP or {}

				-- reload: drop the old step and clean up its gui
				if getgenv().__TensenESPConn then
					pcall(function()
						getgenv().__TensenESPConn:Disconnect()
					end)
					getgenv().__TensenESPConn = nil
				end
				if getgenv().__TensenESPRemoving then
					pcall(function()
						getgenv().__TensenESPRemoving:Disconnect()
					end)
					getgenv().__TensenESPRemoving = nil
				end

				local hui = nil
				pcall(function()
					hui = gethui and gethui()
				end)
				if not hui then
					hui = game:GetService("CoreGui")
				end

				local oldGui = hui:FindFirstChild("TensenESP")
				if oldGui then
					oldGui:Destroy()
				end

				local gui = Instance.new("ScreenGui")
				gui.Name = "TensenESP"
				gui.IgnoreGuiInset = true
				gui.ResetOnSpawn = false
				gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
				gui.DisplayOrder = 5

				local parented = pcall(function()
					gui.Parent = hui
				end)
				if not parented or not gui.Parent then
					gui.Parent = localPlayer:WaitForChild("PlayerGui")
				end

				local tracersFrame = Instance.new("Frame")
				tracersFrame.Name = "Tracers"
				tracersFrame.BackgroundTransparency = 1
				tracersFrame.Size = UDim2.fromScale(1, 1)
				tracersFrame.ZIndex = 1
				tracersFrame.Parent = gui

				-- theme + small helpers
				local PALETTE = {
					CardBg = Color3.fromRGB(24, 24, 24),
					Border = Color3.fromRGB(35, 35, 35),
					White = Color3.fromRGB(255, 255, 255),
					TextGray = Color3.fromRGB(154, 154, 154),
					TrackBg = Color3.fromRGB(43, 43, 43),
					Accent = Color3.fromRGB(167, 200, 244),
				}
				local HP_GREEN = Color3.fromRGB(105, 166, 124)
				local HP_AMBER = Color3.fromRGB(190, 154, 84)
				local HP_RED = Color3.fromRGB(190, 99, 99)
				local STAMINA_BLUE = Color3.fromRGB(110, 170, 230)
				local FOLLOW = { CardBg = "CardBgColor", White = "CardTextColor", TextGray = "CardSubColor", TrackBg = "CardTrackColor" }
				local theme = PALETTE

				-- colour of a card part. "Card follow theme" off = your own card colours (ESP.CardBgColor / CardTextColor / CardSubColor / CardTrackColor)
				local function themeColor(name)
					local esp = getgenv().ESP
					if esp and esp.CardFollowTheme == false and FOLLOW[name] then
						return getgenv().ESPColor(FOLLOW[name])
					end
					return theme and theme[name] or PALETTE[name]
				end

				-- called every 0.5s by the render step: follow the ui library's current theme
				local function refreshTheme()
					local lib = getgenv().TensenUILib
					local name = lib and lib.GetTheme and lib:GetTheme()
					theme = lib and lib.Themes and name and lib.Themes[name] or PALETTE
				end

				local function getInstance(className, props)
					local inst = Instance.new(className)
					for k, v in pairs(props) do
						if k ~= "Parent" then
							inst[k] = v
						end
					end
					inst.Parent = props.Parent
					return inst
				end

				local function corner(parent, radius)
					getInstance("UICorner", { CornerRadius = UDim.new(0, radius), Parent = parent })
				end

				-- marker colour: rainbow, menu accent, or your colour for `key`
				local function colorFor(key, phase, espOverride)
					local esp = espOverride or getgenv().ESP
					if esp.Rainbow then
						return Color3.fromHSV((tick() * 0.12 + (phase or 0)) % 1, 0.5, 1)
					end
					if esp.MenuAccent then
						return themeColor("Accent")
					end
					return getgenv().ESPColor(key)
				end

				-- text width, cached (4000 entries max)
				local widthCache = {}
				local widthCount = 0
				local function textWidth(text, size, font)
					local key = text .. "|" .. size .. "|" .. font.Name
					local cached = widthCache[key]
					if cached then
						return cached
					end
					local ok, result = pcall(function()
						return TextService:GetTextSize(text, size, font, Vector2.new(1000, 100))
					end)
					local x = ok and result.X or #text * size * 0.55
					if widthCount < 4000 then
						widthCount += 1
						widthCache[key] = x
					end
					return x
				end

				local function formatDistance(studs)
					if studs >= 1000 then
						return string.format("%.1fk studs", studs / 1000)
					end
					return string.format("%d studs", math.floor(studs))
				end

				-- ESPSetProp(instance, property, value): only writes when the value changed
				local propCache = setmetatable({}, { __mode = "k" })
				local function setProp(inst, prop, value)
					local c = propCache[inst]
					if not c then
						c = {}
						propCache[inst] = c
					end
					if c[prop] ~= value then
						c[prop] = value
						inst[prop] = value
					end
				end
				getgenv().ESPSetProp = setProp

				-- "Card Size" slider (percent), phones start at 60
				local function cardScale()
					return math.clamp(tonumber(getgenv().ESP.CardSize) or (getgenv().ESPIsMobile() and 60 or 100), 30, 150) / 100
				end

				-- width of a card's hp / stamina bars
				local function barWidth(card)
					return math.clamp(card.width - 20, 24, 70)
				end

				-- read through getfenv() on purpose
				local keypoint = getfenv().NumberSequenceKeypoint
				local SPIN = NumberSequence.new({
					keypoint.new(0, 0.8),
					keypoint.new(0.38, 0.8),
					keypoint.new(0.5, 0),
					keypoint.new(0.62, 0.8),
					keypoint.new(1, 0.8),
				})
				local FLAT = NumberSequence.new(0.55)

				-- the card
				local function newCard(withBars)
					local holder = getInstance("Frame", {
						AnchorPoint = Vector2.new(0.5, 1),
						BackgroundTransparency = 1,
						Size = UDim2.fromOffset(100, 34),
						Visible = false,
						ZIndex = 5,
						Parent = gui,
					})
					local scale = getInstance("UIScale", { Scale = 0.85, Parent = holder })
					local glow = getInstance("Frame", {
						Position = UDim2.fromOffset(-1, -1),
						Size = UDim2.new(1, 2, 1, 2),
						BackgroundColor3 = themeColor("Accent"),
						BackgroundTransparency = 1,
						BorderSizePixel = 0,
						ZIndex = 5,
						Parent = holder,
					})
					corner(glow, 7)
					local grad = getInstance("UIGradient", { Parent = glow })
					local body = getInstance("CanvasGroup", {
						Size = UDim2.fromScale(1, 1),
						BackgroundColor3 = themeColor("CardBg"),
						BorderSizePixel = 0,
						GroupTransparency = 1,
						ZIndex = 6,
						Parent = holder,
					})
					corner(body, 6)
					local strip = getInstance("Frame", {
						Size = UDim2.new(0, 3, 1, 0),
						BackgroundColor3 = themeColor("Accent"),
						BorderSizePixel = 0,
						ZIndex = 7,
						Parent = body,
					})
					local title = getInstance("TextLabel", {
						BackgroundTransparency = 1,
						Font = Enum.Font.GothamBold,
						Text = "",
						TextColor3 = themeColor("White"),
						TextXAlignment = Enum.TextXAlignment.Left,
						Position = UDim2.fromOffset(10, 5),
						Size = UDim2.new(1, -16, 0, 14),
						ZIndex = 7,
						Parent = body,
					})
					local sub = getInstance("TextLabel", {
						BackgroundTransparency = 1,
						Font = Enum.Font.Gotham,
						Text = "",
						TextColor3 = themeColor("TextGray"),
						TextXAlignment = Enum.TextXAlignment.Left,
						Position = UDim2.fromOffset(10, 20),
						Size = UDim2.new(1, -16, 0, 12),
						ZIndex = 7,
						Parent = body,
					})
					local track, fill, track2, fill2
					if withBars then
						track = getInstance("Frame", {
							BackgroundColor3 = themeColor("TrackBg"),
							BorderSizePixel = 0,
							Position = UDim2.fromOffset(10, 0),
							Size = UDim2.fromOffset(70, 2),
							ZIndex = 7,
							Parent = body,
						})
						corner(track, 2)
						fill = getInstance("Frame", { BackgroundColor3 = HP_GREEN, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), ZIndex = 8, Parent = track })
						corner(fill, 2)
						track2 = getInstance("Frame", {
							BackgroundColor3 = themeColor("TrackBg"),
							BorderSizePixel = 0,
							Position = UDim2.fromOffset(10, 0),
							Size = UDim2.fromOffset(70, 2),
							ZIndex = 7,
							Parent = body,
						})
						corner(track2, 2)
						fill2 = getInstance("Frame", { BackgroundColor3 = STAMINA_BLUE, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), ZIndex = 8, Parent = track2 })
						corner(fill2, 2)
					end
					return {
						holder = holder,
						scale = scale,
						glow = glow,
						grad = grad,
						body = body,
						strip = strip,
						title = title,
						sub = sub,
						track = track,
						fill = fill,
						track2 = track2,
						fill2 = fill2,
						alpha = 0,
						hp = 1,
						stam = 1,
						width = 100,
					}
				end

				local function hpColor(fraction)
					if fraction >= 0.6 then
						return HP_GREEN
					elseif fraction >= 0.3 then
						return HP_AMBER
					end
					return HP_RED
				end

				-- per-frame update of one card:
				--   card, pos (Vector2, bottom center), target alpha (1 on screen / 0), accent colour, phase, title, sub text, hp (0..1 or nil), dt,
				--   size factor, ESP table override (battle royale) or nil, stamina (0..1 or nil), team colour (or nil)
				local function updateCard(card, pos, target, color, phase, title, sub, hp, dt, sizeFactor, espOverride, stamina, teamColor)
					local esp = getgenv().ESP
					local esp = espOverride or esp
					card.alpha += (target - card.alpha) * math.min(1, dt * 12)
					if card.alpha < 0.01 and target == 0 then
						card.alpha = 0
						setProp(card.holder, "Visible", false)
						return
					end

					local textSize = math.clamp(tonumber(esp.TextSize) or 12, 9, 18)
					local subSize = math.max(textSize - 2, 8)

					-- text + width, only when something changed
					if title ~= card.lastTitle or sub ~= card.lastSub or textSize ~= card.lastSize then
						card.lastTitle = title
						card.lastSub = sub
						card.lastSize = textSize
						card.title.Text = title or ""
						card.sub.Text = sub or ""
						card.title.TextSize = textSize
						card.sub.TextSize = subSize
						-- rebuilt: only the end of the width math survived, math.max(max(titleWidth, subWidth) + 22, 70)
						local titleW = title and title ~= "" and textWidth(title, textSize, Enum.Font.GothamBold) or 0
						local subW = sub and sub ~= "" and textWidth(sub, subSize, Enum.Font.Gotham) or 0
						card.width = math.max(math.max(titleW, subW) + 22, 70)
					end

					-- layout: title / sub Visible, Position, Size, running y, holder size. the bars' y step is rebuilt (5 = 2px bar + 3px gap)
					local y = 5
					setProp(card.title, "Visible", title ~= nil)
					if title ~= nil then
						setProp(card.title, "Position", UDim2.fromOffset(10, y))
						setProp(card.title, "Size", UDim2.new(1, -16, 0, textSize + 2))
						y = y + textSize + 3
					end
					setProp(card.sub, "Visible", sub ~= nil)
					if sub ~= nil then
						setProp(card.sub, "Position", UDim2.fromOffset(10, y))
						setProp(card.sub, "Size", UDim2.new(1, -16, 0, subSize + 2))
						y = y + subSize + 3
					end
					local trackW = barWidth(card)
					if card.track then
						setProp(card.track, "Visible", hp ~= nil)
						if hp ~= nil then
							-- rebuilt: hp bar (smoothed fill, green / amber / red)
							card.hp += (hp - card.hp) * math.min(1, dt * 8)
							local shown = math.clamp(card.hp, 0, 1)
							setProp(card.track, "Position", UDim2.fromOffset(10, y + 1))
							setProp(card.track, "Size", UDim2.fromOffset(trackW, 2))
							setProp(card.fill, "Size", UDim2.fromScale(shown, 1))
							setProp(card.fill, "BackgroundColor3", hpColor(shown))
							setProp(card.track, "BackgroundColor3", themeColor("TrackBg"))
							y = y + 5
						end
					end
					if card.track2 then
						setProp(card.track2, "Visible", stamina ~= nil)
						if stamina ~= nil then
							-- smoothed stamina, track / fill position and size
							local current = card.stam
							card.stam = current + (stamina - current) * math.min(1, dt * 8)
							local shown = math.clamp(card.stam, 0, 1)
							setProp(card.track2, "Position", UDim2.fromOffset(10, y + 1))
							setProp(card.track2, "Size", UDim2.fromOffset(trackW, 2))
							setProp(card.fill2, "Size", UDim2.fromScale(shown, 1))
							-- rebuilt: colours (only the 0.4 lerp toward black for the team colour and the ESPColor lookup survived)
							setProp(card.fill2, "BackgroundColor3", getgenv().ESPColor("PlayerStaminaColor"))
							setProp(card.track2, "BackgroundColor3", teamColor and teamColor:Lerp(Color3.new(0, 0, 0), 0.4) or themeColor("TrackBg"))
							y = y + 5
						end
					end
					setProp(card.holder, "Size", UDim2.fromOffset(card.width, y + 3))
					setProp(card.holder, "Position", UDim2.fromOffset(pos.X, pos.Y))
					setProp(card.holder, "Visible", true)

					-- appearance: easing (1 - alpha)^2, UIScale, GroupTransparency = 1 - 0.94 * eased, CardBg lookup.
					-- rebuilt: the exact UIScale value (0.85 pop-in * size factor * Card Size) and everything after (colours, glow, gradient), from the builder's start values
					local alpha = card.alpha
					local eased = 1 - (1 - alpha) * (1 - alpha)
					setProp(card.scale, "Scale", (0.85 + 0.15 * eased) * (sizeFactor or 1) * cardScale())
					setProp(card.body, "GroupTransparency", 1 - eased * 0.94)
					setProp(card.body, "BackgroundColor3", themeColor("CardBg"))
					setProp(card.title, "TextColor3", themeColor("White"))
					setProp(card.sub, "TextColor3", themeColor("TextGray"))
					setProp(card.strip, "BackgroundColor3", color)
					setProp(card.glow, "BackgroundColor3", color)
					local pulse = esp.Pulse and (math.sin(phase * 3) + 1) / 2 or 0.5
					setProp(card.glow, "BackgroundTransparency", 1 - alpha * (0.3 + 0.2 * pulse))
					if esp.AnimatedBorder then
						setProp(card.grad, "Transparency", SPIN)
						setProp(card.grad, "Rotation", (phase * 90) % 360)
					else
						setProp(card.grad, "Transparency", FLAT)
						setProp(card.grad, "Rotation", 0)
					end
				end

				-- per-player entries
				local entries = {}

				local function removePlayerEntry(player)
					local e = entries[player]
					if not e then
						return
					end
					pcall(function()
						e.card.holder:Destroy()
					end)
					pcall(function()
						e.hl:Destroy()
					end)
					pcall(function()
						e.line:Destroy()
					end)
					pcall(function()
						e.dot:Destroy()
					end)
					entries[player] = nil
				end

				local removingConn = Players.PlayerRemoving:Connect(removePlayerEntry)

				local function getPlayerEntry(player)
					local e = entries[player]
					if e then
						return e
					end
					e = { card = newCard(true), lineAlpha = 0 }
					e.hl = getInstance("Highlight", {
						DepthMode = Enum.HighlightDepthMode.AlwaysOnTop,
						Enabled = false,
						FillTransparency = 1,
						OutlineTransparency = 1,
						Parent = gui,
					})
					e.line = getInstance("Frame", {
						AnchorPoint = Vector2.new(0.5, 0.5),
						BorderSizePixel = 0,
						BackgroundTransparency = 1,
						Visible = false,
						ZIndex = 2,
						Parent = tracersFrame,
					})
					e.dot = getInstance("Frame", {
						AnchorPoint = Vector2.new(0.5, 0.5),
						BorderSizePixel = 0,
						Size = UDim2.fromOffset(6, 6),
						BackgroundTransparency = 1,
						Visible = false,
						ZIndex = 3,
						Parent = tracersFrame,
					})
					corner(e.dot, 3)
					entries[player] = e
					return e
				end

				-- player card text helpers
				local function isTeammate(player)
					local f = getgenv().ESPIsTeammate
					if not f then
						return false
					end
					local ok, result = pcall(f, player)
					return ok and result == true
				end

				-- the player's data folder (same as in ESPIsTeammate)
				local function statsFolder(player)
					return ReplicatedStorage:FindFirstChild("Stats" .. player.Name)
				end

				-- stamina and max stamina of a player, or nil
				local function staminaOf(player)
					local folder = statsFolder(player)
					local stamina = folder and folder:FindFirstChild("Stamina")
					if not stamina then
						return nil
					end
					local ok, value, maximum = pcall(function()
						return stamina.Value, stamina.MaxValue
					end)
					if not ok or type(value) ~= "number" or type(maximum) ~= "number" or maximum <= 0 then
						return nil
					end
					return value, maximum
				end

				-- first Tool in the character ("Show Weapon" text)
				local function weaponText(player)
					local character = player.Character
					if not character then
						return nil
					end
					for _, child in ipairs(character:GetChildren()) do
						if child:IsA("Tool") then
							return child.Name
						end
					end
					return nil
				end

				-- the fruit a player ate, from their data folder. stat names come from getgenv().ESPFruitStatKeys (not in the code),
				-- without it every child with "fruit" in the name is tried
				local function stringStat(child)
					local ok, value = pcall(function()
						return child.Value
					end)
					if ok and type(value) == "string" and value ~= "" and string.lower(value) ~= "none" then
						return value
					end
					return nil
				end

				local function eatenFruit(folder)
					if not folder then
						return nil
					end
					local containers = { folder, folder:FindFirstChild("Stats") }
					for _, container in ipairs(containers) do
						if not container then
							continue
						end

						for _, key in ipairs(getgenv().ESPFruitStatKeys or {}) do
							local child = container:FindFirstChild(key)
							if child then
								local value = stringStat(child)
								if value then
									return value
								end
							end
						end
					end
					for _, container in ipairs(containers) do
						if not container then
							continue
						end

						for _, child in ipairs(container:GetChildren()) do
							local name = string.lower(child.Name)
							if not string.find(name, "fruit", 1, true) then
								continue
							end

							local skip = false
							for _, word in ipairs(getgenv().ESPFruitStatSkip or {}) do
								if string.find(name, word, 1, true) then
									skip = true
									break
								end
							end
							if not skip then
								local value = stringStat(child)
								if value then
									return value
								end
							end
						end
					end
					return nil
				end

				-- a fruit tool in the character ("held") or backpack ("bag"), fruit names from getgenv().fruitNameSet()
				local function toolFruit(container)
					if not container then
						return nil
					end
					local ok, names = pcall(getgenv().fruitNameSet)
					if not ok or type(names) ~= "table" then
						return nil
					end
					for _, child in ipairs(container:GetChildren()) do
						if child:IsA("Tool") and names[child.Name] then
							return child.Name
						end
					end
					return nil
				end

				local fruitCache = setmetatable({}, { __mode = "k" })

				-- fruit line of the card, cached 5s per player
				local function fruitText(player)
					local cached = fruitCache[player]
					if cached and tick() - cached.at < 5 then
						return cached.text
					end
					local text = nil
					pcall(function()
						local folder = statsFolder(player)
						local eaten = eatenFruit(folder)
						if eaten then
							text = eaten
							return
						end
						local held = toolFruit(player.Character)
						if held then
							text = held .. " (held)"
							return
						end
						if getgenv().ESP.PlayerFruitEatenOnly ~= false then
							return
						end
						if game.PlaceId == 11424731604 then
							return
						end
						local bag = toolFruit(player:FindFirstChildOfClass("Backpack"))
						if bag then
							text = bag .. " (bag)"
						end
					end)
					fruitCache[player] = { at = tick(), text = text }
					return text
				end

				-- island entries
				local islandEntries = {}

				local function getIslandEntry(model)
					local e = islandEntries[model]
					if e then
						return e
					end
					e = { card = newCard(false), at = 0 }
					-- rebuilt: pin and ring, sizes match what the render step sets every frame
					e.pin = getInstance("Frame", {
						AnchorPoint = Vector2.new(0.5, 0.5),
						BorderSizePixel = 0,
						Size = UDim2.fromOffset(8, 8),
						BackgroundTransparency = 1,
						Visible = false,
						ZIndex = 3,
						Parent = tracersFrame,
					})
					corner(e.pin, 4)
					e.ring = getInstance("Frame", {
						AnchorPoint = Vector2.new(0.5, 0.5),
						BorderSizePixel = 0,
						Size = UDim2.fromOffset(8, 8),
						BackgroundTransparency = 1,
						Visible = false,
						ZIndex = 2,
						Parent = tracersFrame,
					})
					corner(e.ring, 20)
					e.ringStroke = getInstance("UIStroke", { Thickness = 1.5, Parent = e.ring })
					islandEntries[model] = e
					return e
				end

				-- where the island marker goes: center of the bounding box, raised by half its height + 10
				local function islandPosition(model)
					local ok, boxCFrame, boxSize = pcall(function()
						local cf, size = model:GetBoundingBox()
						return cf, size
					end)
					if ok and boxCFrame and boxSize and boxSize.Magnitude > 1 then
						return boxCFrame.Position + Vector3.new(0, boxSize.Y / 2 + 10, 0)
					end
					local pivotOk, pivot = pcall(function()
						return model:GetPivot()
					end)
					return pivotOk and pivot and pivot.Position or nil
				end

				-- shared api for the battle royale markers
				local api = {
					gui = gui,
					tracersFrame = tracersFrame,
					newCard = newCard,
					updateCard = updateCard,
					colorFor = colorFor,
					formatDistance = formatDistance,
					setProp = setProp,
					getInstance = getInstance,
					corner = corner,
					themeColor = themeColor,
					cardScale = cardScale,
				}
				getgenv().__TensenESPApi = api

				-- the render step
				local idleSince = nil
				local accumulated = 0
				local lastStep = 0
				local lastHousekeeping = 0
				local camera = workspace.CurrentCamera

				local function step(dtFrame)
					local esp = getgenv().ESP
					local currentCamera = workspace.CurrentCamera or camera
					if not (esp and currentCamera) then
						return
					end

					-- idle gate: with everything off the step keeps going for 1.5s (cards fade out), then does nothing
					if esp.Players or esp.Islands or esp.Chests or esp.Medals or esp.Vendings or esp.Trainers then
						idleSince = nil
					else
						idleSince = idleSince or tick()
						if tick() - idleSince > 1.5 then
							return
						end
					end

					local now = tick()
					local refreshRate = math.clamp(tonumber(esp.RefreshRate) or 60, 1, 240)
					accumulated += dtFrame
					if now - lastStep < 1 / refreshRate - 0.0005 then
						return
					end
					local dt = accumulated
					lastStep = now
					accumulated = 0

					if now - lastHousekeeping > 0.5 then
						lastHousekeeping = now
						refreshTheme()
					end

					local viewportSize = currentCamera.ViewportSize
					local character = localPlayer.Character
					local hrp = character and character:FindFirstChild("HumanoidRootPart")
					local position = hrp and hrp.Position or currentCamera.CFrame.Position
					local pulse = esp.Pulse and (math.sin(now * 3) + 1) / 2 or 0.5
					local pulseStep = math.floor(pulse * 6 + 0.5) / 6

					local function project(worldPos)
						local screenPos, onScreen = currentCamera:WorldToViewportPoint(worldPos)
						onScreen = onScreen and screenPos.Z > 0 and screenPos.X > -50 and screenPos.X < viewportSize.X + 50 and screenPos.Y > -50 and screenPos.Y < viewportSize.Y + 50
						return Vector2.new(screenPos.X, screenPos.Y), onScreen
					end

					-- players
					local seen = {}
					local maxDist = tonumber(esp.PlayerMaxDist) or 3000
					for index, player in ipairs(Players:GetPlayers()) do
						if player == localPlayer then
							continue
						end

						seen[player] = true
						local e = getPlayerEntry(player)
						local char = player.Character
						local root = char and char:FindFirstChild("HumanoidRootPart")
						local humanoid = char and char:FindFirstChildOfClass("Humanoid")
						local head = char and char:FindFirstChild("Head")
						local team = esp.PlayerTeamESP ~= false and isTeammate(player)
						local color
						if team then
							color = getgenv().ESPColor("PlayerTeamColor")
						end
						color = color or (esp.PlayerEnemyESP and getgenv().ESPColor("PlayerEnemyColor")) or colorFor("PlayerColor", index * 0.07)
						local teamColor = team and color or nil
						local alive = root and humanoid and humanoid.Health > 0
						local distance = alive and (root.Position - position).Magnitude or math.huge
						local shown = esp.Players and alive and distance <= maxDist

						if not shown and e.card.alpha < 0.01 and e.lineAlpha < 0.01 then
							setProp(e.card.holder, "Visible", false)
							setProp(e.hl, "Enabled", false)
							setProp(e.line, "Visible", false)
							setProp(e.dot, "Visible", false)
							continue
						end

						local onScreenAlpha = 0
						local screen = Vector2.zero
						if shown then
							local anchor = (head and head.Position or root.Position) + Vector3.new(0, 2.6, 0)
							local onScreen
							screen, onScreen = project(anchor)
							if onScreen then
								onScreenAlpha = 1
							end
						end

						local displayName = player.DisplayName
						local name = player.Name
						if getgenv().StreamerNamesFor then
							local ok, shownName, shownUser = pcall(getgenv().StreamerNamesFor, player)
							if ok and shownName then
								displayName = shownName
								name = shownUser or shownName
							end
						end
						local title = esp.PlayerName and displayName or nil
						local parts = {}
						if esp.PlayerName and displayName ~= name then
							table.insert(parts, "@" .. name)
						end
						if esp.PlayerDistance and alive then
							table.insert(parts, formatDistance(distance))
						end
						if shown and esp.PlayerFruit then
							local fruit = fruitText(player)
							if fruit then
								table.insert(parts, fruit)
							end
						end
						if shown and esp.PlayerWeapon then
							local weapon = weaponText(player)
							if weapon then
								table.insert(parts, weapon)
							end
						end
						local sub = #parts > 0 and table.concat(parts, "  \u{2022}  ") or nil
						if title or sub then
							displayName = title
						end
						local hp = esp.PlayerHealth and humanoid and humanoid.MaxHealth > 0 and humanoid.Health / humanoid.MaxHealth or nil
						local stamina = nil
						if shown and esp.PlayerStamina then
							local value, maximum = staminaOf(player)
							if value then
								stamina = math.clamp(value / maximum, 0, 1)
							end
						end
						local sizeFactor = alive and math.clamp(1.1 - distance / 5000, 0.8, 1.1) or 1
						updateCard(e.card, screen - Vector2.new(0, 4), onScreenAlpha, color, now + index, displayName, sub, hp, dt, sizeFactor, nil, stamina, teamColor)

						-- highlight
						if shown and esp.PlayerHighlight then
							if e.hl.Adornee ~= char then
								e.hl.Adornee = char
							end
							setProp(e.hl, "Enabled", true)
							setProp(e.hl, "FillColor", color)
							setProp(e.hl, "OutlineColor", color:Lerp(Color3.new(1, 1, 1), 0.35))
							setProp(e.hl, "FillTransparency", 0.55 + pulseStep * 0.25)
							setProp(e.hl, "OutlineTransparency", 0.05 + pulseStep * 0.25)
						else
							setProp(e.hl, "Enabled", false)
						end

						-- tracer (rebuilt: the "tracers off / card off screen" branch fades the line out)
						e.lineAlpha += (((esp.PlayerTracers and onScreenAlpha == 1) and 1 or 0) - e.lineAlpha) * math.min(1, dt * 12)
						if e.lineAlpha > 0.01 and root then
							local target = project(root.Position - Vector3.new(0, 3, 0))
							local origin = Vector2.new(viewportSize.X / 2, viewportSize.Y - 2)
							local offset = target - origin
							setProp(e.line, "Visible", true)
							setProp(e.dot, "Visible", true)
							setProp(e.line, "Position", UDim2.fromOffset((origin.X + target.X) / 2, (origin.Y + target.Y) / 2))
							setProp(e.line, "Size", UDim2.fromOffset(offset.Magnitude, 1.5))
							setProp(e.line, "Rotation", math.deg(math.atan2(offset.Y, offset.X)))
							setProp(e.line, "BackgroundColor3", color)
							setProp(e.line, "BackgroundTransparency", 1 - e.lineAlpha * (0.45 + pulse * 0.2))
							setProp(e.dot, "Position", UDim2.fromOffset(target.X, target.Y))
							setProp(e.dot, "BackgroundColor3", color)
							setProp(e.dot, "BackgroundTransparency", 1 - e.lineAlpha)
						else
							setProp(e.line, "Visible", false)
							setProp(e.dot, "Visible", false)
						end
					end
					for player in pairs(entries) do
						if not seen[player] then
							removePlayerEntry(player)
						end
					end

					-- islands
					local islands = workspace:FindFirstChild("Islands")
					local liveIslands = {}
					local islandMax = tonumber(esp.IslandMaxDist) or 30000
					if islands then
						for index, model in ipairs(islands:GetChildren()) do
							liveIslands[model] = true
							local e = getIslandEntry(model)
							if not esp.Islands and e.card.alpha < 0.01 then
								setProp(e.card.holder, "Visible", false)
								setProp(e.pin, "Visible", false)
								setProp(e.ring, "Visible", false)
								continue
							end

							if esp.Islands and (now - e.at > 10 or not e.pos) then
								e.at = now
								e.pos = islandPosition(model) or e.pos
							end
							local color = colorFor("IslandColor", index * 0.05)
							local screen = Vector2.zero
							local onScreenAlpha = 0
							local distance = 0
							if esp.Islands and e.pos then
								distance = (e.pos - position).Magnitude
								if distance <= islandMax then
									local onScreen
									screen, onScreen = project(e.pos)
									if onScreen then
										onScreenAlpha = 1
									end
								end
							end
							local sizeFactor = math.clamp(1.05 - distance / 40000, 0.8, 1.05)
							updateCard(e.card, screen - Vector2.new(0, 12), onScreenAlpha, color, now + index * 0.3, model.Name, esp.IslandDistance and formatDistance(distance) or nil, nil, dt, sizeFactor)
							local alpha = e.card.alpha
							if alpha > 0.01 then
								setProp(e.pin, "Visible", true)
								setProp(e.ring, "Visible", true)
								setProp(e.pin, "Position", UDim2.fromOffset(screen.X, screen.Y))
								setProp(e.pin, "BackgroundColor3", color)
								setProp(e.pin, "BackgroundTransparency", 1 - alpha)
								local grow = esp.Pulse and (now * 0.8 + index * 0.13) % 1 or 0.35
								setProp(e.ring, "Position", UDim2.fromOffset(screen.X, screen.Y))
								setProp(e.ring, "Size", UDim2.fromOffset(8 + grow * 26, 8 + grow * 26))
								setProp(e.ringStroke, "Color", color)
								setProp(e.ringStroke, "Transparency", 1 - alpha * (1 - grow) * 0.9)
							else
								setProp(e.pin, "Visible", false)
								setProp(e.ring, "Visible", false)
							end
						end
					end
					for model, e in pairs(islandEntries) do
						if liveIslands[model] then
							continue
						end

						pcall(function()
							e.card.holder:Destroy()
						end)
						pcall(function()
							e.ring:Destroy()
						end)
						pcall(function()
							e.pin:Destroy()
						end)
						islandEntries[model] = nil
					end

					-- Battle Royale markers (chests, medals, vending machines, trainers)
					local br = api.br
					if br then
						br(now, dt, position, project, pulse, esp)
					end
				end

				-- the connect call was missing, the step takes frame time so RenderStepped
				getgenv().__TensenESPConn = RunService.RenderStepped:Connect(step)
				getgenv().__TensenESPRemoving = removingConn
			end

			-- esp, battle royale markers (Chest / Medal / Vending Machine / Trainer ESP). needs getgenv().__TensenESPApi
			--   scan loop: every 2s while Chests / Medals / Vendings / Trainers is on, run the scan (pcall'd)
			--   scan: workspace.Effects children -> medals and chests, vending machines, trainers, clears stale entries
			--   cull: distance filter, nearest `BRMaxCards` per type, drop markers of removed entries (every 0.2s)
			--   show: per-type loops (colour key, title, sub text, y offset), br style, pulse, highlight cap
			-- rebuilt / guessed (marked): chest test, medal label, vending containers, trainer detection and its npc containers,
			-- family -> rarity table (not in the code, set getgenv().ChestFamilyRarity = { family = "Rare", ... }), and the marker show routine
			do
				local api = getgenv().__TensenESPApi
				if not api then
					return
				end

				local Players = game:GetService("Players")
				local gui = api.gui
				local tracersFrame = api.tracersFrame
				local newCard = api.newCard
				local updateCard = api.updateCard
				local colorFor = api.colorFor
				local formatDistance = api.formatDistance
				local setProp = api.setProp
				local getInstance = api.getInstance
				local corner = api.corner

				getgenv().TrainersSeen = getgenv().TrainersSeen or {}
				getgenv().TrainerFound = getgenv().TrainerFound or false

				-- rarity -> esp toggle key / colour key (names from the esp defaults in the hub)
				local RARITY_FLAG = {
					Common = "ChestCommon",
					Uncommon = "ChestUncommon",
					Rare = "ChestRare",
					Legendary = "ChestLegendary",
					Mythical = "ChestMythical",
				}
				local RARITY_COLOR = {
					Common = "ChestCommonColor",
					Uncommon = "ChestUncommonColor",
					Rare = "ChestRareColor",
					Legendary = "ChestLegendaryColor",
					Mythical = "ChestMythicalColor",
					Unknown = "ChestUnknownColor",
				}

				-- style table passed to the card updater instead of getgenv().ESP
				local brStyle = { TextSize = 12, AnimatedBorder = true, Rainbow = false, MenuAccent = false, Pulse = true }

				-- entries by model, raw lists (from the scan), culled lists (for drawing), marker pools
				local chestEntries, medalEntries, vendingEntries, trainerEntries = {}, {}, {}, {}
				local chestRaw, medalRaw, vendingRaw, trainerRaw = {}, {}, {}, {}
				local chestList, medalList, vendingList, trainerList = {}, {}, {}, {}
				local chestPool, medalPool, vendingPool, trainerPool = {}, {}, {}, {}
				local lastCull = 0

				-- markers
				local function clearMarker(pool, key)
					local m = pool[key]
					if not m then
						return
					end
					pcall(function()
						m.card.holder:Destroy()
					end)
					pcall(function()
						m.hl:Destroy()
					end)
					pcall(function()
						m.line:Destroy()
					end)
					pcall(function()
						m.dot:Destroy()
					end)
					pool[key] = nil
				end

				-- rebuilt: same parts as a player entry
				local function getMarker(pool, entry)
					local m = pool[entry]
					if m then
						return m
					end
					m = { card = newCard(false), lineAlpha = 0 }
					m.hl = getInstance("Highlight", {
						DepthMode = Enum.HighlightDepthMode.AlwaysOnTop,
						Enabled = false,
						FillTransparency = 1,
						OutlineTransparency = 1,
						Parent = gui,
					})
					m.line = getInstance("Frame", {
						AnchorPoint = Vector2.new(0.5, 0.5),
						BorderSizePixel = 0,
						BackgroundTransparency = 1,
						Visible = false,
						ZIndex = 2,
						Parent = tracersFrame,
					})
					m.dot = getInstance("Frame", {
						AnchorPoint = Vector2.new(0.5, 0.5),
						BorderSizePixel = 0,
						Size = UDim2.fromOffset(6, 6),
						BackgroundTransparency = 1,
						Visible = false,
						ZIndex = 3,
						Parent = tracersFrame,
					})
					corner(m.dot, 3)
					pool[entry] = m
					return m
				end

				-- rebuilt: (pool, entry, index, colour, title, sub, distance, y offset)
				local function showMarker(ctx, pool, entry, index, color, title, sub, magnitude, yOffset)
					local esp = ctx.esp
					local m = getMarker(pool, entry)
					local screen, onScreen = ctx.project(entry.pos + Vector3.new(0, yOffset, 0))
					local target = onScreen and 1 or 0
					local sizeFactor = math.clamp(1.1 - magnitude / 2500, 0.8, 1.1)
					updateCard(m.card, screen - Vector2.new(0, 4), target, color, ctx.now + index, title, sub, nil, ctx.dt, sizeFactor, brStyle)

					if esp.BRHighlight and index <= ctx.highlightMax and entry.model and entry.model.Parent then
						if m.hl.Adornee ~= entry.model then
							m.hl.Adornee = entry.model
						end
						setProp(m.hl, "Enabled", true)
						setProp(m.hl, "FillColor", color)
						setProp(m.hl, "OutlineColor", color:Lerp(Color3.new(1, 1, 1), 0.35))
						setProp(m.hl, "FillTransparency", 0.55 + ctx.pulseStep * 0.25)
						setProp(m.hl, "OutlineTransparency", 0.05 + ctx.pulseStep * 0.25)
					else
						setProp(m.hl, "Enabled", false)
					end

					m.lineAlpha += (((esp.BRTracers and onScreen) and 1 or 0) - m.lineAlpha) * math.min(1, ctx.dt * 12)
					if m.lineAlpha > 0.01 then
						local origin = Vector2.new(ctx.viewport.X / 2, ctx.viewport.Y - 2)
						local offset = screen - origin
						setProp(m.line, "Visible", true)
						setProp(m.dot, "Visible", true)
						setProp(m.line, "Position", UDim2.fromOffset((origin.X + screen.X) / 2, (origin.Y + screen.Y) / 2))
						setProp(m.line, "Size", UDim2.fromOffset(offset.Magnitude, 1.5))
						setProp(m.line, "Rotation", math.deg(math.atan2(offset.Y, offset.X)))
						setProp(m.line, "BackgroundColor3", color)
						setProp(m.line, "BackgroundTransparency", 1 - m.lineAlpha * (0.45 + ctx.pulse * 0.2))
						setProp(m.dot, "Position", UDim2.fromOffset(screen.X, screen.Y))
						setProp(m.dot, "BackgroundColor3", color)
						setProp(m.dot, "BackgroundTransparency", 1 - m.lineAlpha)
					else
						setProp(m.line, "Visible", false)
						setProp(m.dot, "Visible", false)
					end
				end

				-- scan checks
				local function isMedal(instance)
					if not instance:IsA("Model") then
						return false
					end
					local name = string.lower(instance.Name)
					if string.find(name, "piller", 1, true) or string.find(name, "pillar", 1, true) then
						return false
					end
					return string.find(name, "medal", 1, true) ~= nil
				end

				-- medal marker text (guess)
				local function medalLabel()
					return "Medal"
				end

				-- a chest is a Model with "chest" in the name (guess)
				local function isChest(instance)
					return instance:IsA("Model") and string.find(string.lower(instance.Name), "chest", 1, true) ~= nil
				end

				-- chest family from the Weld names "Meshes/<family>_...", mapped to a rarity. the mapping isn't in the code
				local unknownFamilies = {}
				local function chestRarity(instance)
					local families = getgenv().ChestFamilyRarity or {}
					for _, descendant in ipairs(instance:GetDescendants()) do
						if not descendant:IsA("Weld") then
							continue
						end

						local match = descendant.Name:match("^Meshes/(.-)_")
						if not (match and match ~= "") then
							continue
						end

						local family = match:lower():gsub("[%s%.%d]+$", "")
						local rarity = families[family]
						if not rarity then
							for key, value in pairs(families) do
								if family:sub(1, #key) == key then
									rarity = value
									break
								end
							end
						end
						if rarity then
							return rarity
						end
						if not unknownFamilies[family] then
							unknownFamilies[family] = true
							if getgenv().KDLog then
								getgenv().KDLog("[ChestESP] unknown chest family: " .. family)
							end
						end
					end
					return nil
				end

				local function isVending(instance)
					if not instance:IsA("Model") then
						return false
					end
					local name = string.lower(instance.Name)
					return string.find(name, "vending", 1, true) ~= nil or string.find(name, "vender", 1, true) ~= nil
				end

				local function vendingLabel(instance)
					local attribute
					pcall(function()
						attribute = instance:GetAttribute("VendingType")
					end)
					if type(attribute) ~= "string" or attribute == "" then
						return "Vending Machine", nil
					end
					return ((getgenv().VendingNames or {})[attribute] or string.gsub(attribute, "(%l)(%u)", "%1 %2")) .. " Vending", attribute
				end

				-- vending machine "stock" text: its Stock / Remaining attribute, else nil (guess)
				local function vendingStock(instance)
					local value
					pcall(function()
						value = instance:GetAttribute("Stock") or instance:GetAttribute("Remaining")
					end)
					if value ~= nil then
						return "stock " .. tostring(value)
					end
					return nil
				end

				-- where vending machines are: Effects and workspace's direct children (guess)
				local function vendingContainers()
					local out = {}
					local effects = workspace:FindFirstChild("Effects")
					if effects then
						out[#out + 1] = effects
					end
					out[#out + 1] = workspace
					return out
				end

				-- models that are never trainers
				local function notTrainer(instance)
					local name = string.lower(instance.Name)
					for _, skip in ipairs(getgenv().TrainerNotNames or {}) do
						if skip ~= "" and string.find(name, string.lower(skip), 1, true) then
							return true
						end
					end
					if string.find(name, "vending", 1, true) or string.find(name, "vender", 1, true) or string.find(name, "medal", 1, true) or string.find(name, "chest", 1, true) then
						return true
					end
					if instance:FindFirstChild("Top") and instance:FindFirstChild("Lock") then
						return true
					end
					if Players:GetPlayerFromCharacter(instance) then
						return true
					end
					return false
				end

				-- (isTrainer, label, why). a trainer is an npc in a ForceField (TrainerNeedsForceField == false: every npc counts)
				-- or a name in getgenv().TrainerNames (guess)
				local function detectTrainer(model)
					if notTrainer(model) then
						return false
					end
					local label = model.Name
					local prompt = model:FindFirstChildWhichIsA("ProximityPrompt", true)
					if prompt then
						local text = prompt.ObjectText ~= "" and prompt.ObjectText or prompt.ActionText
						if text and text ~= "" then
							label = text
						end
					end
					for _, pinned in ipairs(getgenv().TrainerNames or {}) do
						if pinned == model.Name then
							return true, label, "pinned by name"
						end
					end
					if getgenv().TrainerNeedsForceField == false then
						return true, label, "every NPC counts"
					end
					local ff = getgenv().npcHasForceField
					if ff and ff(model) then
						return true, label, "ForceField"
					end
					return false
				end

				-- every npc model (workspace.NPCs children with a Humanoid)
				local function eachNPC(callback)
					local npcs = workspace:FindFirstChild("NPCs")
					if not npcs then
						return
					end
					for _, child in ipairs(npcs:GetChildren()) do
						if child:IsA("Model") and child:FindFirstChildOfClass("Humanoid") then
							callback(child, npcs)
						end
					end
				end

				local function pivotPosition(model)
					local ok, result = pcall(function()
						return model:GetPivot()
					end)
					return ok and result and result.Position or nil
				end

				-- the scan
				local function scan()
					local effects = workspace:FindFirstChild("Effects")
					if not effects then
						for k in pairs(chestPool) do clearMarker(chestPool, k) end
						for k in pairs(medalPool) do clearMarker(medalPool, k) end
						for k in pairs(vendingPool) do clearMarker(vendingPool, k) end
						chestEntries, medalEntries, vendingEntries = {}, {}, {}
						chestRaw, medalRaw, vendingRaw = {}, {}, {}
						return
					end
					local chests, chestSeen = {}, {}
					local medals, medalSeen = {}, {}
					local count = 0
					for _, child in ipairs(effects:GetChildren()) do
						if isMedal(child) then
							medalSeen[child] = true
							local e = medalEntries[child]
							if not e then
								e = { model = child, label = medalLabel() }
								medalEntries[child] = e
							end
							local pos = pivotPosition(child)
							if pos then
								e.pos = pos
							end
							if e.pos then
								medals[#medals + 1] = e
							end
						elseif isChest(child) then
							chestSeen[child] = true
							local e = chestEntries[child]
							if not e then
								e = { model = child, rarity = "Unknown" }
								chestEntries[child] = e
							end
							if e.rarity == "Unknown" then
								e.rarity = chestRarity(child) or "Unknown"
							end
							local pos = pivotPosition(child)
							if pos then
								e.pos = pos
							end
							if e.pos then
								chests[#chests + 1] = e
							end
						end
						count += 1
						if count % 150 == 0 then
							task.wait()
						end
					end
					for model, e in pairs(chestEntries) do
						if not chestSeen[model] then
							clearMarker(chestPool, e)
							chestEntries[model] = nil
						end
					end
					for model, e in pairs(medalEntries) do
						if not medalSeen[model] then
							clearMarker(medalPool, e)
							medalEntries[model] = nil
						end
					end

					local vendings, vendingSeen = {}, {}
					if getgenv().ESP.Vendings then
						local visited = 0
						for _, container in ipairs(vendingContainers()) do
							for _, child in ipairs(container:GetChildren()) do
								if isVending(child) then
									vendingSeen[child] = true
									local e = vendingEntries[child]
									if not e then
										e = { model = child }
										vendingEntries[child] = e
									end
									e.stock = vendingStock(child)
									local label, kind = vendingLabel(child)
									e.label = label
									e.kind = kind
									local pos = pivotPosition(child)
									if pos then
										e.pos = pos
									end
									if e.pos then
										vendings[#vendings + 1] = e
									end
								end
								visited += 1
								if visited % 8 == 0 then
									task.wait()
								end
							end
						end
					end
					for model, e in pairs(vendingEntries) do
						if not vendingSeen[model] then
							clearMarker(vendingPool, e)
							vendingEntries[model] = nil
						end
					end

					local trainers, trainerSeen = {}, {}
					if getgenv().ESP.Trainers then
						eachNPC(function(model, container)
							local isTrainer, label, why = detectTrainer(model)
							if not isTrainer then
								return
							end
							trainerSeen[model] = true
							local e = trainerEntries[model]
							if not e then
								e = { model = model }
								trainerEntries[model] = e
							end
							e.label = label
							e.why = why
							local pos = pivotPosition(model)
							if pos then
								e.pos = pos
							end
							if e.pos then
								trainers[#trainers + 1] = e
							end
							local key = tostring(label)
							if not getgenv().TrainersSeen[key] then
								getgenv().TrainersSeen[key] = true
								local log = getgenv().KDLog or getgenv().BMLog
								if log then
									log(string.format("[Trainer] '%s' is in this match (%s) - '%s'.", tostring(label), tostring(why), tostring(model.Name)))
								end
							end
						end)
					end
					for model, e in pairs(trainerEntries) do
						if not trainerSeen[model] then
							clearMarker(trainerPool, e)
							trainerEntries[model] = nil
						end
					end

					getgenv().TrainerFound = #trainers > 0
					chestRaw, medalRaw, vendingRaw, trainerRaw = chests, medals, vendings, trainers
				end

				-- cull: nearest `BRMaxCards` per type within range, everything else loses its marker
				local function byDistance(a, b)
					return a.dist < b.dist
				end

				local function cullType(raw, enabled, maxDist, maxCards, position, pool, accept)
					local list = {}
					if enabled then
						for i = 1, #raw do
							local e = raw[i]
							if accept == nil or accept(e) then
								local magnitude = (e.pos - position).Magnitude
								if magnitude <= maxDist then
									list[#list + 1] = e
									e.dist = magnitude
								end
							end
						end
						table.sort(list, byDistance)
						for i = maxCards + 1, #list do
							list[i] = nil
						end
					end
					local keep = {}
					for i = 1, #list do
						keep[list[i]] = true
					end
					for key in pairs(pool) do
						if not keep[key] then
							clearMarker(pool, key)
						end
					end
					return list
				end

				local function cull(position)
					local esp = getgenv().ESP
					local maxCards = math.max(tonumber(esp.BRMaxCards) or 60, 1)
					chestList = cullType(chestRaw, esp.Chests, tonumber(esp.ChestMaxDist) or 2500, maxCards, position, chestPool, function(e)
						return esp[RARITY_FLAG[e.rarity] or "ChestUnknown"]
					end)
					medalList = cullType(medalRaw, esp.Medals, tonumber(esp.MedalMaxDist) or 5000, maxCards, position, medalPool)
					vendingList = cullType(vendingRaw, esp.Vendings, tonumber(esp.VendingMaxDist) or 5000, maxCards, position, vendingPool)
					trainerList = cullType(trainerRaw, esp.Trainers, tonumber(esp.TrainerMaxDist) or 6000, maxCards, position, trainerPool)
				end

				-- show part of the render step, called by the esp core every refresh
				local function br(now, dt, position, project, pulse, esp)
					if esp.Chests or esp.Medals or esp.Vendings or esp.Trainers then
						if now - lastCull > 0.2 then
							lastCull = now
							cull(position)
						end
						brStyle.TextSize = tonumber(esp.BRTextSize) or esp.TextSize
						brStyle.AnimatedBorder = esp.BRAnimatedBorder
						brStyle.Rainbow = esp.BRRainbow
						brStyle.MenuAccent = esp.BRMenuAccent
						brStyle.Pulse = esp.BRPulse
						local brPulse = esp.BRPulse and (math.sin(now * 3) + 1) / 2 or nil
						local ctx = {
							esp = esp,
							now = now,
							dt = dt,
							project = project,
							pulse = brPulse or 0.5,
							pulseStep = math.floor((brPulse or 0.5) * 6 + 0.5) / 6,
							highlightMax = math.max(tonumber(esp.BRHighlightMax) or 8, 0),
							viewport = (workspace.CurrentCamera or {}).ViewportSize or Vector2.new(1920, 1080),
						}
						for i = 1, #chestList do
							local e = chestList[i]
							local color = colorFor(RARITY_COLOR[e.rarity] or "ChestUnknownColor", i * 0.05, brStyle)
							local title = "Chest"
							if esp.ChestRarityText and e.rarity ~= "Unknown" then
								title = e.rarity .. " Chest"
							end
							showMarker(ctx, chestPool, e, i, color, title, esp.ChestDistance and formatDistance(e.dist) or nil, e.dist, 3.2)
						end
						for i = 1, #medalList do
							local e = medalList[i]
							local color = colorFor("MedalColor", i * 0.05, brStyle)
							showMarker(ctx, medalPool, e, i, color, e.label, esp.MedalDistance and formatDistance(e.dist) or nil, e.dist, 4)
						end
						for i = 1, #vendingList do
							local e = vendingList[i]
							local color = colorFor("VendingColor", i * 0.05, brStyle)
							local lines = {}
							if esp.VendingStock and e.stock then
								lines[#lines + 1] = e.stock
							end
							if esp.VendingDistance then
								lines[#lines + 1] = formatDistance(e.dist)
							end
							showMarker(ctx, vendingPool, e, i, color, e.label or "Vending Machine", #lines > 0 and table.concat(lines, "  \u{2022}  ") or nil, e.dist, 6)
						end
						for i = 1, #trainerList do
							local e = trainerList[i]
							local color = colorFor("TrainerColor", i * 0.05, brStyle)
							showMarker(ctx, trainerPool, e, i, color, esp.TrainerStyleText ~= false and tostring(e.label) or "Trainer", esp.TrainerDistance and formatDistance(e.dist) or nil, e.dist, 5)
						end
					elseif next(chestPool) or next(medalPool) or next(vendingPool) or next(trainerPool) then
						for k in pairs(chestPool) do clearMarker(chestPool, k) end
						for k in pairs(medalPool) do clearMarker(medalPool, k) end
						for k in pairs(vendingPool) do clearMarker(vendingPool, k) end
						for k in pairs(trainerPool) do clearMarker(trainerPool, k) end
						chestList, medalList, vendingList, trainerList = {}, {}, {}, {}
					end
				end
				api.br = br

				-- scan loop, replaces any older copy on reload
				local loops = getgenv().__TensenLoops
				if type(loops) ~= "table" then
					loops = {}
					getgenv().__TensenLoops = loops
				end
				local token = {}
				loops.ESPScan = token
				task.spawn(function()
					task.wait()
					while loops.ESPScan == token do
						local esp = getgenv().ESP
						if esp and (esp.Chests or esp.Medals or esp.Vendings or esp.Trainers) then
							pcall(scan)
						end
						task.wait(2)
					end
				end)
			end

			-- auto factory: "is the rose kingdom factory open" check. auto farm reads it as getgenv().FactoryPending
			-- the Auto Factory toggle has no loop of its own, it only
			--   * makes auto farm wait while the factory is open (second sea)
			--   * makes the m1 loops use the boss hit delay and adds workspace.Env.FactoryPool.hitbox within 50 studs to the targets
			--   * counts as a farm flag everywhere
			-- it's labelled "Auto Factory (WIP)" in the hub
			-- label: workspace.Islands["Rose Kingdom"].Factory.FrontDoor.Top.BillboardGui.TextLabel
			getgenv().factoryDoorLabel = getgenv().factoryDoorLabel or function()
				local islands = workspace:FindFirstChild("Islands")
				local roseKingdom = islands and islands:FindFirstChild("Rose Kingdom")
				local factory = roseKingdom and roseKingdom:FindFirstChild("Factory")
				local frontDoor = factory and factory:FindFirstChild("FrontDoor")
				local top = frontDoor and frontDoor:FindFirstChild("Top")
				local billboardGui = top and top:FindFirstChild("BillboardGui")
				return billboardGui and billboardGui:FindFirstChild("TextLabel")
			end

			-- door says CLOSED -> false, OPEN -> true, anything else (no label / other text) -> true
			getgenv().FactoryPending = getgenv().FactoryPending or function()
				local label = getgenv().factoryDoorLabel()
				if label and label.Text then
					local text = label.Text:upper()
					if text:find("CLOSED") then
						return false
					end
					if text:find("OPEN") then
						return true
					end
				end
				return true
			end

			getgenv().releaseAimStance = function()
				return getgenv().sendFaceMouse(false)
			end

			genv4 = getgenv()
			faceMouseConfirmTimeout = getgenv().TpFaceMouseMinY
		end

		if not (game.PlaceId == 3978370137 or game.PlaceId == 7465136166 or game.PlaceId == 1730877806 or game.PlaceId == 116480749200627 or game.PlaceId == 6811831486 or game.PlaceId == 11424731604) then
			game.Players.LocalPlayer:Kick("Please Use this script in First/Second Sea or main menu")
		end
	else
		game.Players.LocalPlayer:Kick("Game Not Support")
	end
elseif getgenv().AlreadyLoad then
	guardNoop()
end

return
